	// Collapses linear RGB to a single-channel scalar using equal tristimulus weights
	// (Y = (R+G+B)/3). Name retained for call-site stability; semantics are NOT BT.709
	// photopic anymore — see RGBToLuminance.usf for rationale.
	float ComputeRec709LuminanceLinear(const FLinearColor& Color)
	{
		if (!FMath::IsFinite(Color.R) || !FMath::IsFinite(Color.G) || !FMath::IsFinite(Color.B))
		{
			return 0.0f;
		}
		return (Color.R + Color.G + Color.B) * (1.0f / 3.0f);
	}

	double ComputeBenchmarkFiniteMean(const TArray<float>& Values)
	{
		double Sum = 0.0;
		int32 Count = 0;
		for (const float Value : Values)
		{
			if (FMath::IsFinite(Value))
			{
				Sum += static_cast<double>(Value);
				++Count;
			}
		}
		return Count > 0 ? (Sum / static_cast<double>(Count)) : std::numeric_limits<double>::quiet_NaN();
	}

	double ComputeBenchmarkFiniteStd(const TArray<float>& Values, double Mean)
	{
		if (!FMath::IsFinite(static_cast<float>(Mean)))
		{
			return std::numeric_limits<double>::quiet_NaN();
		}

		double SumSquares = 0.0;
		int32 Count = 0;
		for (const float Value : Values)
		{
			if (FMath::IsFinite(Value))
			{
				const double Delta = static_cast<double>(Value) - Mean;
				SumSquares += Delta * Delta;
				++Count;
			}
		}
		return Count > 0 ? FMath::Sqrt(SumSquares / static_cast<double>(Count)) : std::numeric_limits<double>::quiet_NaN();
	}

	double ComputeBenchmarkFiniteMaeToTarget(const TArray<float>& Values, double Target)
	{
		double SumAbs = 0.0;
		int32 Count = 0;
		for (const float Value : Values)
		{
			if (FMath::IsFinite(Value))
			{
				SumAbs += FMath::Abs(static_cast<double>(Value) - Target);
				++Count;
			}
		}
		return Count > 0 ? (SumAbs / static_cast<double>(Count)) : std::numeric_limits<double>::quiet_NaN();
	}

	double SafeNormalizeBenchmarkValue(double Numerator, float Denominator)
	{
		return (FMath::IsFinite(Denominator) && Denominator > 1.0e-6f)
			? (Numerator / static_cast<double>(Denominator))
			: std::numeric_limits<double>::quiet_NaN();
	}

	bool BenchmarkNearlyEqual(double A, double B)
	{
		if (!FMath::IsFinite(static_cast<float>(A)) || !FMath::IsFinite(static_cast<float>(B)))
		{
			return false;
		}

		const double Scale = FMath::Max(1.0, FMath::Max(FMath::Abs(A), FMath::Abs(B)));
		const double Tolerance = 1.0e-4 * Scale;
		return FMath::Abs(A - B) <= Tolerance;
	}

	struct FBenchmarkSVFStatistics
	{
		double Mean = std::numeric_limits<double>::quiet_NaN();
		double Std = std::numeric_limits<double>::quiet_NaN();
		double MaeToHalf = std::numeric_limits<double>::quiet_NaN();
		bool bUsedInteriorMask = false;
		FString DomainLabel = TEXT("full_domain");
	};

	bool ShouldPreferInteriorSVFStatistics(const FString& MapTag)
	{
		return MapTag.Contains(TEXT("hemisphericalcavity"), ESearchCase::IgnoreCase);
	}

	bool ShouldUseSurfaceNormalSVFForBenchmark(const ASnowSimulationActor& Owner)
	{
		return Owner.bRadiationBenchmarkUseSurfaceNormalSVF
			&& ShouldPreferInteriorSVFStatistics(Owner.GetCurrentMapTag());
	}

	void BuildHemisphereTangentBasis(const FVector& HemisphereNormal, FVector& OutTangentX, FVector& OutTangentY)
	{
		const FVector Normal = HemisphereNormal.GetSafeNormal().IsNearlyZero()
			? FVector::UpVector
			: HemisphereNormal.GetSafeNormal();

		FVector ReferenceAxis = (FMath::Abs(Normal.Z) < 0.999f) ? FVector::UpVector : FVector::ForwardVector;
		OutTangentX = FVector::CrossProduct(ReferenceAxis, Normal).GetSafeNormal();
		if (OutTangentX.IsNearlyZero())
		{
			ReferenceAxis = FVector::RightVector;
			OutTangentX = FVector::CrossProduct(ReferenceAxis, Normal).GetSafeNormal();
		}

		if (OutTangentX.IsNearlyZero())
		{
			OutTangentX = FVector::ForwardVector;
		}

		OutTangentY = FVector::CrossProduct(Normal, OutTangentX).GetSafeNormal();
		if (OutTangentY.IsNearlyZero())
		{
			OutTangentY = FVector::CrossProduct(Normal, FVector::RightVector).GetSafeNormal();
		}
	}

	const TCHAR* GetSVFDefinitionLabel(bool bUseSurfaceNormalHemisphere)
	{
		return bUseSurfaceNormalHemisphere ? TEXT("SurfaceNormalHemisphere") : TEXT("HorizontalHemisphere");
	}

	const TCHAR* GetSVFVariantSuffix(bool bUseSurfaceNormalHemisphere)
	{
		return bUseSurfaceNormalHemisphere ? TEXT("SurfaceNormal") : TEXT("Horizontal");
	}

	FString GetSVFDefinitionDescription(bool bUseSurfaceNormalHemisphere, bool bIsRayTracingBackend)
	{
		if (bIsRayTracingBackend)
		{
			return FString::Printf(
				TEXT("SVF ~= mean visibility of cosine-weighted hemisphere rays against the full-scene TLAS using a %s"),
				bUseSurfaceNormalHemisphere ? TEXT("surface-normal hemisphere") : TEXT("horizontal hemisphere"));
		}

		return FString::Printf(
			TEXT("SVF = mean_phi(cos(horizon(phi))^2) using a %s"),
			bUseSurfaceNormalHemisphere ? TEXT("surface-normal hemisphere") : TEXT("horizontal hemisphere"));
	}

	bool BuildBenchmarkInteriorMask(
		const TArray<float>& SVFValues,
		const TArray<FLandscapeCell>* Cells,
		const FString& MapTag,
		TArray<uint8>& OutMask,
		FString& OutDomainLabel)
	{
		OutMask.Reset();
		OutDomainLabel = TEXT("full_domain");

		if (SVFValues.Num() <= 0 || !ShouldPreferInteriorSVFStatistics(MapTag))
		{
			return false;
		}

		const int32 NumValues = SVFValues.Num();
		int32 FiniteCount = 0;
		int32 SvfInteriorCount = 0;
		OutMask.Init(0, NumValues);
		for (int32 Index = 0; Index < NumValues; ++Index)
		{
			const float SVFValue = SVFValues[Index];
			if (!FMath::IsFinite(SVFValue))
			{
				continue;
			}

			++FiniteCount;
			if (SVFValue < 0.99f)
			{
				OutMask[Index] = 1;
				++SvfInteriorCount;
			}
		}

		TArray<uint8> AltitudeMask;
		if (Cells && Cells->Num() == NumValues)
		{
			float MinAltitude = TNumericLimits<float>::Max();
			float MaxAltitude = TNumericLimits<float>::Lowest();
			double OpenSkyAltitudeSum = 0.0;
			int32 OpenSkyCount = 0;

			for (int32 Index = 0; Index < NumValues; ++Index)
			{
				const float SVFValue = SVFValues[Index];
				const float Altitude = (*Cells)[Index].Altitude;
				if (!FMath::IsFinite(SVFValue) || !FMath::IsFinite(Altitude))
				{
					continue;
				}

				MinAltitude = FMath::Min(MinAltitude, Altitude);
				MaxAltitude = FMath::Max(MaxAltitude, Altitude);
				if (SVFValue >= 0.995f)
				{
					OpenSkyAltitudeSum += static_cast<double>(Altitude);
					++OpenSkyCount;
				}
			}

			const float Relief = MaxAltitude - MinAltitude;
			if (FiniteCount > 0 && FMath::IsFinite(Relief) && Relief > 1.0f)
			{
				const float RimAltitude = (OpenSkyCount > 0)
					? static_cast<float>(OpenSkyAltitudeSum / static_cast<double>(OpenSkyCount))
					: MaxAltitude;
				const float AltitudeTolerance = FMath::Max(1.0f, Relief * 0.01f);

				AltitudeMask.Init(0, NumValues);
				int32 AltitudeInteriorCount = 0;
				for (int32 Index = 0; Index < NumValues; ++Index)
				{
					const float Altitude = (*Cells)[Index].Altitude;
					if (!FMath::IsFinite(Altitude))
					{
						continue;
					}

					if (Altitude < (RimAltitude - AltitudeTolerance))
					{
						AltitudeMask[Index] = 1;
						++AltitudeInteriorCount;
					}
				}

				if (AltitudeInteriorCount > 0 && AltitudeInteriorCount < FiniteCount)
				{
					OutMask = MoveTemp(AltitudeMask);
					OutDomainLabel = TEXT("cavity_interior_altitude_below_rim");
					return true;
				}
			}
		}

		if (SvfInteriorCount > 0 && SvfInteriorCount < FiniteCount)
		{
			OutDomainLabel = TEXT("cavity_interior_svf_lt_0p99");
			return true;
		}

		OutMask.Reset();
		OutDomainLabel = TEXT("full_domain");
		return false;
	}

	FBenchmarkSVFStatistics ComputeBenchmarkSVFStatistics(
		const TArray<float>& Values,
		const TArray<uint8>* AnalysisMask,
		const FString& DomainLabel)
	{
		FBenchmarkSVFStatistics Stats;
		if (!AnalysisMask || AnalysisMask->Num() != Values.Num())
		{
			Stats.Mean = ComputeBenchmarkFiniteMean(Values);
			Stats.Std = ComputeBenchmarkFiniteStd(Values, Stats.Mean);
			Stats.MaeToHalf = ComputeBenchmarkFiniteMaeToTarget(Values, 0.5);
			return Stats;
		}

		TArray<float> MaskedValues;
		MaskedValues.Reserve(Values.Num());
		for (int32 Index = 0; Index < Values.Num(); ++Index)
		{
			if ((*AnalysisMask)[Index] != 0 && FMath::IsFinite(Values[Index]))
			{
				MaskedValues.Add(Values[Index]);
			}
		}

		if (MaskedValues.Num() <= 0)
		{
			Stats.Mean = ComputeBenchmarkFiniteMean(Values);
			Stats.Std = ComputeBenchmarkFiniteStd(Values, Stats.Mean);
			Stats.MaeToHalf = ComputeBenchmarkFiniteMaeToTarget(Values, 0.5);
			return Stats;
		}

		Stats.bUsedInteriorMask = true;
		Stats.DomainLabel = DomainLabel;
		Stats.Mean = ComputeBenchmarkFiniteMean(MaskedValues);
		Stats.Std = ComputeBenchmarkFiniteStd(MaskedValues, Stats.Mean);
		Stats.MaeToHalf = ComputeBenchmarkFiniteMaeToTarget(MaskedValues, 0.5);
		return Stats;
	}

	double ComputeBenchmarkFiniteMeanWithMask(
		const TArray<float>& Values,
		const TArray<uint8>* AnalysisMask)
	{
		if (!AnalysisMask || AnalysisMask->Num() != Values.Num())
		{
			return ComputeBenchmarkFiniteMean(Values);
		}

		double Sum = 0.0;
		int32 Count = 0;
		for (int32 Index = 0; Index < Values.Num(); ++Index)
		{
			const float Value = Values[Index];
			if (!FMath::IsFinite(Value) || (*AnalysisMask)[Index] == 0)
			{
				continue;
			}

			Sum += static_cast<double>(Value);
			++Count;
		}

		return Count > 0 ? (Sum / static_cast<double>(Count)) : std::numeric_limits<double>::quiet_NaN();
	}

	void GatherBenchmarkFiniteValuesWithMask(
		const TArray<float>& Values,
		const TArray<uint8>* AnalysisMask,
		TArray<float>& OutValues)
	{
		OutValues.Reset();
		OutValues.Reserve(Values.Num());
		for (int32 Index = 0; Index < Values.Num(); ++Index)
		{
			const float Value = Values[Index];
			if (!FMath::IsFinite(Value))
			{
				continue;
			}
			if (AnalysisMask && AnalysisMask->Num() == Values.Num() && (*AnalysisMask)[Index] == 0)
			{
				continue;
			}
			OutValues.Add(Value);
		}
	}

	double ComputeBenchmarkFinitePercentileWithMask(
		const TArray<float>& Values,
		const TArray<uint8>* AnalysisMask,
		double Percentile)
	{
		TArray<float> MaskedValues;
		GatherBenchmarkFiniteValuesWithMask(Values, AnalysisMask, MaskedValues);
		if (MaskedValues.Num() == 0)
		{
			return std::numeric_limits<double>::quiet_NaN();
		}

		MaskedValues.Sort();
		const double ClampedPercentile = FMath::Clamp(Percentile, 0.0, 100.0);
		const int32 LastIndex = MaskedValues.Num() - 1;
		const int32 SampleIndex = FMath::Clamp(
			FMath::RoundToInt((ClampedPercentile / 100.0) * static_cast<double>(LastIndex)),
			0,
			LastIndex);
		return static_cast<double>(MaskedValues[SampleIndex]);
	}

	double ComputeBenchmarkFiniteMaxWithMask(
		const TArray<float>& Values,
		const TArray<uint8>* AnalysisMask)
	{
		double MaxValue = -std::numeric_limits<double>::infinity();
		bool bFoundAny = false;
		for (int32 Index = 0; Index < Values.Num(); ++Index)
		{
			const float Value = Values[Index];
			if (!FMath::IsFinite(Value))
			{
				continue;
			}
			if (AnalysisMask && AnalysisMask->Num() == Values.Num() && (*AnalysisMask)[Index] == 0)
			{
				continue;
			}
			MaxValue = FMath::Max(MaxValue, static_cast<double>(Value));
			bFoundAny = true;
		}
		return bFoundAny ? MaxValue : std::numeric_limits<double>::quiet_NaN();
	}

	double ComputeCentralCropMeanLuminance(
		const TArray<FLinearColor>& Pixels,
		int32 Width,
		int32 Height,
		float CropFraction)
	{
		if (Width <= 0 || Height <= 0 || Pixels.Num() != Width * Height)
		{
			return std::numeric_limits<double>::quiet_NaN();
		}

		const float SafeCropFraction = FMath::Clamp(CropFraction, 0.05f, 1.0f);
		const int32 CropWidth = FMath::Max(1, FMath::FloorToInt(static_cast<float>(Width) * SafeCropFraction));
		const int32 CropHeight = FMath::Max(1, FMath::FloorToInt(static_cast<float>(Height) * SafeCropFraction));
		const int32 StartX = FMath::Clamp((Width - CropWidth) / 2, 0, Width - 1);
		const int32 StartY = FMath::Clamp((Height - CropHeight) / 2, 0, Height - 1);
		const int32 EndX = FMath::Min(StartX + CropWidth, Width);
		const int32 EndY = FMath::Min(StartY + CropHeight, Height);

		double Sum = 0.0;
		int32 Count = 0;
		for (int32 Y = StartY; Y < EndY; ++Y)
		{
			for (int32 X = StartX; X < EndX; ++X)
			{
				const float Luminance = ComputeRec709LuminanceLinear(Pixels[Y * Width + X]);
				if (!FMath::IsFinite(Luminance))
				{
					continue;
				}

				Sum += static_cast<double>(Luminance);
				++Count;
			}
		}

		return Count > 0 ? (Sum / static_cast<double>(Count)) : std::numeric_limits<double>::quiet_NaN();
	}

	UTextureCube* ResolveUniformRadiationBenchmarkSkyCubemap()
	{
		static TWeakObjectPtr<UTextureCube> CachedUniformCubemap;
		if (CachedUniformCubemap.IsValid())
		{
			return CachedUniformCubemap.Get();
		}

		static const TCHAR* UniformCubemapPaths[] =
		{
			TEXT("/Engine/EngineResources/GrayLightTextureCube.GrayLightTextureCube"),
			TEXT("/Engine/EngineResources/DefaultTextureCube.DefaultTextureCube"),
		};

		for (const TCHAR* CubemapPath : UniformCubemapPaths)
		{
			if (UTextureCube* UniformCubemap = LoadObject<UTextureCube>(nullptr, CubemapPath))
			{
				CachedUniformCubemap = UniformCubemap;
				return UniformCubemap;
			}
		}

		return nullptr;
	}

	bool ReadRenderTargetLinearPixels(
		UTextureRenderTarget2D* Target,
		FTextureRenderTargetResource* Resource,
		TArray<FLinearColor>& OutPixels,
		const FReadSurfaceDataFlags& ReadFlags)
	{
		OutPixels.Reset();

		if (!Target || !Resource)
		{
			return false;
		}

		if (Target->RenderTargetFormat == RTF_RGBA32f)
		{
			return Resource->ReadLinearColorPixels(OutPixels, ReadFlags);
		}

		TArray<FFloat16Color> HalfPixels;
		if (!Resource->ReadFloat16Pixels(HalfPixels, ReadFlags))
		{
			return false;
		}

		OutPixels.SetNumUninitialized(HalfPixels.Num());
		for (int32 Index = 0; Index < HalfPixels.Num(); ++Index)
		{
			const FFloat16Color& Pixel = HalfPixels[Index];
			OutPixels[Index] = FLinearColor(Pixel.R, Pixel.G, Pixel.B, Pixel.A);
		}

		return true;
	}

	struct FCaptureVolumetricCloudVisibilityState
	{
		TWeakObjectPtr<USceneComponent> Component;
		bool bVisible = false;
	};

	struct FVolumetricCloudCaptureDisableScope
	{
		TArray<FCaptureVolumetricCloudVisibilityState> SavedStates;

		explicit FVolumetricCloudCaptureDisableScope(ASnowSimulationActor& Actor)
		{
			if (!Actor.bDisableVolumetricCloudsDuringRadiationCapture)
			{
				return;
			}

			UWorld* const World = Actor.GetWorld();
			if (!World)
			{
				return;
			}

			for (TActorIterator<AActor> ActorIt(World); ActorIt; ++ActorIt)
			{
				AActor* const WorldActor = *ActorIt;
				if (!WorldActor)
				{
					continue;
				}

				TInlineComponentArray<USceneComponent*> SceneComponents(WorldActor);
				for (USceneComponent* const SceneComponent : SceneComponents)
				{
					if (!SceneComponent || !SceneComponent->GetClass())
					{
						continue;
					}

					const FString ClassName = SceneComponent->GetClass()->GetName();
					if (!ClassName.Contains(TEXT("VolumetricCloud"), ESearchCase::IgnoreCase))
					{
						continue;
					}

					FCaptureVolumetricCloudVisibilityState& SavedState = SavedStates.AddDefaulted_GetRef();
					SavedState.Component = SceneComponent;
					SavedState.bVisible = SceneComponent->IsVisible();
					if (SavedState.bVisible)
					{
						SceneComponent->SetVisibility(false, true);
						SceneComponent->MarkRenderStateDirty();
					}
				}
			}
		}

		~FVolumetricCloudCaptureDisableScope()
		{
			for (const FCaptureVolumetricCloudVisibilityState& SavedState : SavedStates)
			{
				if (USceneComponent* const SceneComponent = SavedState.Component.Get())
				{
					SceneComponent->SetVisibility(SavedState.bVisible, true);
					SceneComponent->MarkRenderStateDirty();
				}
			}
		}
	};

	// ---------------------------------------------------------------------------
	// FScopedEmissiveOnlySkyCapture
	//
	// For the Total vs TotalNoGI decomposition to isolate terrain inter-reflection
	// cleanly, the SkyLight cubemap must contain only atmosphere / emissive sources
	// — not light that has already bounced off terrain geometry.
	//
	// Under SLS_CapturedScene the SkyLight re-renders the entire scene into its
	// cubemap.  Setting bCaptureEmissiveOnly = true restricts that capture to
	// emissive surfaces (SkyAtmosphere, sky dome, emissive meshes) so the cubemap
	// represents pure sky radiance.  We then force one synchronous recapture so
	// the clean cubemap is in place before any irradiance captures run.
	//
	// On destruction the original bCaptureEmissiveOnly value is restored and
	// another recapture is issued to return the SkyLight to its prior state.
	// ---------------------------------------------------------------------------
	struct FScopedEmissiveOnlySkyCapture
	{
		USkyLightComponent* SkyLight = nullptr;
		bool bRestoreCaptureEmissiveOnly = false;

		explicit FScopedEmissiveOnlySkyCapture(ASnowSimulationActor& Actor)
			: FScopedEmissiveOnlySkyCapture(Actor.CachedSunSkyLight.Get(), Actor.GetWorld())
		{
		}

		FScopedEmissiveOnlySkyCapture(USkyLightComponent* InSkyLight, UWorld* InWorld)
		{
			SkyLight = InSkyLight;
			if (!SkyLight)
			{
				return;
			}

			// Only meaningful for SLS_CapturedScene — a specified cubemap is static.
			if (SkyLight->SourceType != SLS_CapturedScene)
			{
				SkyLight = nullptr;
				return;
			}

			bRestoreCaptureEmissiveOnly = SkyLight->bCaptureEmissiveOnly;
			if (!bRestoreCaptureEmissiveOnly)
			{
				SkyLight->bCaptureEmissiveOnly = true;
				SkyLight->MarkRenderStateDirty();

				// Force one synchronous recapture so the cubemap is clean.
				if (InWorld)
				{
					SkyLight->RecaptureSky();
					USkyLightComponent::UpdateSkyCaptureContents(InWorld);
					FlushRenderingCommands();
				}
			}
		}

		~FScopedEmissiveOnlySkyCapture()
		{
			if (!SkyLight || bRestoreCaptureEmissiveOnly)
			{
				return;
			}

			SkyLight->bCaptureEmissiveOnly = false;
			SkyLight->MarkRenderStateDirty();

			// Recapture with the original setting so runtime rendering is unaffected.
			if (UWorld* World = SkyLight->GetWorld())
			{
				SkyLight->RecaptureSky();
				USkyLightComponent::UpdateSkyCaptureContents(World);
				FlushRenderingCommands();
			}
		}
	};

	struct FBelowCanopyProbeFace
	{
		const TCHAR* Label = TEXT("Unknown");
		FVector Forward = FVector::ForwardVector;
		FVector Up = FVector::UpVector;
	};

	FVector GetBelowCanopyProbeSurfaceNormal(const FLandscapeCell& Cell)
	{
		const FVector SurfaceNormal = Cell.Normal.GetSafeNormal();
		return SurfaceNormal.IsNearlyZero() ? FVector::UpVector : SurfaceNormal;
	}

	bool ComputeLandscapeCellAxisAlignedDomainMeters(
		TConstArrayView<FLandscapeCell> Cells,
		float MetersPerCell,
		FVector2D& OutOriginMeters,
		FVector2D& OutSizeMeters,
		FVector2D& OutMinCentroidMeters,
		FVector2D& OutMaxCentroidMeters)
	{
		if (Cells.IsEmpty())
		{
			return false;
		}

		FVector2D MinMeters(FLT_MAX, FLT_MAX);
		FVector2D MaxMeters(-FLT_MAX, -FLT_MAX);
		for (const FLandscapeCell& Cell : Cells)
		{
			const FVector2D CellMeters(Cell.Centroid.X / 100.0f, Cell.Centroid.Y / 100.0f);
			MinMeters.X = FMath::Min(MinMeters.X, CellMeters.X);
			MinMeters.Y = FMath::Min(MinMeters.Y, CellMeters.Y);
			MaxMeters.X = FMath::Max(MaxMeters.X, CellMeters.X);
			MaxMeters.Y = FMath::Max(MaxMeters.Y, CellMeters.Y);
		}

		if (!FMath::IsFinite(MinMeters.X) || !FMath::IsFinite(MinMeters.Y)
			|| !FMath::IsFinite(MaxMeters.X) || !FMath::IsFinite(MaxMeters.Y))
		{
			return false;
		}

		const float HalfCellMeters = FMath::Max(0.0f, MetersPerCell) * 0.5f;
		OutMinCentroidMeters = MinMeters;
		OutMaxCentroidMeters = MaxMeters;
		OutOriginMeters = MinMeters - FVector2D(HalfCellMeters, HalfCellMeters);
		OutSizeMeters = (MaxMeters - MinMeters) + FVector2D(HalfCellMeters * 2.0f, HalfCellMeters * 2.0f);
		return OutSizeMeters.X > 0.0f && OutSizeMeters.Y > 0.0f;
	}

	float MaxAbsUvError(const FVector2D& A, const FVector2D& B)
	{
		return FMath::Max(FMath::Abs(A.X - B.X), FMath::Abs(A.Y - B.Y));
	}

	// Current VHM material graph decodes SnowDepthTex as:
	// TextureSample.R * 65.535004 -> Depth_m, then Depth_m * 100 * SnowDisplacementScale.
	//
	// Runtime SnowDepthTex is PF_R16F carrying raw depth in meters, so this value is
	// effectively part of the rendered VHM displacement until the material graph is
	// changed to sample meters directly.
	constexpr float GSnowDepthTextureMaterialDecodeScale = 65.535004f;

	FVector ComputeBelowCanopyProbeOrigin(const FLandscapeCell& Cell, float ProbeHeightCm)
	{
		return Cell.Centroid + GetBelowCanopyProbeSurfaceNormal(Cell) * FMath::Max(0.0f, ProbeHeightCm);
	}

	float GetMaxProbeNeighborhoodSnowDepthMeters(
		int32 CellIndex,
		const TArray<FFloat16>& CpuDepthMeters,
		int32 CellsDimensionX,
		int32 CellsDimensionY,
		int32 NeighborhoodRadius = 1)
	{
		if (!CpuDepthMeters.IsValidIndex(CellIndex))
		{
			return 0.0f;
		}

		float MaxSnowDepthMeters = float(CpuDepthMeters[CellIndex]);
		if (CellsDimensionX <= 0 || CellsDimensionY <= 0 || NeighborhoodRadius <= 0)
		{
			return FMath::Max(0.0f, MaxSnowDepthMeters);
		}

		const int32 CenterX = CellIndex % CellsDimensionX;
		const int32 CenterY = CellIndex / CellsDimensionX;
		const int32 MinX = FMath::Max(0, CenterX - NeighborhoodRadius);
		const int32 MaxX = FMath::Min(CellsDimensionX - 1, CenterX + NeighborhoodRadius);
		const int32 MinY = FMath::Max(0, CenterY - NeighborhoodRadius);
		const int32 MaxY = FMath::Min(CellsDimensionY - 1, CenterY + NeighborhoodRadius);
		for (int32 Y = MinY; Y <= MaxY; ++Y)
		{
			for (int32 X = MinX; X <= MaxX; ++X)
			{
				const int32 Idx = X + Y * CellsDimensionX;
				if (CpuDepthMeters.IsValidIndex(Idx))
				{
					MaxSnowDepthMeters = FMath::Max(MaxSnowDepthMeters, float(CpuDepthMeters[Idx]));
				}
			}
		}

		return FMath::Max(0.0f, MaxSnowDepthMeters);
	}

	// Returns the effective probe displacement along the cell surface normal (cm).
	//
	// Mirror the VHM material displacement, not the physical snow-depth units.
	// The material graph currently applies a legacy 16-bit-mm decode scale
	// (65.535004) before multiplying by 100 cm/m and SnowDisplacementScale.
	// A small neighborhood max also keeps the probe above taller adjacent cells
	// that would otherwise enclose it; this matters for models like FSM2 that
	// produce cell-to-cell depth variability.
	//
	// CpuDepthMeters stores vertical snow depth (straight-down column). The
	// probe displaces along the cell normal, so divide by cos(tilt) to preserve
	// the requested vertical clearance on sloped cells; clamp cos(tilt) to
	// avoid blowup on near-vertical cliffs.
	float GetSnowAwareProbeHeightCm(
		int32 CellIndex,
		const TArray<FFloat16>& CpuDepthMeters,
		float RequestedVerticalClearanceCm,
		const FVector& CellNormal,
		float SnowDisplacementScale,
		int32 CellsDimensionX,
		int32 CellsDimensionY,
		int32 NeighborhoodRadius = 1)
	{
		const float MaxSnowDepthMeters = GetMaxProbeNeighborhoodSnowDepthMeters(
			CellIndex,
			CpuDepthMeters,
			CellsDimensionX,
			CellsDimensionY,
			NeighborhoodRadius);
		const float MaterialDepthMeters = MaxSnowDepthMeters * GSnowDepthTextureMaterialDecodeScale;
		const float VerticalSnowDepthCm = MaterialDepthMeters * 100.0f * FMath::Max(0.0f, SnowDisplacementScale);
		const float ClampedVerticalClearanceCm = FMath::Max(0.0f, RequestedVerticalClearanceCm);
		const float CosTilt = FMath::Clamp(CellNormal.Z, 0.1f, 1.0f);
		return (VerticalSnowDepthCm + ClampedVerticalClearanceCm) / CosTilt;
	}

	FVector ComputeSnowAwareBelowCanopyProbeOrigin(
		const FLandscapeCell& Cell,
		int32 CellIndex,
		const TArray<FFloat16>& CpuDepthMeters,
		float BelowCanopyProbeHeightCm,
		float SnowDisplacementScale,
		int32 CellsDimensionX,
		int32 CellsDimensionY)
	{
		const FVector ProbeNormal = GetBelowCanopyProbeSurfaceNormal(Cell);
		const float EffectiveProbeHeightCm = GetSnowAwareProbeHeightCm(
			CellIndex,
			CpuDepthMeters,
			BelowCanopyProbeHeightCm,
			ProbeNormal,
			SnowDisplacementScale,
			CellsDimensionX,
			CellsDimensionY);
		return ComputeBelowCanopyProbeOrigin(Cell, EffectiveProbeHeightCm);
	}

	void BuildBelowCanopyProbeFrame(
		const FVector& ProbeNormal,
		const FRotator& LandscapeRotation,
		FVector& OutUpAxis,
		FVector& OutForwardAxis,
		FVector& OutRightAxis)
	{
		OutUpAxis = ProbeNormal.GetSafeNormal();
		if (OutUpAxis.IsNearlyZero())
		{
			OutUpAxis = FVector::UpVector;
		}

		FVector ReferenceForward = LandscapeRotation.RotateVector(FVector::ForwardVector).GetSafeNormal();
		if (ReferenceForward.IsNearlyZero())
		{
			ReferenceForward = FVector::ForwardVector;
		}

		OutForwardAxis = (ReferenceForward - FVector::DotProduct(ReferenceForward, OutUpAxis) * OutUpAxis).GetSafeNormal();
		if (OutForwardAxis.IsNearlyZero())
		{
			FVector ReferenceRight = LandscapeRotation.RotateVector(FVector::RightVector).GetSafeNormal();
			if (ReferenceRight.IsNearlyZero())
			{
				ReferenceRight = FVector::RightVector;
			}
			OutForwardAxis = (ReferenceRight - FVector::DotProduct(ReferenceRight, OutUpAxis) * OutUpAxis).GetSafeNormal();
		}

		if (OutForwardAxis.IsNearlyZero())
		{
			const FVector FallbackAxis = (FMath::Abs(OutUpAxis.Z) < 0.99f) ? FVector::UpVector : FVector::ForwardVector;
			OutForwardAxis = FVector::CrossProduct(FallbackAxis, OutUpAxis).GetSafeNormal();
		}
		if (OutForwardAxis.IsNearlyZero())
		{
			OutForwardAxis = FVector::ForwardVector;
		}

		OutRightAxis = FVector::CrossProduct(OutUpAxis, OutForwardAxis).GetSafeNormal();
		if (OutRightAxis.IsNearlyZero())
		{
			const FVector FallbackAxis = (FMath::Abs(OutUpAxis.Z) < 0.99f) ? FVector::ForwardVector : FVector::RightVector;
			OutRightAxis = FVector::CrossProduct(OutUpAxis, FallbackAxis).GetSafeNormal();
		}
		if (OutRightAxis.IsNearlyZero())
		{
			OutRightAxis = FVector::RightVector;
		}

		OutForwardAxis = FVector::CrossProduct(OutRightAxis, OutUpAxis).GetSafeNormal();
		if (OutForwardAxis.IsNearlyZero())
		{
			OutForwardAxis = FVector::ForwardVector;
		}
	}

	bool ProjectProbeDirectionToFaceUV(
		const FVector& Direction,
		const FBelowCanopyProbeFace& Face,
		float& OutU,
		float& OutV)
	{
		const FVector Forward = Face.Forward.GetSafeNormal();
		const FVector Up = Face.Up.GetSafeNormal();
		const FVector Right = FVector::CrossProduct(Up, Forward).GetSafeNormal();
		const float ForwardComponent = FVector::DotProduct(Direction, Forward);
		if (ForwardComponent <= 1.0e-6f)
		{
			return false;
		}

		const float LocalX = FVector::DotProduct(Direction, Right) / ForwardComponent;
		const float LocalY = FVector::DotProduct(Direction, Up) / ForwardComponent;
		OutU = 0.5f * (LocalX + 1.0f);
		OutV = 0.5f * (1.0f - LocalY);
		return OutU >= 0.0f && OutU <= 1.0f && OutV >= 0.0f && OutV <= 1.0f;
	}

	FLinearColor SampleFacePixelsBilinear(
		const TArray<FLinearColor>& Pixels,
		int32 Width,
		int32 Height,
		float U,
		float V)
	{
		if (Width <= 0 || Height <= 0 || Pixels.Num() != Width * Height)
		{
			return FLinearColor::Black;
		}

		const float PixelX = FMath::Clamp(U, 0.0f, 1.0f) * static_cast<float>(Width - 1);
		const float PixelY = FMath::Clamp(V, 0.0f, 1.0f) * static_cast<float>(Height - 1);
		const int32 X0 = FMath::Clamp(FMath::FloorToInt(PixelX), 0, Width - 1);
		const int32 Y0 = FMath::Clamp(FMath::FloorToInt(PixelY), 0, Height - 1);
		const int32 X1 = FMath::Clamp(X0 + 1, 0, Width - 1);
		const int32 Y1 = FMath::Clamp(Y0 + 1, 0, Height - 1);
		const float FracX = PixelX - static_cast<float>(X0);
		const float FracY = PixelY - static_cast<float>(Y0);

		const FLinearColor C00 = Pixels[Y0 * Width + X0];
		const FLinearColor C10 = Pixels[Y0 * Width + X1];
		const FLinearColor C01 = Pixels[Y1 * Width + X0];
		const FLinearColor C11 = Pixels[Y1 * Width + X1];
		const FLinearColor Top = FMath::Lerp(C00, C10, FracX);
		const FLinearColor Bottom = FMath::Lerp(C01, C11, FracX);
		return FMath::Lerp(Top, Bottom, FracY);
	}

	void ConvertFacePixelsToLuminanceGrid(
		const TArray<FLinearColor>& Pixels,
		TArray<float>& OutLuminance)
	{
		OutLuminance.SetNumUninitialized(Pixels.Num());
		for (int32 Index = 0; Index < Pixels.Num(); ++Index)
		{
			OutLuminance[Index] = ComputeRec709LuminanceLinear(Pixels[Index]);
		}
	}

	bool IsValidBelowCanopyForcingTimestamp(const FDateTime& Value)
	{
		return Value.GetTicks() > 0;
	}

	void AddBelowCanopyForcingProvenanceFields(TSharedPtr<FJsonObject>& JsonObject, const FBelowCanopyForcingProvenance& Provenance)
	{
		if (!JsonObject.IsValid())
		{
			return;
		}

		JsonObject->SetStringField(TEXT("ForcingProviderSource"), Provenance.ProviderSelectionLabel);
		JsonObject->SetStringField(TEXT("ForcingProviderClass"), Provenance.ProviderClassName);
		JsonObject->SetStringField(TEXT("ForcingProviderInstance"), Provenance.ProviderInstanceName);
		JsonObject->SetStringField(TEXT("ShortwaveSplitSource"), Provenance.ShortwaveSplitSource);
		JsonObject->SetBoolField(TEXT("UsedBenchmarkOverride"), Provenance.bUsedBenchmarkOverride);
		JsonObject->SetBoolField(TEXT("UsedWeatherProvider"), Provenance.bUsedWeatherProvider);
		JsonObject->SetBoolField(TEXT("UsedCurrentLightFallback"), Provenance.bUsedCurrentLightFallback);
		JsonObject->SetNumberField(TEXT("CosZenith"), Provenance.CosZenith);
		JsonObject->SetNumberField(TEXT("RawSWdownWm2"), Provenance.RawSWdown_Wm2);
		JsonObject->SetBoolField(TEXT("RawSWdownAvailable"), FMath::IsFinite(Provenance.RawSWdown_Wm2) && Provenance.RawSWdown_Wm2 >= 0.0f);
		JsonObject->SetNumberField(TEXT("RawDirectSWdownWm2"), Provenance.RawDirectSWdown_Wm2);
		JsonObject->SetBoolField(TEXT("RawDirectSWdownAvailable"), FMath::IsFinite(Provenance.RawDirectSWdown_Wm2) && Provenance.RawDirectSWdown_Wm2 >= 0.0f);
		JsonObject->SetNumberField(TEXT("RawDiffuseSWdownWm2"), Provenance.RawDiffuseSWdown_Wm2);
		JsonObject->SetBoolField(TEXT("RawDiffuseSWdownAvailable"), FMath::IsFinite(Provenance.RawDiffuseSWdown_Wm2) && Provenance.RawDiffuseSWdown_Wm2 >= 0.0f);
		JsonObject->SetNumberField(TEXT("RawDNI_Wm2"), Provenance.RawDNI_Wm2);
		JsonObject->SetBoolField(TEXT("RawDNIAvailable"), FMath::IsFinite(Provenance.RawDNI_Wm2) && Provenance.RawDNI_Wm2 >= 0.0f);
		JsonObject->SetNumberField(TEXT("RawDHI_Wm2"), Provenance.RawDHI_Wm2);
		JsonObject->SetBoolField(TEXT("RawDHIAvailable"), FMath::IsFinite(Provenance.RawDHI_Wm2) && Provenance.RawDHI_Wm2 >= 0.0f);
		JsonObject->SetNumberField(TEXT("ResolvedDNI_Wm2"), Provenance.ResolvedDNI_Wm2);
		JsonObject->SetNumberField(TEXT("ResolvedDHI_Wm2"), Provenance.ResolvedDHI_Wm2);
		JsonObject->SetNumberField(TEXT("ResolvedDiffuseFraction"), Provenance.ResolvedDiffuseFraction);
		if (IsValidBelowCanopyForcingTimestamp(Provenance.ForcingTimestamp))
		{
			JsonObject->SetStringField(TEXT("ForcingTimestamp"), Provenance.ForcingTimestamp.ToString());
			JsonObject->SetStringField(TEXT("ForcingTimestampIso"), Provenance.ForcingTimestamp.ToIso8601());
		}
	}

	void LogBelowCanopyForcingProvenance(
		const TCHAR* ProductLabel,
		const FDateTime& Time,
		const FBelowCanopyForcingProvenance& Provenance,
		float DirectHorizontalWm2,
		float DiffuseHorizontalWm2)
	{
		UE_LOG(
			LogTemp,
			Display,
			TEXT("[Snow] %s forcing at %s | provider=%s | class=%s | split=%s | rawSW=%.3f | rawDir=%.3f | rawDiff=%.3f | rawDNI=%.3f | rawDHI=%.3f | resolvedDirHoriz=%.3f | resolvedDiffHoriz=%.3f | resolvedDNI=%.3f | resolvedDHI=%.3f | diffuseFrac=%.3f | cosZ=%.4f"),
			ProductLabel,
			*Time.ToString(),
			Provenance.ProviderSelectionLabel.IsEmpty() ? TEXT("Unknown") : *Provenance.ProviderSelectionLabel,
			Provenance.ProviderClassName.IsEmpty() ? TEXT("n/a") : *Provenance.ProviderClassName,
			Provenance.ShortwaveSplitSource.IsEmpty() ? TEXT("Unknown") : *Provenance.ShortwaveSplitSource,
			Provenance.RawSWdown_Wm2,
			Provenance.RawDirectSWdown_Wm2,
			Provenance.RawDiffuseSWdown_Wm2,
			Provenance.RawDNI_Wm2,
			Provenance.RawDHI_Wm2,
			DirectHorizontalWm2,
			DiffuseHorizontalWm2,
			Provenance.ResolvedDNI_Wm2,
			Provenance.ResolvedDHI_Wm2,
			Provenance.ResolvedDiffuseFraction,
			Provenance.CosZenith);
	}

	FRotator MakePerspectiveCaptureRotation(const FVector& Forward, const FVector& Up)
	{
		return FRotationMatrix::MakeFromXZ(Forward.GetSafeNormal(), Up.GetSafeNormal()).Rotator();
	}

	void FlushDeferredRadiationCaptureGpuResources()
	{
		FlushRenderingCommands();
		ENQUEUE_RENDER_COMMAND(FlushDeferredRadiationCaptureGpuResourcesCmd)(
			[](FRHICommandListImmediate& RHICmdList)
			{
				// Release all free pooled render targets so their D3D12 heap
				// allocations can be reclaimed by pool cleanup.
				GRenderTargetPool.FreeUnusedResources();

				// Advance the render-thread frame counter so that D3D12's
				// frame-lag-based pool cleanup (CleanupFreeBlocks, CleanupPages,
				// TransientMemoryCache::GarbageCollect) actually considers our
				// allocations as "old" enough to free.  Without this, the frame
				// counter never advances during synchronous probe capture loops,
				// and all pooled D3D12 heap memory accumulates indefinitely.
				// Precedent: Epic's ReflectionEnvironmentCapture.cpp does this
				// for cubemap capture outside the normal tick.
				GFrameNumberRenderThread++;
				RHICmdList.EndFrame();
			});
		FlushRenderingCommands();
	}

	void ReleaseTransientSceneCaptureTarget(USceneCaptureComponent2D* Capture, UTextureRenderTarget2D* Target)
	{
		if (!Target)
		{
			return;
		}

		if (Capture && Capture->TextureTarget == Target)
		{
			Capture->TextureTarget = nullptr;
			Capture->MarkRenderStateDirty();
		}

		FlushRenderingCommands();
		Target->ReleaseResource();
		FlushDeferredRadiationCaptureGpuResources();
	}

	struct FScopedTransientSceneCaptureTargetRelease
	{
		USceneCaptureComponent2D* Capture = nullptr;
		UTextureRenderTarget2D* Target = nullptr;

		FScopedTransientSceneCaptureTargetRelease(USceneCaptureComponent2D* InCapture, UTextureRenderTarget2D* InTarget)
			: Capture(InCapture)
			, Target(InTarget)
		{
		}

		~FScopedTransientSceneCaptureTargetRelease()
		{
			ReleaseTransientSceneCaptureTarget(Capture, Target);
		}
	};

	double IntegratePerspectiveFaceIrradiance(
		const TArray<FLinearColor>& Pixels,
		int32 Width,
		int32 Height,
		const FVector& FaceForward,
		const FVector& FaceUp,
		const FVector& ReceiverNormal,
		float HorizontalFovDegrees)
	{
		if (Width <= 0 || Height <= 0 || Pixels.Num() != Width * Height)
		{
			return 0.0;
		}

		const FVector Forward = FaceForward.GetSafeNormal();
		const FVector Up = FaceUp.GetSafeNormal();
		const FVector Right = FVector::CrossProduct(Up, Forward).GetSafeNormal();
		const FVector Normal = ReceiverNormal.GetSafeNormal();
		const double TanHalfFov = FMath::Tan(FMath::DegreesToRadians(FMath::Max(1.0f, HorizontalFovDegrees) * 0.5f));
		const double Du = (2.0 * TanHalfFov) / static_cast<double>(Width);
		const double Dv = (2.0 * TanHalfFov) / static_cast<double>(Height);

		double Irradiance = 0.0;
		for (int32 PixelY = 0; PixelY < Height; ++PixelY)
		{
			const double V = (1.0 - (2.0 * (static_cast<double>(PixelY) + 0.5) / static_cast<double>(Height))) * TanHalfFov;
			for (int32 PixelX = 0; PixelX < Width; ++PixelX)
			{
				const double U = (((2.0 * (static_cast<double>(PixelX) + 0.5)) / static_cast<double>(Width)) - 1.0) * TanHalfFov;
				const FVector RayDirection = (Forward + Right * static_cast<float>(U) + Up * static_cast<float>(V)).GetSafeNormal();
				const double CosTheta = FVector::DotProduct(RayDirection, Normal);
				if (CosTheta <= 0.0)
				{
					continue;
				}

				const double SolidAngle = (Du * Dv) / FMath::Pow(1.0 + (U * U) + (V * V), 1.5);
				const int32 LinearIndex = PixelY * Width + PixelX;
				const float Luminance = ComputeRec709LuminanceLinear(Pixels[LinearIndex]);
				if (!FMath::IsFinite(Luminance) || Luminance <= 0.0f)
				{
					continue;
				}

				Irradiance += static_cast<double>(Luminance) * CosTheta * SolidAngle;
			}
		}

		return Irradiance;
	}

	bool IntegrateProbeFaceIrradianceWithCpuReadback(
		UTextureRenderTarget2D* Target,
		int32 Width,
		int32 Height,
		const FVector& FaceForward,
		const FVector& FaceUp,
		const FVector& ReceiverNormal,
		float HorizontalFovDegrees,
		float& OutIrradiance,
		FString* OutFailureReason)
	{
		OutIrradiance = 0.0f;
		if (OutFailureReason)
		{
			OutFailureReason->Empty();
		}

		if (!Target)
		{
			if (OutFailureReason)
			{
				*OutFailureReason = TEXT("Probe render target is unavailable.");
			}
			return false;
		}

		FTextureRenderTargetResource* Resource = Target->GameThread_GetRenderTargetResource();
		if (!Resource)
		{
			if (OutFailureReason)
			{
				*OutFailureReason = TEXT("Probe render-target resource is unavailable.");
			}
			return false;
		}

		FReadSurfaceDataFlags ReadFlags(RCM_MinMax);
		ReadFlags.SetLinearToGamma(false);

		TArray<FLinearColor> Pixels;
		if (!ReadRenderTargetLinearPixels(Target, Resource, Pixels, ReadFlags))
		{
			if (OutFailureReason)
			{
				*OutFailureReason = TEXT("Probe render-target readback failed.");
			}
			return false;
		}

		OutIrradiance = FMath::Max(0.0f, static_cast<float>(IntegratePerspectiveFaceIrradiance(
			Pixels,
			Width,
			Height,
			FaceForward,
			FaceUp,
			ReceiverNormal,
			HorizontalFovDegrees)));
		return true;
	}

	bool IntegrateProbeFaceIrradianceWithGpuReduction(
		UTextureRenderTarget2D* Target,
		int32 Width,
		int32 Height,
		const FVector& FaceForward,
		const FVector& FaceUp,
		const FVector& ReceiverNormal,
		float HorizontalFovDegrees,
		float& OutIrradiance,
		FString* OutFailureReason)
	{
		struct FPendingBelowCanopyProbeFaceGpuIntegration
		{
			TUniquePtr<FRHIGPUBufferReadback> PartialReadback;
			TArray<float> PartialSumsCopy;
			uint32 NumPartialSums = 0u;
			uint32 PartialBytes = 0u;
		};

		const auto EnqueueProbeFaceIrradianceGpuReduction =
			[](
				UTextureRenderTarget2D* InTarget,
				int32 InWidth,
				int32 InHeight,
				const FVector& InFaceForward,
				const FVector& InFaceUp,
				const FVector& InReceiverNormal,
				float InHorizontalFovDegrees,
				FPendingBelowCanopyProbeFaceGpuIntegration& OutPending,
				FString* InOutFailureReason) -> bool
		{
			if (InOutFailureReason)
			{
				InOutFailureReason->Empty();
			}

			OutPending.PartialReadback.Reset();
			OutPending.PartialSumsCopy.Reset();
			OutPending.NumPartialSums = 0u;
			OutPending.PartialBytes = 0u;

			if (!InTarget)
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("Probe render target is unavailable.");
				}
				return false;
			}

			FTextureRenderTargetResource* Resource = InTarget->GameThread_GetRenderTargetResource();
			if (!Resource)
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("Probe render-target resource is unavailable.");
				}
				return false;
			}

			const FTextureRHIRef TextureRHI = Resource->TextureRHI;
			if (!TextureRHI.IsValid())
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("Probe render-target texture handle is invalid.");
				}
				return false;
			}

			const uint32 GroupCountX = FMath::DivideAndRoundUp(static_cast<uint32>(FMath::Max(1, InWidth)), 8u);
			const uint32 GroupCountY = FMath::DivideAndRoundUp(static_cast<uint32>(FMath::Max(1, InHeight)), 8u);
			const uint32 NumPartialSums = GroupCountX * GroupCountY;
			const uint32 PartialBytes = NumPartialSums * sizeof(float);
			if (NumPartialSums == 0u)
			{
				return true;
			}

			OutPending.PartialReadback = MakeUnique<FRHIGPUBufferReadback>(TEXT("BelowCanopyProbeFacePartialReadback"));
			if (!OutPending.PartialReadback)
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("Failed to allocate GPU probe-face readback.");
				}
				return false;
			}

			OutPending.NumPartialSums = NumPartialSums;
			OutPending.PartialBytes = PartialBytes;
			OutPending.PartialSumsCopy.SetNumZeroed(static_cast<int32>(NumPartialSums));

			const FVector SafeForward = InFaceForward.GetSafeNormal();
			const FVector SafeUp = InFaceUp.GetSafeNormal();
			const FVector SafeReceiverNormal = InReceiverNormal.GetSafeNormal().IsNearlyZero()
				? FVector::UpVector
				: InReceiverNormal.GetSafeNormal();
			FRHIGPUBufferReadback* ReadbackPtr = OutPending.PartialReadback.Get();
			ENQUEUE_RENDER_COMMAND(IntegrateBelowCanopyProbeFaceCommand)(
				[TextureRHI,
				 InWidth,
				 InHeight,
				 GroupCountX,
				 GroupCountY,
				 NumPartialSums,
				 PartialBytes,
				 InHorizontalFovDegrees,
				 SafeForward,
				 SafeUp,
				 SafeReceiverNormal,
				 Readback = ReadbackPtr](FRHICommandListImmediate& RHICmdList)
				{
					FRDGBuilder GraphBuilder(RHICmdList);

					FRDGTextureRef RDGTexture = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TextureRHI, TEXT("BelowCanopyProbeFaceTexture")));
					FRDGBufferRef RDGPartialSums = GraphBuilder.CreateBuffer(
						FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumPartialSums),
						TEXT("BelowCanopyProbeFacePartialSums"));

					TShaderMapRef<FBelowCanopyProbeIntegrateCS> Shader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
					FBelowCanopyProbeIntegrateCS::FParameters* Params = GraphBuilder.AllocParameters<FBelowCanopyProbeIntegrateCS::FParameters>();
					Params->TextureDimensions = FUintVector2(InWidth, InHeight);
					Params->NumThreadGroupsX = GroupCountX;
					Params->HorizontalFovDegrees = InHorizontalFovDegrees;
					Params->FaceForwardX = SafeForward.X;
					Params->FaceForwardY = SafeForward.Y;
					Params->FaceForwardZ = SafeForward.Z;
					Params->FaceUpX = SafeUp.X;
					Params->FaceUpY = SafeUp.Y;
					Params->FaceUpZ = SafeUp.Z;
					Params->ReceiverNormalX = SafeReceiverNormal.X;
					Params->ReceiverNormalY = SafeReceiverNormal.Y;
					Params->ReceiverNormalZ = SafeReceiverNormal.Z;
					Params->InputTexture = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDGTexture));
					Params->PartialSums = GraphBuilder.CreateUAV(FRDGBufferUAVDesc(RDGPartialSums));

					FComputeShaderUtils::AddPass(
						GraphBuilder,
						RDG_EVENT_NAME("IntegrateBelowCanopyProbeFace"),
						Shader,
						Params,
						FIntVector(static_cast<int32>(GroupCountX), static_cast<int32>(GroupCountY), 1));

					AddEnqueueCopyPass(GraphBuilder, Readback, RDGPartialSums, PartialBytes);
					GraphBuilder.Execute();
				});

			return true;
		};

		const auto FinalizePendingProbeFaceGpuReductions =
			[](
				FPendingBelowCanopyProbeFaceGpuIntegration* PendingFaces,
				int32 PendingFaceCount,
				TArray<float>& OutIrradiances,
				FString* InOutFailureReason) -> bool
		{
			OutIrradiances.Reset();
			if (InOutFailureReason)
			{
				InOutFailureReason->Empty();
			}

			if (PendingFaceCount <= 0 || !PendingFaces)
			{
				return true;
			}

			FlushRenderingCommands();

			const int32 MaxRetries = 1000;
			int32 Retries = 0;
			auto AreAllReady = [PendingFaces, PendingFaceCount]() -> bool
			{
				for (int32 FaceIndex = 0; FaceIndex < PendingFaceCount; ++FaceIndex)
				{
					const FPendingBelowCanopyProbeFaceGpuIntegration& Pending = PendingFaces[FaceIndex];
					if (Pending.PartialReadback.IsValid() && !Pending.PartialReadback->IsReady())
					{
						return false;
					}
				}
				return true;
			};

			while (!AreAllReady() && Retries < MaxRetries)
			{
				if (Retries == 100 || Retries == 500)
				{
					FlushRenderingCommands();
				}
				FPlatformProcess::Sleep(0.001f);
				++Retries;
			}

			if (!AreAllReady())
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("GPU partial-sum readback batch was not ready after waiting.");
				}
				return false;
			}

			TArray<FRHIGPUBufferReadback*> Readbacks;
			TArray<uint32> PartialBytesList;
			TArray<float*> PartialDataOutputs;
			Readbacks.Reserve(PendingFaceCount);
			PartialBytesList.Reserve(PendingFaceCount);
			PartialDataOutputs.Reserve(PendingFaceCount);
			for (int32 FaceIndex = 0; FaceIndex < PendingFaceCount; ++FaceIndex)
			{
				FPendingBelowCanopyProbeFaceGpuIntegration& Pending = PendingFaces[FaceIndex];
				if (!Pending.PartialReadback.IsValid())
				{
					if (InOutFailureReason)
					{
						*InOutFailureReason = FString::Printf(TEXT("Probe-face batch readback %d is invalid."), FaceIndex);
					}
					return false;
				}

				Readbacks.Add(Pending.PartialReadback.Get());
				PartialBytesList.Add(Pending.PartialBytes);
				PartialDataOutputs.Add(Pending.PartialSumsCopy.GetData());
			}

			bool bReadbackSuccess = true;
			int32 FailedFaceIndex = INDEX_NONE;
			ENQUEUE_RENDER_COMMAND(ReadbackBelowCanopyProbeFacePartialSumsBatch)(
				[Readbacks, PartialBytesList, PartialDataOutputs, &bReadbackSuccess, &FailedFaceIndex](FRHICommandListImmediate& RHICmdList) mutable
				{
					for (int32 FaceIndex = 0; FaceIndex < Readbacks.Num(); ++FaceIndex)
					{
						const void* PartialData = Readbacks[FaceIndex] ? Readbacks[FaceIndex]->Lock(PartialBytesList[FaceIndex]) : nullptr;
						if (PartialData && PartialDataOutputs[FaceIndex])
						{
							FMemory::Memcpy(PartialDataOutputs[FaceIndex], PartialData, PartialBytesList[FaceIndex]);
							Readbacks[FaceIndex]->Unlock();
							continue;
						}

						if (PartialData && Readbacks[FaceIndex])
						{
							Readbacks[FaceIndex]->Unlock();
						}
						bReadbackSuccess = false;
						FailedFaceIndex = FaceIndex;
						break;
					}
				});
			FlushRenderingCommands();

			if (!bReadbackSuccess)
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = FString::Printf(
						TEXT("Failed to lock/copy the GPU partial-sum readback for probe face %d."),
						FailedFaceIndex);
				}
				return false;
			}

			OutIrradiances.SetNumZeroed(PendingFaceCount);
			for (int32 FaceIndex = 0; FaceIndex < PendingFaceCount; ++FaceIndex)
			{
				double IrradianceSum = 0.0;
				const FPendingBelowCanopyProbeFaceGpuIntegration& Pending = PendingFaces[FaceIndex];
				for (uint32 PartialIndex = 0; PartialIndex < Pending.NumPartialSums; ++PartialIndex)
				{
					IrradianceSum += Pending.PartialSumsCopy[static_cast<int32>(PartialIndex)];
				}
				OutIrradiances[FaceIndex] = FMath::Max(0.0f, static_cast<float>(IrradianceSum));
			}

			return true;
		};

		FPendingBelowCanopyProbeFaceGpuIntegration PendingFace;
		if (!EnqueueProbeFaceIrradianceGpuReduction(
			Target,
			Width,
			Height,
			FaceForward,
			FaceUp,
			ReceiverNormal,
			HorizontalFovDegrees,
			PendingFace,
			OutFailureReason))
		{
			return false;
		}

		TArray<float> FaceIrradiances;
		if (!FinalizePendingProbeFaceGpuReductions(&PendingFace, 1, FaceIrradiances, OutFailureReason))
		{
			return false;
		}

		OutIrradiance = FaceIrradiances.Num() > 0 ? FaceIrradiances[0] : 0.0f;
		return true;
	}

	struct FBelowCanopyProbeFaceCaptureDiagnostics
	{
		bool bUsedGpuIntegration = false;
		bool bUsedCpuFallback = false;
		int32 GpuSuccessCount = 0;
		int32 GpuFailureCount = 0;
		int32 CpuFallbackSuccessCount = 0;
		FString FirstGpuFailureReason;
		FString FirstGpuFailureContext;
		FString LastGpuFailureReason;
		FString LastGpuFailureContext;
		TMap<FString, int32> GpuFailureReasonCounts;
	};

	struct FScopedProbeCaptureStateRestore
	{
		USceneCaptureComponent2D* Capture = nullptr;
		FEngineShowFlags SavedShowFlags = FEngineShowFlags(ESFIM_Game);
		UTextureRenderTarget2D* SavedTextureTarget = nullptr;
		ESceneCaptureSource SavedCaptureSource = SCS_FinalColorLDR;
		ECameraProjectionMode::Type SavedProjectionType = ECameraProjectionMode::Perspective;
		float SavedFOV = 90.0f;
		float SavedOrthoWidth = 0.0f;
		bool bSavedCaptureEveryFrame = false;
		bool bSavedCaptureOnMovement = false;
		bool bSavedAlwaysPersistRenderingState = false;
		bool bSavedVisible = false;
		FVector SavedLocation = FVector::ZeroVector;
		FRotator SavedRotation = FRotator::ZeroRotator;

		explicit FScopedProbeCaptureStateRestore(USceneCaptureComponent2D* InCapture)
			: Capture(InCapture)
		{
			if (!Capture)
			{
				return;
			}

			SavedShowFlags = Capture->ShowFlags;
			SavedTextureTarget = Capture->TextureTarget;
			SavedCaptureSource = Capture->CaptureSource;
			SavedProjectionType = Capture->ProjectionType;
			SavedFOV = Capture->FOVAngle;
			SavedOrthoWidth = Capture->OrthoWidth;
			bSavedCaptureEveryFrame = Capture->bCaptureEveryFrame;
			bSavedCaptureOnMovement = Capture->bCaptureOnMovement;
			bSavedAlwaysPersistRenderingState = Capture->bAlwaysPersistRenderingState;
			bSavedVisible = Capture->IsVisible();
			SavedLocation = Capture->GetComponentLocation();
			SavedRotation = Capture->GetComponentRotation();
		}

		~FScopedProbeCaptureStateRestore()
		{
			if (!Capture)
			{
				return;
			}

			Capture->ShowFlags = SavedShowFlags;
			Capture->TextureTarget = SavedTextureTarget;
			Capture->CaptureSource = SavedCaptureSource;
			Capture->ProjectionType = SavedProjectionType;
			Capture->FOVAngle = SavedFOV;
			Capture->OrthoWidth = SavedOrthoWidth;
			Capture->bCaptureEveryFrame = bSavedCaptureEveryFrame;
			Capture->bCaptureOnMovement = bSavedCaptureOnMovement;
			Capture->bAlwaysPersistRenderingState = bSavedAlwaysPersistRenderingState;
			Capture->SetVisibility(bSavedVisible);
			Capture->SetWorldLocationAndRotation(SavedLocation, SavedRotation);
			Capture->MarkRenderStateDirty();
		}
	};

	bool CaptureBelowCanopyProbeIrradianceFaces(
		UWorld* World,
		USceneCaptureComponent2D* Capture,
		UTextureRenderTarget2D* ProbeTarget,
		int32 ProbeResolution,
		const FRotator& LandscapeRotation,
		const FString& CaptureContext,
		const FVector& ProbeOrigin,
		const FVector& ProbeNormal,
		const FEngineShowFlags& ProbeFlags,
		float& OutIrradiance,
		FString& OutFailureReason,
		FBelowCanopyProbeFaceCaptureDiagnostics* OutDiagnostics = nullptr,
		// HPEval-style sky masking outputs (optional; nullptr disables masking)
		float* OutTerrainOnlyIrradiance = nullptr,
		float* OutCosWeightedSkyFraction = nullptr)
	{
		OutIrradiance = 0.0f;
		if (OutTerrainOnlyIrradiance)  { *OutTerrainOnlyIrradiance  = 0.0f; }
		if (OutCosWeightedSkyFraction) { *OutCosWeightedSkyFraction = 0.0f; }
		const bool bComputeSkyMask = (OutTerrainOnlyIrradiance != nullptr || OutCosWeightedSkyFraction != nullptr);
		OutFailureReason.Empty();
		if (!World)
		{
			OutFailureReason = TEXT("World is unavailable for probe capture.");
			return false;
		}
		if (!Capture || !ProbeTarget)
		{
			OutFailureReason = TEXT("Scene capture or probe render target is unavailable.");
			return false;
		}

		double IrradianceSum = 0.0;
		FVector ProbeUpAxis = FVector::UpVector;
		FVector ProbeForwardAxis = FVector::ForwardVector;
		FVector ProbeRightAxis = FVector::RightVector;
		BuildBelowCanopyProbeFrame(ProbeNormal, LandscapeRotation, ProbeUpAxis, ProbeForwardAxis, ProbeRightAxis);
		const FBelowCanopyProbeFace ProbeFaces[] =
		{
			{ TEXT("Up"), ProbeUpAxis, ProbeForwardAxis },
			{ TEXT("Forward"), ProbeForwardAxis, ProbeUpAxis },
			{ TEXT("Backward"), -ProbeForwardAxis, ProbeUpAxis },
			{ TEXT("Right"), ProbeRightAxis, ProbeUpAxis },
			{ TEXT("Left"), -ProbeRightAxis, ProbeUpAxis }
		};

		Capture->ShowFlags = ProbeFlags;
		Capture->TextureTarget = ProbeTarget;
		Capture->MarkRenderStateDirty();

		struct FPendingBelowCanopyProbeFaceGpuIntegrationBatch
		{
			// Integration outputs
			TUniquePtr<FRHIGPUBufferReadback> PartialReadback;
			TArray<float> PartialSumsCopy;
			uint32 NumPartialSums = 0u;
			uint32 PartialBytes = 0u;

			// Terrain / sky-fraction outputs (HPEval sky mask)
			TUniquePtr<FRHIGPUBufferReadback> TerrainReadback;
			TArray<float> TerrainSumsCopy;
			TUniquePtr<FRHIGPUBufferReadback> SkyFractionReadback;
			TArray<float> SkyFractionSumsCopy;

		};

		// Single-capture three-dispatch design:
		//   Dispatch 1 (FBelowCanopyProbeFaceStatsCS)   – per-group luminance stats
		//   Dispatch 2 (FBelowCanopyProbeThresholdCS)   – reduce stats → one threshold float
		//   Dispatch 3 (FBelowCanopyProbeIntegrateCS)   – cosine-weighted integration w/ sky mask
		// All three run in one ENQUEUE_RENDER_COMMAND on the same captured texture.
		// No re-capture, no CPU stall for the threshold value.
		const auto EnqueuePendingProbeFace =
			[](
				UTextureRenderTarget2D* InTarget,
				int32 InResolution,
				const FVector& InFaceForward,
				const FVector& InFaceUp,
				const FVector& InReceiverNormal,
				bool bInComputeSkyMask,
				FPendingBelowCanopyProbeFaceGpuIntegrationBatch& OutPending,
				FString* InOutFailureReason) -> bool
		{
			if (InOutFailureReason)
			{
				InOutFailureReason->Empty();
			}

			OutPending.PartialReadback.Reset();
			OutPending.PartialSumsCopy.Reset();
			OutPending.TerrainReadback.Reset();
			OutPending.TerrainSumsCopy.Reset();
			OutPending.SkyFractionReadback.Reset();
			OutPending.SkyFractionSumsCopy.Reset();
			OutPending.NumPartialSums = 0u;
			OutPending.PartialBytes = 0u;

			if (!InTarget)
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("Probe render target is unavailable.");
				}
				return false;
			}

			FTextureRenderTargetResource* Resource = InTarget->GameThread_GetRenderTargetResource();
			if (!Resource)
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("Probe render-target resource is unavailable.");
				}
				return false;
			}

			const FTextureRHIRef TextureRHI = Resource->TextureRHI;
			if (!TextureRHI.IsValid())
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("Probe render-target texture handle is invalid.");
				}
				return false;
			}

			const uint32 GroupCountX = FMath::DivideAndRoundUp(static_cast<uint32>(FMath::Max(1, InResolution)), 8u);
			const uint32 GroupCountY = FMath::DivideAndRoundUp(static_cast<uint32>(FMath::Max(1, InResolution)), 8u);
			const uint32 NumPartialSums = GroupCountX * GroupCountY;
			const uint32 PartialBytes = NumPartialSums * sizeof(float);
			if (NumPartialSums == 0u)
			{
				return true;
			}

			OutPending.PartialReadback = MakeUnique<FRHIGPUBufferReadback>(TEXT("BelowCanopyProbeFacePartialReadback"));
			if (!OutPending.PartialReadback)
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("Failed to allocate GPU probe-face readback.");
				}
				return false;
			}

			OutPending.NumPartialSums = NumPartialSums;
			OutPending.PartialBytes = PartialBytes;
			OutPending.PartialSumsCopy.SetNumZeroed(static_cast<int32>(NumPartialSums));

			if (bInComputeSkyMask)
			{
				OutPending.TerrainReadback = MakeUnique<FRHIGPUBufferReadback>(TEXT("BelowCanopyProbeFaceTerrainReadback"));
				OutPending.SkyFractionReadback = MakeUnique<FRHIGPUBufferReadback>(TEXT("BelowCanopyProbeFaceSkyFractionReadback"));
				if (!OutPending.TerrainReadback || !OutPending.SkyFractionReadback)
				{
					// Non-fatal: fall back to no sky masking for this probe
					OutPending.TerrainReadback.Reset();
					OutPending.SkyFractionReadback.Reset();
				}
				else
				{
					OutPending.TerrainSumsCopy.SetNumZeroed(static_cast<int32>(NumPartialSums));
					OutPending.SkyFractionSumsCopy.SetNumZeroed(static_cast<int32>(NumPartialSums));
				}
			}

			const FVector SafeForward = InFaceForward.GetSafeNormal();
			const FVector SafeUp = InFaceUp.GetSafeNormal();
			const FVector SafeReceiverNormal = InReceiverNormal.GetSafeNormal().IsNearlyZero()
				? FVector::UpVector
				: InReceiverNormal.GetSafeNormal();

			FRHIGPUBufferReadback* ReadbackPtr = OutPending.PartialReadback.Get();
			FRHIGPUBufferReadback* TerrainReadbackPtr = OutPending.TerrainReadback.Get();
			FRHIGPUBufferReadback* SkyFracReadbackPtr = OutPending.SkyFractionReadback.Get();
			const bool bHasSkyMaskReadbacks = (TerrainReadbackPtr != nullptr && SkyFracReadbackPtr != nullptr);

			ENQUEUE_RENDER_COMMAND(IntegrateBelowCanopyProbeFaceCommand)(
				[TextureRHI,
				 InResolution,
				 GroupCountX,
				 GroupCountY,
				 NumPartialSums,
				 PartialBytes,
				 SafeForward,
				 SafeUp,
				 SafeReceiverNormal,
				 bHasSkyMaskReadbacks,
				 Readback = ReadbackPtr,
				 TerrainReadback = TerrainReadbackPtr,
				 SkyFracReadback = SkyFracReadbackPtr](FRHICommandListImmediate& RHICmdList)
				{
					FRDGBuilder GraphBuilder(RHICmdList);

					// ── Shared texture ──────────────────────────────────────────────────────
					FRDGTextureRef RDGTexture = GraphBuilder.RegisterExternalTexture(
						CreateRenderTarget(TextureRHI, TEXT("BelowCanopyProbeFaceTexture")));

					// ── Output buffers ──────────────────────────────────────────────────────
					FRDGBufferRef RDGPartialSums = GraphBuilder.CreateBuffer(
						FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumPartialSums),
						TEXT("BelowCanopyProbeFacePartialSums"));
					FRDGBufferRef RDGTerrainSums = GraphBuilder.CreateBuffer(
						FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumPartialSums),
						TEXT("BelowCanopyProbeFaceTerrainSums"));
					FRDGBufferRef RDGSkyFracSums = GraphBuilder.CreateBuffer(
						FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumPartialSums),
						TEXT("BelowCanopyProbeFaceSkyFracSums"));

					// ── Dispatch 1: per-group luminance stats ───────────────────────────────
					// Always needed when sky masking is requested; threshold buffer is still
					// created either way so Dispatch 3 always has a valid SRV.
					const uint32 NumGroups = NumPartialSums; // GroupCountX * GroupCountY
					FRDGBufferRef RDGStats = GraphBuilder.CreateBuffer(
						FRDGBufferDesc::CreateStructuredDesc(sizeof(FVector2f), NumGroups),
						TEXT("BelowCanopyProbeFaceStats"));
					FRDGBufferRef RDGThreshold = GraphBuilder.CreateBuffer(
						FRDGBufferDesc::CreateStructuredDesc(sizeof(float), 1),
						TEXT("BelowCanopyProbeSkyThreshold"));

					if (bHasSkyMaskReadbacks)
					{
						TShaderMapRef<FBelowCanopyProbeFaceStatsCS> StatsShader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
						FBelowCanopyProbeFaceStatsCS::FParameters* StatsParams =
							GraphBuilder.AllocParameters<FBelowCanopyProbeFaceStatsCS::FParameters>();
						StatsParams->TextureDimensions = FUintVector2(InResolution, InResolution);
						StatsParams->NumThreadGroupsX  = GroupCountX;
						StatsParams->InputTexture       = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDGTexture));
						StatsParams->OutStats           = GraphBuilder.CreateUAV(FRDGBufferUAVDesc(RDGStats));
						FComputeShaderUtils::AddPass(GraphBuilder, RDG_EVENT_NAME("BelowCanopyProbeFaceStats"),
							StatsShader, StatsParams,
							FIntVector(static_cast<int32>(GroupCountX), static_cast<int32>(GroupCountY), 1));

						// ── Dispatch 2: reduce stats → single threshold float ───────────────
						TShaderMapRef<FBelowCanopyProbeThresholdCS> ThresholdShader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
						FBelowCanopyProbeThresholdCS::FParameters* ThreshParams =
							GraphBuilder.AllocParameters<FBelowCanopyProbeThresholdCS::FParameters>();
						ThreshParams->NumStats         = NumGroups;
						ThreshParams->ThresholdFraction = 0.50f;  // threshold = globalMax * 0.50; sky is always the brightest
						ThreshParams->InStats           = GraphBuilder.CreateSRV(FRDGBufferSRVDesc(RDGStats));
						ThreshParams->OutThreshold      = GraphBuilder.CreateUAV(FRDGBufferUAVDesc(RDGThreshold));
						FComputeShaderUtils::AddPass(GraphBuilder, RDG_EVENT_NAME("BelowCanopyProbeThreshold"),
							ThresholdShader, ThreshParams,
							FIntVector(1, 1, 1));
					}
					else
					{
						// Sky masking disabled — zero-init threshold buffer so the SRV is valid
						AddClearUAVPass(GraphBuilder,
							GraphBuilder.CreateUAV(FRDGBufferUAVDesc(RDGThreshold)), 0u);
					}

					// ── Dispatch 3: cosine-weighted integration ─────────────────────────────
					TShaderMapRef<FBelowCanopyProbeIntegrateCS> IntegrateShader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
					FBelowCanopyProbeIntegrateCS::FParameters* Params =
						GraphBuilder.AllocParameters<FBelowCanopyProbeIntegrateCS::FParameters>();
					Params->TextureDimensions   = FUintVector2(InResolution, InResolution);
					Params->NumThreadGroupsX    = GroupCountX;
					Params->HorizontalFovDegrees = 90.0f;
					Params->FaceForwardX         = SafeForward.X;
					Params->FaceForwardY         = SafeForward.Y;
					Params->FaceForwardZ         = SafeForward.Z;
					Params->FaceUpX              = SafeUp.X;
					Params->FaceUpY              = SafeUp.Y;
					Params->FaceUpZ              = SafeUp.Z;
					Params->ReceiverNormalX      = SafeReceiverNormal.X;
					Params->ReceiverNormalY      = SafeReceiverNormal.Y;
					Params->ReceiverNormalZ      = SafeReceiverNormal.Z;
					Params->bUseSkyMask          = bHasSkyMaskReadbacks ? 1u : 0u;
					Params->SkyThresholdBuffer   = GraphBuilder.CreateSRV(FRDGBufferSRVDesc(RDGThreshold));
					Params->InputTexture          = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDGTexture));
					Params->PartialSums           = GraphBuilder.CreateUAV(FRDGBufferUAVDesc(RDGPartialSums));
					Params->TerrainPartialSums    = GraphBuilder.CreateUAV(FRDGBufferUAVDesc(RDGTerrainSums));
					Params->SkyFractionPartialSums = GraphBuilder.CreateUAV(FRDGBufferUAVDesc(RDGSkyFracSums));
					FComputeShaderUtils::AddPass(
						GraphBuilder,
						RDG_EVENT_NAME("IntegrateBelowCanopyProbeFace"),
						IntegrateShader,
						Params,
						FIntVector(static_cast<int32>(GroupCountX), static_cast<int32>(GroupCountY), 1));

					AddEnqueueCopyPass(GraphBuilder, Readback, RDGPartialSums, PartialBytes);
					if (bHasSkyMaskReadbacks)
					{
						AddEnqueueCopyPass(GraphBuilder, TerrainReadback, RDGTerrainSums, PartialBytes);
						AddEnqueueCopyPass(GraphBuilder, SkyFracReadback, RDGSkyFracSums, PartialBytes);
					}
					GraphBuilder.Execute();
				});

			return true;
		};

			const auto FinalizePendingProbeFaces =
			[](
				FPendingBelowCanopyProbeFaceGpuIntegrationBatch* PendingFaces,
				int32 PendingFaceCount,
				TArray<float>& OutFaceIrradiances,
				TArray<float>* OutFaceTerrainIrradiances,
				TArray<float>* OutFaceSkyFractions,
				FString* InOutFailureReason) -> bool
		{
			OutFaceIrradiances.Reset();
			if (OutFaceTerrainIrradiances) { OutFaceTerrainIrradiances->Reset(); }
			if (OutFaceSkyFractions)       { OutFaceSkyFractions->Reset(); }
			if (InOutFailureReason)
			{
				InOutFailureReason->Empty();
			}

			if (PendingFaceCount <= 0 || !PendingFaces)
			{
				return true;
			}

			FlushRenderingCommands();

			const int32 MaxRetries = 1000;
			int32 Retries = 0;
			auto AreAllReady = [PendingFaces, PendingFaceCount]() -> bool
			{
				for (int32 FaceIndex = 0; FaceIndex < PendingFaceCount; ++FaceIndex)
				{
					const FPendingBelowCanopyProbeFaceGpuIntegrationBatch& Pending = PendingFaces[FaceIndex];
					if (Pending.PartialReadback.IsValid() && !Pending.PartialReadback->IsReady())   { return false; }
					if (Pending.TerrainReadback.IsValid() && !Pending.TerrainReadback->IsReady())   { return false; }
					if (Pending.SkyFractionReadback.IsValid() && !Pending.SkyFractionReadback->IsReady()) { return false; }
				}
				return true;
			};

			while (!AreAllReady() && Retries < MaxRetries)
			{
				if (Retries == 100 || Retries == 500)
				{
					FlushRenderingCommands();
				}
				FPlatformProcess::Sleep(0.001f);
				++Retries;
			}

			if (!AreAllReady())
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = TEXT("GPU partial-sum readback batch was not ready after waiting.");
				}
				return false;
			}

			// Batch lock/copy for all three buffer types
			struct FReadbackCopyEntry { FRHIGPUBufferReadback* Readback; float* Dst; uint32 Bytes; };
			TArray<FReadbackCopyEntry> CopyEntries;
			CopyEntries.Reserve(PendingFaceCount * 3);
			for (int32 FaceIndex = 0; FaceIndex < PendingFaceCount; ++FaceIndex)
			{
				FPendingBelowCanopyProbeFaceGpuIntegrationBatch& Pending = PendingFaces[FaceIndex];
				if (!Pending.PartialReadback.IsValid())
				{
					if (InOutFailureReason)
					{
						*InOutFailureReason = FString::Printf(TEXT("Probe-face batch readback %d is invalid."), FaceIndex);
					}
					return false;
				}
				CopyEntries.Add({ Pending.PartialReadback.Get(), Pending.PartialSumsCopy.GetData(), Pending.PartialBytes });
				if (Pending.TerrainReadback.IsValid())
				{
					CopyEntries.Add({ Pending.TerrainReadback.Get(), Pending.TerrainSumsCopy.GetData(), Pending.PartialBytes });
				}
				if (Pending.SkyFractionReadback.IsValid())
				{
					CopyEntries.Add({ Pending.SkyFractionReadback.Get(), Pending.SkyFractionSumsCopy.GetData(), Pending.PartialBytes });
				}
			}

			bool bReadbackSuccess = true;
			int32 FailedIndex = INDEX_NONE;
			ENQUEUE_RENDER_COMMAND(ReadbackBelowCanopyProbeFacePartialSumsBatch)(
				[CopyEntries, &bReadbackSuccess, &FailedIndex](FRHICommandListImmediate& RHICmdList) mutable
				{
					for (int32 Idx = 0; Idx < CopyEntries.Num(); ++Idx)
					{
						auto& Entry = CopyEntries[Idx];
						const void* Data = Entry.Readback ? Entry.Readback->Lock(Entry.Bytes) : nullptr;
						if (Data && Entry.Dst)
						{
							FMemory::Memcpy(Entry.Dst, Data, Entry.Bytes);
							Entry.Readback->Unlock();
							continue;
						}
						if (Data && Entry.Readback) { Entry.Readback->Unlock(); }
						bReadbackSuccess = false;
						FailedIndex = Idx;
						break;
					}
				});
			FlushRenderingCommands();

			if (!bReadbackSuccess)
			{
				if (InOutFailureReason)
				{
					*InOutFailureReason = FString::Printf(
						TEXT("Failed to lock/copy the GPU partial-sum readback entry %d."),
						FailedIndex);
				}
				return false;
			}

			OutFaceIrradiances.SetNumZeroed(PendingFaceCount);
			if (OutFaceTerrainIrradiances) { OutFaceTerrainIrradiances->SetNumZeroed(PendingFaceCount); }
			if (OutFaceSkyFractions)       { OutFaceSkyFractions->SetNumZeroed(PendingFaceCount); }

			for (int32 FaceIndex = 0; FaceIndex < PendingFaceCount; ++FaceIndex)
			{
				const FPendingBelowCanopyProbeFaceGpuIntegrationBatch& Pending = PendingFaces[FaceIndex];
				double IrradianceSum = 0.0, TerrainSum = 0.0, SkyFracSum = 0.0;
				for (uint32 Pi = 0; Pi < Pending.NumPartialSums; ++Pi)
				{
					IrradianceSum += Pending.PartialSumsCopy[static_cast<int32>(Pi)];
					if (Pending.TerrainSumsCopy.IsValidIndex(static_cast<int32>(Pi)))
					{
						TerrainSum  += Pending.TerrainSumsCopy[static_cast<int32>(Pi)];
						SkyFracSum  += Pending.SkyFractionSumsCopy[static_cast<int32>(Pi)];
					}
				}
				OutFaceIrradiances[FaceIndex] = FMath::Max(0.0f, static_cast<float>(IrradianceSum));
				if (OutFaceTerrainIrradiances)
				{
					(*OutFaceTerrainIrradiances)[FaceIndex] = FMath::Max(0.0f, static_cast<float>(TerrainSum));
				}
				if (OutFaceSkyFractions)
				{
					(*OutFaceSkyFractions)[FaceIndex] = FMath::Max(0.0f, static_cast<float>(SkyFracSum));
				}
			}

			return true;
		};

		constexpr int32 NumProbeFaces = UE_ARRAY_COUNT(ProbeFaces);
		FPendingBelowCanopyProbeFaceGpuIntegrationBatch PendingFaces[NumProbeFaces];
		bool bBatchedGpuPathSucceeded = true;
		FString BatchedGpuFailureReason;

		// Single-capture loop: stats + threshold + integration in one RDG graph per face.
		for (int32 FaceIndex = 0; FaceIndex < NumProbeFaces; ++FaceIndex)
		{
			const FBelowCanopyProbeFace& Face = ProbeFaces[FaceIndex];
			Capture->SetWorldLocationAndRotation(
				ProbeOrigin,
				MakePerspectiveCaptureRotation(Face.Forward, Face.Up));

			World->SendAllEndOfFrameUpdates();
			Capture->CaptureScene();

			if (!EnqueuePendingProbeFace(
				ProbeTarget,
				ProbeResolution,
				Face.Forward,
				Face.Up,
				ProbeUpAxis,
				bComputeSkyMask,
				PendingFaces[FaceIndex],
				&BatchedGpuFailureReason))
			{
				bBatchedGpuPathSucceeded = false;
				break;
			}
		}

		TArray<float> BatchedGpuFaceIrradiances;
		TArray<float> BatchedGpuFaceTerrainIrradiances;
		TArray<float> BatchedGpuFaceSkyFractions;
		if (bBatchedGpuPathSucceeded)
		{
			bBatchedGpuPathSucceeded = FinalizePendingProbeFaces(
				PendingFaces,
				NumProbeFaces,
				BatchedGpuFaceIrradiances,
				bComputeSkyMask ? &BatchedGpuFaceTerrainIrradiances : nullptr,
				bComputeSkyMask ? &BatchedGpuFaceSkyFractions : nullptr,
				&BatchedGpuFailureReason);
		}

		if (bBatchedGpuPathSucceeded && BatchedGpuFaceIrradiances.Num() == NumProbeFaces)
		{
			if (OutDiagnostics)
			{
				OutDiagnostics->bUsedGpuIntegration = true;
				OutDiagnostics->GpuSuccessCount += NumProbeFaces;
			}
			double TerrainIrradianceSum = 0.0;
			double SkyFractionWeightSum = 0.0;
			double TotalCosWeightSum = 0.0;
			for (int32 Fi = 0; Fi < NumProbeFaces; ++Fi)
			{
				IrradianceSum += BatchedGpuFaceIrradiances[Fi];
				if (bComputeSkyMask)
				{
					TerrainIrradianceSum += BatchedGpuFaceTerrainIrradiances[Fi];
					SkyFractionWeightSum += BatchedGpuFaceSkyFractions[Fi];
					TotalCosWeightSum    += BatchedGpuFaceIrradiances[Fi]; // denominator for SVF
				}
			}

			OutIrradiance = FMath::Max(0.0f, static_cast<float>(IrradianceSum));
			if (OutTerrainOnlyIrradiance)
			{
				*OutTerrainOnlyIrradiance = FMath::Max(0.0f, static_cast<float>(TerrainIrradianceSum));
			}
			if (OutCosWeightedSkyFraction)
			{
				// SkyFraction = cosine-weighted sky pixel integral / total cosine-weighted hemisphere integral
				// (equivalent to SVF derived from the same captures)
				*OutCosWeightedSkyFraction = (TotalCosWeightSum > 1.0e-12)
					? FMath::Clamp(static_cast<float>(SkyFractionWeightSum / TotalCosWeightSum), 0.0f, 1.0f)
					: 0.0f;
			}
			return true;
		}

		FlushRenderingCommands();
		const FString EffectiveBatchFailureReason = BatchedGpuFailureReason.IsEmpty()
			? TEXT("unknown failure")
			: BatchedGpuFailureReason;
		const FString EffectiveBatchFailureContext = FString::Printf(TEXT("%s/BatchedFaces"), *CaptureContext);
		if (OutDiagnostics)
		{
			OutDiagnostics->bUsedCpuFallback = true;
			OutDiagnostics->GpuFailureCount += NumProbeFaces;
			if (OutDiagnostics->FirstGpuFailureReason.IsEmpty())
			{
				OutDiagnostics->FirstGpuFailureReason = EffectiveBatchFailureReason;
				OutDiagnostics->FirstGpuFailureContext = EffectiveBatchFailureContext;
			}
			OutDiagnostics->LastGpuFailureReason = EffectiveBatchFailureReason;
			OutDiagnostics->LastGpuFailureContext = EffectiveBatchFailureContext;
			OutDiagnostics->GpuFailureReasonCounts.FindOrAdd(EffectiveBatchFailureReason) += NumProbeFaces;
		}
		UE_LOG(
			LogTemp,
			Warning,
			TEXT("[Snow] Below-canopy probe-face batched GPU integration failed at %s; recapturing with CPU readback (%s)."),
			*EffectiveBatchFailureContext,
			*EffectiveBatchFailureReason);

		for (const FBelowCanopyProbeFace& Face : ProbeFaces)
		{
			Capture->SetWorldLocationAndRotation(
				ProbeOrigin,
				MakePerspectiveCaptureRotation(Face.Forward, Face.Up));

			World->SendAllEndOfFrameUpdates();
			Capture->CaptureScene();

			float FaceIrradiance = 0.0f;
			FString FaceFailureReason;
			if (!IntegrateProbeFaceIrradianceWithCpuReadback(
				ProbeTarget,
				ProbeResolution,
				ProbeResolution,
				Face.Forward,
				Face.Up,
				ProbeUpAxis,
				90.0f,
				FaceIrradiance,
				&FaceFailureReason))
			{
				OutFailureReason = FaceFailureReason.IsEmpty()
					? TEXT("Probe render-target CPU fallback integration failed.")
					: FaceFailureReason;
				return false;
			}

			if (OutDiagnostics)
			{
				++OutDiagnostics->CpuFallbackSuccessCount;
			}
			IrradianceSum += FaceIrradiance;
		}

		OutIrradiance = FMath::Max(0.0f, static_cast<float>(IrradianceSum));
		return true;
	}

	void BuildSparseProbeAxis(int32 Dimension, int32 SpacingCells, TArray<int32>& OutCoords)
	{
		OutCoords.Reset();
		if (Dimension <= 0)
		{
			return;
		}

		const int32 SafeSpacing = FMath::Max(1, SpacingCells);
		for (int32 Coord = 0; Coord < Dimension; Coord += SafeSpacing)
		{
			OutCoords.Add(Coord);
		}

		const int32 LastCoord = Dimension - 1;
		if (OutCoords.Num() == 0 || OutCoords.Last() != LastCoord)
		{
			OutCoords.Add(LastCoord);
		}
	}

	void BuildSparseProbeAxisInRange(int32 Dimension, int32 MinCoord, int32 MaxCoord, int32 SpacingCells, TArray<int32>& OutCoords)
	{
		OutCoords.Reset();
		if (Dimension <= 0)
		{
			return;
		}

		const int32 ClampedMin = FMath::Clamp(FMath::Min(MinCoord, MaxCoord), 0, Dimension - 1);
		const int32 ClampedMax = FMath::Clamp(FMath::Max(MinCoord, MaxCoord), 0, Dimension - 1);
		const int32 SafeSpacing = FMath::Max(1, SpacingCells);
		for (int32 Coord = ClampedMin; Coord <= ClampedMax; Coord += SafeSpacing)
		{
			OutCoords.Add(Coord);
		}

		if (OutCoords.Num() == 0 || OutCoords.Last() != ClampedMax)
		{
			OutCoords.Add(ClampedMax);
		}
	}

	int32 FindSparseProbeLowerIndex(const TArray<int32>& Coords, int32 TargetCoord)
	{
		if (Coords.Num() <= 1)
		{
			return 0;
		}

		for (int32 Index = 0; Index < Coords.Num() - 1; ++Index)
		{
			if (TargetCoord <= Coords[Index + 1])
			{
				return Index;
			}
		}

		return Coords.Num() - 2;
	}

	void BilinearExpandSparseGrid(
		const TArray<int32>& SampleXs,
		const TArray<int32>& SampleYs,
		const TArray<float>& SparseValues,
		int32 FullWidth,
		int32 FullHeight,
		TArray<float>& OutValues)
	{
		OutValues.SetNumZeroed(FullWidth * FullHeight);
		if (FullWidth <= 0 || FullHeight <= 0
			|| SampleXs.Num() == 0
			|| SampleYs.Num() == 0
			|| SparseValues.Num() != SampleXs.Num() * SampleYs.Num())
		{
			return;
		}

		for (int32 Y = 0; Y < FullHeight; ++Y)
		{
			const int32 Y0Index = FindSparseProbeLowerIndex(SampleYs, Y);
			const int32 Y1Index = FMath::Min(Y0Index + 1, SampleYs.Num() - 1);
			const int32 Y0 = SampleYs[Y0Index];
			const int32 Y1 = SampleYs[Y1Index];
			const float Ty = (Y1 > Y0) ? static_cast<float>(Y - Y0) / static_cast<float>(Y1 - Y0) : 0.0f;

			for (int32 X = 0; X < FullWidth; ++X)
			{
				const int32 X0Index = FindSparseProbeLowerIndex(SampleXs, X);
				const int32 X1Index = FMath::Min(X0Index + 1, SampleXs.Num() - 1);
				const int32 X0 = SampleXs[X0Index];
				const int32 X1 = SampleXs[X1Index];
				const float Tx = (X1 > X0) ? static_cast<float>(X - X0) / static_cast<float>(X1 - X0) : 0.0f;

				const float V00 = SparseValues[Y0Index * SampleXs.Num() + X0Index];
				const float V10 = SparseValues[Y0Index * SampleXs.Num() + X1Index];
				const float V01 = SparseValues[Y1Index * SampleXs.Num() + X0Index];
				const float V11 = SparseValues[Y1Index * SampleXs.Num() + X1Index];

				const float V0 = FMath::Lerp(V00, V10, Tx);
				const float V1 = FMath::Lerp(V01, V11, Tx);
				OutValues[Y * FullWidth + X] = FMath::Lerp(V0, V1, Ty);
			}
		}
	}

	struct FGeometryRayTracingRay
	{
		float Origin[3];
		uint32 Mask = 0xFFFFFFFFu;
		float Direction[3];
		float TFar = 0.0f;
	};

	static_assert(sizeof(FGeometryRayTracingRay) == 32, "FGeometryRayTracingRay must match FBasicRayData layout.");

	struct FGeometryRayTracingDispatchState
	{
		TArray<uint32> Results;
		FString FailureReason;
		bool bSuccess = false;
	};

#if RHI_RAYTRACING
	struct FGeometryRayTracingPipeline
	{
		FRayTracingPipelineState* PipelineState = nullptr;
		FShaderBindingTableRHIRef SBT;
		TShaderRef<FGeometryRayTracingOcclusionRGS> OcclusionRGS;
		TShaderRef<FGeometryRayTracingIntersectionRGS> IntersectionRGS;
	};
#endif

	constexpr float DiffuseNoGIReferenceAbsoluteFloor = 1.0e-4f;
	constexpr float DiffuseNoGIReferenceRelativeFloor = 1.0e-2f;
	constexpr float DiffuseNoGIReferenceMinTotalFraction = 1.0e-2f;
	constexpr int32 GeometryRayTracingMaxBatchRays = 1000000;

	float RadicalInverseVanDerCorput(uint32 Bits)
	{
		Bits = (Bits << 16) | (Bits >> 16);
		Bits = ((Bits & 0x55555555u) << 1) | ((Bits & 0xAAAAAAAAu) >> 1);
		Bits = ((Bits & 0x33333333u) << 2) | ((Bits & 0xCCCCCCCCu) >> 2);
		Bits = ((Bits & 0x0F0F0F0Fu) << 4) | ((Bits & 0xF0F0F0F0u) >> 4);
		Bits = ((Bits & 0x00FF00FFu) << 8) | ((Bits & 0xFF00FF00u) >> 8);
		return static_cast<float>(static_cast<double>(Bits) * 2.3283064365386963e-10);
	}

	int32 ResolveSVFGpuHemisphereSampleCount(int32 RequestedAzimuthSampleCount)
	{
		// GPU SVF uses direct hemispherical visibility sampling rather than CPU horizon binary searches.
		// Clamp the sample budget so the backend stays predictable even when the CPU path is configured
		// with very high azimuth counts for offline-quality tracing.
		return FMath::Clamp(FMath::Max(32, RequestedAzimuthSampleCount * 2), 32, 128);
	}

	FVector GenerateSVFGpuSampleDirection(int32 SampleIndex, int32 SampleCount)
	{
		const float U = (static_cast<float>(SampleIndex) + 0.5f) / static_cast<float>(FMath::Max(1, SampleCount));
		const float V = RadicalInverseVanDerCorput(static_cast<uint32>(SampleIndex));
		const float Radius = FMath::Sqrt(FMath::Clamp(U, 0.0f, 1.0f));
		const float Phi = 2.0f * PI * V;
		const float X = Radius * FMath::Cos(Phi);
		const float Y = Radius * FMath::Sin(Phi);
		const float Z = FMath::Sqrt(FMath::Max(0.0f, 1.0f - U));
		return FVector(X, Y, Z).GetSafeNormal();
	}

	bool HasGeometryRayTracingScene(UWorld* World)
	{
#if !RHI_RAYTRACING
		return false;
#else
		return World && World->Scene && UE::FXRenderingUtils::RayTracing::HasRayTracingScene(World->Scene);
#endif
	}

#if RHI_RAYTRACING
	bool BuildGeometryRayTracingPipeline(
		FRHICommandList& RHICmdList,
		FGeometryRayTracingPipeline& OutPipeline,
		FString& OutFailureReason)
	{
		FGlobalShaderMap* ShaderMap = GetGlobalShaderMap(GMaxRHIFeatureLevel);
		if (!ShaderMap)
		{
			OutFailureReason = TEXT("Failed to resolve the global shader map for ray tracing.");
			return false;
		}

		FRayTracingPipelineStateInitializer PipelineInitializer;

		OutPipeline.OcclusionRGS = ShaderMap->GetShader<FGeometryRayTracingOcclusionRGS>();
		OutPipeline.IntersectionRGS = ShaderMap->GetShader<FGeometryRayTracingIntersectionRGS>();
		FRHIRayTracingShader* RayGenShaderTable[] =
		{
			OutPipeline.OcclusionRGS.GetRayTracingShader(),
			OutPipeline.IntersectionRGS.GetRayTracingShader()
		};
		PipelineInitializer.SetRayGenShaderTable(RayGenShaderTable);

		const TShaderRef<FGeometryRayTracingIntersectionCHS> ClosestHitShader = ShaderMap->GetShader<FGeometryRayTracingIntersectionCHS>();
		FRHIRayTracingShader* HitShaderTable[] = { ClosestHitShader.GetRayTracingShader() };
		PipelineInitializer.SetHitGroupTable(HitShaderTable);

		const TShaderRef<FDefaultPayloadMS> MissShader = ShaderMap->GetShader<FDefaultPayloadMS>();
		FRHIRayTracingShader* MissShaderTable[] = { MissShader.GetRayTracingShader() };
		PipelineInitializer.SetMissShaderTable(MissShaderTable);

		FRayTracingShaderBindingTableInitializer SBTInitializer;
		SBTInitializer.ShaderBindingMode = ERayTracingShaderBindingMode::RTPSO;
		SBTInitializer.HitGroupIndexingMode = ERayTracingHitGroupIndexingMode::Disallow;
		SBTInitializer.NumGeometrySegments = 1;
		SBTInitializer.NumShaderSlotsPerGeometrySegment = RAY_TRACING_NUM_SHADER_SLOTS;
		SBTInitializer.NumMissShaderSlots = 1;
		SBTInitializer.NumCallableShaderSlots = 0;
		SBTInitializer.LocalBindingDataSize = PipelineInitializer.GetMaxLocalBindingDataSize();

		OutPipeline.PipelineState = PipelineStateCache::GetAndOrCreateRayTracingPipelineState(RHICmdList, PipelineInitializer);
		if (!OutPipeline.PipelineState)
		{
			OutFailureReason = TEXT("Failed to create the ray-tracing pipeline state.");
			return false;
		}

		OutPipeline.SBT = RHICmdList.CreateRayTracingShaderBindingTable(SBTInitializer);
		return true;
	}

	bool DispatchGeometryOcclusionRays(
		FRHICommandList& RHICmdList,
		FRHIShaderResourceView* SceneView,
		FRHIShaderResourceView* RayBufferView,
		FRHIUnorderedAccessView* ResultView,
		uint32 NumRays,
		FString& OutFailureReason)
	{
		FGeometryRayTracingPipeline Pipeline;
		if (!BuildGeometryRayTracingPipeline(RHICmdList, Pipeline, OutFailureReason))
		{
			return false;
		}

		RHICmdList.SetDefaultRayTracingHitGroup(Pipeline.SBT, Pipeline.PipelineState, 0);
		RHICmdList.SetRayTracingMissShader(Pipeline.SBT, 0, Pipeline.PipelineState, 0, 0, nullptr, 0);
		RHICmdList.CommitShaderBindingTable(Pipeline.SBT);

		FGeometryRayTracingOcclusionRGS::FParameters Parameters;
		Parameters.TLAS = SceneView;
		Parameters.Rays = RayBufferView;
		Parameters.OcclusionOutput = ResultView;

		FRHIBatchedShaderParameters& GlobalResources = RHICmdList.GetScratchShaderParameters();
		SetShaderParameters(GlobalResources, Pipeline.OcclusionRGS, Parameters);
		RHICmdList.RayTraceDispatch(Pipeline.PipelineState, Pipeline.OcclusionRGS.GetRayTracingShader(), Pipeline.SBT, GlobalResources, NumRays, 1);
		return true;
	}
#endif

	bool PrimeGeometryRayTracingSceneWithCapture(
		UWorld* World,
		USceneCaptureComponent2D* ExistingCaptureComponent,
		const FVector& PrimeLocation,
		const FRotator& PrimeRotation,
		FString* OutFailureReason)
	{
#if !RHI_RAYTRACING
		if (OutFailureReason)
		{
			*OutFailureReason = TEXT("RHI_RAYTRACING is not enabled for this build.");
		}
		return false;
#else
		if (OutFailureReason)
		{
			OutFailureReason->Empty();
		}

		if (!World || !World->Scene)
		{
			if (OutFailureReason)
			{
				*OutFailureReason = TEXT("World or world scene is null.");
			}
			return false;
		}

		if (HasGeometryRayTracingScene(World))
		{
			return true;
		}

		UTextureRenderTarget2D* PrimeTarget = NewObject<UTextureRenderTarget2D>(GetTransientPackage(), NAME_None, RF_Transient);
		if (!PrimeTarget)
		{
			if (OutFailureReason)
			{
				*OutFailureReason = TEXT("Failed to allocate a transient render target for TLAS priming.");
			}
			return false;
		}

		PrimeTarget->RenderTargetFormat = RTF_RGBA16f;
		PrimeTarget->ClearColor = FLinearColor::Black;
		PrimeTarget->bAutoGenerateMips = false;
		PrimeTarget->InitAutoFormat(4, 4);
		PrimeTarget->UpdateResourceImmediate(true);

		USceneCaptureComponent2D* CaptureComponent = ExistingCaptureComponent;
		const bool bCreatedTransientCapture = (CaptureComponent == nullptr);
		if (bCreatedTransientCapture)
		{
			CaptureComponent = NewObject<USceneCaptureComponent2D>(World, NAME_None, RF_Transient);
			if (!CaptureComponent)
			{
				if (OutFailureReason)
				{
					*OutFailureReason = TEXT("Failed to allocate a transient scene capture for TLAS priming.");
				}
				return false;
			}

			CaptureComponent->RegisterComponentWithWorld(World);
		}

		TOptional<FEngineShowFlags> SavedShowFlags;
		UTextureRenderTarget2D* SavedTextureTarget = nullptr;
		ESceneCaptureSource SavedCaptureSource = SCS_SceneColorHDR;
		ECameraProjectionMode::Type SavedProjectionType = ECameraProjectionMode::Perspective;
		float SavedFOV = 90.0f;
		float SavedOrthoWidth = 512.0f;
		bool bSavedUseRayTracingIfEnabled = false;
		bool bSavedCaptureEveryFrame = false;
		bool bSavedCaptureOnMovement = false;
		bool bSavedAlwaysPersistRenderingState = false;
		FVector SavedLocation = FVector::ZeroVector;
		FRotator SavedRotation = FRotator::ZeroRotator;

		if (!bCreatedTransientCapture)
		{
			SavedShowFlags.Emplace(CaptureComponent->ShowFlags);
			SavedTextureTarget = CaptureComponent->TextureTarget;
			SavedCaptureSource = CaptureComponent->CaptureSource;
			SavedProjectionType = CaptureComponent->ProjectionType;
			SavedFOV = CaptureComponent->FOVAngle;
			SavedOrthoWidth = CaptureComponent->OrthoWidth;
			bSavedUseRayTracingIfEnabled = CaptureComponent->bUseRayTracingIfEnabled;
			bSavedCaptureEveryFrame = CaptureComponent->bCaptureEveryFrame;
			bSavedCaptureOnMovement = CaptureComponent->bCaptureOnMovement;
			bSavedAlwaysPersistRenderingState = CaptureComponent->bAlwaysPersistRenderingState;
			SavedLocation = CaptureComponent->GetComponentLocation();
			SavedRotation = CaptureComponent->GetComponentRotation();
		}

		CaptureComponent->SetVisibility(true);
		CaptureComponent->TextureTarget = PrimeTarget;
		CaptureComponent->CaptureSource = SCS_SceneColorHDR;
		CaptureComponent->ProjectionType = ECameraProjectionMode::Perspective;
		CaptureComponent->FOVAngle = 90.0f;
		CaptureComponent->bCaptureEveryFrame = false;
		CaptureComponent->bCaptureOnMovement = false;
		CaptureComponent->bAlwaysPersistRenderingState = false;
		CaptureComponent->bUseRayTracingIfEnabled = true;
		CaptureComponent->ShowFlags.SetRayTracingDebug(true);
		CaptureComponent->SetWorldLocationAndRotation(PrimeLocation, PrimeRotation);
		CaptureComponent->MarkRenderStateDirty();

		World->SendAllEndOfFrameUpdates();
		CaptureComponent->CaptureScene();
		FlushRenderingCommands();

		const bool bPrimed = HasGeometryRayTracingScene(World);

		if (!bCreatedTransientCapture && SavedShowFlags.IsSet())
		{
			CaptureComponent->ShowFlags = SavedShowFlags.GetValue();
			CaptureComponent->TextureTarget = SavedTextureTarget;
			CaptureComponent->CaptureSource = SavedCaptureSource;
			CaptureComponent->ProjectionType = SavedProjectionType;
			CaptureComponent->FOVAngle = SavedFOV;
			CaptureComponent->OrthoWidth = SavedOrthoWidth;
			CaptureComponent->bUseRayTracingIfEnabled = bSavedUseRayTracingIfEnabled;
			CaptureComponent->bCaptureEveryFrame = bSavedCaptureEveryFrame;
			CaptureComponent->bCaptureOnMovement = bSavedCaptureOnMovement;
			CaptureComponent->bAlwaysPersistRenderingState = bSavedAlwaysPersistRenderingState;
			CaptureComponent->SetWorldLocationAndRotation(SavedLocation, SavedRotation);
			CaptureComponent->MarkRenderStateDirty();
		}
		else if (bCreatedTransientCapture)
		{
			CaptureComponent->DestroyComponent();
		}

		if (bPrimed)
		{
			UE_LOG(LogTemp, Display, TEXT("[Snow] Primed the geometry ray-tracing TLAS using a transient ray-tracing scene capture."));
			return true;
		}

		if (OutFailureReason)
		{
			*OutFailureReason = TEXT("A transient ray-tracing scene capture rendered successfully, but the world still did not expose a TLAS.");
		}
		return false;
#endif
	}

#if WITH_EDITOR
	bool PrimeGeometryRayTracingSceneInEditor(UWorld* World, FString* OutFailureReason)
	{
#if !RHI_RAYTRACING
		if (OutFailureReason)
		{
			*OutFailureReason = TEXT("RHI_RAYTRACING is not enabled for this build.");
		}
		return false;
#else
		if (OutFailureReason)
		{
			OutFailureReason->Empty();
		}

		if (!World)
		{
			if (OutFailureReason)
			{
				*OutFailureReason = TEXT("World is null.");
			}
			return false;
		}

		if (!World->Scene)
		{
			if (OutFailureReason)
			{
				*OutFailureReason = TEXT("World scene is null.");
			}
			return false;
		}

		if (HasGeometryRayTracingScene(World))
		{
			return true;
		}

		if (!GEditor)
		{
			if (OutFailureReason)
			{
				*OutFailureReason = TEXT("GEditor is unavailable, so no editor viewport can be used to build a TLAS.");
			}
			return false;
		}

		World->SendAllEndOfFrameUpdates();
		FlushRenderingCommands();
		if (HasGeometryRayTracingScene(World))
		{
			return true;
		}

		FString CapturePrimeFailureReason;
		if (PrimeGeometryRayTracingSceneWithCapture(
			World,
			nullptr,
			FVector(0.0f, 0.0f, 10000.0f),
			FRotator(-90.0f, 0.0f, 0.0f),
			&CapturePrimeFailureReason))
		{
			return true;
		}

		TArray<FEditorViewportClient*> CandidateViewports;
		TArray<FEditorViewportClient*> HiddenCandidateViewports;
		const FSceneInterface* const TargetScene = World->Scene;
		int32 NumSceneOrWorldMatches = 0;
		auto TryRegisterEditorViewport = [&](FEditorViewportClient* ViewportClient)
		{
			if (!ViewportClient || !ViewportClient->Viewport || !ViewportClient->GetScene())
			{
				return;
			}

			const bool bWorldMatch = (ViewportClient->GetWorld() == World);
			const bool bSceneMatch = (ViewportClient->GetScene() == TargetScene);
			if (!bWorldMatch && !bSceneMatch)
			{
				return;
			}

			++NumSceneOrWorldMatches;
			if (CandidateViewports.Contains(ViewportClient) || HiddenCandidateViewports.Contains(ViewportClient))
			{
				return;
			}

			if (ViewportClient->IsVisible())
			{
				if (ViewportClient->IsPerspective())
				{
					CandidateViewports.Insert(ViewportClient, 0);
				}
				else
				{
					CandidateViewports.Add(ViewportClient);
				}
				return;
			}

			if (ViewportClient->IsPerspective())
			{
				HiddenCandidateViewports.Insert(ViewportClient, 0);
			}
			else
			{
				HiddenCandidateViewports.Add(ViewportClient);
			}
		};

		for (FEditorViewportClient* ViewportClient : GEditor->GetAllViewportClients())
		{
			TryRegisterEditorViewport(ViewportClient);
		}
		TryRegisterEditorViewport(static_cast<FEditorViewportClient*>(GCurrentLevelEditingViewportClient));

		if (HiddenCandidateViewports.Num() > 0)
		{
			CandidateViewports.Append(HiddenCandidateViewports);
		}

		int32 NumViewportDraws = 0;
		for (FEditorViewportClient* ViewportClient : CandidateViewports)
		{
			World->SendAllEndOfFrameUpdates();
			ViewportClient->Invalidate(false, false);

			bool bViewportDrawn = false;
			GEditor->UpdateSingleViewportClient(ViewportClient, true, false, &bViewportDrawn);
			FlushRenderingCommands();

			if (!bViewportDrawn)
			{
				continue;
			}

			++NumViewportDraws;
			if (HasGeometryRayTracingScene(World))
			{
				UE_LOG(
					LogTemp,
					Display,
					TEXT("[Snow] Primed the geometry ray-tracing TLAS using editor viewport draws: %d."),
					NumViewportDraws);
				return true;
			}
		}

		if (GEngine)
		{
			if (UGameViewportClient* GameViewport = GEngine->GameViewportForWorld(World))
			{
				if (GameViewport->Viewport)
				{
					World->SendAllEndOfFrameUpdates();

					UWorld* OldGWorld = nullptr;
					const bool bNeedsPIEWorldScope = (GEditor->PlayWorld == World) && !GEditor->bIsSimulatingInEditor;
					if (bNeedsPIEWorldScope)
					{
						OldGWorld = SetPlayInEditorWorld(World);
					}

					GameViewport->LayoutPlayers();
					GameViewport->Viewport->Draw();

					if (bNeedsPIEWorldScope)
					{
						RestoreEditorWorld(OldGWorld);
					}

					FlushRenderingCommands();
					if (HasGeometryRayTracingScene(World))
					{
						UE_LOG(
							LogTemp,
							Display,
							TEXT("[Snow] Primed the geometry ray-tracing TLAS using the PIE game viewport."));
						return true;
					}
				}
			}
		}

		if (OutFailureReason)
		{
			if (CandidateViewports.Num() == 0)
			{
				*OutFailureReason = FString::Printf(
					TEXT("No scene-matched editor viewport or PIE game viewport with a drawable viewport was found for the current world (matches=%d)."),
					NumSceneOrWorldMatches);
			}
			else
			{
				*OutFailureReason = FString::Printf(
					TEXT("Transient RT capture and %d scene-matched editor viewport draw(s) plus the PIE game viewport if available still did not expose a ray-tracing TLAS (matches=%d, capture_reason=%s)."),
					NumViewportDraws,
					NumSceneOrWorldMatches,
					CapturePrimeFailureReason.IsEmpty() ? TEXT("n/a") : *CapturePrimeFailureReason);
			}
		}
		return false;
#endif
	}
#endif

	bool HasUsableSkyOnlyReference(float SkyOnlyReference, float DiffuseReference, float TotalReference)
	{
		if (!FMath::IsFinite(SkyOnlyReference) || SkyOnlyReference <= DiffuseNoGIReferenceAbsoluteFloor)
		{
			return false;
		}

		const float SafeDiffuseReference = FMath::IsFinite(DiffuseReference)
			? FMath::Max(0.0f, DiffuseReference)
			: 0.0f;
		const float SafeTotalReference = FMath::IsFinite(TotalReference)
			? FMath::Max(0.0f, TotalReference)
			: 0.0f;
		if (SafeDiffuseReference <= DiffuseNoGIReferenceAbsoluteFloor
			|| SafeTotalReference <= DiffuseNoGIReferenceAbsoluteFloor)
		{
			return false;
		}

		return SkyOnlyReference >= (SafeDiffuseReference * DiffuseNoGIReferenceRelativeFloor)
			&& SkyOnlyReference >= (SafeTotalReference * DiffuseNoGIReferenceMinTotalFraction);
	}

	float BlendDualReferenceValue(float GroundValue, float SnowValue, float SnowWeight, float FullStripFallback)
	{
		const bool bGroundValid = FMath::IsFinite(GroundValue) && GroundValue >= 0.0f;
		const bool bSnowValid = FMath::IsFinite(SnowValue) && SnowValue >= 0.0f;
		const float ClampedSnowWeight = FMath::Clamp(SnowWeight, 0.0f, 1.0f);

		if (bGroundValid && bSnowValid)
		{
			return FMath::Lerp(GroundValue, SnowValue, ClampedSnowWeight);
		}
		if (bSnowValid)
		{
			return SnowValue;
		}
		if (bGroundValid)
		{
			return GroundValue;
		}
		return FMath::Max(0.0f, FullStripFallback);
	}

	bool TryComputeDirectReferenceIndex(float SampleDirectRTY, float ReferenceDirectLuminance, float& OutDirectIndex)
	{
		if (!FMath::IsFinite(SampleDirectRTY) || SampleDirectRTY < 0.0f
			|| !FMath::IsFinite(ReferenceDirectLuminance) || ReferenceDirectLuminance <= KINDA_SMALL_NUMBER)
		{
			OutDirectIndex = 0.0f;
			return false;
		}

		OutDirectIndex = SampleDirectRTY / ReferenceDirectLuminance;
		return FMath::IsFinite(OutDirectIndex) && OutDirectIndex >= 0.0f;
	}

	bool TryComputeRenderSurfaceSnowBlendWeight(
		float SurfaceStateValue,
		float GroundReferenceValue,
		float SnowReferenceValue,
		float& OutSnowBlendWeight)
	{
		if (!FMath::IsFinite(SurfaceStateValue) || SurfaceStateValue < 0.0f
			|| !FMath::IsFinite(GroundReferenceValue) || GroundReferenceValue < 0.0f
			|| !FMath::IsFinite(SnowReferenceValue) || SnowReferenceValue < 0.0f)
		{
			OutSnowBlendWeight = 0.0f;
			return false;
		}

		const float ReferenceDelta = SnowReferenceValue - GroundReferenceValue;
		if (!FMath::IsFinite(ReferenceDelta) || FMath::Abs(ReferenceDelta) <= 1.0e-4f)
		{
			OutSnowBlendWeight = 0.0f;
			return false;
		}

		OutSnowBlendWeight = FMath::Clamp((SurfaceStateValue - GroundReferenceValue) / ReferenceDelta, 0.0f, 1.0f);
		return FMath::IsFinite(OutSnowBlendWeight);
	}

	const UFSM2SnowSimulation* ResolveFSM2ShortwavePartitionSource(const ASnowSimulationActor* Actor)
	{
		if (!Actor)
		{
			return nullptr;
		}

		if (const UFSM2SnowSimulation* RuntimeSimulation = Cast<UFSM2SnowSimulation>(Actor->Simulation))
		{
			return RuntimeSimulation;
		}

		return Cast<UFSM2SnowSimulation>(Actor->SimulationConfiguration);
	}

	bool ResolveHorizontalShortwaveComponentsFromFSM2(const ASnowSimulationActor* Actor,
		const FWeatherForcingData& Forcing,
		float& OutDirectHorizontalWm2,
		float& OutDiffuseHorizontalWm2)
	{
		const UFSM2SnowSimulation* const FSM2 = ResolveFSM2ShortwavePartitionSource(Actor);
		if (!FSM2)
		{
			return false;
		}

		const float IncomingSW = FMath::Max(0.0f, Forcing.SWdown_Wm2);
		OutDirectHorizontalWm2 = 0.0f;
		OutDiffuseHorizontalWm2 = IncomingSW;

		if (FSM2->ModelParameters.Atmosphere.ShortwavePartition != EFSM2ShortwavePartition::DiffuseAndDirect
			|| IncomingSW <= KINDA_SMALL_NUMBER)
		{
			return true;
		}

		const float LatitudeDeg = (FMath::IsFinite(Actor->Latitude) && FMath::Abs(Actor->Latitude) > KINDA_SMALL_NUMBER)
			? Actor->Latitude
			: FSM2->ModelParameters.Atmosphere.LatitudeDegrees;
		const float LatitudeRad = FMath::DegreesToRadians(LatitudeDeg);
		const int32 DayOfYear = Forcing.Timestamp.GetDayOfYear();
		const float HourLocal = Forcing.Timestamp.GetHour()
			+ Forcing.Timestamp.GetMinute() / 60.0f
			+ Forcing.Timestamp.GetSecond() / 3600.0f;
		const float SolarNoon = FSM2->ModelParameters.Atmosphere.SolarNoonLocalTime;

		const float DayAngle = 2.0f * PI * static_cast<float>(DayOfYear - 1) / 365.0f;
		const float Declination = 0.006918f
			- 0.399912f * FMath::Cos(DayAngle)
			+ 0.070257f * FMath::Sin(DayAngle)
			- 0.006758f * FMath::Cos(2.0f * DayAngle)
			+ 0.000907f * FMath::Sin(2.0f * DayAngle)
			- 0.002697f * FMath::Cos(3.0f * DayAngle)
			+ 0.001480f * FMath::Sin(3.0f * DayAngle);

		const float EquationOfTimeHours = (0.000075f
			+ 0.001868f * FMath::Cos(DayAngle)
			- 0.032077f * FMath::Sin(DayAngle)
			- 0.014615f * FMath::Cos(2.0f * DayAngle)
			- 0.04089f * FMath::Sin(2.0f * DayAngle)) * (12.0f / PI);

		const float HourAngle = (PI / 12.0f) * (SolarNoon - HourLocal - EquationOfTimeHours);
		const float Elevation = FMath::Asin(
			FMath::Sin(Declination) * FMath::Sin(LatitudeRad)
			+ FMath::Cos(Declination) * FMath::Cos(LatitudeRad) * FMath::Cos(HourAngle));

		const float SolarConstant = FSM2->ModelParameters.PhysicalConstants.SolarConstant_Wm2;
		float Kt = 0.0f;
		if (Elevation > 0.0f)
		{
			const float SinElevation = FMath::Sin(Elevation);
			if (SinElevation > KINDA_SMALL_NUMBER)
			{
				Kt = IncomingSW / (SolarConstant * SinElevation);
			}
		}

		float DiffuseFraction = 1.0f - 0.09f * Kt;
		if (Kt > 0.22f)
		{
			DiffuseFraction = 0.95f
				- 0.16f * Kt
				+ 4.39f * FMath::Square(Kt)
				- 16.64f * FMath::Pow(Kt, 3.0f)
				+ 12.34f * FMath::Pow(Kt, 4.0f);
		}
		if (Kt > 0.8f)
		{
			DiffuseFraction = 0.165f;
		}

		if (!FMath::IsFinite(DiffuseFraction))
		{
			DiffuseFraction = 1.0f;
		}

		DiffuseFraction = FMath::Clamp(DiffuseFraction, 0.0f, 1.0f);
		OutDiffuseHorizontalWm2 = DiffuseFraction * IncomingSW;
		OutDirectHorizontalWm2 = FMath::Max(0.0f, IncomingSW - OutDiffuseHorizontalWm2);
		return true;
	}

	void ResolveHorizontalShortwaveComponentsWithDegreeDayDniDhi(
		const FWeatherForcingData& Forcing,
		float CosZenith,
		float& OutDirectHorizontalWm2,
		float& OutDiffuseHorizontalWm2,
		float* OutResolvedDNI_Wm2 = nullptr,
		float* OutResolvedDiffuseFraction = nullptr)
	{
		const float GHI = FMath::Max(0.0f, Forcing.SWdown_Wm2);
		const float ClampedCosZenith = FMath::Clamp(CosZenith, -1.0f, 1.0f);
		const float SolarZenithRad = FMath::Acos(ClampedCosZenith);
		FForcingRadiation ForcingRadiation(GHI, SolarZenithRad);
		UDegreeDaySimulation::ComputeDNI_DHI(ForcingRadiation);

		OutDiffuseHorizontalWm2 = FMath::Max(0.0f, ForcingRadiation.DHI);
		OutDirectHorizontalWm2 = FMath::Max(0.0f, GHI - OutDiffuseHorizontalWm2);
		if (OutResolvedDNI_Wm2)
		{
			*OutResolvedDNI_Wm2 = FMath::Max(0.0f, ForcingRadiation.DNI);
		}
		if (OutResolvedDiffuseFraction)
		{
			*OutResolvedDiffuseFraction = FMath::Clamp(ForcingRadiation.DiffuseFraction, 0.0f, 1.0f);
		}
	}

	FString SanitizeMeltoutTag(const FString& InTag)
	{
		FString Out = InTag;
		Out.ReplaceInline(TEXT(" "), TEXT("_"));
		Out.ReplaceInline(TEXT("("), TEXT(""));
		Out.ReplaceInline(TEXT(")"), TEXT(""));
		Out.ReplaceInline(TEXT("+"), TEXT(""));
		Out.ReplaceInline(TEXT("-"), TEXT("_"));
		Out.ReplaceInline(TEXT("."), TEXT(""));
		Out.ReplaceInline(TEXT("/"), TEXT("_"));
		Out.ReplaceInline(TEXT("\\"), TEXT("_"));
		Out.ReplaceInline(TEXT(":"), TEXT("_"));
		Out.ReplaceInline(TEXT("*"), TEXT("_"));
		Out.ReplaceInline(TEXT("?"), TEXT("_"));
		Out.ReplaceInline(TEXT("\""), TEXT(""));
		Out.ReplaceInline(TEXT("<"), TEXT("_"));
		Out.ReplaceInline(TEXT(">"), TEXT("_"));
		Out.ReplaceInline(TEXT("|"), TEXT("_"));
		Out.ReplaceInline(TEXT("__"), TEXT("_"));
		Out.ReplaceInline(TEXT("__"), TEXT("_"));
		Out = Out.TrimStartAndEnd();
		if (Out.IsEmpty())
		{
			Out = TEXT("Unknown");
		}
		return Out;
	}

	FString StripPIEPrefix(const FString& InMapName)
	{
		if (!InMapName.StartsWith(TEXT("UEDPIE_")))
		{
			return InMapName;
		}

		TArray<FString> Tokens;
		InMapName.ParseIntoArray(Tokens, TEXT("_"), false);
		if (Tokens.Num() >= 3)
		{
			FString Joined;
			for (int32 i = 2; i < Tokens.Num(); ++i)
			{
				if (!Joined.IsEmpty())
				{
					Joined += TEXT("_");
				}
				Joined += Tokens[i];
			}
			return Joined;
		}

		return InMapName;
	}

	FString GetMeltoutModelTag(const USimulationBase* Simulation)
	{
		if (!Simulation)
		{
			return TEXT("Unknown");
		}

		if (const UDegreeDaySimulation* DD = Cast<UDegreeDaySimulation>(Simulation))
		{
			switch (DD->DegreeDayMeltModel)
			{
			case EDegreeDayMeltModel::Enhanced:
				return TEXT("DD_Enhanced");
			case EDegreeDayMeltModel::HockModel2:
				return TEXT("DD_Hock2");
			case EDegreeDayMeltModel::HockModel3Exact:
				return TEXT("DD_Hock3Exact");
			case EDegreeDayMeltModel::HockModel3_UE_SWR:
				return TEXT("DD_PellicciottiD_LegacyUE");
			case EDegreeDayMeltModel::PellicciottiModelD:
				return TEXT("DD_PellicciottiD");
			case EDegreeDayMeltModel::PellicciottiModelD_RI:
				return TEXT("DD_PellicciottiD_Lambertian");
			case EDegreeDayMeltModel::PellicciottiModelD_PBR:
				return TEXT("DD_PellicciottiD_PBR");
			default:
				return TEXT("DD_PellicciottiUE");
			}
		}

		return SanitizeMeltoutTag(Simulation->GetSimulationName());
	}

	bool TryGetDebugCameraLocation(UWorld* World, FVector& OutViewLocation, const AActor*& OutIgnoredActor)
	{
		OutIgnoredActor = nullptr;
		if (!World)
		{
			return false;
		}

		if (APlayerController* PlayerController = World->GetFirstPlayerController())
		{
			if (const APlayerCameraManager* CameraManager = PlayerController->PlayerCameraManager)
			{
				OutViewLocation = CameraManager->GetCameraLocation();
				OutIgnoredActor = PlayerController->GetPawn();
				return true;
			}

			if (const APawn* Pawn = PlayerController->GetPawn())
			{
				OutViewLocation = Pawn->GetActorLocation();
				OutIgnoredActor = Pawn;
				return true;
			}
		}

		// Fallback for editor viewports and non-player rendering contexts.
		if (World->ViewLocationsRenderedLastFrame.Num() > 0)
		{
			OutViewLocation = World->ViewLocationsRenderedLastFrame[0];
			return true;
		}

		return false;
	}

	bool SetFloatPropertyIfPresent(UObject* Target, const TCHAR* PropertyName, float NewValue)
	{
		if (!Target)
		{
			return false;
		}

		if (FFloatProperty* FloatProp = FindFProperty<FFloatProperty>(Target->GetClass(), PropertyName))
		{
			FloatProp->SetPropertyValue_InContainer(Target, NewValue);
			return true;
		}

		return false;
	}

	bool SetIntPropertyIfPresent(UObject* Target, const TCHAR* PropertyName, int32 NewValue)
	{
		if (!Target)
		{
			return false;
		}

		if (FIntProperty* IntProp = FindFProperty<FIntProperty>(Target->GetClass(), PropertyName))
		{
			IntProp->SetPropertyValue_InContainer(Target, NewValue);
			return true;
		}

		return false;
	}

	/** Scoped helper that bumps key Lumen quality CVars for deterministic radiation captures. */
	class FLumenCaptureQualityScope
	{
	public:
		explicit FLumenCaptureQualityScope(const ASnowSimulationActor& Owner)
		{
			if (!Owner.bOverrideLumenCaptureCVars)
			{
				if (Owner.bDebugRadiationCapture)
				{
					UE_LOG(SimulationLog, Display, TEXT("[LumenScope] Override disabled: using runtime CVars"));
				}
				return;
			}

			OverrideFloat(TEXT("r.Lumen.DiffuseIndirect.TraceStepFactor"), Owner.LumenCaptureTraceStepFactor);
			OverrideFloat(TEXT("r.Lumen.TraceDistanceScale"), Owner.LumenCaptureTraceDistanceScale);
			OverrideInt(TEXT("r.Lumen.TraceMeshSDFs"), Owner.bLumenCaptureForceMeshSDFs ? 1 : 0);

			// CRITICAL: Disable temporal filtering to prevent lag in radiation values
			// Without these, Lumen accumulates lighting over multiple frames causing 2-3 hour delays
			OverrideInt(TEXT("r.Lumen.ScreenProbeGather.TemporalFilter"), 0);
			OverrideFloat(TEXT("r.Lumen.ScreenProbeGather.HistoryWeight"), 0.0f);
			OverrideInt(TEXT("r.Lumen.Reflections.TemporalFilter"), 0);

			// Additional aggressive history clearing
			OverrideInt(TEXT("r.Lumen.ScreenProbeGather.FixedJitterIndex"), 0);  // Disable temporal jitter
			OverrideFloat(TEXT("r.Lumen.ScreenProbeGather.AdaptiveProbeMinDownsampleFactor"), 1.0f);
			OverrideInt(TEXT("r.Lumen.DiffuseIndirect.TemporalFilter"), 0);  // Disable diffuse temporal filter

			if (Owner.bDebugRadiationCapture)
			{
				for (const FOverrideEntry& Entry : Overrides)
				{
					if (!Entry.Var)
					{
						continue;
					}

					if (Entry.bIsInt)
					{
						UE_LOG(SimulationLog, Display, TEXT("[LumenScope] %s: %d -> %d"),
							Entry.Name, static_cast<int32>(Entry.PreviousValue), static_cast<int32>(Entry.NewValue));
					}
					else
					{
						UE_LOG(SimulationLog, Display, TEXT("[LumenScope] %s: %.4f -> %.4f"),
							Entry.Name, Entry.PreviousValue, Entry.NewValue);
					}
				}
			}
		}

		~FLumenCaptureQualityScope()
		{
			for (const FOverrideEntry& Entry : Overrides)
			{
				if (!Entry.Var)
				{
					continue;
				}

				if (Entry.bIsInt)
				{
					Entry.Var->Set(static_cast<int32>(Entry.PreviousValue), ECVF_SetByCode);
				}
				else
				{
					Entry.Var->Set(static_cast<float>(Entry.PreviousValue), ECVF_SetByCode);
				}
			}
		}

	private:
		struct FOverrideEntry
		{
			IConsoleVariable* Var = nullptr;
			double PreviousValue = 0.0;
			double NewValue = 0.0;
			bool bIsInt = false;
			const TCHAR* Name = nullptr;
		};

		TArray<FOverrideEntry, TInlineAllocator<4>> Overrides;

		void OverrideFloat(const TCHAR* Name, float NewValue)
		{
			if (IConsoleVariable* Var = IConsoleManager::Get().FindConsoleVariable(Name))
			{
				FOverrideEntry& Entry = Overrides.Emplace_GetRef();
				Entry.Var = Var;
				Entry.PreviousValue = Var->GetFloat();
				Entry.NewValue = NewValue;
				Entry.bIsInt = false;
				Entry.Name = Name;
				Var->Set(NewValue, ECVF_SetByCode);
			}
		}

		void OverrideInt(const TCHAR* Name, int32 NewValue)
		{
			if (IConsoleVariable* Var = IConsoleManager::Get().FindConsoleVariable(Name))
			{
				FOverrideEntry& Entry = Overrides.Emplace_GetRef();
				Entry.Var = Var;
				Entry.PreviousValue = Var->GetInt();
				Entry.NewValue = NewValue;
				Entry.bIsInt = true;
				Entry.Name = Name;
				Var->Set(NewValue, ECVF_SetByCode);
			}
		}
	};

	/** Scoped helper that disables Lumen history so captures always use fresh lighting. */
	class FLumenHistoryDisableScope
	{
	public:
		FLumenHistoryDisableScope()
		{
			DisableHistory(TEXT("r.Lumen.DiffuseIndirect.AllowHistory"), DiffuseIndirectEntry);
			DisableHistory(TEXT("r.Lumen.Reflections.AllowHistory"), ReflectionsEntry);
		}

		~FLumenHistoryDisableScope()
		{
			Restore(DiffuseIndirectEntry);
			Restore(ReflectionsEntry);
		}

	private:
		struct FHistoryEntry
		{
			IConsoleVariable* Var = nullptr;
			int32 PreviousValue = INDEX_NONE;
		};

		void DisableHistory(const TCHAR* Name, FHistoryEntry& Entry)
		{
			if (IConsoleVariable* Var = IConsoleManager::Get().FindConsoleVariable(Name))
			{
				Entry.Var = Var;
				Entry.PreviousValue = Var->GetInt();
				Var->Set(0, ECVF_SetByCode);
			}
		}

		void Restore(FHistoryEntry& Entry)
		{
			if (Entry.Var && Entry.PreviousValue != INDEX_NONE)
			{
				Entry.Var->Set(Entry.PreviousValue, ECVF_SetByCode);
			}
		}

		FHistoryEntry DiffuseIndirectEntry;
		FHistoryEntry ReflectionsEntry;
	};

	/**
	 * Warms up Lumen GI before a probe-lattice cavity capture.
	 *
	 * FLumenCaptureQualityScope + FLumenHistoryDisableScope force AllowHistory=0
	 * and TemporalFilter=0, so a single CaptureScene() per face from inside a
	 * cavity cannot resolve indirect bounce — the ground albedo never shows up
	 * in Total RTY (e.g. the probe-lattice albedo sweep stays flat).  This
	 * scope mirrors the probe-disk convergence block: it re-enables history
	 * and temporal filtering, cycles the 5 hemisphere faces for
	 * LumenConvergenceFrames to populate Lumen's radiance cache, and keeps
	 * history ON for its lifetime so subsequent sparse Total captures sample
	 * the warmed cache.  Destruction flushes rendering and restores CVars.
	 */
	class FLumenProbeLatticeWarmUpScope
	{
	public:
		FLumenProbeLatticeWarmUpScope(
			ASnowSimulationActor& Owner,
			UWorld* World,
			USceneCaptureComponent2D* Capture,
			UTextureRenderTarget2D* ProbeTarget,
			const FEngineShowFlags& TotalFlags,
			const FVector& WarmUpOrigin,
			const FVector& WarmUpNormal,
			const FRotator& LandscapeRotation)
			: CaptureRef(Capture)
		{
			if (!Owner.bOverrideLumenCaptureCVars || !Owner.bEnableLumenConvergence
				|| Owner.LumenConvergenceFrames <= 0
				|| !Capture || !World || !ProbeTarget)
			{
				return;
			}

			ProbeGatherTemporalVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.ScreenProbeGather.TemporalFilter"));
			HistoryWeightVar       = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.ScreenProbeGather.HistoryWeight"));
			DiffuseTemporalVar     = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.DiffuseIndirect.TemporalFilter"));
			DiffuseAllowHistoryVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.DiffuseIndirect.AllowHistory"));

			SavedProbeGatherTemporal = ProbeGatherTemporalVar ? ProbeGatherTemporalVar->GetInt() : 0;
			SavedHistoryWeight       = HistoryWeightVar       ? HistoryWeightVar->GetFloat()     : 0.0f;
			SavedDiffuseTemporal     = DiffuseTemporalVar     ? DiffuseTemporalVar->GetInt()     : 0;
			SavedDiffuseAllowHistory = DiffuseAllowHistoryVar ? DiffuseAllowHistoryVar->GetInt() : 0;
			SavedPersistRenderState  = Capture->bAlwaysPersistRenderingState;

			if (DiffuseAllowHistoryVar) DiffuseAllowHistoryVar->Set(1);
			if (ProbeGatherTemporalVar) ProbeGatherTemporalVar->Set(1);
			if (HistoryWeightVar)       HistoryWeightVar->Set(Owner.LumenConvergenceHistoryWeight);
			if (DiffuseTemporalVar)     DiffuseTemporalVar->Set(1);
			Capture->bAlwaysPersistRenderingState = true;

			// Surface-cache refresh burst, scoped to the warm-up render loop only.
			// Why: after the runtime material swap, Lumen's surface cards still hold
			// the original-material radiosity.  We force one pass where every card
			// gets re-captured, let radiosity integrate over the remaining warm-up
			// frames, then restore defaults before sparse captures so they don't
			// keep thrashing the cache.
			IConsoleVariable* CardRefreshFractionVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.LumenScene.SurfaceCache.CardCaptureRefreshFraction"));
			IConsoleVariable* CardRefreshPagesVar    = IConsoleManager::Get().FindConsoleVariable(TEXT("r.LumenScene.SurfaceCache.CardCaptureRefreshNumPages"));
			IConsoleVariable* RadiosityUpdateVar     = IConsoleManager::Get().FindConsoleVariable(TEXT("r.LumenScene.Radiosity.UpdateFactor"));
			const float LocalSavedCardRefreshFraction = CardRefreshFractionVar ? CardRefreshFractionVar->GetFloat() : 0.0f;
			const int32 LocalSavedCardRefreshPages    = CardRefreshPagesVar    ? CardRefreshPagesVar->GetInt()     : 0;
			const int32 LocalSavedRadiosityUpdate    = RadiosityUpdateVar     ? RadiosityUpdateVar->GetInt()      : 0;
			if (CardRefreshFractionVar) CardRefreshFractionVar->Set(1.0f);
			if (CardRefreshPagesVar)    CardRefreshPagesVar->Set(1024);
			if (RadiosityUpdateVar)     RadiosityUpdateVar->Set(1);

			FVector WUp, WForward, WRight;
			BuildBelowCanopyProbeFrame(WarmUpNormal, LandscapeRotation, WUp, WForward, WRight);
			const FVector FaceForwards[5] = { WUp, WForward, -WForward, WRight, -WRight };
			const FVector FaceUps[5]      = { WForward, WUp, WUp, WUp, WUp };

			Capture->ShowFlags = TotalFlags;
			Capture->TextureTarget = ProbeTarget;
			Capture->MarkRenderStateDirty();
			const int32 CacheRefreshBurstFrames = FMath::Min(4, Owner.LumenConvergenceFrames);
			for (int32 Frame = 0; Frame < Owner.LumenConvergenceFrames; ++Frame)
			{
				if (Frame == CacheRefreshBurstFrames)
				{
					if (CardRefreshFractionVar) CardRefreshFractionVar->Set(LocalSavedCardRefreshFraction);
					if (CardRefreshPagesVar)    CardRefreshPagesVar->Set(LocalSavedCardRefreshPages);
					if (RadiosityUpdateVar)     RadiosityUpdateVar->Set(LocalSavedRadiosityUpdate);
				}
				for (int32 FaceIdx = 0; FaceIdx < 5; ++FaceIdx)
				{
					Capture->SetWorldLocationAndRotation(
						WarmUpOrigin,
						MakePerspectiveCaptureRotation(FaceForwards[FaceIdx], FaceUps[FaceIdx]));
					Capture->MarkRenderStateDirty();
					World->SendAllEndOfFrameUpdates();
					Capture->CaptureScene();
				}
			}

			if (Owner.LumenConvergenceFrames <= CacheRefreshBurstFrames)
			{
				if (CardRefreshFractionVar) CardRefreshFractionVar->Set(LocalSavedCardRefreshFraction);
				if (CardRefreshPagesVar)    CardRefreshPagesVar->Set(LocalSavedCardRefreshPages);
				if (RadiosityUpdateVar)     RadiosityUpdateVar->Set(LocalSavedRadiosityUpdate);
			}

			bActive = true;
		}

		~FLumenProbeLatticeWarmUpScope()
		{
			if (!bActive)
			{
				return;
			}

			FlushRenderingCommands();
			if (CaptureRef)
			{
				CaptureRef->bAlwaysPersistRenderingState = SavedPersistRenderState;
			}
			if (ProbeGatherTemporalVar) ProbeGatherTemporalVar->Set(SavedProbeGatherTemporal);
			if (HistoryWeightVar)       HistoryWeightVar->Set(SavedHistoryWeight);
			if (DiffuseTemporalVar)     DiffuseTemporalVar->Set(SavedDiffuseTemporal);
			if (DiffuseAllowHistoryVar) DiffuseAllowHistoryVar->Set(SavedDiffuseAllowHistory);
		}

		bool IsActive() const { return bActive; }

	private:
		USceneCaptureComponent2D* CaptureRef = nullptr;
		IConsoleVariable* ProbeGatherTemporalVar = nullptr;
		IConsoleVariable* HistoryWeightVar       = nullptr;
		IConsoleVariable* DiffuseTemporalVar     = nullptr;
		IConsoleVariable* DiffuseAllowHistoryVar = nullptr;
		int32 SavedProbeGatherTemporal = 0;
		float SavedHistoryWeight       = 0.0f;
		int32 SavedDiffuseTemporal     = 0;
		int32 SavedDiffuseAllowHistory = 0;
		bool  SavedPersistRenderState  = false;
		bool  bActive                  = false;
	};

	static EDegreeDayMeltModel GetDegreeDayMeltModel(const ASnowSimulationActor& Owner)
	{
		const UDegreeDaySimulation* DegreeDay = Cast<UDegreeDaySimulation>(Owner.SimulationConfiguration);
		return DegreeDay ? DegreeDay->DegreeDayMeltModel : EDegreeDayMeltModel::Enhanced;
	}

	static bool IsPellicciottiPbrModel(const ASnowSimulationActor& Owner)
	{
		return GetDegreeDayMeltModel(Owner) == EDegreeDayMeltModel::PellicciottiModelD_PBR;
	}

	static bool IsPellicciottiRiModel(const ASnowSimulationActor& Owner)
	{
		return GetDegreeDayMeltModel(Owner) == EDegreeDayMeltModel::PellicciottiModelD_RI;
	}

	static bool ShouldApplyLambertianOverride(const ASnowSimulationActor& /*Owner*/)
	{
		// Superseded by the dual-reference same-material construction: assigning the evolving
		// snow master material to both landscape and the reference strip halves cancels surface
		// albedo directly in the RTY ratio, so the Lambertian-override path is no longer used.
		return false;
	}

	static UMaterialInterface* LoadMaterialSoft(const TSoftObjectPtr<UMaterialInterface>& SoftMaterial)
	{
		if (SoftMaterial.IsValid() || SoftMaterial.ToSoftObjectPath().IsValid())
		{
			return SoftMaterial.LoadSynchronous();
		}
		return nullptr;
	}

	static UMaterialInterface* ResolveSnowSurfaceMaterial(const ASnowSimulationActor& Owner)
	{
		return LoadMaterialSoft(Owner.SnowSurfaceMaterial);
	}

	static UMaterialInterface* ResolveLambertianOverrideMaterial(const ASnowSimulationActor& Owner)
	{
		return LoadMaterialSoft(Owner.LambertianCaptureMaterial);
	}

	class FScopedBenchmarkSurfaceMaterialOverride
	{
	public:
		FScopedBenchmarkSurfaceMaterialOverride(
			ASnowSimulationActor& Owner,
			const TArray<UPrimitiveComponent*>& InComponents,
			UMaterialInterface* InBaseMaterial)
			: OwnerRef(Owner)
		{
			if (!InBaseMaterial)
			{
				return;
			}

			const float ClampedAlbedo = FMath::Clamp(OwnerRef.RadiationBenchmarkAlbedo, 0.0f, 1.0f);
			for (UPrimitiveComponent* Component : InComponents)
			{
				if (!Component)
				{
					continue;
				}

				if (ULandscapeComponent* LandscapeComponent = Cast<ULandscapeComponent>(Component))
				{
					FLandscapeEntry& Entry = LandscapeEntries.Emplace_GetRef();
					Entry.Component = LandscapeComponent;
					UMaterialInterface* OriginalOverrideMaterial = LandscapeComponent->OverrideMaterial;
					if (OriginalOverrideMaterial && OriginalOverrideMaterial->IsA<UMaterialInstanceDynamic>())
					{
						// Landscape material instances cannot legally parent from a MID.
						OriginalOverrideMaterial = nullptr;
					}
					Entry.OriginalOverrideMaterial = OriginalOverrideMaterial;

					if (ALandscapeProxy* LandscapeProxy = LandscapeComponent->GetLandscapeProxy())
					{
						FLandscapeProxyEntry* ExistingProxyEntry = LandscapeProxyEntries.Find(LandscapeProxy);
						if (!ExistingProxyEntry)
						{
							FLandscapeProxyEntry NewProxyEntry;
							NewProxyEntry.Proxy = LandscapeProxy;
							NewProxyEntry.bOriginalUseDynamicMaterialInstance = LandscapeProxy->bUseDynamicMaterialInstance;
							LandscapeProxyEntries.Add(LandscapeProxy, MoveTemp(NewProxyEntry));
						}
						LandscapeProxy->bUseDynamicMaterialInstance = true;
					}

					LandscapeComponent->OverrideMaterial = InBaseMaterial;
					LandscapeComponent->MarkRenderStateDirty();
					bHasAppliedMaterials = true;
					continue;
				}

				const int32 NumSlots = FMath::Max(1, Component->GetNumMaterials());
				for (int32 SlotIndex = 0; SlotIndex < NumSlots; ++SlotIndex)
				{
					FMeshEntry Entry;
					Entry.Component = Component;
					Entry.SlotIndex = SlotIndex;
					Entry.OriginalMaterial = Component->GetMaterial(SlotIndex);

					UMaterialInstanceDynamic* OverrideMaterial = UMaterialInstanceDynamic::Create(InBaseMaterial, &OwnerRef);
					if (!OverrideMaterial)
					{
						continue;
					}

					Entry.OverrideMaterial = OverrideMaterial;
					ConfigureMaterialParameters(OverrideMaterial, ClampedAlbedo, OwnerRef);
					Component->SetMaterial(SlotIndex, OverrideMaterial);
					MeshEntries.Add(MoveTemp(Entry));
					bHasAppliedMaterials = true;
				}

				Component->MarkRenderStateDirty();
			}

			for (auto& Pair : LandscapeProxyEntries)
			{
				if (ALandscapeProxy* LandscapeProxy = Pair.Value.Proxy.Get())
				{
					LandscapeProxy->UpdateAllComponentMaterialInstances();
					ConfigureLandscapeParameters(*LandscapeProxy, ClampedAlbedo, OwnerRef);
					LandscapeProxy->MarkComponentsRenderStateDirty();
				}
			}

			if (bHasAppliedMaterials)
			{
				FlushRenderingCommands();
			}
		}

		~FScopedBenchmarkSurfaceMaterialOverride()
		{
			if (!OwnerRef.bRadiationBenchmarkRestoreSurfaceMaterials)
			{
				return;
			}

			for (const FMeshEntry& Entry : MeshEntries)
			{
				if (UPrimitiveComponent* Component = Entry.Component.Get())
				{
					Component->SetMaterial(Entry.SlotIndex, Entry.OriginalMaterial.Get());
					Component->MarkRenderStateDirty();
				}
			}

			for (const FLandscapeEntry& Entry : LandscapeEntries)
			{
				if (ULandscapeComponent* LandscapeComponent = Entry.Component.Get())
				{
					UMaterialInterface* RestoreOverrideMaterial = Entry.OriginalOverrideMaterial.Get();
					if (RestoreOverrideMaterial && RestoreOverrideMaterial->IsA<UMaterialInstanceDynamic>())
					{
						RestoreOverrideMaterial = nullptr;
					}
					LandscapeComponent->OverrideMaterial = RestoreOverrideMaterial;
					LandscapeComponent->MarkRenderStateDirty();
				}
			}

			for (auto& Pair : LandscapeProxyEntries)
			{
				if (ALandscapeProxy* LandscapeProxy = Pair.Value.Proxy.Get())
				{
					LandscapeProxy->bUseDynamicMaterialInstance = Pair.Value.bOriginalUseDynamicMaterialInstance;
					LandscapeProxy->UpdateAllComponentMaterialInstances();
					LandscapeProxy->MarkComponentsRenderStateDirty();
				}
			}

			if (bHasAppliedMaterials)
			{
				FlushRenderingCommands();
			}
		}

		bool HasAppliedMaterials() const
		{
			return bHasAppliedMaterials;
		}

	private:
		struct FMeshEntry
		{
			TWeakObjectPtr<UPrimitiveComponent> Component;
			int32 SlotIndex = INDEX_NONE;
			TWeakObjectPtr<UMaterialInterface> OriginalMaterial;
			TWeakObjectPtr<UMaterialInstanceDynamic> OverrideMaterial;
		};

		struct FLandscapeEntry
		{
			TWeakObjectPtr<ULandscapeComponent> Component;
			TWeakObjectPtr<UMaterialInterface> OriginalOverrideMaterial;
		};

		struct FLandscapeProxyEntry
		{
			TWeakObjectPtr<ALandscapeProxy> Proxy;
			bool bOriginalUseDynamicMaterialInstance = false;
		};

		static void ConfigureMaterialParameters(
			UMaterialInstanceDynamic* Material,
			float ClampedAlbedo,
			const ASnowSimulationActor& Owner)
		{
			if (!Material)
			{
				return;
			}

			Material->SetScalarParameterValue(Owner.RadiationBenchmarkScalarAlbedoParameter, ClampedAlbedo);
			Material->SetVectorParameterValue(
				Owner.RadiationBenchmarkVectorAlbedoParameter,
				FLinearColor(ClampedAlbedo, ClampedAlbedo, ClampedAlbedo, 1.0f));
			Material->SetScalarParameterValue(TEXT("Roughness"), 1.0f);
			Material->SetScalarParameterValue(TEXT("Specular"), 0.0f);
			Material->SetScalarParameterValue(TEXT("Metallic"), 0.0f);
		}

		static void ConfigureLandscapeParameters(
			ALandscapeProxy& LandscapeProxy,
			float ClampedAlbedo,
			const ASnowSimulationActor& Owner)
		{
			LandscapeProxy.SetLandscapeMaterialScalarParameterValue(Owner.RadiationBenchmarkScalarAlbedoParameter, ClampedAlbedo);
			LandscapeProxy.SetLandscapeMaterialVectorParameterValue(
				Owner.RadiationBenchmarkVectorAlbedoParameter,
				FLinearColor(ClampedAlbedo, ClampedAlbedo, ClampedAlbedo, 1.0f));
			LandscapeProxy.SetLandscapeMaterialScalarParameterValue(TEXT("Roughness"), 1.0f);
			LandscapeProxy.SetLandscapeMaterialScalarParameterValue(TEXT("Specular"), 0.0f);
			LandscapeProxy.SetLandscapeMaterialScalarParameterValue(TEXT("Metallic"), 0.0f);
		}

		ASnowSimulationActor& OwnerRef;
		TArray<FMeshEntry> MeshEntries;
		TArray<FLandscapeEntry> LandscapeEntries;
		TMap<ALandscapeProxy*, FLandscapeProxyEntry> LandscapeProxyEntries;
		bool bHasAppliedMaterials = false;
	};

	static float ComputeMeanSnowAgeDays(const TArray<float>& Ages, const TArray<float>& DepthMeters, float DepthThresholdM)
	{
		const int32 Count = FMath::Min(Ages.Num(), DepthMeters.Num());
		if (Count <= 0)
		{
			return 0.0f;
		}

		const float Threshold = FMath::Max(0.0f, DepthThresholdM);
		double Sum = 0.0;
		int32 Num = 0;

		for (int32 i = 0; i < Count; ++i)
		{
			if (DepthMeters[i] > Threshold)
			{
				Sum += Ages[i];
				++Num;
			}
		}

		return (Num > 0) ? static_cast<float>(Sum / Num) : 0.0f;
	}

	// Mean snow surface albedo over cells with depth above threshold. Used to drive the fresh<->old
	// material blend from simulations (FSM2) whose internal state is an evolving albedo rather than
	// a "days since last snowfall" counter. Fresh-snow default returned when no cell meets the
	// threshold so the material starts bright instead of collapsing to 0.
	static float ComputeMeanSnowAlbedo(const TArray<float>& Albedos, const TArray<float>& DepthMeters, float DepthThresholdM, float FreshAlbedoDefault = 0.85f)
	{
		const int32 Count = FMath::Min(Albedos.Num(), DepthMeters.Num());
		if (Count <= 0)
		{
			return FreshAlbedoDefault;
		}

		const float Threshold = FMath::Max(0.0f, DepthThresholdM);
		double Sum = 0.0;
		int32 Num = 0;

		for (int32 i = 0; i < Count; ++i)
		{
			if (DepthMeters[i] > Threshold && Albedos[i] > 0.0f)
			{
				Sum += Albedos[i];
				++Num;
			}
		}

		return (Num > 0) ? FMath::Clamp(static_cast<float>(Sum / Num), 0.0f, 1.0f) : FreshAlbedoDefault;
	}

	/** Scoped helper that applies and automatically removes Lambertian overrides. */
	class FLambertianOverrideScope
	{
	public:
		explicit FLambertianOverrideScope(ASnowSimulationActor& Owner)
			: OwnerRef(Owner)
			, CaptureComponent(Owner.GetRadiationCaptureComponent())
		{
			if (!ShouldApplyLambertianOverride(Owner) || !CaptureComponent)
			{
				return;
			}

			if (UMaterialInterface* LoadedMaterial = ResolveLambertianOverrideMaterial(Owner))
			{
				CaptureComponent->PostProcessSettings.AddBlendable(LoadedMaterial, 1.0f);
				OverrideMaterial = LoadedMaterial;
				if (Owner.bDebugRadiationCapture)
				{
					UE_LOG(LogTemp, VeryVerbose, TEXT("[RadCapture] Applied custom Lambertian material override"));
				}
			}
			else
			{
				CaptureComponent->ShowFlags.SetReflectionEnvironment(false);
				CaptureComponent->ShowFlags.SetSpecular(false);
				bAdjustedShowFlags = true;
				if (Owner.bDebugRadiationCapture)
				{
					UE_LOG(LogTemp, VeryVerbose, TEXT("[RadCapture] Applied C++ Lambertian approximation (disable specular)"));
				}
			}
		}

		~FLambertianOverrideScope()
		{
			if (!CaptureComponent)
			{
				return;
			}

			if (OverrideMaterial.IsValid())
			{
				CaptureComponent->PostProcessSettings.RemoveBlendable(OverrideMaterial.Get());
				if (OwnerRef.bDebugRadiationCapture)
				{
					UE_LOG(LogTemp, VeryVerbose, TEXT("[RadCapture] Removed Lambertian material override"));
				}
			}

			if (bAdjustedShowFlags)
			{
				CaptureComponent->ShowFlags.SetReflectionEnvironment(true);
				CaptureComponent->ShowFlags.SetSpecular(true);
			}
		}

	private:
		ASnowSimulationActor& OwnerRef;
		USceneCaptureComponent2D* CaptureComponent = nullptr;
		TWeakObjectPtr<UMaterialInterface> OverrideMaterial;
		bool bAdjustedShowFlags = false;
	};

	bool EnsureDirectoryExists(const FString& DirectoryPath)
	{
		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
		if (PlatformFile.DirectoryExists(*DirectoryPath))
		{
			return true;
		}
		return PlatformFile.CreateDirectoryTree(*DirectoryPath);
	}

	const TCHAR* MobilityToLabel(EComponentMobility::Type Mobility)
	{
		switch (Mobility)
		{
		case EComponentMobility::Static:
			return TEXT("Static");
		case EComponentMobility::Stationary:
			return TEXT("Stationary");
		case EComponentMobility::Movable:
			return TEXT("Movable");
		default:
			return TEXT("Unknown");
		}
	}

	const TCHAR* SkyLightSourceTypeToLabel(ESkyLightSourceType SourceType)
	{
		switch (SourceType)
		{
		case SLS_CapturedScene:
			return TEXT("CapturedScene");
		case SLS_SpecifiedCubemap:
			return TEXT("SpecifiedCubemap");
		default:
			return TEXT("Unknown");
		}
	}

