		Output += FString::Printf(TEXT("%s.Fog=%d%s"), Prefix, Flags.Fog ? 1 : 0, LINE_TERMINATOR);
		Output += FString::Printf(TEXT("%s.VolumetricFog=%d%s"), Prefix, Flags.VolumetricFog ? 1 : 0, LINE_TERMINATOR);
