bool ASnowSimulationActor::ValidateMaterialParameters(UMaterialInterface* BaseMat)
{
	if (!BaseMat)
	{
		UE_LOG(LogTemp, Error, TEXT("[Snow] Material validation failed: No material provided"));
		return false;
	}

	bool bValidationPassed = true;

	// Core snow parameters (required - hard fail if missing)
	if (!HasTexParam(BaseMat, Param_SnowDepthTex))
	{
		UE_LOG(LogTemp, Error, TEXT("[Snow] Material validation failed: Missing required texture parameter '%s'"), *Param_SnowDepthTex.ToString());
		bValidationPassed = false;
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("[Snow] Material validation: Found required texture parameter '%s'"), *Param_SnowDepthTex.ToString());
	}

	if (!HasVectorParam(BaseMat, Param_SnowOriginMeters))
	{
		UE_LOG(LogTemp, Error, TEXT("[Snow] Material validation failed: Missing required vector parameter '%s'"), *Param_SnowOriginMeters.ToString());
		bValidationPassed = false;
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("[Snow] Material validation: Found required vector parameter '%s'"), *Param_SnowOriginMeters.ToString());
	}

	if (!HasVectorParam(BaseMat, Param_SnowInvSizePerMeter))
	{
		UE_LOG(LogTemp, Error, TEXT("[Snow] Material validation failed: Missing required vector parameter '%s'"), *Param_SnowInvSizePerMeter.ToString());
		bValidationPassed = false;
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("[Snow] Material validation: Found required vector parameter '%s'"), *Param_SnowInvSizePerMeter.ToString());
	}

	if (!HasScalarParam(BaseMat, Param_SnowDisplacementScale))
	{
		UE_LOG(LogTemp, Error, TEXT("[Snow] Material validation failed: Missing required scalar parameter '%s'"), *Param_SnowDisplacementScale.ToString());
		bValidationPassed = false;
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("[Snow] Material validation: Found required scalar parameter '%s'"), *Param_SnowDisplacementScale.ToString());
	}

	// Visual parameters (optional - warn but don't fail)
	if (!HasScalarParam(BaseMat, Param_AlbedoWSA))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional scalar param %s"), *Param_AlbedoWSA.ToString());
	}
	if (!HasScalarParam(BaseMat, Param_AlbedoBSA))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional scalar param %s"), *Param_AlbedoBSA.ToString());
	}
	if (!HasScalarParam(BaseMat, Param_RoughnessBase))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional scalar param %s"), *Param_RoughnessBase.ToString());
	}
	if (!HasScalarParam(BaseMat, Param_SparkleIntensity))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional scalar param %s"), *Param_SparkleIntensity.ToString());
	}
	if (!HasScalarParam(BaseMat, Param_SparkleScale))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional scalar param %s"), *Param_SparkleScale.ToString());
	}
	if (!HasScalarParam(BaseMat, Param_SnowAgeDays))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional scalar param %s"), *Param_SnowAgeDays.ToString());
	}
	if (!HasTexParam(BaseMat, Param_SnowAlbedoTex))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional texture param %s"), *Param_SnowAlbedoTex.ToString());
	}
	if (!HasScalarParam(BaseMat, Param_SnowAlbedoMean))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional scalar param %s"), *Param_SnowAlbedoMean.ToString());
	}
	if (!HasScalarParam(BaseMat, Param_Grain_um))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional scalar param %s"), *Param_Grain_um.ToString());
	}
	if (!HasScalarParam(BaseMat, Param_Impurity_ppm))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] Material missing optional scalar param %s"), *Param_Impurity_ppm.ToString());
	}

	return bValidationPassed;
}

void ASnowSimulationActor::StepSimulation(float dtSeconds)
{
	// Accumulate simulated seconds towards weather step size
	SimulatedSecondsAccumulator += dtSeconds;

	if (SimulatedSecondsAccumulator + 1e-6f < TimeStepSeconds)
	{
		return;
	}

	int32 NumSteps = FMath::Max(1, FMath::FloorToInt(SimulatedSecondsAccumulator / TimeStepSeconds));
	SimulatedSecondsAccumulator -= NumSteps * TimeStepSeconds;

	static bool bLoggedWeatherUnits = false;

	for (int32 StepIdx = 0; StepIdx < NumSteps; ++StepIdx)
	{
		FWeatherForcingData WeatherForcing;
			if (WeatherProvider)
			{
				WeatherForcing = WeatherProvider->GetWeatherForcing(CurrentSimulationTime);
			}

		if (bEnableDebugLogging && !bLoggedWeatherUnits)
		{
			UE_LOG(LogTemp, Display, TEXT("[Snow] Weather units: T(K)=%.1f, SWdown(W/m²)=%.0f, LWdown(W/m²)=%.0f, Wind(m/s)=%.1f, RH(0-1)=%.2f, PrecipRate(kg/m²/s)=%.6f, SnowFrac(0-1)=%.2f"),
			   WeatherForcing.Temperature_K, WeatherForcing.SWdown_Wm2, WeatherForcing.LWdown_Wm2,
			   WeatherForcing.Wind_mps, WeatherForcing.RH_01, WeatherForcing.PrecipRate_kgm2s, WeatherForcing.SnowFrac_01);
			bLoggedWeatherUnits = true;
		}

		if (Simulation)
		{
			// If the simulation derives from USnowSimulation, use its Step/Upload path
			if (USnowSimulation* SnowSim = Cast<USnowSimulation>(Simulation))
			{
				SnowSim->Step(TimeStepSeconds, WeatherForcing, SnowSim->DepthMeters);
				SnowSim->UploadDepthToTexture();
				
				// Sync CPU buffer with simulation data for HUD display
				UpdateCpuDepthMeters(SnowSim->DepthMeters);
				const TArray<float> SimAlbedo = SnowSim->GetCellSnowAlbedoState();
				if (SimAlbedo.Num() == CellsDimensionX * CellsDimensionY)
				{
					UpdateCpuAlbedo(SimAlbedo);
					SnowAlbedoMean = ComputeMeanSnowAlbedo(SimAlbedo, SnowSim->DepthMeters, SnowAgeDepthThreshold_m);
				}
				
				// Stats logging for visibility
				float MinV = FLT_MAX, MaxV = -FLT_MAX; double Sum = 0.0; int32 Count = SnowSim->DepthMeters.Num();
				for (int32 i = 0; i < Count; ++i) { float v = SnowSim->DepthMeters[i]; MinV = FMath::Min(MinV, v); MaxV = FMath::Max(MaxV, v); Sum += v; }
				float Mean = (Count > 0) ? static_cast<float>(Sum / Count) : 0.0f;
				if (bEnableDebugLogging)
				{
					UE_LOG(LogTemp, Display, TEXT("[Snow] DepthTex min=%.4f m, max=%.4f m, mean=%.4f m"), MinV, MaxV, Mean);

					// Log HUD stats for CPU buffer
					if (CpuDepthMeters.Num() > 0)
					{
						float CpuMinV = FLT_MAX, CpuMaxV = -FLT_MAX;
						for (int32 i = 0; i < CpuDepthMeters.Num(); ++i) 
						{ 
							const float v = CpuDepthMeters[i]; 
							CpuMinV = FMath::Min(CpuMinV, v); 
							CpuMaxV = FMath::Max(CpuMaxV, v); 
						}
						UE_LOG(LogTemp, Display, TEXT("[Snow][HUD] CPUbuf min/max(mm)=%.1f/%.1f, tex size=%dx%d"), 
							CpuMinV * 1000.0f, CpuMaxV * 1000.0f, CellsDimensionX, CellsDimensionY);
					}
				}
			}
			else
			{
				// Fallback to legacy Simulate API
				Simulation->Simulate(this, this->CurrentSimulationStep, Timesteps, SaveMaterialTextures, IsDebugOverlayActive(), DebugCells);
				if (Landscape)
				{
					SetScalarParameterValue(Landscape, Param_MaxSnow, Simulation->GetMaxSnow());
				}
			}
		}

		CurrentSimulationTime += FTimespan(0, 0, 0, 0, FMath::RoundToInt(TimeStepSeconds));
		this->CurrentSimulationStep += FMath::RoundToInt(TimeStepSeconds / 3600.0f);

        		if (bLoopTime && CurrentSimulationTime >= EndTime)
		{
			CurrentSimulationTime = StartTime;
			this->CurrentSimulationStep = 0;
			if (bEnableDebugLogging)
			{
				UE_LOG(LogTemp, Display, TEXT("[Snow] Time looped back to start"));
			}
		}
	}

	// After steps, update material instance parameters using the current snow map texture
	UpdateMaterialTexture();
}

void ASnowSimulationActor::LogDepthStats()
{
	if (CpuDepthMeters.Num() == 0) return;
	float MinV = FLT_MAX;
	float MaxV = -FLT_MAX;
	double Sum = 0.0;
	int32 Count = CpuDepthMeters.Num();
	for (int32 i = 0; i < Count; ++i)
	{
		float v = CpuDepthMeters[i];
		MinV = FMath::Min(MinV, v);
		MaxV = FMath::Max(MaxV, v);
		Sum += v;
	}
	float Mean = static_cast<float>(Sum / FMath::Max(1, Count));
	UE_LOG(LogTemp, Display, TEXT("[Snow] DepthTex min=%.4f m, max=%.4f m, mean=%.4f m"), MinV, MaxV, Mean);
}

void ASnowSimulationActor::UploadDepthToTexture()
{
	if (CpuDepthMeters.Num() != CellsDimensionX * CellsDimensionY)
	{
		return;
	}

	if (!SnowDepthTexture)
	{
		SnowDepthTexture = UTexture2D::CreateTransient(CellsDimensionX, CellsDimensionY, EPixelFormat::PF_R16F);
		SnowDepthTexture->SRGB = false;
		SnowDepthTexture->CompressionSettings = TC_HDR;
		SnowDepthTexture->LODGroup = TEXTUREGROUP_Pixels2D;
		SnowDepthTexture->MipLoadOptions = ETextureMipLoadOptions::OnlyFirstMip;
		SnowDepthTexture->VirtualTextureStreaming = false;
		SnowDepthTexture->LODBias = 0;
#if WITH_EDITORONLY_DATA
		SnowDepthTexture->MipGenSettings = TMGS_NoMipmaps;
#endif
		SnowDepthTexture->AddressX = TA_Clamp;
		SnowDepthTexture->AddressY = TA_Clamp;
		SnowDepthTexture->Filter = TF_Nearest;
		SnowDepthTexture->UpdateResource();
		
		// One-time log after texture creation
		UE_LOG(LogTemp, Display, TEXT("[Snow] Created SnowDepthTexture: PF=%s, sRGB=%s, size=%dx%d, Filter=Nearest, MipLoad=OnlyFirstMip"),
			*UEnum::GetValueAsString(SnowDepthTexture->GetPixelFormat()),
			SnowDepthTexture->SRGB ? TEXT("true") : TEXT("false"),
			SnowDepthTexture->GetSizeX(), SnowDepthTexture->GetSizeY());
	}

	bool bDepthTexturePolicyChanged = false;
	if (SnowDepthTexture)
	{
		if (SnowDepthTexture->MipLoadOptions != ETextureMipLoadOptions::OnlyFirstMip)
		{
			SnowDepthTexture->MipLoadOptions = ETextureMipLoadOptions::OnlyFirstMip;
			bDepthTexturePolicyChanged = true;
		}
		if (SnowDepthTexture->VirtualTextureStreaming)
		{
			SnowDepthTexture->VirtualTextureStreaming = false;
			bDepthTexturePolicyChanged = true;
		}
		if (SnowDepthTexture->LODBias != 0)
		{
			SnowDepthTexture->LODBias = 0;
			bDepthTexturePolicyChanged = true;
		}
#if WITH_EDITORONLY_DATA
		if (SnowDepthTexture->MipGenSettings != TMGS_NoMipmaps)
		{
			SnowDepthTexture->MipGenSettings = TMGS_NoMipmaps;
			bDepthTexturePolicyChanged = true;
		}
#endif
		if (SnowDepthTexture->Filter != TF_Nearest)
		{
			SnowDepthTexture->Filter = TF_Nearest;
			bDepthTexturePolicyChanged = true;
		}
		if (bDepthTexturePolicyChanged)
		{
			SnowDepthTexture->UpdateResource();
		}
	}

	UTexture2D* TextureToUpdate = SnowDepthTexture;
	// Upload with correct half-float stride using UpdateTextureRegions
	FUpdateTextureRegion2D* Region = new FUpdateTextureRegion2D(0, 0, 0, 0, CellsDimensionX, CellsDimensionY);
	const uint32 SrcBpp = sizeof(FFloat16);
	const uint32 SrcPitch = CellsDimensionX * sizeof(FFloat16);
	// Allocate heap buffer; copy half values
	const int32 Count = CellsDimensionX * CellsDimensionY;
	FFloat16* HalfData = new FFloat16[Count];
	for (int32 i = 0; i < Count; ++i)
	{
		HalfData[i] = CpuDepthMeters.IsValidIndex(i) ? CpuDepthMeters[i] : FFloat16(0.0f);
	}
	auto Cleanup = [](uint8* SrcData, const FUpdateTextureRegion2D* Regions)
	{
		delete[] reinterpret_cast<FFloat16*>(SrcData);
		delete Regions;
	};
	TextureToUpdate->UpdateTextureRegions(0, 1, Region, SrcPitch, SrcBpp, reinterpret_cast<uint8*>(HalfData), Cleanup);

	// Bind for preview and log stats
	if (Landscape)
	{
		SetTextureParameterValue(Landscape, Param_SnowDepthTex, SnowDepthTexture, GEngine);
		UE_LOG(LogTemp, Display, TEXT("[Snow] Landscape SetParam SnowDepthTex=Texture"));
	}
	LogDepthStats();
}

bool ASnowSimulationActor::ShouldUploadAlbedoTexture() const
{
	return bEnableRadiationCapture || SaveMaterialTextures;
}

void ASnowSimulationActor::UploadAlbedoToTexture()
{
	if (!ShouldUploadAlbedoTexture())
	{
		return;
	}

	if (CpuAlbedo.Num() != CellsDimensionX * CellsDimensionY)
	{
		return;
	}

	const bool bNeedsRecreateAlbedoTexture =
		!SnowAlbedoTexture
		|| SnowAlbedoTexture->GetSizeX() != CellsDimensionX
		|| SnowAlbedoTexture->GetSizeY() != CellsDimensionY
		|| SnowAlbedoTexture->GetPixelFormat() != PF_B8G8R8A8;

	if (bNeedsRecreateAlbedoTexture)
	{
		SnowAlbedoTexture = UTexture2D::CreateTransient(CellsDimensionX, CellsDimensionY, EPixelFormat::PF_B8G8R8A8);
		SnowAlbedoTexture->SRGB = false;
		SnowAlbedoTexture->CompressionSettings = TC_Default;
		SnowAlbedoTexture->LODGroup = TEXTUREGROUP_Pixels2D;
		SnowAlbedoTexture->MipLoadOptions = ETextureMipLoadOptions::OnlyFirstMip;
		SnowAlbedoTexture->VirtualTextureStreaming = false;
		SnowAlbedoTexture->LODBias = 0;
#if WITH_EDITORONLY_DATA
		SnowAlbedoTexture->MipGenSettings = TMGS_NoMipmaps;
#endif
		SnowAlbedoTexture->AddressX = TA_Clamp;
		SnowAlbedoTexture->AddressY = TA_Clamp;
		SnowAlbedoTexture->Filter = TF_Nearest;
		SnowAlbedoTexture->UpdateResource();

		UE_LOG(LogTemp, Display, TEXT("[Snow] Created SnowAlbedoTexture: PF=%s, sRGB=%s, size=%dx%d, Filter=Nearest, MipLoad=OnlyFirstMip"),
			*UEnum::GetValueAsString(SnowAlbedoTexture->GetPixelFormat()),
			SnowAlbedoTexture->SRGB ? TEXT("true") : TEXT("false"),
			SnowAlbedoTexture->GetSizeX(), SnowAlbedoTexture->GetSizeY());
	}

	bool bAlbedoTexturePolicyChanged = false;
	if (SnowAlbedoTexture)
	{
		if (SnowAlbedoTexture->MipLoadOptions != ETextureMipLoadOptions::OnlyFirstMip)
		{
			SnowAlbedoTexture->MipLoadOptions = ETextureMipLoadOptions::OnlyFirstMip;
			bAlbedoTexturePolicyChanged = true;
		}
		if (SnowAlbedoTexture->VirtualTextureStreaming)
		{
			SnowAlbedoTexture->VirtualTextureStreaming = false;
			bAlbedoTexturePolicyChanged = true;
		}
		if (SnowAlbedoTexture->LODBias != 0)
		{
			SnowAlbedoTexture->LODBias = 0;
			bAlbedoTexturePolicyChanged = true;
		}
#if WITH_EDITORONLY_DATA
		if (SnowAlbedoTexture->MipGenSettings != TMGS_NoMipmaps)
		{
			SnowAlbedoTexture->MipGenSettings = TMGS_NoMipmaps;
			bAlbedoTexturePolicyChanged = true;
		}
#endif
		if (SnowAlbedoTexture->Filter != TF_Nearest)
		{
			SnowAlbedoTexture->Filter = TF_Nearest;
			bAlbedoTexturePolicyChanged = true;
		}
		if (bAlbedoTexturePolicyChanged)
		{
			SnowAlbedoTexture->UpdateResource();
		}
	}

	UTexture2D* TextureToUpdate = SnowAlbedoTexture;
	FUpdateTextureRegion2D* Region = new FUpdateTextureRegion2D(0, 0, 0, 0, CellsDimensionX, CellsDimensionY);
	const uint32 SrcBpp = sizeof(FColor);
	const uint32 SrcPitch = CellsDimensionX * sizeof(FColor);
	const int32 Count = CellsDimensionX * CellsDimensionY;
	FColor* ColorData = new FColor[Count];
	float MinAlbedo = FLT_MAX;
	float MaxAlbedo = -FLT_MAX;
	double SumAlbedo = 0.0;
	for (int32 i = 0; i < Count; ++i)
	{
		const float AlbedoValue = CpuAlbedo.IsValidIndex(i) ? static_cast<float>(CpuAlbedo[i]) : 0.0f;
		MinAlbedo = FMath::Min(MinAlbedo, AlbedoValue);
		MaxAlbedo = FMath::Max(MaxAlbedo, AlbedoValue);
		SumAlbedo += AlbedoValue;
		const uint8 Gray = static_cast<uint8>(FMath::RoundToInt(FMath::Clamp(AlbedoValue, 0.0f, 1.0f) * 255.0f));
		ColorData[i] = FColor(Gray, Gray, Gray, Gray);
	}
	auto Cleanup = [](uint8* SrcData, const FUpdateTextureRegion2D* Regions)
	{
		delete[] reinterpret_cast<FColor*>(SrcData);
		delete Regions;
	};
	TextureToUpdate->UpdateTextureRegions(0, 1, Region, SrcPitch, SrcBpp, reinterpret_cast<uint8*>(ColorData), Cleanup);

	if (!bLoggedInitialAlbedoUpload)
	{
		const float MeanAlbedo = Count > 0 ? static_cast<float>(SumAlbedo / static_cast<double>(Count)) : 0.0f;
		UE_LOG(LogTemp, Warning,
			TEXT("[Snow][AlbedoTex] Upload size=%dx%d pf=%s min=%.4f max=%.4f mean=%.4f"),
			CellsDimensionX, CellsDimensionY,
			*UEnum::GetValueAsString(TextureToUpdate->GetPixelFormat()),
			Count > 0 ? MinAlbedo : 0.0f,
			Count > 0 ? MaxAlbedo : 0.0f,
			MeanAlbedo);
		bLoggedInitialAlbedoUpload = true;
	}

	// Bind albedo texture to landscape for preview
	if (Landscape)
	{
		SetTextureParameterValue(Landscape, Param_SnowAlbedoTex, SnowAlbedoTexture, GEngine);
		UE_LOG(LogTemp, Display, TEXT("[Snow] Landscape SetParam SnowAlbedoTex=Texture"));
	}
}

float ASnowSimulationActor::SampleSunCosine() const
{
	if (const UDirectionalLightComponent* SunLight = GetSunDirectionalLight())
	{
		const FVector SunDir = SunLight->GetDirection();
		return FMath::Clamp(-SunDir.Z, 0.0f, 1.0f);
	}

	return 0.0f;
}

float ASnowSimulationActor::EvaluateSunVisibility(float CosZenith) const
{
	if (CosZenith <= 0.0f)
	{
		return 0.0f;
	}

	const float ThresholdCos = GetSunVisibilityThresholdCos();
	if (ThresholdCos <= KINDA_SMALL_NUMBER)
	{
		return 1.0f;
	}

	const float Normalized = CosZenith / ThresholdCos;
	return FMath::Clamp(Normalized, 0.0f, 1.0f);
}

float ASnowSimulationActor::GetSunVisibilityThresholdCos() const
{
	if (RadiationSunVisibilityThreshold <= KINDA_SMALL_NUMBER)
	{
		return 0.0f;
	}

	const float ClampedDeg = FMath::Clamp(RadiationSunVisibilityThreshold, 0.0f, 90.0f);
	const float ThresholdCos = FMath::Sin(FMath::DegreesToRadians(ClampedDeg));
	return FMath::Max(ThresholdCos, 1e-4f);
}

void ASnowSimulationActor::DebugFillDepth(float MaxDepthMeters /*= 0.2f*/)
{
#if !UE_BUILD_SHIPPING
	if (!GIsEditor)
	{
		checkf(false, TEXT("Debug depth writer is active — disable before shipping."));
		return;
	}
#else
	checkf(false, TEXT("Debug depth writer is active — disable before shipping."));
	return;
#endif

	if (CellsDimensionX <= 0 || CellsDimensionY <= 0)
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] DebugFillDepth: invalid dimensions."));
		return;
	}

	if (USnowSimulation* SnowSim = Cast<USnowSimulation>(Simulation))
	{
		// Fill a linear X ramp into the sim's depth buffer and upload
		TArray<float>& H = SnowSim->DepthMeters;
		const int32 Wd = SnowSim->GridX;
		const int32 Hg = SnowSim->GridY;
		if (H.Num() == Wd * Hg && Wd > 1)
		{
			for (int32 y = 0; y < Hg; ++y)
			{
				for (int32 x = 0; x < Wd; ++x)
				{
					H[y * Wd + x] = (static_cast<float>(x) / static_cast<float>(Wd - 1)) * MaxDepthMeters;
				}
			}
			SnowSim->UploadDepthToTexture();
			UpdateMaterialTexture();
			UE_LOG(LogTemp, Display, TEXT("[Snow] DebugFillDepth max=%.3f m"), MaxDepthMeters);
		}
		return;
	}

	// Fallback: keep old local gradient path
	CpuDepthMeters.SetNum(CellsDimensionX * CellsDimensionY, EAllowShrinking::No);
	const float CenterX = (CellsDimensionX - 1) * 0.5f;
	const float CenterY = (CellsDimensionY - 1) * 0.5f;
	const float MaxRadius = FMath::Sqrt(CenterX * CenterX + CenterY * CenterY);
	for (int32 y = 0; y < CellsDimensionY; ++y)
	{
		for (int32 x = 0; x < CellsDimensionX; ++x)
		{
			float dx = (float)x - CenterX;
			float dy = (float)y - CenterY;
			float r = FMath::Sqrt(dx*dx + dy*dy);
			float t = FMath::Clamp(r / MaxRadius, 0.0f, 1.0f);
			CpuDepthMeters[y * CellsDimensionX + x] = t * MaxDepthMeters;
		}
	}
	UploadDepthToTexture();
	UpdateMaterialTexture();
}

void ASnowSimulationActor::PrintStatus()
{
	UE_LOG(LogTemp, Display, TEXT("=== SNOW SIMULATION STATUS ==="));
	
	// Provider/Simulation classes in use
	UE_LOG(LogTemp, Display, TEXT("Provider: %s"), 
		WeatherProvider ? *WeatherProvider->GetClass()->GetName() : TEXT("None"));
	UE_LOG(LogTemp, Display, TEXT("Simulation: %s"), 
		Simulation ? *Simulation->GetClass()->GetName() : TEXT("None"));
	
	// Grid information
	if (Landscape)
	{
		FVector LandscapeMin = Landscape->GetActorLocation();
		FVector LocalLandscapeScale = Landscape->GetActorScale();
		float OriginX_m = LandscapeMin.X / 100.0f;
		float OriginY_m = LandscapeMin.Y / 100.0f;
		float WidthMeters = CellsDimensionX * MetersPerCell;
		float HeightMeters = CellsDimensionY * MetersPerCell;
		FVector2D CellDomainOriginMeters;
		FVector2D CellDomainSizeMeters;
		FVector2D MinCellCentroidMeters;
		FVector2D MaxCellCentroidMeters;
		if (ComputeLandscapeCellAxisAlignedDomainMeters(
			LandscapeCells,
			MetersPerCell,
			CellDomainOriginMeters,
			CellDomainSizeMeters,
			MinCellCentroidMeters,
			MaxCellCentroidMeters))
		{
			OriginX_m = CellDomainOriginMeters.X;
			OriginY_m = CellDomainOriginMeters.Y;
			WidthMeters = CellDomainSizeMeters.X;
			HeightMeters = CellDomainSizeMeters.Y;
		}
		float CellSizeMeters = MetersPerCell;
		
		UE_LOG(LogTemp, Display, TEXT("Grid Origin: (%.3f, %.3f) m"), OriginX_m, OriginY_m);
		UE_LOG(LogTemp, Display, TEXT("Grid Size: %.3f x %.3f m"), WidthMeters, HeightMeters);
		UE_LOG(LogTemp, Display, TEXT("Cells: %d x %d"), CellsDimensionX, CellsDimensionY);
		UE_LOG(LogTemp, Display, TEXT("Cell Size: %.3f m"), CellSizeMeters);
		UE_LOG(LogTemp, Display, TEXT("LandscapeScale: (%.3f, %.3f, %.3f)"), LocalLandscapeScale.X, LocalLandscapeScale.Y, LocalLandscapeScale.Z);
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("Grid: No landscape found"));
	}
	
	// Material parameter values
	if (VHMMaterialInstance)
	{
		FLinearColor OriginMeters, InvSizePerMeter;
		float DisplacementScale;
		
		VHMMaterialInstance->GetVectorParameterValue(Param_SnowOriginMeters, OriginMeters);
		VHMMaterialInstance->GetVectorParameterValue(Param_SnowInvSizePerMeter, InvSizePerMeter);
		VHMMaterialInstance->GetScalarParameterValue(Param_SnowDisplacementScale, DisplacementScale);
		
		UE_LOG(LogTemp, Display, TEXT("VHM Material Params:"));
		UE_LOG(LogTemp, Display, TEXT("  SnowOriginMeters: (%.6f, %.6f)"), OriginMeters.R, OriginMeters.G);
		UE_LOG(LogTemp, Display, TEXT("  SnowInvSizePerMeter: (%.8f, %.8f)"), InvSizePerMeter.R, InvSizePerMeter.G);
		UE_LOG(LogTemp, Display, TEXT("  SnowDisplacementScale: %.3f"), DisplacementScale);
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("VHM Material: Not bound"));
	}
	
	if (SnowMID)
	{
		FLinearColor OriginMeters, InvSizePerMeter;
		float DisplacementScale;
		
		SnowMID->GetVectorParameterValue(Param_SnowOriginMeters, OriginMeters);
		SnowMID->GetVectorParameterValue(Param_SnowInvSizePerMeter, InvSizePerMeter);
		SnowMID->GetScalarParameterValue(Param_SnowDisplacementScale, DisplacementScale);
		
		UE_LOG(LogTemp, Display, TEXT("SnowMID Material Params:"));
		UE_LOG(LogTemp, Display, TEXT("  SnowOriginMeters: (%.6f, %.6f)"), OriginMeters.R, OriginMeters.G);
		UE_LOG(LogTemp, Display, TEXT("  SnowInvSizePerMeter: (%.8f, %.8f)"), InvSizePerMeter.R, InvSizePerMeter.G);
		UE_LOG(LogTemp, Display, TEXT("  SnowDisplacementScale: %.3f"), DisplacementScale);
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("SnowMID Material: Not created"));
	}
	
	// Depth statistics (CPU-side if available)
	if (CpuDepthMeters.Num() > 0)
	{
		float MinV = FLT_MAX, MaxV = -FLT_MAX;
		double Sum = 0.0;
		int32 Count = CpuDepthMeters.Num();
		
		for (int32 i = 0; i < Count; ++i)
		{
			const float v = CpuDepthMeters[i];
			MinV = FMath::Min(MinV, v);
			MaxV = FMath::Max(MaxV, v);
			Sum += v;
		}
		
		float Mean = (Count > 0) ? static_cast<float>(Sum / Count) : 0.0f;
		UE_LOG(LogTemp, Display, TEXT("CPU Depth Stats: min=%.4f m, max=%.4f m, mean=%.4f m"), MinV, MaxV, Mean);
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("CPU Depth Stats: No data available"));
	}
	
	// Simulation-specific depth stats
	if (USnowSimulation* SnowSim = Cast<USnowSimulation>(Simulation))
	{
		if (SnowSim->DepthMeters.Num() > 0)
		{
			float MinV = FLT_MAX, MaxV = -FLT_MAX;
			double Sum = 0.0;
			int32 Count = SnowSim->DepthMeters.Num();
			
			for (int32 i = 0; i < Count; ++i)
			{
				const float v = SnowSim->DepthMeters[i];
				MinV = FMath::Min(MinV, v);
				MaxV = FMath::Max(MaxV, v);
				Sum += v;
			}
			
			float Mean = (Count > 0) ? static_cast<float>(Sum / Count) : 0.0f;
			UE_LOG(LogTemp, Display, TEXT("Simulation Depth Stats: min=%.4f m, max=%.4f m, mean=%.4f m"), MinV, MaxV, Mean);
		}
		else
		{
			UE_LOG(LogTemp, Display, TEXT("Simulation Depth Stats: No data available"));
		}
	}
	
	UE_LOG(LogTemp, Display, TEXT("=== END STATUS ==="));
}

void ASnowSimulationActor::UpdateCpuDepthMeters(const TArray<float>& InDepthMeters)
{
	const int32 TotalCells = CellsDimensionX * CellsDimensionY;

	if (InDepthMeters.Num() != TotalCells)
	{
		UE_LOG(LogTemp, Warning, TEXT("[Snow] UpdateCpuDepthMeters mismatch: In=%d, TotalCells=%d"), InDepthMeters.Num(), TotalCells);
		// If mismatch is due to uninitialized CPU buffer, resize it
		if (CpuDepthMeters.Num() != TotalCells)
		{
			CpuDepthMeters.SetNumZeroed(TotalCells);
		}
		
		// If input is still wrong, abort
		if (InDepthMeters.Num() != TotalCells)
		{
			return;
		}
	}

	if (CpuDepthMeters.Num() != TotalCells)
	{
		CpuDepthMeters.SetNumUninitialized(TotalCells);
	}

	for (int32 i = 0; i < TotalCells; ++i)
	{
		CpuDepthMeters[i] = FFloat16(InDepthMeters.IsValidIndex(i) ? InDepthMeters[i] : 0.0f);
	}

	UploadDepthToTexture();
}

void ASnowSimulationActor::ApplyDepthSnapshotToRuntime(const TArray<float>& SnapshotDepthMeters, const FDateTime& TargetTime, const TCHAR* SourceLabel)
{
	const int32 TotalCells = CellsDimensionX * CellsDimensionY;
	const TCHAR* SnapshotSource = SourceLabel ? SourceLabel : TEXT("unknown");
	if (SnapshotDepthMeters.Num() != TotalCells)
	{
		UE_LOG(LogTemp, Warning,
			TEXT("[Snow] ApplyDepthSnapshotToRuntime(%s, %s): snapshot cells=%d but grid cells=%d; skipping restore."),
			*TargetTime.ToString(), SnapshotSource, SnapshotDepthMeters.Num(), TotalCells);
		return;
	}

	// Keep probe placement, diagnostics, and the rendered VHM/material snow surface on the same depth snapshot.
	UpdateCpuDepthMeters(SnapshotDepthMeters);

	bool bSyncedSimulationTexture = false;
	if (USnowSimulation* SnowSim = Cast<USnowSimulation>(Simulation))
	{
		if (SnowSim->GridX == CellsDimensionX && SnowSim->GridY == CellsDimensionY)
		{
			SnowSim->DepthMeters = SnapshotDepthMeters;
			SnowSim->EnsureSnowTexture(CellsDimensionX, CellsDimensionY, PF_R16F);
			SnowSim->UploadDepthToTexture();
			bSyncedSimulationTexture = true;
		}
		else
		{
			UE_LOG(LogTemp, Warning,
				TEXT("[Snow] ApplyDepthSnapshotToRuntime(%s, %s): simulation grid %dx%d does not match actor grid %dx%d; rendered snow texture not restored."),
				*TargetTime.ToString(), SnapshotSource,
				SnowSim->GridX, SnowSim->GridY, CellsDimensionX, CellsDimensionY);
		}
	}

	if (!bSyncedSimulationTexture && Simulation)
	{
		UE_LOG(LogTemp, Warning,
			TEXT("[Snow] ApplyDepthSnapshotToRuntime(%s, %s): simulation class %s does not expose a USnowSimulation depth texture; probe and rendered snow depths may diverge."),
			*TargetTime.ToString(), SnapshotSource, *Simulation->GetClass()->GetName());
	}

	UpdateMaterialTexture();
	FlushRenderingCommands();

	UE_LOG(LogTemp, Display,
		TEXT("[Snow] Applied depth snapshot to runtime (%s) for TargetTime=%s: cells=%d, simTextureSynced=%s"),
		SnapshotSource, *TargetTime.ToString(), TotalCells, bSyncedSimulationTexture ? TEXT("true") : TEXT("false"));
}

FString ASnowSimulationActor::GetDepthSnapshotCachePath(const FDateTime& TargetTime) const
{
	// Keyed by date + grid size so a cache file from a different grid is never loaded.
	const FString Filename = FString::Printf(
		TEXT("SnowDepth_%s_%dx%d.depthbin"),
		*TargetTime.ToString(TEXT("%Y%m%d_%H%M%S")),
		CellsDimensionX,
		CellsDimensionY);
	return FPaths::ProjectSavedDir() / TEXT("SnowDepthSnapshots") / Filename;
}

void ASnowSimulationActor::CacheDepthSnapshotForTargetTime(const FDateTime& TargetTime)
{
	const int32 TotalCells = CellsDimensionX * CellsDimensionY;
	if (TotalCells <= 0)
	{
		return;
	}

	TArray<float> Snapshot;
	Snapshot.SetNumUninitialized(TotalCells);

	const USnowSimulation* SnowSim = Cast<USnowSimulation>(Simulation);
	const UDegreeDaySimulation* DegreeDay = Cast<UDegreeDaySimulation>(Simulation);
	bool bFilled = false;
	if (SnowSim && SnowSim->DepthMeters.Num() == TotalCells)
	{
		FMemory::Memcpy(Snapshot.GetData(), SnowSim->DepthMeters.GetData(), TotalCells * sizeof(float));
		bFilled = true;
	}
	else if (DegreeDay && DegreeDay->DepthMeters.Num() == TotalCells)
	{
		FMemory::Memcpy(Snapshot.GetData(), DegreeDay->DepthMeters.GetData(), TotalCells * sizeof(float));
		bFilled = true;
	}
	else if (CpuDepthMeters.Num() == TotalCells)
	{
		for (int32 i = 0; i < TotalCells; ++i)
		{
			Snapshot[i] = float(CpuDepthMeters[i]);
		}
		bFilled = true;
	}

	if (!bFilled)
	{
		UE_LOG(LogTemp, Warning,
			TEXT("[Snow] CacheDepthSnapshotForTargetTime(%s): no valid depth source; snapshot not stored."),
			*TargetTime.ToString());
		return;
	}

	float SnapMin = FLT_MAX, SnapMax = -FLT_MAX;
	for (float V : Snapshot) { SnapMin = FMath::Min(SnapMin, V); SnapMax = FMath::Max(SnapMax, V); }

	// Persist to disk so the snapshot survives editor session restarts.
	{
		const FString CachePath = GetDepthSnapshotCachePath(TargetTime);
		IFileManager::Get().MakeDirectory(*FPaths::GetPath(CachePath), /*Tree=*/true);

		TArray<uint8> FileBytes;
		FileBytes.SetNumUninitialized(sizeof(int32) + TotalCells * sizeof(float));
		*reinterpret_cast<int32*>(FileBytes.GetData()) = TotalCells;
		FMemory::Memcpy(FileBytes.GetData() + sizeof(int32), Snapshot.GetData(), TotalCells * sizeof(float));

		if (FFileHelper::SaveArrayToFile(FileBytes, *CachePath))
		{
			UE_LOG(LogTemp, Display,
				TEXT("[Snow] Depth snapshot persisted to disk: %s"), *CachePath);
		}
		else
		{
			UE_LOG(LogTemp, Warning,
				TEXT("[Snow] CacheDepthSnapshotForTargetTime: failed to write disk cache at %s"), *CachePath);
		}
	}

	DepthSnapshotsByTargetTime.Add(TargetTime, MoveTemp(Snapshot));

	UE_LOG(LogTemp, Display,
		TEXT("[Snow] Cached depth snapshot for TargetTime=%s  min=%.4f m  max=%.4f m  cells=%d"),
		*TargetTime.ToString(), SnapMin, SnapMax, TotalCells);
}

bool ASnowSimulationActor::RestoreDepthSnapshotForTargetTime(const FDateTime& TargetTime)
{
	// Check in-memory cache first (populated during the same session's sim tick).
	const TArray<float>* Snapshot = DepthSnapshotsByTargetTime.Find(TargetTime);
	if (Snapshot)
	{
		ApplyDepthSnapshotToRuntime(*Snapshot, TargetTime, TEXT("memory"));
		float RestMin = FLT_MAX, RestMax = -FLT_MAX;
		for (float V : *Snapshot) { RestMin = FMath::Min(RestMin, V); RestMax = FMath::Max(RestMax, V); }
		UE_LOG(LogTemp, Display,
			TEXT("[Snow] Restored depth snapshot (memory) for TargetTime=%s  min=%.4f m  max=%.4f m"),
			*TargetTime.ToString(), RestMin, RestMax);
		return true;
	}

	// Fall back to the disk cache written by a previous sim run.
	const FString CachePath = GetDepthSnapshotCachePath(TargetTime);
	TArray<uint8> FileBytes;
	if (FFileHelper::LoadFileToArray(FileBytes, *CachePath))
	{
		const int32 TotalCells = CellsDimensionX * CellsDimensionY;
		const int32 ExpectedBytes = sizeof(int32) + TotalCells * sizeof(float);
		if (FileBytes.Num() == ExpectedBytes)
		{
			const int32 SavedCount = *reinterpret_cast<const int32*>(FileBytes.GetData());
			if (SavedCount == TotalCells)
			{
				TArray<float> LoadedSnapshot;
				LoadedSnapshot.SetNumUninitialized(TotalCells);
				FMemory::Memcpy(LoadedSnapshot.GetData(), FileBytes.GetData() + sizeof(int32), TotalCells * sizeof(float));

				float RestMin = FLT_MAX, RestMax = -FLT_MAX;
				for (float V : LoadedSnapshot) { RestMin = FMath::Min(RestMin, V); RestMax = FMath::Max(RestMax, V); }
				UE_LOG(LogTemp, Display,
					TEXT("[Snow] Restored depth snapshot (disk) for TargetTime=%s  min=%.4f m  max=%.4f m  path=%s"),
					*TargetTime.ToString(), RestMin, RestMax, *CachePath);

				ApplyDepthSnapshotToRuntime(LoadedSnapshot, TargetTime, TEXT("disk"));
				DepthSnapshotsByTargetTime.Add(TargetTime, MoveTemp(LoadedSnapshot));
				return true;
			}
		}
		UE_LOG(LogTemp, Warning,
			TEXT("[Snow] RestoreDepthSnapshotForTargetTime(%s): disk cache at %s is corrupt or mismatched (file=%d bytes, expected=%d)."),
			*TargetTime.ToString(), *CachePath, FileBytes.Num(), ExpectedBytes);
	}

	UE_LOG(LogTemp, Warning,
		TEXT("[Snow] RestoreDepthSnapshotForTargetTime(%s): no snapshot in memory or on disk (%s). "
		     "Run the simulation past this date with ExportTargetTimesteps populated to build the cache."),
		*TargetTime.ToString(), *CachePath);
	return false;
}

void ASnowSimulationActor::UpdateCpuAlbedo(const TArray<float>& InAlbedo)
{
	const int32 TotalCells = CellsDimensionX * CellsDimensionY;
	if (CpuAlbedo.Num() != TotalCells)
	{
		CpuAlbedo.SetNumZeroed(TotalCells, EAllowShrinking::No);
	}

	const int32 Count = FMath::Min(CpuAlbedo.Num(), InAlbedo.Num());
	for (int32 i = 0; i < Count; ++i)
	{
		CpuAlbedo[i] = FMath::Clamp(InAlbedo[i], 0.0f, 1.0f);
	}

	if (ShouldUploadAlbedoTexture())
	{
		UploadAlbedoToTexture();
	}
}

USimulationWeatherDataProviderBase* ASnowSimulationActor::GetActiveWeatherProvider() const
{
	return ClimateDataComponent ? ClimateDataComponent : WeatherProvider;
}

USimulationWeatherDataProviderBase* ASnowSimulationActor::EnsureActiveWeatherProviderReady()
{
	ClimateDataComponent = Cast<USimulationWeatherDataProviderBase>(GetComponentByClass(USimulationWeatherDataProviderBase::StaticClass()));
	if (ClimateDataComponent && InitializedClimateDataComponent.Get() != ClimateDataComponent)
	{
		ClimateDataComponent->Initialize(StartTime, EndTime);
		InitializedClimateDataComponent = ClimateDataComponent;
		UE_LOG(LogTemp, Display, TEXT("[Snow] Initialized component weather provider for editor/export use: %s"), *ClimateDataComponent->GetClass()->GetName());
	}

	if (!WeatherProvider)
	{
		if (UseInlineWeatherProvider)
		{
			if (InlineWeatherProvider)
			{
				WeatherProvider = InlineWeatherProvider;
				UE_LOG(LogTemp, Display, TEXT("[Snow] Using inline weather provider: %s"), *InlineWeatherProvider->GetClass()->GetName());
			}
			else
			{
				UE_LOG(LogTemp, Warning, TEXT("[Snow] UseInlineWeatherProvider=true but no InlineWeatherProvider specified. Creating default."));
				WeatherProvider = NewObject<UConstantWeatherProvider>(this);
			}
		}
		else
		{
			if (WeatherProviderClass)
			{
				USimulationWeatherDataProviderBase* NewProvider = NewObject<USimulationWeatherDataProviderBase>(this, WeatherProviderClass);
				if (NewProvider)
				{
					WeatherProvider = NewProvider;
					UE_LOG(LogTemp, Display, TEXT("[Snow] Using weather provider class: %s"), *WeatherProviderClass->GetName());
				}
				else
				{
					UE_LOG(LogTemp, Warning, TEXT("[Snow] Failed to instantiate weather provider from class. Creating default."));
					WeatherProvider = NewObject<UConstantWeatherProvider>(this);
				}
			}
			else
			{
				UE_LOG(LogTemp, Warning, TEXT("[Snow] UseInlineWeatherProvider=false but no WeatherProviderClass specified. Creating default."));
				WeatherProvider = NewObject<UConstantWeatherProvider>(this);
			}
		}
	}

	bSimulationTimesRepresentLocal = false;
	SimulationLocalToUtcOffset = FTimespan::Zero();
	if (const UFrostSettings* FrostSettings = UFrostSettings::Get())
	{
		if (FrostSettings->bTreatSimulationTimesAsLocal)
		{
			bSimulationTimesRepresentLocal = true;
			SimulationLocalToUtcOffset = FTimespan::FromHours(FrostSettings->SimulationUtcOffsetHours);
		}
	}

	if (WeatherProvider && InitializedWeatherProvider.Get() != WeatherProvider)
	{
		FDateTime StartUtc = StartTime;
		FDateTime EndUtc = EndTime;
		if (bSimulationTimesRepresentLocal)
		{
			StartUtc -= SimulationLocalToUtcOffset;
			EndUtc -= SimulationLocalToUtcOffset;
		}

		WeatherProvider->Initialize(StartUtc, EndUtc);
		InitializedWeatherProvider = WeatherProvider;
		UE_LOG(LogTemp, Display, TEXT("[Snow] Initialized standalone weather provider for editor/export use: %s"), *WeatherProvider->GetClass()->GetName());
	}

	return GetActiveWeatherProvider();
}

FDateTime ASnowSimulationActor::GetWeatherQueryTimeUtc() const
{
	return bSimulationTimesRepresentLocal ? (CurrentSimulationTime - SimulationLocalToUtcOffset) : CurrentSimulationTime;
}

USimulationBase* ASnowSimulationActor::ResolveSimulation()
{
    if (SimulationConfiguration)
    {
        // Clone the configuration instance to create the runtime instance
        return DuplicateObject<USimulationBase>(SimulationConfiguration, this);
    }

    // Fallback: Create a default FSM2 simulation if no configuration is set
    UE_LOG(LogTemp, Warning, TEXT("[Snow] No SimulationConfiguration set. creating default FSM2 simulation."));
    return NewObject<UFSM2SnowSimulation>(this);
}

#if WITH_SUNSKY_SUPPORT
void ASnowSimulationActor::UpdateSunSkyActors()
{
	UpdateSunSkyActorsAtTime(CurrentSimulationTime);
}

void ASnowSimulationActor::UpdateSunSkyActorsAtTime(const FDateTime& Time)
{
    UWorld* World = GetWorld();
    if (!World)
    {
        UE_LOG(LogTemp, Warning, TEXT("[Snow] UpdateSunSkyActors: No world available"));
        return;
    }

	const FTimespan LocalOffset = FTimespan::FromHours(SunSkyLocalTimeOffsetHours);
	const FDateTime EffectiveTime = Time + LocalOffset;

	if (!LocalOffset.IsZero())
	{
		UE_LOG(LogTemp, Display, TEXT("[Snow] UpdateSunSkyActors called - sim=%s | sun-local=%s (offset %+0.2fh)"),
			*Time.ToString(), *EffectiveTime.ToString(), SunSkyLocalTimeOffsetHours);
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("[Snow] UpdateSunSkyActors called - looking for SunSky actors at time %s"), *Time.ToString());
	}

    int32 SunSkyCount = 0;
    auto CacheSunComponent = [this](AActor* Actor)
    {
        if (!Actor)
        {
            return;
        }

        if (ADirectionalLight* DirActor = Cast<ADirectionalLight>(Actor))
        {
            if (UDirectionalLightComponent* LightComp = Cast<UDirectionalLightComponent>(DirActor->GetLightComponent()))
            {
                CachedSunDirectionalLight = LightComp;
            }
        }
        else if (ASkyLight* SkyActor = Cast<ASkyLight>(Actor))
        {
             if (USkyLightComponent* LightComp = Cast<USkyLightComponent>(SkyActor->GetLightComponent()))
            {
                CachedSunSkyLight = LightComp;
            }
        }

        if (!CachedSunDirectionalLight.IsValid())
        {
            if (UDirectionalLightComponent* LightComp = Actor->FindComponentByClass<UDirectionalLightComponent>())
            {
                CachedSunDirectionalLight = LightComp;
            }
        }

        if (!CachedSunSkyLight.IsValid())
        {
             if (USkyLightComponent* LightComp = Actor->FindComponentByClass<USkyLightComponent>())
            {
                CachedSunSkyLight = LightComp;
            }
        }
    };

    // Find all actors that might be SunSky actors (look for actors with SunSky in name or class)
    for (TActorIterator<AActor> It(World); It; ++It)
    {
        AActor* Actor = *It;
        if (!Actor)
        {
            continue;
        }

        // Check if this actor is a SunSky actor by name or class
        FString ActorName = Actor->GetName();
        FString ClassName = Actor->GetClass()->GetName();
        
        if (ActorName.Contains(TEXT("SunSky")) || ClassName.Contains(TEXT("SunSky")))
        {
            SunSkyCount++;

            auto SetFloatLikeProperty = [Actor](FProperty* Property, double Value, const TCHAR* PropertyLabel) -> bool
            {
                if (!Property)
                {
                    return false;
                }

                if (FFloatProperty* FloatProp = CastField<FFloatProperty>(Property))
                {
                    const float FloatValue = static_cast<float>(Value);
                    FloatProp->SetPropertyValue_InContainer(Actor, FloatValue);
                    return true;
                }

                if (FDoubleProperty* DoubleProp = CastField<FDoubleProperty>(Property))
                {
                    DoubleProp->SetPropertyValue_InContainer(Actor, Value);
                    return true;
                }

                UE_LOG(LogTemp, Warning, TEXT("[Snow] %s property has unsupported type: %s"),
                    PropertyLabel, *Property->GetClass()->GetName());
                return false;
            };

            auto SetIntegerLikeProperty = [Actor](FProperty* Property, int32 Value, const TCHAR* PropertyLabel) -> bool
            {
                if (!Property)
                {
                    return false;
                }

                if (FIntProperty* IntProp = CastField<FIntProperty>(Property))
                {
                    IntProp->SetPropertyValue_InContainer(Actor, Value);
                    return true;
                }

                if (FInt64Property* Int64Prop = CastField<FInt64Property>(Property))
                {
                    Int64Prop->SetPropertyValue_InContainer(Actor, static_cast<int64>(Value));
                    return true;
                }

                UE_LOG(LogTemp, Warning, TEXT("[Snow] %s property has unsupported integer type: %s"),
                    PropertyLabel, *Property->GetClass()->GetName());
                return false;
            };

            UE_LOG(LogTemp, Display, TEXT("[Snow] Found SunSky actor: %s (Class: %s)"), *ActorName, *ClassName);
            
            // Debug: List all properties on the SunSky actor - DISABLED
            UClass* ActorClass = Actor->GetClass();
            // UE_LOG(LogTemp, Display, TEXT("[Snow] SunSky actor properties:"));
            // for (TFieldIterator<FProperty> PropIt(ActorClass); PropIt; ++PropIt)
            // {
            //     FProperty* Prop = *PropIt;
            //     if (Prop)
            //     {
            //         UE_LOG(LogTemp, Display, TEXT("[Snow]   Property: %s (Type: %s)"),
            //             *Prop->GetName(), *Prop->GetClass()->GetName());
            //     }
            // }
            
            // Calculate time of day in hours (0-24)
            // Ensure we have valid time values
            int32 Hour = FMath::Clamp(EffectiveTime.GetHour(), 0, 23);
            int32 Minute = FMath::Clamp(EffectiveTime.GetMinute(), 0, 59);
            int32 Second = FMath::Clamp(EffectiveTime.GetSecond(), 0, 59);
            
            float Hours = Hour + Minute / 60.0f + Second / 3600.0f;

            // UE_LOG(LogTemp, Display, TEXT("[Snow] Time calculation: Hour=%d, Minute=%d, Second=%d, Hours=%.2f"),
            //     Hour, Minute, Second, Hours);

            // Validate date values
            int32 Year = FMath::Clamp(EffectiveTime.GetYear(), 1900, 2100);
            int32 Month = FMath::Clamp(EffectiveTime.GetMonth(), 1, 12);
            int32 Day = FMath::Clamp(EffectiveTime.GetDay(), 1, 31);

            // UE_LOG(LogTemp, Display, TEXT("[Snow] Date validation: Year=%d, Month=%d, Day=%d"), Year, Month, Day);

            // Try to set properties using reflection
            
            // Try to set Latitude property
            FProperty* LatProperty = ActorClass->FindPropertyByName(TEXT("Latitude"));
            SetFloatLikeProperty(LatProperty, Latitude, TEXT("Latitude"));
            
            // Try to set Longitude property
            FProperty* LonProperty = ActorClass->FindPropertyByName(TEXT("Longitude"));
            SetFloatLikeProperty(LonProperty, Longitude, TEXT("Longitude"));
            
            // Try to set Hour property with proper type checking
            FProperty* HourProperty = ActorClass->FindPropertyByName(TEXT("Hour"));
            if (!HourProperty)
            {
                HourProperty = ActorClass->FindPropertyByName(TEXT("TimeOfDay"));
            }
            if (!HourProperty)
            {
                HourProperty = ActorClass->FindPropertyByName(TEXT("SolarTime"));
            }
            if (HourProperty)
            {
                // Check property type and set accordingly
                if (HourProperty->IsA<FFloatProperty>())
                {
                    HourProperty->SetValue_InContainer(Actor, &Hours);
                    // UE_LOG(LogTemp, Display, TEXT("[Snow] Set Hour/SolarTime (float) = %.2f"), Hours);
                }
                else if (HourProperty->IsA<FIntProperty>())
                {
                    int32 HoursInt = FMath::RoundToInt(Hours);
                    HourProperty->SetValue_InContainer(Actor, &HoursInt);
                    // UE_LOG(LogTemp, Display, TEXT("[Snow] Set Hour/SolarTime (int) = %d"), HoursInt);
                }
                else if (HourProperty->IsA<FDoubleProperty>())
                {
                    double HoursDouble = static_cast<double>(Hours);
                    HourProperty->SetValue_InContainer(Actor, &HoursDouble);
                    // UE_LOG(LogTemp, Display, TEXT("[Snow] Set Hour/SolarTime (double) = %.2f"), HoursDouble);
                }
                else
                {
                    UE_LOG(LogTemp, Warning, TEXT("[Snow] Hour/SolarTime property has unsupported type: %s"), *HourProperty->GetClass()->GetName());
                }
            }
            else
            {
                UE_LOG(LogTemp, Warning, TEXT("[Snow] No Hour/TimeOfDay/SolarTime property found on SunSky actor"));
            }
            
            // Try to set Daylight Saving Time property
            bool bDST = bSunSkyUseDaylightSavingTime;
            FProperty* DSTProperty = ActorClass->FindPropertyByName(TEXT("DaylightSavingTime"));
            if (!DSTProperty)
            {
                DSTProperty = ActorClass->FindPropertyByName(TEXT("UseDaylightSavingTime"));
            }
            if (DSTProperty)
            {
                DSTProperty->SetValue_InContainer(Actor, &bDST);
                // UE_LOG(LogTemp, Display, TEXT("[Snow] Set DaylightSavingTime = %s"), bDST ? TEXT("true") : TEXT("false"));
            }
            
            // Try to set Date properties
            FProperty* YearProperty = ActorClass->FindPropertyByName(TEXT("Year"));
            SetIntegerLikeProperty(YearProperty, Year, TEXT("Year"));
            
            FProperty* MonthProperty = ActorClass->FindPropertyByName(TEXT("Month"));
            SetIntegerLikeProperty(MonthProperty, Month, TEXT("Month"));
            
            FProperty* DayProperty = ActorClass->FindPropertyByName(TEXT("Day"));
            SetIntegerLikeProperty(DayProperty, Day, TEXT("Day"));
            
            // Try to call UpdateSun method if it exists
            UFunction* UpdateSunFunc = ActorClass->FindFunctionByName(TEXT("UpdateSun"));
            if (!UpdateSunFunc)
            {
                UpdateSunFunc = ActorClass->FindFunctionByName(TEXT("UpdateSunPosition"));
            }
            if (UpdateSunFunc)
            {
                Actor->ProcessEvent(UpdateSunFunc, nullptr);
                UE_LOG(LogTemp, Display, TEXT("[Snow] Called UpdateSun method on %s"), *ActorName);
            }
            else
            {
                UE_LOG(LogTemp, Warning, TEXT("[Snow] No UpdateSun/UpdateSunPosition method found on %s"), *ActorName);
            }
            
			UE_LOG(LogTemp, Display, TEXT("[Snow] Updated SunSky actor %s with simulation time: %s (%.2f hours)"),
                *ActorName, *CurrentSimulationTime.ToString(), Hours);
            CacheSunComponent(Actor);
        }
    }
    
    if (SunSkyCount == 0)
    {
        UE_LOG(LogTemp, Warning, TEXT("[Snow] No SunSky actors found in the world! Make sure you have a SunSky actor placed in your level."));
    }
    else
    {
        // UE_LOG(LogTemp, Display, TEXT("[Snow] Found and updated %d SunSky actor(s)"), SunSkyCount);
    }

    if (!CachedSunDirectionalLight.IsValid())
    {
        for (TActorIterator<ADirectionalLight> LightIt(World); LightIt; ++LightIt)
        {
            if (ADirectionalLight* Light = *LightIt)
            {
                if (UDirectionalLightComponent* LightComp = Cast<UDirectionalLightComponent>(Light->GetLightComponent()))
                {
                    CachedSunDirectionalLight = LightComp;
                    break;
                }
            }
        }
    }

	// Intensity overrides are handled separately by benchmark/calibration paths and,
	// when enabled, by production forcing-based scaling.
}

void ASnowSimulationActor::UpdateSunSkyFromForcing(float DNI, float DHI)
{
	// Lazy Cache Init: If cache is empty, try to find the Sun (DirectionalLight)
	if (!CachedSunDirectionalLight.IsValid())
	{
		for (TActorIterator<ADirectionalLight> LightIt(GetWorld()); LightIt; ++LightIt)
		{
			if (ADirectionalLight* Light = *LightIt)
			{
				if (UDirectionalLightComponent* LightComp = Cast<UDirectionalLightComponent>(Light->GetLightComponent()))
				{
					CachedSunDirectionalLight = LightComp;
					UE_LOG(LogTemp, Warning, TEXT("[Snow] UpdateSunSkyFromForcing: Lazily cached Sun light: %s"), *Light->GetName());
					break;
				}
			}
		}
	}
	// SkyLight cache check
	if (!CachedSunSkyLight.IsValid())
	{
		for (TActorIterator<ASkyLight> LightIt(GetWorld()); LightIt; ++LightIt)
		{
			if (ASkyLight* Light = *LightIt)
			{
				if (USkyLightComponent* LightComp = Cast<USkyLightComponent>(Light->GetLightComponent()))
				{
					CachedSunSkyLight = LightComp;
					UE_LOG(LogTemp, Warning, TEXT("[Snow] UpdateSunSkyFromForcing: Lazily cached Sky light: %s"), *Light->GetName());
					break;
				}
			}
		}
	}

	// Scale Sun (Directional Light)
	if (UDirectionalLightComponent* SunLight = CachedSunDirectionalLight.Get())
	{
		float NewSunLik = FMath::Max(0.0f, DNI * SunLuminousEfficacy);
		LastSunLightIntensity = NewSunLik;
		SunLight->SetIntensity(NewSunLik);
	}

	// Scale Sky (Sky Light)
	if (USkyLightComponent* SkyLight = CachedSunSkyLight.Get())
	{
		float NewSkyLik = FMath::Max(0.0f, DHI * SkyLuminousEfficacy * SkyLightIntensityMultiplier);
		LastSkyLightIntensity = NewSkyLik;
		SkyLight->SetIntensity(NewSkyLik);
	}
	else
	{
		LastSkyLightIntensity = FMath::Max(0.0f, DHI * SkyLuminousEfficacy * SkyLightIntensityMultiplier);
	}

	if (bUseDedicatedRadiationSkyLight)
	{
		EnsureRadiationSkyLightComponent();
		if (USkyLightComponent* LocalRadiationSkyLight = RadiationSkyLight)
		{
			LocalRadiationSkyLight->SetIntensity(LastSkyLightIntensity);
		}
	}

	UE_LOG(LogTemp, Verbose, TEXT("[Snow] Immediate Light Update: DNI=%.1f -> Sun=%.0f Lux | DHI=%.1f -> Sky=%.3f"),
		DNI, LastSunLightIntensity, DHI, LastSkyLightIntensity);
}

bool ASnowSimulationActor::ApplyBenchmarkLightingFromForcingIfEnabled(float DNI, float DHI)
{
	if (bBenchmarkLightingUsesForcingIntensityScaling)
	{
		UpdateSunSkyFromForcing(DNI, DHI);
		return true;
	}

	return SyncCachedLightIntensitiesFromScene();
}

bool ASnowSimulationActor::SyncCachedLightIntensitiesFromScene()
{
	if (!CachedSunDirectionalLight.IsValid())
	{
		for (TActorIterator<ADirectionalLight> LightIt(GetWorld()); LightIt; ++LightIt)
		{
			if (ADirectionalLight* Light = *LightIt)
			{
				if (UDirectionalLightComponent* LightComp = Cast<UDirectionalLightComponent>(Light->GetLightComponent()))
				{
					CachedSunDirectionalLight = LightComp;
					break;
				}
			}
		}
	}

	if (!CachedSunSkyLight.IsValid())
	{
		for (TActorIterator<ASkyLight> LightIt(GetWorld()); LightIt; ++LightIt)
		{
			if (ASkyLight* Light = *LightIt)
			{
				if (USkyLightComponent* LightComp = Cast<USkyLightComponent>(Light->GetLightComponent()))
				{
					CachedSunSkyLight = LightComp;
					break;
				}
			}
		}
	}

	bool bFoundAnyLight = false;
	if (const UDirectionalLightComponent* SunLight = CachedSunDirectionalLight.Get())
	{
		LastSunLightIntensity = FMath::Max(0.0f, SunLight->Intensity);
		bFoundAnyLight = true;
	}
	else
	{
		LastSunLightIntensity = 0.0f;
	}

	if (const USkyLightComponent* SkyLight = CachedSunSkyLight.Get())
	{
		LastSkyLightIntensity = FMath::Max(0.0f, SkyLight->Intensity);
		bFoundAnyLight = true;
	}
	else
	{
		LastSkyLightIntensity = 0.0f;
	}

	if (bUseDedicatedRadiationSkyLight)
	{
		EnsureRadiationSkyLightComponent();
		if (USkyLightComponent* LocalRadiationSkyLight = RadiationSkyLight)
		{
			LocalRadiationSkyLight->SetIntensity(LastSkyLightIntensity);
			LocalRadiationSkyLight->MarkRenderStateDirty();
		}
	}

	return bFoundAnyLight;
}

void ASnowSimulationActor::ApplyRadiationBenchmarkSunOverride()
{
	if (!CachedSunDirectionalLight.IsValid())
	{
		for (TActorIterator<ADirectionalLight> LightIt(GetWorld()); LightIt; ++LightIt)
		{
			if (ADirectionalLight* Light = *LightIt)
			{
				if (UDirectionalLightComponent* LightComp = Cast<UDirectionalLightComponent>(Light->GetLightComponent()))
				{
					CachedSunDirectionalLight = LightComp;
					break;
				}
			}
		}
	}

	UDirectionalLightComponent* SunLight = CachedSunDirectionalLight.Get();
	if (!SunLight)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadBenchmark] Cannot apply manual sun override: no directional light is cached."));
		return;
	}

	const float ClampedElevationDeg = FMath::Clamp(RadiationBenchmarkOverrideSunElevationDeg, 0.0f, 89.9f);
	const float ElevationRad = FMath::DegreesToRadians(ClampedElevationDeg);
	const float AzimuthRad = FMath::DegreesToRadians(RadiationBenchmarkOverrideSunAzimuthDeg);
	const float CosElevation = FMath::Cos(ElevationRad);
	const FVector SunToLight(
		CosElevation * FMath::Cos(AzimuthRad),
		CosElevation * FMath::Sin(AzimuthRad),
		-FMath::Sin(ElevationRad));

	SunLight->SetWorldRotation(SunToLight.Rotation());
	SunLight->MarkRenderStateDirty();
}

bool ASnowSimulationActor::CollectRadiationBenchmarkSurfaceComponents(TArray<UPrimitiveComponent*>& OutComponents) const
{
	OutComponents.Reset();

	TSet<const UPrimitiveComponent*> SeenComponents;
	auto AppendActorComponents = [&OutComponents, &SeenComponents](AActor* Actor)
	{
		if (!Actor)
		{
			return;
		}

		TArray<UPrimitiveComponent*> PrimitiveComponents;
		Actor->GetComponents<UPrimitiveComponent>(PrimitiveComponents);
		for (UPrimitiveComponent* Component : PrimitiveComponents)
		{
			if (!Component || SeenComponents.Contains(Component))
			{
				continue;
			}

			SeenComponents.Add(Component);
			OutComponents.Add(Component);
		}
	};

	for (AActor* Actor : RadiationBenchmarkSurfaceActors)
	{
		AppendActorComponents(Actor);
	}

	if (OutComponents.Num() == 0 && Landscape)
	{
		AppendActorComponents(Landscape);
	}

	return OutComponents.Num() > 0;
}

bool ASnowSimulationActor::CollectBelowCanopyRenderSurfaceComponents(TArray<UPrimitiveComponent*>& OutComponents, bool bIncludeLandscapeLeakProtection) const
{
	OutComponents.Reset();

	TSet<const UPrimitiveComponent*> SeenComponents;
	auto AppendComponent = [&OutComponents, &SeenComponents](UPrimitiveComponent* Component)
	{
		if (!Component || SeenComponents.Contains(Component))
		{
			return;
		}

		SeenComponents.Add(Component);
		OutComponents.Add(Component);
	};

	auto AppendActorComponents = [&AppendComponent](AActor* Actor)
	{
		if (!Actor)
		{
			return;
		}

		TArray<UPrimitiveComponent*> PrimitiveComponents;
		Actor->GetComponents<UPrimitiveComponent>(PrimitiveComponents);
		for (UPrimitiveComponent* Component : PrimitiveComponents)
		{
			AppendComponent(Component);
		}
	};

	if (ActiveRenderBinding.PrimaryComponent.IsValid())
	{
		AppendComponent(ActiveRenderBinding.PrimaryComponent.Get());
	}

	if (Landscape && (ActiveRenderBinding.Target == FRenderBinding::ETarget::Landscape || bIncludeLandscapeLeakProtection))
	{
		AppendActorComponents(Landscape);
	}

	if (OutComponents.Num() == 0 && Landscape)
	{
		AppendActorComponents(Landscape);
	}

	return OutComponents.Num() > 0;
}

bool ASnowSimulationActor::WriteRadiationBenchmarkMetadata(
	const FString& TargetDir,
	const FString& RunTag,
	const FDateTime& CaptureTime) const
{
	const FString MetadataFilename = FString::Printf(TEXT("RadiationBenchmarkMetadata_%s.txt"), *RunTag);
	const FString MetadataPath = FPaths::Combine(TargetDir, MetadataFilename);

	FString Output;
	Output += FString::Printf(TEXT("RunTag=%s%s"), *RunTag, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("CaptureTimeIso=%s%s"), *CaptureTime.ToIso8601(), LINE_TERMINATOR);
	Output += FString::Printf(TEXT("IncidentMode=%d%s"), static_cast<int32>(RadiationBenchmarkIncidentMode), LINE_TERMINATOR);
	Output += FString::Printf(TEXT("RequestedAlbedo=%.6f%s"), RadiationBenchmarkAlbedo, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("RequestedSunElevationDeg=%.6f%s"), RadiationBenchmarkSunElevationDeg, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("RequestedSunAzimuthDeg=%.6f%s"), RadiationBenchmarkSunAzimuthDeg, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("RequestedDNI_Wm2=%.6f%s"), RadiationBenchmarkOverrideDNI_Wm2, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("RequestedDHI_Wm2=%.6f%s"), RadiationBenchmarkOverrideDHI_Wm2, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("UseTelephotoCapture=%d%s"), bUseTelephotoCapture ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("CaptureProjectionMode=%s%s"),
		bUseTelephotoCapture ? TEXT("PerspectiveTelephoto") : TEXT("Orthographic"),
		LINE_TERMINATOR);
	Output += FString::Printf(TEXT("TelephotoFOVDegrees=%.6f%s"), TelephotoFOVDegrees, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("RadiationCaptureEV100=%.6f%s"), RadiationCaptureEV100, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("CaptureDiffuseNoGIForTerrain=%d%s"), bCaptureDiffuseNoGIForTerrain ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("UseDiffuseCapture=%d%s"), bUseDiffuseCapture ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("UseReferenceTile=%d%s"), bUseReferenceTile ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("UseDualReferenceStrip=%d%s"), bUseDualReferenceStrip ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("TerrainResidualMode=%d%s"), static_cast<int32>(TerrainResidualMode), LINE_TERMINATOR);
	Output += FString::Printf(TEXT("LambertianCaptureShowFlagOverride=%d%s"), bLambertianCaptureShowFlagOverride ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("NonDirectCapturesIncludeAtmosphere=%d%s"), bNonDirectCapturesIncludeAtmosphere ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("DirectCaptureIncludesAtmosphere=%d%s"), bDirectCaptureIncludesAtmosphere ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("MatchDirectPassAtmosphereToReferenceCalibration=%d%s"), bMatchDirectPassAtmosphereToReferenceCalibration ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("UseDedicatedRadiationSkyLight=%d%s"), bUseDedicatedRadiationSkyLight ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("DisableAtmosphereWhenUsingDedicatedRadiationSkyLight=%d%s"), bDisableAtmosphereWhenUsingDedicatedRadiationSkyLight ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("DisableVolumetricCloudsDuringRadiationCapture=%d%s"), bDisableVolumetricCloudsDuringRadiationCapture ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("RecaptureSkyBeforeRadiationSample=%d%s"), bRecaptureSkyBeforeRadiationSample ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("OverrideLumenCaptureCVars=%d%s"), bOverrideLumenCaptureCVars ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("LumenCaptureTraceStepFactor=%.6f%s"), LumenCaptureTraceStepFactor, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("LumenCaptureTraceDistanceScale=%.6f%s"), LumenCaptureTraceDistanceScale, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("LumenCaptureDiffuseIndirectScale=%.6f%s"), LumenCaptureDiffuseIndirectScale, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("LumenCaptureForceMeshSDFs=%d%s"), bLumenCaptureForceMeshSDFs ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("CaptureUsePreExposure=%d%s"), bCaptureUsePreExposure ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("LumenConvergenceEnabled=%d%s"), bEnableLumenConvergence ? 1 : 0, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("LumenConvergenceFrames=%d%s"), LumenConvergenceFrames, LINE_TERMINATOR);
	Output += FString::Printf(TEXT("LumenConvergenceHistoryWeight=%.6f%s"), LumenConvergenceHistoryWeight, LINE_TERMINATOR);

	AppendBenchmarkShowFlagSnapshot(Output, TEXT("ShowFlags.Total"), CachedShowFlags_Total);
	AppendBenchmarkShowFlagSnapshot(Output, TEXT("ShowFlags.Direct"), CachedShowFlags_Direct);
	AppendBenchmarkShowFlagSnapshot(Output, TEXT("ShowFlags.Diffuse"), CachedShowFlags_Diffuse);
	AppendBenchmarkShowFlagSnapshot(Output, TEXT("ShowFlags.DiffuseNoGI"), CachedShowFlags_DiffuseNoGI);

	AppendBenchmarkSkyLightSnapshot(Output, TEXT("SceneSkyLight"), CachedSunSkyLight.Get());
	AppendBenchmarkSkyLightSnapshot(Output, TEXT("DedicatedRadiationSkyLight"), RadiationSkyLight);

	if (const UDirectionalLightComponent* SunLight = CachedSunDirectionalLight.Get())
	{
		const FVector SunDirection = SunLight->GetDirection();
		Output += FString::Printf(TEXT("SceneSun.Exists=1%s"), LINE_TERMINATOR);
		Output += FString::Printf(TEXT("SceneSun.Intensity=%.6f%s"), SunLight->Intensity, LINE_TERMINATOR);
		Output += FString::Printf(TEXT("SceneSun.Mobility=%s%s"), MobilityToLabel(SunLight->Mobility), LINE_TERMINATOR);
		Output += FString::Printf(TEXT("SceneSun.DirectionX=%.6f%s"), SunDirection.X, LINE_TERMINATOR);
		Output += FString::Printf(TEXT("SceneSun.DirectionY=%.6f%s"), SunDirection.Y, LINE_TERMINATOR);
		Output += FString::Printf(TEXT("SceneSun.DirectionZ=%.6f%s"), SunDirection.Z, LINE_TERMINATOR);
	}
	else
	{
		Output += FString::Printf(TEXT("SceneSun.Exists=0%s"), LINE_TERMINATOR);
	}

	if (!FFileHelper::SaveStringToFile(Output, *MetadataPath))
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadBenchmark] Failed to write benchmark metadata: %s"), *MetadataPath);
		return false;
	}

	return true;
}

bool ASnowSimulationActor::WriteRadiationBenchmarkSummary(
	const FString& TargetDir,
	const FString& RunTag,
	const FDateTime& CaptureTime,
	const TArray<float>* SVFValues,
	const FString& SVFBackendLabel,
	const FString& SVFBackendReason,
	FString& OutSummaryCsvPath) const
{
	OutSummaryCsvPath.Reset();

	auto ComputeFiniteMean = [](const TArray<float>& Values) -> double
	{
		double Sum = 0.0;
		int32 Count = 0;
		for (const float Value : Values)
		{
			if (FMath::IsFinite(Value))
			{
				Sum += static_cast<double>(Value);
				++Count;
			}
		}
		return Count > 0 ? (Sum / static_cast<double>(Count)) : std::numeric_limits<double>::quiet_NaN();
	};

	auto SafeNormalize = [](double Numerator, float Denominator) -> double
	{
		return (FMath::IsFinite(Denominator) && Denominator > 1.0e-6f)
			? (Numerator / static_cast<double>(Denominator))
			: std::numeric_limits<double>::quiet_NaN();
	};

	auto NearlyEqual = [](double A, double B) -> bool
	{
		if (!FMath::IsFinite(static_cast<float>(A)) || !FMath::IsFinite(static_cast<float>(B)))
		{
			return false;
		}

		const double Scale = FMath::Max(1.0, FMath::Max(FMath::Abs(A), FMath::Abs(B)));
		const double Tolerance = 1.0e-4 * Scale;
		return FMath::Abs(A - B) <= Tolerance;
	};

	auto CsvField = [](const FString& Value) -> FString
	{
		FString Escaped = Value;
		Escaped.ReplaceInline(TEXT("\""), TEXT("\"\""));
		return FString::Printf(TEXT("\"%s\""), *Escaped);
	};

	TArray<uint8> BenchmarkAnalysisMask;
	FString BenchmarkAnalysisDomainLabel = TEXT("full_domain");
	const TArray<uint8>* BenchmarkAnalysisMaskPtr = nullptr;
	if (SVFValues
		&& SVFValues->Num() == CellsDimensionX * CellsDimensionY
		&& BuildBenchmarkInteriorMask(*SVFValues, &LandscapeCells, GetCurrentMapTag(), BenchmarkAnalysisMask, BenchmarkAnalysisDomainLabel))
	{
		BenchmarkAnalysisMaskPtr = &BenchmarkAnalysisMask;
	}

	const double MeanTotal = ComputeBenchmarkFiniteMeanWithMask(CachedRTY_Total, BenchmarkAnalysisMaskPtr);
	const double MeanDirect = ComputeBenchmarkFiniteMeanWithMask(CachedRTY_Direct, BenchmarkAnalysisMaskPtr);
	const double MeanDiffuse = ComputeBenchmarkFiniteMeanWithMask(CachedRTY_Diffuse, BenchmarkAnalysisMaskPtr);
	const double MeanDiffuseNoGI = ComputeBenchmarkFiniteMeanWithMask(CachedRTY_DiffuseNoGI, BenchmarkAnalysisMaskPtr);
	const double MeanTotalNoGI = ComputeBenchmarkFiniteMeanWithMask(CachedRTY_TotalNoGI, BenchmarkAnalysisMaskPtr);
	const double MeanTerrain = ComputeBenchmarkFiniteMeanWithMask(CachedRTY_Terrain, BenchmarkAnalysisMaskPtr);
	const bool bHasSkyOnlyField = CachedRTY_DiffuseNoGI.Num() == CachedRTY_Total.Num();
	const bool bHasTotalNoGIField = CachedRTY_TotalNoGI.Num() == CachedRTY_Total.Num();
	const float DiffuseReferenceForNormalization =
		(FMath::IsFinite(ReferenceLuminance_DiffuseNoGI) && ReferenceLuminance_DiffuseNoGI > 1.0e-6f)
			? ReferenceLuminance_DiffuseNoGI
			: ReferenceLuminance_Diffuse;
	const float EffectiveSkyReferenceForNormalization =
		(RadiationBenchmarkOverrideDNI_Wm2 <= 1.0e-3f
			&& (!FMath::IsFinite(ReferenceLuminance_DiffuseNoGI) || ReferenceLuminance_DiffuseNoGI <= 1.0e-6f)
			&& FMath::IsFinite(ReferenceLuminance_TotalNoGI)
			&& ReferenceLuminance_TotalNoGI > 1.0e-6f)
			? ReferenceLuminance_TotalNoGI
			: ReferenceLuminance_DiffuseNoGI;
	const float TotalReferenceForNormalization =
		(FMath::IsFinite(ReferenceLuminance_Total) && ReferenceLuminance_Total > 1.0e-6f)
			? ReferenceLuminance_Total
			: ReferenceLuminance_TotalNoGI;

	const bool bMeanTotalMatchesDirect = NearlyEqual(MeanTotal, MeanDirect);
	const bool bMeanTotalMatchesTotalNoGI = NearlyEqual(MeanTotal, MeanTotalNoGI);
	const bool bMeanTotalNoGIMatchesDirect = NearlyEqual(MeanTotalNoGI, MeanDirect);
	const bool bSkyOnlyCollapsed =
		RadiationBenchmarkOverrideDHI_Wm2 > 1.0e-3f
		&& bHasTotalNoGIField
		&& bMeanTotalNoGIMatchesDirect
		&& (!FMath::IsFinite(static_cast<float>(MeanDiffuseNoGI)) || FMath::Abs(MeanDiffuseNoGI) <= 1.0e-6);
	const bool bIndirectCollapsed =
		(RadiationBenchmarkOverrideDNI_Wm2 + RadiationBenchmarkOverrideDHI_Wm2) > 1.0e-3f
		&& RadiationBenchmarkAlbedo > 1.0e-3f
		&& bMeanTotalMatchesTotalNoGI;

	double MeanShadowedDirect = std::numeric_limits<double>::quiet_NaN();
	double MeanShadowedDirectNormalized = std::numeric_limits<double>::quiet_NaN();
	double FractionShadowedDirectLeak = std::numeric_limits<double>::quiet_NaN();
	if (CachedSunMask_UE_Map.Num() == CachedRTY_Direct.Num() && CachedSWdir_UE_Map.Num() == CachedRTY_Direct.Num())
	{
		double ShadowedSum = 0.0;
		int32 ShadowedCount = 0;
		int32 ShadowedLeakCount = 0;
		const double LeakThreshold = FMath::Max(1.0e-6, static_cast<double>(ReferenceLuminance_Direct) * 0.05);
		for (int32 Index = 0; Index < CachedRTY_Direct.Num(); ++Index)
		{
			const bool bShadowedByGeometry =
				CachedSunMask_UE_Map[Index] <= 1.0e-6f
				&& CachedSWdir_UE_Map[Index] <= 1.0e-6f;
			if (!bShadowedByGeometry)
			{
				continue;
			}

			const double DirectValue = static_cast<double>(CachedRTY_Direct[Index]);
			ShadowedSum += DirectValue;
			++ShadowedCount;
			if (DirectValue > LeakThreshold)
			{
				++ShadowedLeakCount;
			}
		}

		if (ShadowedCount > 0)
		{
			MeanShadowedDirect = ShadowedSum / static_cast<double>(ShadowedCount);
			MeanShadowedDirectNormalized = SafeNormalize(MeanShadowedDirect, ReferenceLuminance_Direct);
			FractionShadowedDirectLeak = static_cast<double>(ShadowedLeakCount) / static_cast<double>(ShadowedCount);
		}
	}

	const bool bDirectShadowLeak =
		FMath::IsFinite(static_cast<float>(MeanShadowedDirectNormalized))
		&& FMath::IsFinite(static_cast<float>(FractionShadowedDirectLeak))
		&& MeanShadowedDirectNormalized > 0.05
		&& FractionShadowedDirectLeak > 0.05;

	const bool bMissingSVF =
		!SVFValues
		|| !FMath::IsFinite(static_cast<float>(ComputeFiniteMean(*SVFValues)));

	TArray<FString> DiagnosticFlags;
	if (bMissingSVF)
	{
		DiagnosticFlags.Add(TEXT("missing_svf"));
	}
	if (bDirectShadowLeak)
	{
		DiagnosticFlags.Add(TEXT("direct_shadow_leak"));
	}
	if (bSkyOnlyCollapsed)
	{
		DiagnosticFlags.Add(TEXT("sky_only_collapsed"));
	}
	if (bIndirectCollapsed)
	{
		DiagnosticFlags.Add(TEXT("indirect_collapsed"));
	}

	const FString BenchmarkDiagnosticsLabel =
		DiagnosticFlags.Num() > 0
			? FString::Join(DiagnosticFlags, TEXT("+"))
			: TEXT("ok");
	const FString BenchmarkSVFDefinitionLabel = ShouldUseSurfaceNormalSVFForBenchmark(*this)
		? TEXT("SurfaceNormalHemisphere")
		: TEXT("HorizontalHemisphere");
	const FString BenchmarkPrimaryObservableLabel = TEXT("Total");
	const FString DecompositionReliabilityLabel = TEXT("DiagnosticsOnly");
	const FString TotalNoGIInterpretationLabel = TEXT("StrictGIOffDiagnostic");
	const FString TerrainInterpretationLabel = TEXT("ResidualDiagnostic_MaxTotalMinusTotalNoGI");

	double MeanSVF = std::numeric_limits<double>::quiet_NaN();
	double StdSVF = std::numeric_limits<double>::quiet_NaN();
	double MaeSVFToHalf = std::numeric_limits<double>::quiet_NaN();
	double MeanSVFFullDomain = std::numeric_limits<double>::quiet_NaN();
	double StdSVFFullDomain = std::numeric_limits<double>::quiet_NaN();
	double MaeSVFToHalfFullDomain = std::numeric_limits<double>::quiet_NaN();
	FString SVFAnalysisDomainLabel = TEXT("full_domain");
	if (SVFValues)
	{
		const FBenchmarkSVFStatistics FullDomainSVFStats =
			ComputeBenchmarkSVFStatistics(*SVFValues, nullptr, TEXT("full_domain"));
		const FBenchmarkSVFStatistics BenchmarkDomainSVFStats =
			ComputeBenchmarkSVFStatistics(*SVFValues, BenchmarkAnalysisMaskPtr, BenchmarkAnalysisDomainLabel);
		MeanSVF = BenchmarkDomainSVFStats.Mean;
		StdSVF = BenchmarkDomainSVFStats.Std;
		MaeSVFToHalf = BenchmarkDomainSVFStats.MaeToHalf;
		MeanSVFFullDomain = FullDomainSVFStats.Mean;
		StdSVFFullDomain = FullDomainSVFStats.Std;
		MaeSVFToHalfFullDomain = FullDomainSVFStats.MaeToHalf;
		SVFAnalysisDomainLabel = BenchmarkDomainSVFStats.DomainLabel;
	}

	const TCHAR* IncidentModeLabel = TEXT("Unknown");
	switch (RadiationBenchmarkIncidentMode)
	{
	case ERadiationBenchmarkIncidentMode::DirectOnly:
		IncidentModeLabel = TEXT("DirectOnly");
		break;
	case ERadiationBenchmarkIncidentMode::DiffuseOnly:
		IncidentModeLabel = TEXT("DiffuseOnly");
		break;
	case ERadiationBenchmarkIncidentMode::DirectAndDiffuse:
		IncidentModeLabel = TEXT("DirectAndDiffuse");
		break;
	default:
		break;
	}

	const FString SummaryFilename = FString::Printf(TEXT("RadiationBenchmarkSummary_%s.csv"), *RunTag);
	OutSummaryCsvPath = FPaths::Combine(TargetDir, SummaryFilename);

	FString Output;
	Output += TEXT("RunTag,CaptureTimeIso,IncidentMode,CaptureProjectionMode,RequestedAlbedo,RequestedSunElevationDeg,RequestedSunAzimuthDeg,");
	Output += TEXT("UseTelephotoCapture,TelephotoFOVDegrees,LumenConvergenceEnabled,LumenConvergenceFrames,");
	Output += TEXT("BenchmarkPrimaryObservable,DecompositionReliability,TotalNoGIInterpretation,TerrainInterpretation,");
	Output += TEXT("OpenSkyReference_RTY_Total,OpenSkyReference_RTY_Direct,OpenSkyReference_RTY_Diffuse,OpenSkyReference_RTY_DiffuseNoGI,OpenSkyReference_RTY_TotalNoGI,");
	Output += TEXT("MeanCavity_RTY_Total,MeanCavity_RTY_Direct,MeanCavity_RTY_Diffuse,MeanCavity_RTY_DiffuseNoGI,MeanCavity_RTY_TotalNoGI,MeanCavity_RTY_Terrain,");
	Output += TEXT("MeanNormalized_CavityTotal,MeanNormalized_CavityDirect,MeanNormalized_CavityDiffuse,MeanNormalized_CavityDiffuseNoGI,MeanNormalized_CavityTotalNoGI,MeanNormalized_CavityTerrain,");
	Output += TEXT("HasSkyOnlyField,HasTotalNoGIField,MeanTotalMatchesDirect,MeanTotalMatchesTotalNoGI,MeanTotalNoGIMatchesDirect,SkyOnlyCollapsed,IndirectCollapsed,");
	Output += TEXT("DirectShadowLeakDetected,MeanShadowed_RTY_Direct,MeanShadowedNormalized_Direct,ShadowedDirectLeakFraction,");
	Output += TEXT("Mean_SVF,Std_SVF,MAE_SVF_To_0p5,Mean_SVF_FullDomain,Std_SVF_FullDomain,MAE_SVF_To_0p5_FullDomain,SVFAnalysisDomain,SVFDefinition,DiagnosticsLabel,SVFBackendLabel,SVFBackendReason");
	Output += LINE_TERMINATOR;

	Output += CsvField(RunTag);
	Output += TEXT(",");
	Output += CsvField(CaptureTime.ToIso8601());
	Output += TEXT(",");
	Output += CsvField(IncidentModeLabel);
	Output += TEXT(",");
	Output += CsvField(bUseTelephotoCapture ? TEXT("PerspectiveTelephoto") : TEXT("Orthographic"));
	Output += FString::Printf(
		TEXT(",%.6f,%.6f,%.6f,%d,%.6f,%d,%d"),
		RadiationBenchmarkAlbedo,
		RadiationBenchmarkSunElevationDeg,
		RadiationBenchmarkSunAzimuthDeg,
		bUseTelephotoCapture ? 1 : 0,
		TelephotoFOVDegrees,
		bEnableLumenConvergence ? 1 : 0,
		LumenConvergenceFrames);
	Output += TEXT(",");
	Output += CsvField(BenchmarkPrimaryObservableLabel);
	Output += TEXT(",");
	Output += CsvField(DecompositionReliabilityLabel);
	Output += TEXT(",");
	Output += CsvField(TotalNoGIInterpretationLabel);
	Output += TEXT(",");
	Output += CsvField(TerrainInterpretationLabel);
	Output += FString::Printf(
		TEXT(",%.6f,%.6f,%.6f,%.6f,%.6f"),
		ReferenceLuminance_Total,
		ReferenceLuminance_Direct,
		ReferenceLuminance_Diffuse,
		ReferenceLuminance_DiffuseNoGI,
		ReferenceLuminance_TotalNoGI);
	Output += FString::Printf(
		TEXT(",%.6f,%.6f,%.6f,%.6f,%.6f,%.6f"),
		MeanTotal,
		MeanDirect,
		MeanDiffuse,
		MeanDiffuseNoGI,
		MeanTotalNoGI,
		MeanTerrain);
	Output += FString::Printf(
		TEXT(",%.6f,%.6f,%.6f,%.6f,%.6f,%.6f"),
		SafeNormalize(MeanTotal, TotalReferenceForNormalization),
		SafeNormalize(MeanDirect, ReferenceLuminance_Direct),
		SafeNormalize(MeanDiffuse, DiffuseReferenceForNormalization),
		SafeNormalize(MeanDiffuseNoGI, EffectiveSkyReferenceForNormalization),
		SafeNormalize(MeanTotalNoGI, ReferenceLuminance_TotalNoGI),
		SafeNormalize(MeanTerrain, TotalReferenceForNormalization));
	Output += FString::Printf(
		TEXT(",%d,%d,%d,%d,%d,%d,%d"),
		bHasSkyOnlyField ? 1 : 0,
		bHasTotalNoGIField ? 1 : 0,
		bMeanTotalMatchesDirect ? 1 : 0,
		bMeanTotalMatchesTotalNoGI ? 1 : 0,
		bMeanTotalNoGIMatchesDirect ? 1 : 0,
		bSkyOnlyCollapsed ? 1 : 0,
		bIndirectCollapsed ? 1 : 0);
	Output += FString::Printf(
		TEXT(",%d,%.6f,%.6f,%.6f"),
		bDirectShadowLeak ? 1 : 0,
		MeanShadowedDirect,
		MeanShadowedDirectNormalized,
		FractionShadowedDirectLeak);
	Output += FString::Printf(
		TEXT(",%.6f,%.6f,%.6f,%.6f,%.6f,%.6f"),
		MeanSVF,
		StdSVF,
		MaeSVFToHalf,
		MeanSVFFullDomain,
		StdSVFFullDomain,
		MaeSVFToHalfFullDomain);
	Output += TEXT(",");
	Output += CsvField(SVFAnalysisDomainLabel);
	Output += TEXT(",");
	Output += CsvField(BenchmarkSVFDefinitionLabel);
	Output += TEXT(",");
	Output += CsvField(BenchmarkDiagnosticsLabel);
	Output += TEXT(",");
	Output += CsvField(SVFBackendLabel);
	Output += TEXT(",");
	Output += CsvField(SVFBackendReason);
	Output += LINE_TERMINATOR;

	if (!FFileHelper::SaveStringToFile(Output, *OutSummaryCsvPath))
	{
		UE_LOG(LogTemp, Error, TEXT("[RadBenchmark] Failed to write benchmark summary CSV: %s"), *OutSummaryCsvPath);
		OutSummaryCsvPath.Reset();
		return false;
	}

	return true;
}

bool ASnowSimulationActor::RunRadiationBenchmarkPlotScript(const FString& SummaryCsvPath, const FString& TargetDir, FString& OutPlotPath) const
{
	OutPlotPath.Reset();

	const FString PythonExecutable = RadiationBenchmarkPythonExecutable.IsEmpty()
		? TEXT("python")
		: RadiationBenchmarkPythonExecutable;
	const FString ScriptPath = FPaths::Combine(
		FPaths::ConvertRelativePathToFull(FPaths::ProjectDir()),
		TEXT(".agents"),
		TEXT("skills"),
		TEXT("plot-results"),
		TEXT("scripts"),
		TEXT("plot_radiation_benchmark_capture.py"));

	if (!FPaths::FileExists(ScriptPath))
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadBenchmark] Plot script not found: %s"), *ScriptPath);
		return false;
	}

	const FString OutputDir = FPaths::Combine(
		GetOutputCategoryDirectory(TEXT("Plots")),
		TEXT("RadiationBenchmark"),
		FString::Printf(TEXT("Run_%s"), *SanitizeMeltoutTag(RadiationExportRunTimestampTag)));
	if (!EnsureDirectoryExists(OutputDir))
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadBenchmark] Failed to create plot directory: %s"), *OutputDir);
		return false;
	}

	const FString CommandLine = FString::Printf(
		TEXT("\"%s\" --summary-csv \"%s\" --maps-dir \"%s\" --output-dir \"%s\""),
		*ScriptPath,
		*SummaryCsvPath,
		*TargetDir,
		*OutputDir);

	FString StdOut;
	FString StdErr;
	int32 ReturnCode = 0;
	if (!FPlatformProcess::ExecProcess(*PythonExecutable, *CommandLine, &ReturnCode, &StdOut, &StdErr) || ReturnCode != 0)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadBenchmark] Plot script failed (code %d). StdErr: %s"), ReturnCode, *StdErr);
		return false;
	}

	TArray<FString> StdOutLines;
	StdOut.ParseIntoArrayLines(StdOutLines, false);
	for (const FString& Line : StdOutLines)
	{
		if (Line.StartsWith(TEXT("PLOT:")))
		{
			OutPlotPath = Line.RightChop(5).TrimStartAndEnd();
			break;
		}
	}

	if (OutPlotPath.IsEmpty())
	{
		OutPlotPath = FPaths::Combine(OutputDir, FString::Printf(TEXT("RadiationBenchmark_%s.png"), *FPaths::GetBaseFilename(SummaryCsvPath)));
	}

	return true;
}

bool ASnowSimulationActor::RunBelowCanopyPlotScript(const FString& MapsDir, FString& OutPlotPath) const
{
	OutPlotPath.Reset();

	if (MapsDir.IsEmpty())
	{
		UE_LOG(LogTemp, Warning, TEXT("[BelowCanopy] Plot script requested with an empty maps directory."));
		return false;
	}

	const FString PythonExecutable = BelowCanopyPlotPythonExecutable.IsEmpty()
		? TEXT("python")
		: BelowCanopyPlotPythonExecutable;
	const FString ScriptPath = FPaths::Combine(
		FPaths::ConvertRelativePathToFull(FPaths::ProjectDir()),
		TEXT(".agents"),
		TEXT("skills"),
		TEXT("plot-results"),
		TEXT("scripts"),
		TEXT("plot_below_canopy_radiation_maps.py"));

	if (!FPaths::FileExists(ScriptPath))
	{
		UE_LOG(LogTemp, Warning, TEXT("[BelowCanopy] Plot script not found: %s"), *ScriptPath);
		return false;
	}

	const FString MapsDirFull = FPaths::ConvertRelativePathToFull(MapsDir);
	const FString RunDirName = FPaths::GetCleanFilename(MapsDirFull);
	FString OutputDir;
	const FString ParentDirPath = FPaths::GetPath(MapsDirFull);
	const FString ParentDirName = FPaths::GetCleanFilename(ParentDirPath);
	const FString GrandParentDirName = FPaths::GetCleanFilename(FPaths::GetPath(ParentDirPath));
	if (ParentDirName.Equals(TEXT("Radiation"), ESearchCase::CaseSensitive))
	{
		const FString ScenarioDir = FPaths::GetPath(FPaths::GetPath(MapsDirFull));
		OutputDir = FPaths::Combine(ScenarioDir, TEXT("Plots"), TEXT("BelowCanopyRadiation"), RunDirName);
	}
	else if (GrandParentDirName.Equals(TEXT("RadiationMapExports"), ESearchCase::CaseSensitive))
	{
		OutputDir = FPaths::Combine(ParentDirPath, TEXT("Plots"), TEXT("BelowCanopyRadiation"), RunDirName);
	}
	else
	{
		OutputDir = FPaths::Combine(
			GetOutputCategoryDirectory(TEXT("Plots")),
			TEXT("BelowCanopyRadiation"),
			RunDirName);
	}
	if (!EnsureDirectoryExists(OutputDir))
	{
		UE_LOG(LogTemp, Warning, TEXT("[BelowCanopy] Failed to create plot directory: %s"), *OutputDir);
		return false;
	}

	FString CommandLine = FString::Printf(
		TEXT("\"%s\" --maps-dir \"%s\" --output-dir \"%s\""),
		*ScriptPath,
		*MapsDirFull,
		*OutputDir);
	if (!bGenerateBelowCanopyInteractiveHtml)
	{
		CommandLine += TEXT(" --no-html");
	}

	FString StdOut;
	FString StdErr;
	int32 ReturnCode = 0;
	if (!FPlatformProcess::ExecProcess(*PythonExecutable, *CommandLine, &ReturnCode, &StdOut, &StdErr) || ReturnCode != 0)
	{
		UE_LOG(LogTemp, Warning, TEXT("[BelowCanopy] Plot script failed (code %d). StdErr: %s"), ReturnCode, *StdErr);
		return false;
	}

	TArray<FString> StdOutLines;
	StdOut.ParseIntoArrayLines(StdOutLines, false);
	for (const FString& Line : StdOutLines)
	{
		if (Line.StartsWith(TEXT("PLOT:")))
		{
			OutPlotPath = Line.RightChop(5).TrimStartAndEnd();
			break;
		}
	}

	if (OutPlotPath.IsEmpty())
	{
		OutPlotPath = FPaths::Combine(
			OutputDir,
			FString::Printf(TEXT("BelowCanopyRadiation_RunSummary_%s.png"), *RunDirName));
	}

	return true;
}

bool ASnowSimulationActor::RunBelowCanopyProbeHemispherePlotScript(const FString& MapsDir, FString& OutPlotPath, const FString& SpecificRunTag) const
{
	OutPlotPath.Reset();

	if (MapsDir.IsEmpty())
	{
		UE_LOG(LogTemp, Warning, TEXT("[BelowCanopyHemisphere] Plot script requested with an empty maps directory."));
		return false;
	}

	const FString PythonExecutable = BelowCanopyPlotPythonExecutable.IsEmpty()
		? TEXT("python")
		: BelowCanopyPlotPythonExecutable;
	const FString ScriptPath = FPaths::Combine(
		FPaths::ConvertRelativePathToFull(FPaths::ProjectDir()),
		TEXT(".agents"),
		TEXT("skills"),
		TEXT("plot-results"),
		TEXT("scripts"),
		TEXT("plot_below_canopy_probe_hemisphere_run.py"));

	if (!FPaths::FileExists(ScriptPath))
	{
		UE_LOG(LogTemp, Warning, TEXT("[BelowCanopyHemisphere] Plot script not found: %s"), *ScriptPath);
		return false;
	}

	const FString MapsDirFull = FPaths::ConvertRelativePathToFull(MapsDir);
	const FString RunDirName = FPaths::GetCleanFilename(MapsDirFull);
	FString OutputDir;
	const FString ParentDirPath = FPaths::GetPath(MapsDirFull);
	const FString ParentDirName = FPaths::GetCleanFilename(ParentDirPath);
	const FString GrandParentDirName = FPaths::GetCleanFilename(FPaths::GetPath(ParentDirPath));
	if (ParentDirName.Equals(TEXT("Radiation"), ESearchCase::CaseSensitive))
	{
		const FString ScenarioDir = FPaths::GetPath(FPaths::GetPath(MapsDirFull));
		OutputDir = FPaths::Combine(ScenarioDir, TEXT("Plots"), TEXT("BelowCanopyProbeHemisphere"), RunDirName);
	}
	else if (GrandParentDirName.Equals(TEXT("RadiationMapExports"), ESearchCase::CaseSensitive))
	{
		OutputDir = FPaths::Combine(ParentDirPath, TEXT("Plots"), TEXT("BelowCanopyProbeHemisphere"), RunDirName);
	}
	else
	{
		OutputDir = FPaths::Combine(
			GetOutputCategoryDirectory(TEXT("Plots")),
			TEXT("BelowCanopyProbeHemisphere"),
			RunDirName);
	}
	if (!EnsureDirectoryExists(OutputDir))
	{
		UE_LOG(LogTemp, Warning, TEXT("[BelowCanopyHemisphere] Failed to create plot directory: %s"), *OutputDir);
		return false;
	}

	FString CommandLine = FString::Printf(
		TEXT("\"%s\" --run-dir \"%s\" --output-dir \"%s\""),
		*ScriptPath,
		*MapsDirFull,
		*OutputDir);
	if (!SpecificRunTag.IsEmpty())
	{
		CommandLine += FString::Printf(TEXT(" --run-tag \"%s\""), *SpecificRunTag);
	}

	FString StdOut;
	FString StdErr;
	int32 ReturnCode = 0;
	if (!FPlatformProcess::ExecProcess(*PythonExecutable, *CommandLine, &ReturnCode, &StdOut, &StdErr) || ReturnCode != 0)
	{
		UE_LOG(LogTemp, Warning, TEXT("[BelowCanopyHemisphere] Plot script failed (code %d). StdErr: %s"), ReturnCode, *StdErr);
		return false;
	}

	TArray<FString> StdOutLines;
	StdOut.ParseIntoArrayLines(StdOutLines, false);
	for (const FString& Line : StdOutLines)
	{
		if (Line.StartsWith(TEXT("PLOT:")))
		{
			OutPlotPath = Line.RightChop(5).TrimStartAndEnd();
			break;
		}
	}

	if (OutPlotPath.IsEmpty())
	{
		const FString EffectiveRunTag = SpecificRunTag.IsEmpty()
			? BuildRunTag(SanitizeMeltoutTag(RadiationExportRunTimestampTag))
			: SpecificRunTag;
		OutPlotPath = FPaths::Combine(
			OutputDir,
			FString::Printf(TEXT("BelowCanopyProbeHemisphere_%s.png"), *EffectiveRunTag));
	}

	return true;
}

bool ASnowSimulationActor::ShouldUseDedicatedRadiationSkyLightForCapture() const
{
	return bUseDedicatedRadiationSkyLight && ResolveRadiationSkyCubemapForCapture() != nullptr;
}

bool ASnowSimulationActor::IsRadiationBenchmarkOverrideActive() const
{
	return bRadiationBenchmarkCaptureActive || bUseRadiationBenchmarkLightingOverride;
}

UTextureCube* ASnowSimulationActor::ResolveRadiationSkyCubemapForCapture() const
{
	if (RadiationSkyCubemap)
	{
		return RadiationSkyCubemap;
	}

	static TWeakObjectPtr<UTextureCube> CachedFallbackRadiationSkyCubemap;
	if (CachedFallbackRadiationSkyCubemap.IsValid())
	{
		return CachedFallbackRadiationSkyCubemap.Get();
	}

	static const TCHAR* FallbackCubemapPaths[] =
	{
		TEXT("/Engine/MapTemplates/Sky/DaylightAmbientCubemap.DaylightAmbientCubemap"),
		TEXT("/Engine/EngineResources/GrayLightTextureCube.GrayLightTextureCube"),
		TEXT("/Engine/EngineResources/DefaultTextureCube.DefaultTextureCube"),
	};

	for (const TCHAR* FallbackPath : FallbackCubemapPaths)
	{
		if (UTextureCube* FallbackCubemap = LoadObject<UTextureCube>(nullptr, FallbackPath))
		{
			CachedFallbackRadiationSkyCubemap = FallbackCubemap;
			static bool bLoggedFallbackRadiationSkyCubemap = false;
			if (!bLoggedFallbackRadiationSkyCubemap)
			{
				UE_LOG(LogTemp, Display, TEXT("[RadCapture] Using built-in Engine cubemap fallback for dedicated radiation SkyLight: %s"),
					FallbackPath);
				bLoggedFallbackRadiationSkyCubemap = true;
			}
			return FallbackCubemap;
		}
	}

	return nullptr;
}

void ASnowSimulationActor::EnsureRadiationSkyLightComponent()
{
	if (RadiationSkyLight)
	{
		ConfigureRadiationSkyLightComponent();
		return;
	}

	RadiationSkyLight = NewObject<USkyLightComponent>(this, TEXT("RadiationSkyLight"));
	if (!RadiationSkyLight)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Failed to create dedicated radiation SkyLight component."));
		return;
	}

	RadiationSkyLight->Mobility = EComponentMobility::Movable;
	RadiationSkyLight->bAffectsWorld = false;
	RadiationSkyLight->SetVisibility(false);
	RadiationSkyLight->RegisterComponent();
	if (RootComponent)
	{
		RadiationSkyLight->AttachToComponent(RootComponent, FAttachmentTransformRules::KeepRelativeTransform);
	}

	ConfigureRadiationSkyLightComponent();
}

void ASnowSimulationActor::ConfigureRadiationSkyLightComponent()
{
	if (!RadiationSkyLight)
	{
		return;
	}

	UTextureCube* const ResolvedRadiationSkyCubemap = ResolveRadiationSkyCubemapForCapture();
	RadiationSkyLight->Intensity = LastSkyLightIntensity;
	RadiationSkyLight->bCaptureEmissiveOnly = false;
	RadiationSkyLight->bLowerHemisphereIsBlack = true;
	RadiationSkyLight->bRealTimeCapture = false;
	RadiationSkyLight->SourceType = ShouldUseDedicatedRadiationSkyLightForCapture()
		? SLS_SpecifiedCubemap
		: SLS_CapturedScene;
	RadiationSkyLight->Cubemap = ResolvedRadiationSkyCubemap;
	RadiationSkyLight->MarkRenderStateDirty();
}

#endif

// ============================================================================
// Radiation Capture System - Orthographic Irradiance Atlas
// ============================================================================

void ASnowSimulationActor::ApplyPersistentRadiationCaptureLODSettings()
{
	if (!bEnableRadiationCapture || !bLockCaptureLODOnce)
	{
		bRadiationCaptureLODSettingsApplied = false;
		return;
	}

	const float ClampedCaptureLODDistanceFactor = FMath::Clamp(CaptureLODDistanceFactor, 0.01f, 1.0f);
	const float TargetVhmLod0ScreenSize = FMath::Max(0.1f, CaptureVHMLod0ScreenSize);
	const int32 TargetVhmForceLoadLods = FMath::Clamp(CaptureVHMNumForceLoadLods, 0, 4);

	// 1) SceneCapture view LOD policy (applies to all primitives that consume View.LODDistanceFactor).
	if (RadiationCapture)
	{
		RadiationCapture->LODDistanceFactor = ClampedCaptureLODDistanceFactor;
		RadiationCapture->MaxViewDistanceOverride = -1.0f;
	}

	const bool bAlreadyApplied =
		bRadiationCaptureLODSettingsApplied &&
		AppliedRadiationCaptureLODLandscape.Get() == Landscape &&
		FMath::IsNearlyEqual(AppliedRadiationCaptureLODDistanceFactor, ClampedCaptureLODDistanceFactor, KINDA_SMALL_NUMBER) &&
		bAppliedForceLandscapeLOD0ForCapture == bForceLandscapeLOD0ForCapture &&
		bAppliedForceVHMLodForCapture == bForceVHMLodForCapture &&
		FMath::IsNearlyEqual(AppliedCaptureVHMLod0ScreenSize, TargetVhmLod0ScreenSize, KINDA_SMALL_NUMBER) &&
		AppliedCaptureVHMNumForceLoadLods == TargetVhmForceLoadLods &&
		bAppliedEnableVHMViewLodFactorForCapture == bEnableVHMViewLodFactorForCapture;

	if (bAlreadyApplied)
	{
		return;
	}

	// 2) Landscape hard-lock to LOD0 for deterministic geometry/shadows in capture.
	int32 LandscapeComponentCount = 0;
	if (bForceLandscapeLOD0ForCapture && Landscape)
	{
		Landscape->MaxLODLevel = 0;

		for (ULandscapeComponent* LandscapeComponent : Landscape->LandscapeComponents)
		{
			if (!LandscapeComponent)
			{
				continue;
			}

			LandscapeComponent->SetLODBias(0);
			LandscapeComponent->SetForcedLOD(0);
			LandscapeComponent->MarkRenderStateDirty();
			++LandscapeComponentCount;
		}

		Landscape->MarkComponentsRenderStateDirty();
	}

	// 3) VHM lock: force high-detail settings via reflection (no hard plugin dependency).
	int32 VHMComponentCount = 0;
	int32 VHMUpdatedCount = 0;
	if (bForceVHMLodForCapture && GetWorld())
	{
		if (bEnableVHMViewLodFactorForCapture)
		{
			if (IConsoleVariable* EnableViewLodVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.VHM.EnableViewLodFactor")))
			{
				EnableViewLodVar->Set(1, ECVF_SetByCode);
			}
		}

		for (TActorIterator<AActor> ActorIt(GetWorld()); ActorIt; ++ActorIt)
		{
			AActor* Actor = *ActorIt;
			if (!Actor)
			{
				continue;
			}

			const TSet<UActorComponent*>& Components = Actor->GetComponents();
			for (UActorComponent* Component : Components)
			{
				if (!Component)
				{
					continue;
				}

				const FString ClassName = Component->GetClass()->GetName();
				if (!ClassName.Contains(TEXT("VirtualHeightfieldMesh")))
				{
					continue;
				}

				++VHMComponentCount;

				bool bUpdatedComponent = false;
				bUpdatedComponent |= SetFloatPropertyIfPresent(Component, TEXT("Lod0ScreenSize"), TargetVhmLod0ScreenSize);
				bUpdatedComponent |= SetIntPropertyIfPresent(Component, TEXT("NumForceLoadLods"), TargetVhmForceLoadLods);

				if (UPrimitiveComponent* PrimComponent = Cast<UPrimitiveComponent>(Component))
				{
					PrimComponent->MarkRenderStateDirty();
				}

				if (bUpdatedComponent)
				{
					++VHMUpdatedCount;
				}
			}
		}
	}

	bRadiationCaptureLODSettingsApplied = true;
	AppliedRadiationCaptureLODDistanceFactor = ClampedCaptureLODDistanceFactor;
	bAppliedForceLandscapeLOD0ForCapture = bForceLandscapeLOD0ForCapture;
	bAppliedForceVHMLodForCapture = bForceVHMLodForCapture;
	AppliedCaptureVHMLod0ScreenSize = TargetVhmLod0ScreenSize;
	AppliedCaptureVHMNumForceLoadLods = TargetVhmForceLoadLods;
	bAppliedEnableVHMViewLodFactorForCapture = bEnableVHMViewLodFactorForCapture;
	AppliedRadiationCaptureLODLandscape = Landscape;

	UE_LOG(LogTemp, Display,
		TEXT("[RadCapture][LOD] Persistent lock applied: CaptureLODDistanceFactor=%.3f | LandscapeLOD0=%s (%d comps) | VHM=%s (%d/%d comps updated) | VHMViewFactor=%s"),
		ClampedCaptureLODDistanceFactor,
		bForceLandscapeLOD0ForCapture ? TEXT("ON") : TEXT("OFF"),
		LandscapeComponentCount,
		bForceVHMLodForCapture ? TEXT("ON") : TEXT("OFF"),
		VHMUpdatedCount,
		VHMComponentCount,
		(bForceVHMLodForCapture && bEnableVHMViewLodFactorForCapture) ? TEXT("ON") : TEXT("UNCHANGED"));
}

void ASnowSimulationActor::SetupRadiationCapture()
{
	const int32 ExpectedNumCells = CellsDimensionX * CellsDimensionY;

	if (!bEnableRadiationCapture)
	{
		CleanupRadiationExtraction();
		bRadiationCaptureInitialized = false;
		CachedRadiationCaptureWidth = 0;
		CachedRadiationCaptureHeight = 0;
		bCachedUseReferenceTile = false;
		return;
	}

	if (CellsDimensionX <= 0 || CellsDimensionY <= 0)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Cannot setup: invalid grid dimensions"));
		bRadiationCaptureInitialized = false;
		CachedRadiationCaptureWidth = 0;
		CachedRadiationCaptureHeight = 0;
		return;
	}

	const int32 BorderRows = bUseReferenceTile ? ReferenceStripHeight : 0;
	const int32 RTWidth = CellsDimensionX;
	const int32 RTHeight = CellsDimensionY + BorderRows;
	const bool bNeedSurfaceStateCapture = bUseDualReferenceStrip;
	const bool bIndicesValid = CachedRadiationIndices.Num() == ExpectedNumCells;
	const bool bDiffuseCaptureReady = !bUseDiffuseCapture || (RT_Diffuse && RT_Diffuse->bCanCreateUAV);
	const bool bDiffuseNoGICaptureReady = !bCaptureDiffuseNoGIForTerrain
		|| (RT_DiffuseNoGI && RT_DiffuseNoGI->bCanCreateUAV
			&& RTY_DiffuseNoGI && RTY_DiffuseNoGI->bCanCreateUAV
			&& RTY_TotalNoGI && RTY_TotalNoGI->bCanCreateUAV);
	const bool bSurfaceStateCaptureReady = !bNeedSurfaceStateCapture || (RT_SurfaceState && RT_SurfaceState->bCanCreateUAV && RTY_SurfaceState && RTY_SurfaceState->bCanCreateUAV);

	if (bRadiationCaptureInitialized &&
		CachedRadiationCaptureWidth == RTWidth &&
		CachedRadiationCaptureHeight == RTHeight &&
		bCachedUseReferenceTile == bUseReferenceTile &&
		RadiationCapture && RT_Total && RT_Direct &&
		RT_Total->bCanCreateUAV && RT_Direct->bCanCreateUAV &&
		bDiffuseCaptureReady &&
		bDiffuseNoGICaptureReady &&
		bSurfaceStateCaptureReady &&
		bIndicesValid)
	{
		ApplyPersistentRadiationCaptureLODSettings();
		return;
	}

	if (bRadiationCaptureInitialized)
	{
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Configuration changed - reinitializing capture (old=%dx%d, new=%dx%d, refTile %s→%s, CachedIndices=%d, expected=%d)"),
			CachedRadiationCaptureWidth, CachedRadiationCaptureHeight,
			RTWidth, RTHeight,
			bCachedUseReferenceTile ? TEXT("TRUE") : TEXT("FALSE"),
			bUseReferenceTile ? TEXT("TRUE") : TEXT("FALSE"),
			CachedRadiationIndices.Num(), ExpectedNumCells);
	}

	// Create SceneCapture component if needed
	if (!RadiationCapture)
	{
		RadiationCapture = NewObject<USceneCaptureComponent2D>(this, TEXT("RadiationCapture"));
		RadiationCapture->RegisterComponent();
	}

	USceneComponent* CaptureAttachRoot = RootComponent;
	if (!CaptureAttachRoot || CaptureAttachRoot == RadiationCapture)
	{
		USceneComponent* SceneRoot = NewObject<USceneComponent>(this, TEXT("RuntimeSceneRoot"));
		if (SceneRoot)
		{
			SceneRoot->RegisterComponent();
			SetRootComponent(SceneRoot);
			CaptureAttachRoot = SceneRoot;
		}
	}

	if (CaptureAttachRoot && RadiationCapture->GetAttachParent() != CaptureAttachRoot)
	{
		RadiationCapture->AttachToComponent(CaptureAttachRoot, FAttachmentTransformRules::KeepRelativeTransform);
	}

	ApplyPersistentRadiationCaptureLODSettings();

	// Create render targets
	// Option A: Add top border rows at y=0 for reference tile
	
	const ETextureRenderTargetFormat CaptureRenderTargetFormat = GetRadiationCaptureRenderTargetFormat(bUseRGBA32fRadiationTargets);
	const TCHAR* CaptureRenderTargetFormatLabel = GetRadiationCaptureRenderTargetFormatLabel(CaptureRenderTargetFormat);

	// VALIDATION: If existing targets are invalid (wrong size, format, or missing UAV), destroy them so we can recreate fresh.
	if (RT_Total && (RT_Total->SizeX != RTWidth || RT_Total->SizeY != RTHeight || !RT_Total->bCanCreateUAV || RT_Total->RenderTargetFormat != CaptureRenderTargetFormat))
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] RT_Total invalid (Size=%dx%d vs %dx%d, UAV=%d, Format=%s vs %s). Recreating..."),
			RT_Total->SizeX, RT_Total->SizeY, RTWidth, RTHeight, RT_Total->bCanCreateUAV,
			GetRadiationCaptureRenderTargetFormatLabel(RT_Total->RenderTargetFormat), CaptureRenderTargetFormatLabel);
		RT_Total->ReleaseResource();
		RT_Total = nullptr; // Will be recreated below
	}

	if (!RT_Total)
	{
		RT_Total = NewObject<UTextureRenderTarget2D>(this, TEXT("RT_Total"));
		RT_Total->RenderTargetFormat = CaptureRenderTargetFormat; // HDR format
		RT_Total->InitAutoFormat(RTWidth, RTHeight);
		RT_Total->bCanCreateUAV = true; // Required for ClearRenderTargetTexture
		RT_Total->UpdateResourceImmediate(true);
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Created RT_Total: %dx%d (%s) [%d border rows]"),
			RTWidth, RTHeight, CaptureRenderTargetFormatLabel, BorderRows);
	}

	if (RT_Direct && (RT_Direct->SizeX != RTWidth || RT_Direct->SizeY != RTHeight || !RT_Direct->bCanCreateUAV || RT_Direct->RenderTargetFormat != CaptureRenderTargetFormat))
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] RT_Direct invalid (Size=%dx%d vs %dx%d, UAV=%d, Format=%s vs %s). Recreating..."),
			RT_Direct->SizeX, RT_Direct->SizeY, RTWidth, RTHeight, RT_Direct->bCanCreateUAV,
			GetRadiationCaptureRenderTargetFormatLabel(RT_Direct->RenderTargetFormat), CaptureRenderTargetFormatLabel);
		RT_Direct->ReleaseResource();
		RT_Direct = nullptr; // Will be recreated below
	}

	if (!RT_Direct)
	{
		RT_Direct = NewObject<UTextureRenderTarget2D>(this, TEXT("RT_Direct"));
		RT_Direct->RenderTargetFormat = CaptureRenderTargetFormat;
		RT_Direct->InitAutoFormat(RTWidth, RTHeight);
		RT_Direct->bCanCreateUAV = true; // Required for ClearRenderTargetTexture
		RT_Direct->UpdateResourceImmediate(true);
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Created RT_Direct: %dx%d (%s) [%d border rows]"),
			RTWidth, RTHeight, CaptureRenderTargetFormatLabel, BorderRows);
	}

	if (bUseDiffuseCapture)
	{
		if (RT_Diffuse && (RT_Diffuse->SizeX != RTWidth || RT_Diffuse->SizeY != RTHeight || !RT_Diffuse->bCanCreateUAV || RT_Diffuse->RenderTargetFormat != CaptureRenderTargetFormat))
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] RT_Diffuse invalid (Size=%dx%d vs %dx%d, UAV=%d, Format=%s vs %s). Recreating..."),
				RT_Diffuse->SizeX, RT_Diffuse->SizeY, RTWidth, RTHeight, RT_Diffuse->bCanCreateUAV,
				GetRadiationCaptureRenderTargetFormatLabel(RT_Diffuse->RenderTargetFormat), CaptureRenderTargetFormatLabel);
			RT_Diffuse->ReleaseResource();
			RT_Diffuse = nullptr; // Will be recreated below
		}

		if (!RT_Diffuse)
		{
			RT_Diffuse = NewObject<UTextureRenderTarget2D>(this, TEXT("RT_Diffuse"));
			RT_Diffuse->RenderTargetFormat = CaptureRenderTargetFormat;
			RT_Diffuse->InitAutoFormat(RTWidth, RTHeight);
			RT_Diffuse->bCanCreateUAV = true; // Required for ClearRenderTargetTexture
			RT_Diffuse->UpdateResourceImmediate(true);
			UE_LOG(LogTemp, Display, TEXT("[RadCapture] Created RT_Diffuse: %dx%d (%s) [%d border rows]"),
				RTWidth, RTHeight, CaptureRenderTargetFormatLabel, BorderRows);
		}
	}

	if (bCaptureDiffuseNoGIForTerrain)
	{
		if (RT_DiffuseNoGI && (RT_DiffuseNoGI->SizeX != RTWidth || RT_DiffuseNoGI->SizeY != RTHeight || !RT_DiffuseNoGI->bCanCreateUAV || RT_DiffuseNoGI->RenderTargetFormat != CaptureRenderTargetFormat))
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] RT_DiffuseNoGI invalid (Size=%dx%d vs %dx%d, UAV=%d, Format=%s vs %s). Recreating..."),
				RT_DiffuseNoGI->SizeX, RT_DiffuseNoGI->SizeY, RTWidth, RTHeight, RT_DiffuseNoGI->bCanCreateUAV,
				GetRadiationCaptureRenderTargetFormatLabel(RT_DiffuseNoGI->RenderTargetFormat), CaptureRenderTargetFormatLabel);
			RT_DiffuseNoGI->ReleaseResource();
			RT_DiffuseNoGI = nullptr;
		}

		if (!RT_DiffuseNoGI)
		{
			RT_DiffuseNoGI = NewObject<UTextureRenderTarget2D>(this, TEXT("RT_DiffuseNoGI"));
			RT_DiffuseNoGI->RenderTargetFormat = CaptureRenderTargetFormat;
			RT_DiffuseNoGI->InitAutoFormat(RTWidth, RTHeight);
			RT_DiffuseNoGI->bCanCreateUAV = true;
			RT_DiffuseNoGI->UpdateResourceImmediate(true);
			UE_LOG(LogTemp, Display, TEXT("[RadCapture] Created RT_DiffuseNoGI: %dx%d (%s) [%d border rows]"),
				RTWidth, RTHeight, CaptureRenderTargetFormatLabel, BorderRows);
		}
	}

	if (bNeedSurfaceStateCapture)
	{
		if (RT_SurfaceState && (RT_SurfaceState->SizeX != RTWidth || RT_SurfaceState->SizeY != RTHeight || !RT_SurfaceState->bCanCreateUAV || RT_SurfaceState->RenderTargetFormat != CaptureRenderTargetFormat))
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] RT_SurfaceState invalid (Size=%dx%d vs %dx%d, UAV=%d, Format=%s vs %s). Recreating..."),
				RT_SurfaceState->SizeX, RT_SurfaceState->SizeY, RTWidth, RTHeight, RT_SurfaceState->bCanCreateUAV,
				GetRadiationCaptureRenderTargetFormatLabel(RT_SurfaceState->RenderTargetFormat), CaptureRenderTargetFormatLabel);
			RT_SurfaceState->ReleaseResource();
			RT_SurfaceState = nullptr;
		}

		if (!RT_SurfaceState)
		{
			RT_SurfaceState = NewObject<UTextureRenderTarget2D>(this, TEXT("RT_SurfaceState"));
			RT_SurfaceState->RenderTargetFormat = CaptureRenderTargetFormat;
			RT_SurfaceState->InitAutoFormat(RTWidth, RTHeight);
			RT_SurfaceState->bCanCreateUAV = true;
			RT_SurfaceState->UpdateResourceImmediate(true);
			UE_LOG(LogTemp, Display, TEXT("[RadCapture] Created RT_SurfaceState: %dx%d (%s) [%d border rows]"),
				RTWidth, RTHeight, CaptureRenderTargetFormatLabel, BorderRows);
		}
	}

	// Helper lambda to recreate render targets with UAV support when needed
	auto HasUAVFlag = [](UTextureRenderTarget2D* Target) -> bool
	{
		if (!Target)
		{
			return false;
		}

		if (FTextureRenderTargetResource* Resource = Target->GameThread_GetRenderTargetResource())
		{
			if (FTextureRHIRef TextureRHI = Resource->TextureRHI)
			{
				const FRHITextureDesc& Desc = TextureRHI->GetDesc();
				return EnumHasAllFlags(Desc.Flags, TexCreate_UAV);
			}
		}

		return false;
	};

	auto RecreateRenderTarget = [this, &HasUAVFlag](UTextureRenderTarget2D*& Target,
		const TCHAR* DebugName,
		ETextureRenderTargetFormat Format,
		int32 Width,
		int32 Height,
		bool bAutoGenerateMips)
	{
		const bool bHadExisting = (Target != nullptr);

		if (bHadExisting)
		{
			Target->ReleaseResource();
			FlushRenderingCommands();
			Target->ConditionalBeginDestroy();
			Target = nullptr;
		}

		const EPixelFormat PixelFormat = GetPixelFormatFromRenderTargetFormat(Format);
		if (!ensureMsgf(PixelFormat != PF_Unknown, TEXT("[RadCapture] Unsupported render target format for %s"), DebugName))
		{
			return;
		}

		Target = NewObject<UTextureRenderTarget2D>(this, DebugName);
		Target->RenderTargetFormat = Format;
		Target->InitCustomFormat(Width, Height, PixelFormat, /*bForceLinearGamma=*/false);
		Target->bAutoGenerateMips = bAutoGenerateMips;
		Target->bCanCreateUAV = true;
		Target->UpdateResourceImmediate(true);
		FlushRenderingCommands();

		if (HasUAVFlag(Target))
		{
			UE_LOG(LogTemp, Display, TEXT("[RadCapture] %s %s (%dx%d) with UAV support"),
				bHadExisting ? TEXT("Recreated") : TEXT("Created"),
				DebugName,
				Width,
				Height);
		}
		else
		{
			UE_LOG(LogTemp, Error, TEXT("[RadCapture] Failed to %s %s with UAV flag (%dx%d)"),
				bHadExisting ? TEXT("recreate") : TEXT("create"),
				DebugName,
				Width,
				Height);
		}
	};

	auto EnsureUAVReady = [&RecreateRenderTarget, &HasUAVFlag](UTextureRenderTarget2D*& Target,
		const TCHAR* DebugName,
		ETextureRenderTargetFormat Format,
		int32 Width,
		int32 Height,
		bool bAutoGenerateMips)
	{
		if (Target)
		{
			const bool bSizeMismatch = (Target->SizeX != Width) || (Target->SizeY != Height);
			if (bSizeMismatch)
			{
				UE_LOG(LogTemp, Display, TEXT("[RadCapture] %s size mismatch (existing %dx%d, expected %dx%d). Recreating."),
					DebugName, Target->SizeX, Target->SizeY, Width, Height);
				RecreateRenderTarget(Target, DebugName, Format, Width, Height, bAutoGenerateMips);
				return;
			}

			if (HasUAVFlag(Target))
			{
				return;
			}

			Target->bCanCreateUAV = true;
			Target->UpdateResourceImmediate(true);
			FlushRenderingCommands();

			if (HasUAVFlag(Target))
			{
				return;
			}

			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] %s missing UAV support. Recreating."), DebugName);
			RecreateRenderTarget(Target, DebugName, Format, Width, Height, bAutoGenerateMips);
			return;
		}

		RecreateRenderTarget(Target, DebugName, Format, Width, Height, bAutoGenerateMips);
	};

	EnsureUAVReady(RTY_Total, TEXT("RTY_Total"), RTF_R16f, RTWidth, RTHeight, false);
	EnsureUAVReady(RTY_Direct, TEXT("RTY_Direct"), RTF_R16f, RTWidth, RTHeight, false);

	EnsureUAVReady(RTY_Diffuse, TEXT("RTY_Diffuse"), RTF_R16f, RTWidth, RTHeight, false);
	if (bCaptureDiffuseNoGIForTerrain)
	{
		EnsureUAVReady(RTY_TotalNoGI, TEXT("RTY_TotalNoGI"), RTF_R16f, RTWidth, RTHeight, false);
		EnsureUAVReady(RTY_DiffuseNoGI, TEXT("RTY_DiffuseNoGI"), RTF_R16f, RTWidth, RTHeight, false);
	}
	if (bNeedSurfaceStateCapture)
	{
		EnsureUAVReady(RTY_SurfaceState, TEXT("RTY_SurfaceState"), RTF_R16f, RTWidth, RTHeight, false);
	}

	// Temporary buffer for blur (optional)
	if (bBlurDiffuse)
	{
		EnsureUAVReady(RTY_DiffuseTemp, TEXT("RTY_DiffuseTemp"), RTF_R16f, RTWidth, RTHeight, false);
	}

	EnsureUAVReady(RTF_DirIndex, TEXT("RTF_DirIndex"), RTF_R16f, RTWidth, RTHeight, false);
	EnsureUAVReady(RTF_DiffIndex, TEXT("RTF_DiffIndex"), RTF_R16f, RTWidth, RTHeight, false);

	if (bEnableRawRadiationIndexTexture)
	{
		EnsureUAVReady(RTF_rUE_raw, TEXT("RTF_rUE_raw"), RTF_R16f, RTWidth, RTHeight, false);
	}
	else
	{
		// Optional diagnostic texture: release actor reference when disabled.
		RTF_rUE_raw = nullptr;
	}

	if (bEnableTimeIntegratedRadiation)
	{
		EnsureTimeIntegrationTargets(RTWidth, RTHeight);
	}

    // Configure scene capture for orthographic projection
    RadiationCapture->ProjectionType = ECameraProjectionMode::Orthographic;
    // RadiationCapture->FOVAngle = 1.0f; // Not used in Ortho
    RadiationCapture->CaptureSource = SCS_SceneColorHDR; // Pre-tonemap HDR - CRITICAL for linear values
    RadiationCapture->bCaptureEveryFrame = false; // Manual capture
	RadiationCapture->bCaptureOnMovement = false;
	RadiationCapture->bAlwaysPersistRenderingState = false; // Force fresh Lumen history every capture to avoid multi-hour lag

	// ========================================================================
	// CRITICAL: Disable auto-exposure and force fixed EV100 for determinism
	// ========================================================================

	// Method 1: Disable auto-exposure entirely
	RadiationCapture->PostProcessSettings.bOverride_AutoExposureMethod = true;
	RadiationCapture->PostProcessSettings.AutoExposureMethod = AEM_Manual;

	// Method 2: Set manual exposure bias (EV100)
	// EV100 formula: Exposure = 2^EV100
	// EV100=0  → Exposure multiplier = 1.0 (no compensation, physically accurate)
	// EV100=1  → Exposure multiplier = 2.0 (2x brighter)
	// EV100=-1 → Exposure multiplier = 0.5 (2x darker)
	RadiationCapture->PostProcessSettings.bOverride_AutoExposureBias = true;
	RadiationCapture->PostProcessSettings.AutoExposureBias = RadiationCaptureEV100;

	// Method 3: Lock min/max exposure values (prevents auto-adaptation)
	RadiationCapture->PostProcessSettings.bOverride_AutoExposureMinBrightness = true;
	RadiationCapture->PostProcessSettings.AutoExposureMinBrightness = 1.0f;
	RadiationCapture->PostProcessSettings.bOverride_AutoExposureMaxBrightness = true;
	RadiationCapture->PostProcessSettings.AutoExposureMaxBrightness = 1.0f;

	// Method 4: Disable bloom and other post-process contamination
	RadiationCapture->PostProcessSettings.bOverride_BloomIntensity = true;
	RadiationCapture->PostProcessSettings.BloomIntensity = 0.0f;
	RadiationCapture->PostProcessSettings.bOverride_VignetteIntensity = true;
	RadiationCapture->PostProcessSettings.VignetteIntensity = 0.0f;

	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Auto-exposure DISABLED. Manual EV100=%.2f (Exposure multiplier = 2^%.2f = %.4f)"),
		RadiationCaptureEV100, RadiationCaptureEV100, FMath::Pow(2.0f, RadiationCaptureEV100));

	// ========================================================================
	// CRITICAL: Precise Grid-to-Pixel Mapping
	// ========================================================================
	// Goal: Grid cell (i,j) maps exactly to pixel (x=i, y=j) in render targets
	// Coordinate system: +X→right, +Y→up (standard image coordinates)
	// Orthographic projection ensures no perspective distortion
	// ========================================================================

	if (!Landscape)
	{
		UE_LOG(LogTemp, Error, TEXT("[RadCapture] Cannot setup: Landscape is null"));
		return;
	}

	// Grid parameters (derived from landscape)
	const FVector LandscapeMin = Landscape->GetActorLocation(); // World-space origin (cm)
	const FVector LocalLandscapeScale = Landscape->GetActorScale(); // Unreal units per vertex
	const float CellSizeWorld = LocalLandscapeScale.X * static_cast<float>(CellSize); // cm per cell (X and Y should match)
	const float GridWidthWorld = CellSizeWorld * static_cast<float>(CellsDimensionX); // cm
	const float GridHeightWorld = CellSizeWorld * static_cast<float>(CellsDimensionY); // cm

	// Grid center in world space (cm)
	const FVector GridCenterWorld = LandscapeMin + FVector(GridWidthWorld * 0.5f, GridHeightWorld * 0.5f, 0.0f);

	// ========================================================================
	// VALIDATION ASSERTS: Catch configuration mismatches
	// ========================================================================

	// Assert 1: Render target size matches grid dimensions (plus optional border)
	checkf(RTWidth == CellsDimensionX,
		TEXT("[RadCapture] RT width mismatch! RTWidth=%d, CellsDimensionX=%d. Each grid cell must map to exactly one pixel."),
		RTWidth, CellsDimensionX);

	const int32 ExpectedRTHeight = CellsDimensionY + BorderRows;
	checkf(RTHeight == ExpectedRTHeight,
		TEXT("[RadCapture] RT height mismatch! RTHeight=%d, Expected=%d (CellsDimensionY=%d + BorderRows=%d)."),
		RTHeight, ExpectedRTHeight, CellsDimensionY, BorderRows);

	// Assert 2: Landscape scale is uniform (X == Y) to prevent distortion
	const float ScaleDiff = FMath::Abs(LocalLandscapeScale.X - LocalLandscapeScale.Y);
	checkf(ScaleDiff < 0.01f,
		TEXT("[RadCapture] Non-uniform landscape scale! X=%.3f, Y=%.3f. This will cause grid distortion."),
		LocalLandscapeScale.X, LocalLandscapeScale.Y);

	// Assert 3: Cell size produces valid grid.
	// In editor property-change callbacks, MetersPerCell can still be stale (0) before full init.
	const float DerivedMetersPerCell = (LocalLandscapeScale.X / 100.0f) * static_cast<float>(CellSize);
	if (!FMath::IsFinite(MetersPerCell) || MetersPerCell <= 0.0f)
	{
		MetersPerCell = DerivedMetersPerCell;
	}
	if (!FMath::IsFinite(MetersPerCell) || MetersPerCell <= 0.0f)
	{
		UE_LOG(LogTemp, Warning,
			TEXT("[RadCapture] Invalid MetersPerCell=%.3f (derived=%.3f). Skipping SetupRadiationCapture until grid metrics are initialized."),
			MetersPerCell, DerivedMetersPerCell);
		return;
	}

	// ========================================================================
	// PROJECTION SETUP (Orthographic or Telephoto Perspective)
	// ========================================================================

	const float TotalHeightWorld = GridHeightWorld + (BorderRows * CellSizeWorld);

	// Default: orthographic (legacy)
	if (!bUseTelephotoCapture)
	{
		// OrthoWidth is full width of captured area (cm)
		RadiationCapture->ProjectionType = ECameraProjectionMode::Orthographic;
		RadiationCapture->OrthoWidth = GridWidthWorld;

		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Projection = ORTHO | OrthoWidth=%.3f cm, TotalHeight=%.3f cm (Grid=%.3f + Border=%.3f)"),
			RadiationCapture->OrthoWidth, TotalHeightWorld, GridHeightWorld, BorderRows * CellSizeWorld);
	}
	else
	{
		// Telephoto perspective: small FOV, high camera to approximate ortho but enable Lumen GI
		const float Aspect = (RTHeight > 0) ? static_cast<float>(RTWidth) / static_cast<float>(RTHeight) : 1.0f;
		const float ClampedFOV = FMath::Clamp(TelephotoFOVDegrees, 1.0f, 60.0f);
		const float VFOVRad = FMath::DegreesToRadians(ClampedFOV);
		const float TanHalfV = FMath::Max(FMath::Tan(VFOVRad * 0.5f), KINDA_SMALL_NUMBER);
		const float TanHalfH = FMath::Max(TanHalfV * Aspect, KINDA_SMALL_NUMBER);

		const float DistForHeight = (TotalHeightWorld * 0.5f) / TanHalfV;
		const float DistForWidth = (GridWidthWorld * 0.5f) / TanHalfH;
		const float CaptureHeight = FMath::Max(DistForHeight, DistForWidth);

		RadiationCapture->ProjectionType = ECameraProjectionMode::Perspective;
		RadiationCapture->FOVAngle = ClampedFOV;

		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Projection = TELEPHOTO | FOV=%.1f deg | Height to fit (cm)=%.1f | TotalHeight=%.1f | GridWidth=%.1f"),
			ClampedFOV, CaptureHeight, TotalHeightWorld, GridWidthWorld);

		// Override the default ortho height with computed telephoto height
		// (Camera location is applied below)
		// NOTE: we keep OrthoWidth untouched; mapping uses linear grid projection.
	}

	// ========================================================================
	// CAMERA TRANSFORM: Top-Down (aligned with landscape)
	// ========================================================================

	// Get landscape rotation to transform from local to world space
	const FRotator LandscapeRotation = Landscape->GetActorRotation();

	// With reference border, we need to offset the camera to include the top border rows at y=0
	// Reference border is positioned BELOW the grid origin (negative Y offset in LANDSCAPE LOCAL SPACE)
	const float BorderHeightWorld = BorderRows * CellSizeWorld;
	const float TotalCaptureHeightWorld = GridHeightWorld + BorderHeightWorld;

	// Center of TOTAL capture area (grid + border) in LANDSCAPE LOCAL SPACE
	// When a reference strip is enabled, we place it entirely below the simulation grid,
	// so the capture must shift down (negative Y in local space) by half the border height
	const float CaptureCenterYLocal = (GridHeightWorld - BorderHeightWorld) * 0.5f;
	const FVector CaptureCenterLocal = FVector(
		GridWidthWorld * 0.5f,   // X: centered on grid width (local space)
		CaptureCenterYLocal,     // Y: adjusted for border (local space)
		0.0f);                   // Z: at landscape base level

	// Transform capture center from landscape local space to world space
	const FVector CaptureCenterWorldOffset = LandscapeRotation.RotateVector(CaptureCenterLocal);
	const FVector CaptureCenterWorld = LandscapeMin + CaptureCenterWorldOffset;

	// Position: Above capture center, looking down
	float CaptureHeight = 100000.0f; // default height (cm) for ortho - increased to 1km to clear typical terrain
	float MinCaptureHeightForReference = 0.0f;
	if (bUseReferenceTile)
	{
		// Ensure camera is above the dynamically elevated reference plane:
		// plane world Z = max terrain Z + configured offset.
		float MaxTerrainWorldZ = LandscapeMin.Z;
		if (LandscapeCells.Num() > 0)
		{
			for (const FLandscapeCell& Cell : LandscapeCells)
			{
				MaxTerrainWorldZ = FMath::Max(MaxTerrainWorldZ, Cell.Centroid.Z);
			}
		}

		const float RefPlaneWorldZ = MaxTerrainWorldZ + ReferencePlaneHeightOffsetMeters * 100.0f;
		MinCaptureHeightForReference = (RefPlaneWorldZ - CaptureCenterWorld.Z) + 5000.0f; // 50m clearance
		CaptureHeight = FMath::Max(CaptureHeight, MinCaptureHeightForReference);
	}
	if (bUseTelephotoCapture)
	{
		// Recompute using telephoto fit values from above
		const float Aspect = (RTHeight > 0) ? static_cast<float>(RTWidth) / static_cast<float>(RTHeight) : 1.0f;
		const float ClampedFOV = FMath::Clamp(TelephotoFOVDegrees, 1.0f, 60.0f);
		const float VFOVRad = FMath::DegreesToRadians(ClampedFOV);
		const float TanHalfV = FMath::Max(FMath::Tan(VFOVRad * 0.5f), KINDA_SMALL_NUMBER);
		const float TanHalfH = FMath::Max(TanHalfV * Aspect, KINDA_SMALL_NUMBER);

		const float DistForHeight = (TotalHeightWorld * 0.5f) / TanHalfV;
		const float DistForWidth = (GridWidthWorld * 0.5f) / TanHalfH;
		CaptureHeight = FMath::Max(DistForHeight, DistForWidth);
	}
	if (bUseReferenceTile)
	{
		CaptureHeight = FMath::Max(CaptureHeight, MinCaptureHeightForReference);
	}
	const FVector CaptureLocation = CaptureCenterWorld + FVector(0.0f, 0.0f, CaptureHeight);

	// Rotation: Look straight down (-Z axis) with an explicit yaw offset that aligns
	// capture axes to landscape cell indexing:
	// - RT X increases along landscape local +X
	// - RT Y increases along landscape local +Y (down in texture space)
	// This keeps the reference strip at local negative Y on the TOP rows of the RT.
	const float EffectiveCaptureYawOffsetDeg = FMath::Clamp(CaptureYawOffsetDegrees, -180.0f, 180.0f);
	const FRotator CameraBaseRotation = FRotator(-90.0f, 0.0f, 0.0f);
	const FRotator CaptureRotation = FRotator(
		CameraBaseRotation.Pitch,
		CameraBaseRotation.Yaw + LandscapeRotation.Yaw + EffectiveCaptureYawOffsetDeg,
		CameraBaseRotation.Roll + LandscapeRotation.Roll  // Add landscape roll if any
	);

	RadiationCapture->SetWorldLocation(CaptureLocation);
	RadiationCapture->SetWorldRotation(CaptureRotation);

	// ========================================================================
	// VERIFICATION LOG
	// ========================================================================

	UE_LOG(LogTemp, Display, TEXT("[RadCapture] ===== Grid-to-Pixel Mapping Configuration ====="));
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Grid Dimensions: %d x %d cells"), CellsDimensionX, CellsDimensionY);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] RT Dimensions: %d x %d pixels"), RTWidth, RTHeight);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Cell Size: %.3f cm (%.3f m)"), CellSizeWorld, CellSizeWorld / 100.0f);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Grid World Size: %.3f x %.3f cm (%.3f x %.3f m)"),
		GridWidthWorld, GridHeightWorld, GridWidthWorld / 100.0f, GridHeightWorld / 100.0f);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Landscape Origin: X=%.3f, Y=%.3f, Z=%.3f cm"), LandscapeMin.X, LandscapeMin.Y, LandscapeMin.Z);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Landscape Rotation: Pitch=%.1f, Yaw=%.1f, Roll=%.1f"),
		LandscapeRotation.Pitch, LandscapeRotation.Yaw, LandscapeRotation.Roll);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Capture Center (World): X=%.3f, Y=%.3f, Z=%.3f cm"),
		CaptureCenterWorld.X, CaptureCenterWorld.Y, CaptureCenterWorld.Z);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Capture Location: X=%.3f, Y=%.3f, Z=%.3f cm"),
		CaptureLocation.X, CaptureLocation.Y, CaptureLocation.Z);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Capture Rotation: Pitch=%.1f, Yaw=%.1f, Roll=%.1f"),
		CaptureRotation.Pitch, CaptureRotation.Yaw, CaptureRotation.Roll);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] CaptureYawOffsetDegrees: %.1f"), EffectiveCaptureYawOffsetDeg);
	{
		const FVector CaptureRight = CaptureRotation.RotateVector(FVector::RightVector).GetSafeNormal();
		const FVector CaptureUp = CaptureRotation.RotateVector(FVector::UpVector).GetSafeNormal();
		const FVector LandscapeX = LandscapeRotation.RotateVector(FVector::ForwardVector).GetSafeNormal();
		const FVector LandscapeY = LandscapeRotation.RotateVector(FVector::RightVector).GetSafeNormal();
		const float RightAlignX = FVector::DotProduct(CaptureRight, LandscapeX);
		const float UpAlignNegY = FVector::DotProduct(CaptureUp, -LandscapeY);
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Axis alignment: dot(Right,Landscape+X)=%.4f, dot(Up,Landscape-Y)=%.4f"),
			RightAlignX, UpAlignNegY);
	}
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] OrthoWidth: %.3f cm (%.3f m)"),
		RadiationCapture->OrthoWidth, RadiationCapture->OrthoWidth / 100.0f);
	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Coordinate System: RT-X -> Landscape+X, RT-Y(top->bottom) -> Landscape-Y to +Y"));

	UpdateRadiationCellPixelMapping(GridWidthWorld, TotalHeightWorld, CaptureCenterWorld, CaptureLocation, CaptureRotation, RTWidth, RTHeight);

	if (bUseReferenceTile)
	{
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Reference Border: ENABLED (Option A: y=0 border strip)"));
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Mapping: Cell centroids projected to capture atlas (reference row included)"));
	}
	else
	{
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Reference Border: DISABLED"));
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Mapping: Cell centroids projected to capture atlas"));
	}

	UE_LOG(LogTemp, Display, TEXT("[RadCapture] ============================================="));

	// Initialize cached ShowFlags
	CachedShowFlags_Total = FEngineShowFlags(ESFIM_Game);
	CachedShowFlags_Direct = FEngineShowFlags(ESFIM_Game);
	CachedShowFlags_Diffuse = FEngineShowFlags(ESFIM_Game);
	CachedShowFlags_DiffuseNoGI = FEngineShowFlags(ESFIM_Game);
	CachedShowFlags_SurfaceState = FEngineShowFlags(ESFIM_Game);

	ConfigureShowFlags_Total(CachedShowFlags_Total);
	ConfigureShowFlags_Direct(CachedShowFlags_Direct);
	ConfigureShowFlags_Diffuse(CachedShowFlags_Diffuse);
	ConfigureShowFlags_DiffuseNoGI(CachedShowFlags_DiffuseNoGI);
	ConfigureShowFlags_SurfaceState(CachedShowFlags_SurfaceState);

	// Setup reference plane if enabled
	if (bUseReferenceTile)
	{
		SetupReferencePlane();
	}

	UE_LOG(LogTemp, Display, TEXT("[RadCapture] Setup complete: %dx%d atlas, EV100=%.2f"),
		RTWidth, RTHeight, RadiationCaptureEV100);

	InitializeRadiationExtraction();

	// Perform runtime validation of grid-to-pixel mapping
	ValidateGridToPixelMapping();

	bRadiationCaptureInitialized = true;
	CachedRadiationCaptureWidth = RTWidth;
	CachedRadiationCaptureHeight = RTHeight;
	bCachedUseReferenceTile = bUseReferenceTile;
}

void ASnowSimulationActor::UpdateRadiationCellPixelMapping(float GridWidthWorld, float TotalHeightWorld, const FVector& CaptureCenterWorld, const FVector& CaptureLocation, const FRotator& CaptureRotation, int32 RTWidth, int32 RTHeight)
{
	const int32 LocalCellCount = CellsDimensionX * CellsDimensionY;
	if (LocalCellCount <= 0 || LandscapeCells.Num() != LocalCellCount)
	{
		RadiationCellPixelCoords.Reset();
		ReleaseRadiationPixelCoordResources();
		return;
	}

	const FVector RightDir = CaptureRotation.RotateVector(FVector::RightVector).GetSafeNormal();
	const FVector UpDir = CaptureRotation.RotateVector(FVector::UpVector).GetSafeNormal();

	if (RightDir.IsNearlyZero() || UpDir.IsNearlyZero() || GridWidthWorld <= KINDA_SMALL_NUMBER || TotalHeightWorld <= KINDA_SMALL_NUMBER)
	{
		RadiationCellPixelCoords.Reset();
		ReleaseRadiationPixelCoordResources();
		return;
	}

	RadiationCellPixelCoords.SetNum(LocalCellCount);

	if (!bUseTelephotoCapture)
	{
		const float HalfWidth = GridWidthWorld * 0.5f;
		const float HalfHeight = TotalHeightWorld * 0.5f;
		const float InvWidth = 1.0f / GridWidthWorld;
		const float InvHeight = 1.0f / TotalHeightWorld;

		for (int32 Idx = 0; Idx < LocalCellCount; ++Idx)
		{
			const FVector& Centroid = LandscapeCells[Idx].Centroid;
			const FVector Delta = Centroid - CaptureCenterWorld;

			const float AlongRight = FVector::DotProduct(Delta, RightDir);
			const float AlongUp = FVector::DotProduct(Delta, UpDir);

			const float U = FMath::Clamp(((AlongRight + HalfWidth) * InvWidth), 0.0f, 1.0f);
			// Invert V because texture coordinates are 0 at top (Camera Up), but parametric V (0-1) increases along UpDir
			const float V = 1.0f - FMath::Clamp(((AlongUp + HalfHeight) * InvHeight), 0.0f, 1.0f);

			const int32 PixelX = FMath::Clamp(FMath::RoundToInt(U * (RTWidth - 1)), 0, RTWidth - 1);
			const int32 PixelY = FMath::Clamp(FMath::RoundToInt(V * (RTHeight - 1)), 0, RTHeight - 1);

			RadiationCellPixelCoords[Idx] = FIntPoint(PixelX, PixelY);
		}
	}
	else
	{
		// Perspective (telephoto) mapping: project cell centroids into screen space
		const float Aspect = (RTHeight > 0) ? static_cast<float>(RTWidth) / static_cast<float>(RTHeight) : 1.0f;
		const float ClampedFOV = FMath::Clamp(TelephotoFOVDegrees, 1.0f, 60.0f);
		const float VFOVRad = FMath::DegreesToRadians(ClampedFOV);
		const float TanHalfV = FMath::Max(FMath::Tan(VFOVRad * 0.5f), KINDA_SMALL_NUMBER);
		const float TanHalfH = FMath::Max(TanHalfV * Aspect, KINDA_SMALL_NUMBER);

		for (int32 Idx = 0; Idx < LocalCellCount; ++Idx)
		{
			const FVector& Centroid = LandscapeCells[Idx].Centroid;
			const FVector DeltaWorld = Centroid - CaptureLocation;

			// World -> camera space (camera forward = +X)
			const FVector CamSpace = CaptureRotation.UnrotateVector(DeltaWorld);
			const float Forward = FMath::Max(CamSpace.X, 1.0f); // avoid behind-camera / zero

			const float ProjX = CamSpace.Y / (Forward * TanHalfH);
			const float ProjY = CamSpace.Z / (Forward * TanHalfV);

			const float U = FMath::Clamp(0.5f * (ProjX + 1.0f), 0.0f, 1.0f);
			const float V = FMath::Clamp(0.5f * (1.0f - ProjY), 0.0f, 1.0f);

			const int32 PixelX = FMath::Clamp(FMath::RoundToInt(U * (RTWidth - 1)), 0, RTWidth - 1);
			const int32 PixelY = FMath::Clamp(FMath::RoundToInt(V * (RTHeight - 1)), 0, RTHeight - 1);

			RadiationCellPixelCoords[Idx] = FIntPoint(PixelX, PixelY);
		}
	}

	UploadRadiationCellPixelCoords();
}

void ASnowSimulationActor::UploadRadiationCellPixelCoords()
{
	if (RadiationCellPixelCoords.Num() == 0)
	{
		ReleaseRadiationPixelCoordResources();
		return;
	}

	TArray<FIntPoint> PixelCopy = RadiationCellPixelCoords;
	const int32 NumElements = PixelCopy.Num();

	ENQUEUE_RENDER_COMMAND(UploadRadPixelCoords)(
		[this, NumElements, PixelCopy = MoveTemp(PixelCopy)](FRHICommandListImmediate& RHICmdList) mutable
		{
			if (RadiationPixelCoordBuffer.IsValid())
			{
				RadiationPixelCoordBuffer.SafeRelease();
			}
			if (RadiationPixelCoordSRV.IsValid())
			{
				RadiationPixelCoordSRV.SafeRelease();
			}

			const uint32 BufferSize = NumElements * sizeof(FIntPoint);

			const FRHIBufferCreateDesc CreateDesc =
				FRHIBufferCreateDesc::CreateStructured<FIntPoint>(TEXT("RadiationCellPixelCoords"), NumElements)
				.AddUsage(BUF_Static | BUF_ShaderResource)
				.DetermineInitialState();

			FBufferRHIRef Buffer = RHICmdList.CreateBuffer(CreateDesc);
			void* DataPtr = RHICmdList.LockBuffer(Buffer, 0, BufferSize, RLM_WriteOnly);
			FMemory::Memcpy(DataPtr, PixelCopy.GetData(), BufferSize);
			RHICmdList.UnlockBuffer(Buffer);

			FShaderResourceViewRHIRef SRV = RHICmdList.CreateShaderResourceView(
				Buffer,
				FRHIViewDesc::CreateBufferSRV()
					.SetType(FRHIViewDesc::EBufferType::Structured)
					.SetStride(sizeof(FIntPoint))
					.SetNumElements(NumElements));

			RadiationPixelCoordBuffer = Buffer;
			RadiationPixelCoordSRV = SRV;
		});

	FlushRenderingCommands();
}

void ASnowSimulationActor::ReleaseRadiationPixelCoordResources()
{
	if (!RadiationPixelCoordBuffer.IsValid() && !RadiationPixelCoordSRV.IsValid())
	{
		return;
	}

	FBufferRHIRef BufferToRelease = RadiationPixelCoordBuffer;
	FShaderResourceViewRHIRef SRVToRelease = RadiationPixelCoordSRV;
	RadiationPixelCoordBuffer.SafeRelease();
	RadiationPixelCoordSRV.SafeRelease();

	ENQUEUE_RENDER_COMMAND(ReleaseRadPixelCoords)(
		[BufferToRelease, SRVToRelease](FRHICommandListImmediate&) mutable
		{
			if (BufferToRelease.IsValid())
			{
				BufferToRelease.SafeRelease();
			}
			if (SRVToRelease.IsValid())
			{
				SRVToRelease.SafeRelease();
			}
		});

	FlushRenderingCommands();
}

void ASnowSimulationActor::TickRadiationCaptures(const FDateTime& SimTime, const FTimespan& StepDuration)
{
	UE_LOG(LogTemp, Error, TEXT("[RadTrace] ===== TickRadiationCaptures START ====="));
	static bool bLoggedFirstCall = false;
	static bool bLoggedBlocked = false;

	// Re-evaluate cached show flags each tick so editor toggles (e.g., atmosphere) take effect immediately.
	CachedShowFlags_Total = FEngineShowFlags(ESFIM_Game);
	ConfigureShowFlags_Total(CachedShowFlags_Total);
	CachedShowFlags_Direct = FEngineShowFlags(ESFIM_Game);
	ConfigureShowFlags_Direct(CachedShowFlags_Direct);
	CachedShowFlags_Diffuse = FEngineShowFlags(ESFIM_Game);
	ConfigureShowFlags_Diffuse(CachedShowFlags_Diffuse);
	CachedShowFlags_DiffuseNoGI = FEngineShowFlags(ESFIM_Game);
	ConfigureShowFlags_DiffuseNoGI(CachedShowFlags_DiffuseNoGI);
	CachedShowFlags_SurfaceState = FEngineShowFlags(ESFIM_Game);
	ConfigureShowFlags_SurfaceState(CachedShowFlags_SurfaceState);

	if (!bLoggedFirstCall)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] ===== FIRST CALL TO TickRadiationCaptures ====="));
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture]   bEnableRadiationCapture: %s"), bEnableRadiationCapture ? TEXT("TRUE") : TEXT("FALSE"));
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture]   RadiationCapture: %s"), RadiationCapture ? TEXT("Valid") : TEXT("NULL"));
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture]   RT_Total: %s"), RT_Total ? TEXT("Valid") : TEXT("NULL"));
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture]   RT_Direct: %s"), RT_Direct ? TEXT("Valid") : TEXT("NULL"));
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture]   bExportReferenceMappingDebug: %s"), bExportReferenceMappingDebug ? TEXT("TRUE") : TEXT("FALSE"));
			if (bUseDiffuseCapture)
			{
				UE_LOG(LogTemp, Warning, TEXT("[RadCapture]   RT_Diffuse: %s"), RT_Diffuse ? TEXT("Valid") : TEXT("NULL"));
		}
		if (bCaptureDiffuseNoGIForTerrain)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture]   RT_DiffuseNoGI: %s"), RT_DiffuseNoGI ? TEXT("Valid") : TEXT("NULL"));
		}
		if (bUseDualReferenceStrip)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture]   RT_SurfaceState: %s"), RT_SurfaceState ? TEXT("Valid") : TEXT("NULL"));
		}
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture]   StepDuration: %.2f minutes"), StepDuration.GetTotalMinutes());
		bLoggedFirstCall = true;
	}

	const bool bDiffuseTargetReady = !bUseDiffuseCapture || RT_Diffuse;
	const bool bDiffuseNoGITargetReady = !bCaptureDiffuseNoGIForTerrain || (RT_DiffuseNoGI && RTY_DiffuseNoGI && RTY_TotalNoGI);
	const bool bSurfaceStateTargetReady = !bUseDualReferenceStrip || (RT_SurfaceState && RTY_SurfaceState);
		if (!bEnableRadiationCapture || !RadiationCapture || !RT_Total || !RT_Direct || !bDiffuseTargetReady || !bDiffuseNoGITargetReady || !bSurfaceStateTargetReady)
		{
			if (!bLoggedBlocked)
			{
			UE_LOG(LogTemp, Error, TEXT("[RadCapture] ===== TICK BLOCKED - Radiation capture cannot run ====="));
			UE_LOG(LogTemp, Error, TEXT("[RadCapture]   bEnableRadiationCapture: %s"), bEnableRadiationCapture ? TEXT("TRUE") : TEXT("FALSE"));
			UE_LOG(LogTemp, Error, TEXT("[RadCapture]   RadiationCapture: %s"), RadiationCapture ? TEXT("Valid") : TEXT("NULL"));
			UE_LOG(LogTemp, Error, TEXT("[RadCapture]   RT_Total: %s"), RT_Total ? TEXT("Valid") : TEXT("NULL"));
			UE_LOG(LogTemp, Error, TEXT("[RadCapture]   RT_Direct: %s"), RT_Direct ? TEXT("Valid") : TEXT("NULL"));
			if (bUseDiffuseCapture)
			{
				UE_LOG(LogTemp, Error, TEXT("[RadCapture]   RT_Diffuse: %s"), RT_Diffuse ? TEXT("Valid") : TEXT("NULL"));
			}
			if (bCaptureDiffuseNoGIForTerrain)
			{
				UE_LOG(LogTemp, Error, TEXT("[RadCapture]   RT_DiffuseNoGI: %s"), RT_DiffuseNoGI ? TEXT("Valid") : TEXT("NULL"));
			}
			if (bUseDualReferenceStrip)
			{
				UE_LOG(LogTemp, Error, TEXT("[RadCapture]   RT_SurfaceState: %s"), RT_SurfaceState ? TEXT("Valid") : TEXT("NULL"));
				UE_LOG(LogTemp, Error, TEXT("[RadCapture]   RTY_SurfaceState: %s"), RTY_SurfaceState ? TEXT("Valid") : TEXT("NULL"));
			}
			UE_LOG(LogTemp, Error, TEXT("[RadCapture]   Impact: UpdateReferenceLuminance() will never be called!"));
			UE_LOG(LogTemp, Error, TEXT("[RadCapture]   Fix: Ensure InitializeRadiationCapture() ran successfully in BeginPlay"));
				UE_LOG(LogTemp, Error, TEXT("[RadCapture] ======================================================"));
				bLoggedBlocked = true;
			}
			if (bExportReferenceMappingDebug)
			{
				static int32 RefMapBlockedExportLogCount = 0;
				if (RefMapBlockedExportLogCount++ < 5)
				{
					UE_LOG(LogTemp, Warning, TEXT("[RefMapDebug] Tick blocked; attempting debug snapshot with currently available targets."));
				}
				ExportReferenceMappingDebugSnapshot(SimTime, TEXT("BlockedTick"));
			}
			return;
		}

	// Log first few radiation capture ticks
	static int32 TickCounter = 0;
	if (TickCounter++ < 3)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] ===== Tick %d: Starting radiation capture pipeline ====="), TickCounter);
	}

	// Process any pending GPU readbacks before rendering this frame
	ReadbackRadiationIndices();
	const bool bRTYReadbackOK = ReadbackRTYLuminance();
	if (bRTYReadbackOK)
	{
		bool bUsedTerrainFallbackMode = false;
		BuildTerrainResidualLuminance(
			CachedRTY_Total,
			CachedRTY_Direct,
			CachedRTY_Diffuse,
			CachedRTY_DiffuseNoGI,
			CachedRTY_TotalNoGI,
			TerrainResidualMode,
			CachedRTY_Terrain,
			bUsedTerrainFallbackMode);
		if (bBlurTerrainResidual)
		{
			ApplyGaussianBlurToGrid(CachedRTY_Terrain, CellsDimensionX, CellsDimensionY);
		}

		static bool bLoggedTerrainFallbackPreCapture = false;
		if (bUsedTerrainFallbackMode && !bLoggedTerrainFallbackPreCapture)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] RTY_Terrain pre-capture update uses fallback Total-Direct-Diffuse (no sky-only cache)."));
			bLoggedTerrainFallbackPreCapture = true;
		}

		if (!bRadiationBenchmarkCaptureActive)
		{
			if (UDegreeDaySimulation* DDSim = Cast<UDegreeDaySimulation>(Simulation))
			{
				DDSim->UpdateRTYLuminance(CachedRTY_Total, CachedRTY_Direct, CachedRTY_Diffuse, CachedRTY_DiffuseNoGI, CachedRTY_TotalNoGI, CachedRTY_Terrain);
			}
		}
	}
	if (bUseReferenceTile)
	{
		UpdateReferenceLuminance(false);
	}

	auto LogCaptureTelemetry = [&](const TCHAR* StageLabel, bool bIsPriming, const FDateTime& LightingTime)
	{
		if (!bDebugRadiationCapture)
		{
			return;
		}

		const UDirectionalLightComponent* SunLight = GetSunDirectionalLight();
		double SunElevationDeg = -999.0;
		double SunAzimuthDeg = 0.0;
		if (SunLight)
		{
			const FVector SunDir = SunLight->GetDirection();
			SunElevationDeg = FMath::RadiansToDegrees(FMath::Asin(FMath::Clamp(-SunDir.Z, -1.0f, 1.0f)));
			SunAzimuthDeg = FMath::RadiansToDegrees(FMath::Atan2(SunDir.Y, SunDir.X));
		}

		UE_LOG(LogTemp, Display, TEXT("[RadCapture][%s] LightingTime=%s | Priming=%s | Cooldown=%d | SunElev=%.2f deg | SunAz=%.2f deg | RefLuminance=%.4f"),
			StageLabel,
			*LightingTime.ToString(),
			bIsPriming ? TEXT("TRUE") : TEXT("FALSE"),
			RadiationPrimingCooldown,
			SunElevationDeg,
			SunAzimuthDeg,
			ReferenceLuminance_Total);
	};

	const bool bPrimingEnabled = bEnableRadiationCapture && RadiationPrimingFrameCount > 0;
	const int64 CurrentCaptureFrame = static_cast<int64>(GFrameCounter);
	UE_LOG(LogTemp, Error, TEXT("[RadTrace] Priming check: bPrimingEnabled=%d, RadiationPrimingFrameCount=%d, RadiationPrimingCooldown=%d"),
		bPrimingEnabled, RadiationPrimingFrameCount, RadiationPrimingCooldown);
	if (!bPrimingEnabled)
	{
		RadiationPrimingCooldown = 0;
		bRadiationPrimingActive = false;
		LastRadiationPrimingFrame = INDEX_NONE;
		bRadiationPrimingStartTimeValid = false;
	}
	else
	{
		const bool bSimTimeWentBackwards = bRadiationPrimingSimTimeValid && (SimTime < RadiationPrimingSimTime);
		const bool bPrimingRollbackFrame = bSimTimeWentBackwards && (bRadiationPrimingActive || RadiationPrimingCooldown > 0);
		const bool bShouldResetPriming =
			!bRadiationPrimingSimTimeValid || (!bPrimingRollbackFrame && !(RadiationPrimingSimTime == SimTime));

		if (bShouldResetPriming)
		{
			RadiationPrimingSimTime = SimTime;
			bRadiationPrimingSimTimeValid = true;
			RadiationPrimingCooldown = RadiationPrimingFrameCount;
			if (bLastRadiationCaptureTimeValid)
			{
				RadiationPrimingStartTime = LastRadiationCaptureSimTime;
				bRadiationPrimingStartTimeValid = (RadiationPrimingSimTime >= RadiationPrimingStartTime);
			}
			else
			{
				RadiationPrimingStartTime = RadiationPrimingSimTime;
				bRadiationPrimingStartTimeValid = false;
			}
		}
	}

	const auto CaptureTotalPass = [&]()
	{
		RadiationCapture->ShowFlags = CachedShowFlags_Total;
		RadiationCapture->TextureTarget = RT_Total;
		RadiationCapture->CaptureScene();
	};

	const auto CaptureDirectPass = [&]()
	{
		RadiationCapture->ShowFlags = CachedShowFlags_Direct;
		RadiationCapture->TextureTarget = RT_Direct;
		RadiationCapture->CaptureScene();
	};

	const auto CaptureDiffusePass = [&]()
	{
		if (!bUseDiffuseCapture || !RT_Diffuse)
		{
			return;
		}

		RadiationCapture->ShowFlags = CachedShowFlags_Diffuse;
		RadiationCapture->TextureTarget = RT_Diffuse;
		RadiationCapture->CaptureScene();
	};

	const auto CaptureDiffuseNoGIPass = [&]()
	{
		if (!bUseDiffuseNoGICaptureThisFrame || !RT_DiffuseNoGI)
		{
			return;
		}

		RadiationCapture->ShowFlags = CachedShowFlags_DiffuseNoGI;
		RadiationCapture->TextureTarget = RT_DiffuseNoGI;
		RadiationCapture->CaptureScene();
	};

	const bool bUseSurfaceStateCaptureThisFrame = bUseDualReferenceStrip && RT_SurfaceState && RTY_SurfaceState;
	const auto CaptureSurfaceStatePass = [&]()
	{
		if (!bUseSurfaceStateCaptureThisFrame || !RT_SurfaceState)
		{
			return;
		}

		const ESceneCaptureSource PreviousCaptureSource = RadiationCapture->CaptureSource;
		const FEngineShowFlags PreviousShowFlags = RadiationCapture->ShowFlags;
		UTextureRenderTarget2D* const PreviousTextureTarget = RadiationCapture->TextureTarget;
		RadiationCapture->CaptureSource = SCS_BaseColor;
		RadiationCapture->ShowFlags = CachedShowFlags_SurfaceState;
		RadiationCapture->TextureTarget = RT_SurfaceState;
		RadiationCapture->CaptureScene();
		RadiationCapture->CaptureSource = PreviousCaptureSource;
		RadiationCapture->ShowFlags = PreviousShowFlags;
		RadiationCapture->TextureTarget = PreviousTextureTarget;
		RadiationCapture->MarkRenderStateDirty();
	};

#if WITH_SUNSKY_SUPPORT
	auto ApplySunForTime = [this](const FDateTime& LightingTime)
	{
		if (bUseRadiationBenchmarkLightingOverride)
		{
			ApplyRadiationBenchmarkSunOverride();
			return;
		}
		UpdateSunSkyActorsAtTime(LightingTime);
	};
#else
	auto ApplySunForTime = [this](const FDateTime&)
	{
		if (bUseRadiationBenchmarkLightingOverride)
		{
			ApplyRadiationBenchmarkSunOverride();
		}
	};
#endif

	auto ReapplySceneLightingForTime = [this](const FDateTime& ForcingTime)
	{
		if (bUseRadiationBenchmarkLightingOverride)
		{
			ApplyBenchmarkLightingFromForcingIfEnabled(
				RadiationBenchmarkOverrideDNI_Wm2,
				RadiationBenchmarkOverrideDHI_Wm2);
			return;
		}

		if (!bProductionLightingUsesForcingIntensityScaling)
		{
			SyncCachedLightIntensitiesFromScene();
			return;
		}

		if (!WeatherProvider)
		{
			return;
		}

		const FWeatherForcingData CaptureForcing = WeatherProvider->GetWeatherForcing(ForcingTime);
		const float CosZenith = SampleSunCosine();
		float DirectHorizontalWm2 = 0.0f;
		float DiffuseHorizontalWm2 = 0.0f;
		ResolveHorizontalShortwaveComponents(this, CaptureForcing, CosZenith, DirectHorizontalWm2, DiffuseHorizontalWm2);

		const float DNI = (CosZenith > 0.01f)
			? (DirectHorizontalWm2 / CosZenith)
			: 0.0f;
		const float DHI = DiffuseHorizontalWm2;
		UpdateSunSkyFromForcing(DNI, DHI);

		if (bDebugRadiationCapture)
		{
			static int32 ForcingRestoreLogCount = 0;
			if (ForcingRestoreLogCount++ < 12)
			{
				UE_LOG(LogTemp, Display, TEXT("[RadCapture] Reapplied forcing-scaled lighting for %s after SunSky update (cosZ=%.4f, DirH=%.3f, DiffH=%.3f, DNI=%.3f, DHI=%.3f)."),
					*ForcingTime.ToString(), CosZenith, DirectHorizontalWm2, DiffuseHorizontalWm2, DNI, DHI);
			}
		}
	};

	auto RefreshSkyLightCaptureForCurrentSample = [this]()
	{
		if (!bRecaptureSkyBeforeRadiationSample)
		{
			return;
		}

		if (ShouldUseDedicatedRadiationSkyLightForCapture())
		{
			return;
		}

		USkyLightComponent* SkyLight = CachedSunSkyLight.Get();
		UWorld* World = GetWorld();
		if (!SkyLight || !World)
		{
			return;
		}

		// Scene-captured skylights are the most likely source of stale diffuse-no-GI state.
		if (SkyLight->SourceType == SLS_CapturedScene)
		{
			// Do not force a manual recapture when the SkyLight is already running in
			// real-time capture mode. That path updates independently and a second
			// RecaptureSky() here can end up recapturing the temporary radiation-capture
			// render state instead of the normal scene, which destabilizes the non-direct
			// source across timesteps.
			if (SkyLight->bRealTimeCapture)
			{
				if (bDebugRadiationCapture)
				{
					UE_LOG(LogTemp, Display, TEXT("[RadCapture] Skipping manual SkyLight recapture because RealTimeCapture is already enabled."));
				}
				return;
			}

			SkyLight->RecaptureSky();
			USkyLightComponent::UpdateSkyCaptureContents(World);
			FlushRenderingCommands();

			if (bDebugRadiationCapture)
			{
				UE_LOG(LogTemp, Display, TEXT("[RadCapture] Forced SkyLight recapture before radiation sample (%s)."),
					SkyLight->bRealTimeCapture ? TEXT("RealTimeCapture") : TEXT("CapturedScene"));
			}
		}
	};

	{
		UE_LOG(LogTemp, Error, TEXT("[RadTrace] Entering capture scope"));
		FLambertianOverrideScope LambertScope(*this);
		FLumenCaptureQualityScope LumenScope(*this);
		FLumenHistoryDisableScope LumenHistoryScope; // Ensure Lumen history stays off for this capture scope
		FVolumetricCloudCaptureDisableScope VolumetricCloudScope(*this);
		FScopedEmissiveOnlySkyCapture EmissiveOnlySkyScope(*this);
		EnsureRadiationSkyLightComponent();
		struct FRadiationSkyLightCaptureScope
		{
			USkyLightComponent* SceneSkyLight = nullptr;
			USkyLightComponent* CaptureSkyLight = nullptr;
			bool bRestoreSceneAffectsWorld = false;
			bool bRestoreSceneVisible = false;
			bool bRestoreCaptureAffectsWorld = false;
			bool bRestoreCaptureVisible = false;

			FRadiationSkyLightCaptureScope(ASnowSimulationActor& Actor)
			{
				if (!Actor.ShouldUseDedicatedRadiationSkyLightForCapture())
				{
					return;
				}

				SceneSkyLight = Actor.CachedSunSkyLight.Get();
				CaptureSkyLight = Actor.RadiationSkyLight;
				if (!CaptureSkyLight)
				{
					return;
				}

				bRestoreCaptureAffectsWorld = CaptureSkyLight->bAffectsWorld;
				bRestoreCaptureVisible = CaptureSkyLight->GetVisibleFlag();
				CaptureSkyLight->bAffectsWorld = true;
				CaptureSkyLight->SetVisibility(true);
				CaptureSkyLight->SetIntensity(Actor.LastSkyLightIntensity);
				CaptureSkyLight->MarkRenderStateDirty();

				if (SceneSkyLight)
				{
					bRestoreSceneAffectsWorld = SceneSkyLight->bAffectsWorld;
					bRestoreSceneVisible = SceneSkyLight->GetVisibleFlag();
					SceneSkyLight->bAffectsWorld = false;
					SceneSkyLight->SetVisibility(false);
					SceneSkyLight->MarkRenderStateDirty();
				}

				if (UWorld* World = Actor.GetWorld())
				{
					CaptureSkyLight->RecaptureSky();
					USkyLightComponent::UpdateSkyCaptureContents(World);
					FlushRenderingCommands();
				}
			}

			~FRadiationSkyLightCaptureScope()
			{
				if (SceneSkyLight)
				{
					SceneSkyLight->bAffectsWorld = bRestoreSceneAffectsWorld;
					SceneSkyLight->SetVisibility(bRestoreSceneVisible);
					SceneSkyLight->MarkRenderStateDirty();
				}
				if (CaptureSkyLight)
				{
					CaptureSkyLight->bAffectsWorld = bRestoreCaptureAffectsWorld;
					CaptureSkyLight->SetVisibility(bRestoreCaptureVisible);
					CaptureSkyLight->MarkRenderStateDirty();
				}
			}
		} RadiationSkyLightScope(*this);

		// Fix A: Pause bRealTimeCapture on the scene SkyLight for the full capture scope.
		//
		// A SkyLight with bRealTimeCapture=1 continuously submits GPU recapture commands
		// asynchronously. When one of those commands fires while the RadiationCapture
		// SceneCapture is in Direct-only (no sky) or DiffuseNoGI ShowFlags state, the
		// cubemap gets re-captured from a sun-only scene => sky diffuse ~= 0. The next
		// TotalNoGI pass then reads near-zero sky from that corrupt cubemap, driving
		// TotalNoGI ~= Direct and RTY_DiffuseNoGI -> 0 scene-wide. This is the shared
		// root cause of the periodic diffuse collapse that predates TotalNoGI introduction.
		// Freezing bRealTimeCapture here ensures the cubemap stays consistent (last
		// full-lit sky snapshot) for the entire capture sub-sequence.
		struct FSkyLightRealTimePauseScope
		{
			USkyLightComponent* SkyLight = nullptr;
			bool bWasRealTimeCapture = false;

			FSkyLightRealTimePauseScope(ASnowSimulationActor& Actor)
			{
				// Only act on the scene SkyLight, not the dedicated radiation one.
				SkyLight = Actor.CachedSunSkyLight.Get();
				if (!SkyLight || !SkyLight->bRealTimeCapture)
				{
					return;
				}

				// If using dedicated radiation sky, the scene SkyLight is already
				// swapped out in FRadiationSkyLightCaptureScope above.
				if (Actor.ShouldUseDedicatedRadiationSkyLightForCapture())
				{
					return;
				}

				bWasRealTimeCapture = true;
				SkyLight->bRealTimeCapture = false;
				SkyLight->MarkRenderStateDirty();

				UE_LOG(SimulationLog, Verbose,
					TEXT("[RadCapture] FSkyLightRealTimePauseScope: Paused SkyLight real-time recapture "
						 "to prevent mid-pass cubemap corruption."));
			}

			~FSkyLightRealTimePauseScope()
			{
				if (!SkyLight || !bWasRealTimeCapture)
				{
					return;
				}

				SkyLight->bRealTimeCapture = true;
				SkyLight->MarkRenderStateDirty();

				UE_LOG(SimulationLog, Verbose,
					TEXT("[RadCapture] FSkyLightRealTimePauseScope: Restored SkyLight real-time recapture."));
			}
		} SkyLightRTCPauseScope(*this);

		// CRITICAL: Force-clear any cached view state to prevent temporal lag
		// Without this, Lumen's temporal buffers persist across large time steps
		FlushRenderingCommands();
		UE_LOG(LogTemp, Error, TEXT("[RadTrace] FlushRenderingCommands done"));

		if (bPrimingEnabled && RadiationPrimingCooldown > 0)
		{
			// Emit a single priming frame this tick to give Lumen a fresh history sample
			bRadiationPrimingActive = true;
			if (LastRadiationPrimingFrame == CurrentCaptureFrame)
			{
				if (bDebugRadiationCapture)
				{
					UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Skipping duplicate priming pass on frame %lld (cooldown=%d)."),
						CurrentCaptureFrame,
						RadiationPrimingCooldown);
				}
				UE_LOG(LogTemp, Error, TEXT("[RadTrace] EARLY RETURN: Priming already consumed this frame, %d frames remaining"), RadiationPrimingCooldown);
				return;
			}

			FDateTime LightingTime = SimTime;
			if (bRadiationPrimingStartTimeValid && RadiationPrimingFrameCount > 0)
			{
				const int32 FramesRemaining = RadiationPrimingCooldown;
				const int32 FramesCompleted = RadiationPrimingFrameCount - FramesRemaining;
				const int32 FrameNumber = FramesCompleted + 1;
				const int32 TotalSegments = RadiationPrimingFrameCount + 1;
				const double Fraction = FMath::Clamp(static_cast<double>(FrameNumber) / static_cast<double>(TotalSegments), 0.0, 1.0);
				const FTimespan Delta = RadiationPrimingSimTime - RadiationPrimingStartTime;
				const double OffsetSeconds = Delta.GetTotalSeconds() * Fraction;
				LightingTime = RadiationPrimingStartTime + FTimespan::FromSeconds(OffsetSeconds);
			}

			ApplySunForTime(LightingTime);
			ReapplySceneLightingForTime(LightingTime);
			RefreshSkyLightCaptureForCurrentSample();
			LogCaptureTelemetry(TEXT("PrimingCapture"), true, LightingTime);
			CaptureTotalPass();
			if (bExportReferenceMappingDebug)
			{
				ExportReferenceMappingDebugSnapshot(LightingTime, TEXT("PrimingAfterTotalPass"), true, true);
			}
			ApplySunForTime(SimTime);
			ReapplySceneLightingForTime(SimTime);

			LastRadiationPrimingFrame = CurrentCaptureFrame;
			--RadiationPrimingCooldown;

			if (bDebugRadiationCapture)
			{
				UE_LOG(LogTemp, VeryVerbose, TEXT("[RadCapture] Priming frame captured, %d remaining"),
					RadiationPrimingCooldown);
			}
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] EARLY RETURN: Priming active, %d frames remaining"), RadiationPrimingCooldown);
			return;
		}

		bRadiationPrimingActive = false;
		UE_LOG(LogTemp, Error, TEXT("[RadTrace] Past priming block"));

		const FTimeIntegrationConfig IntegrationConfig = BuildTimeIntegrationConfig(SimTime, StepDuration);
		const bool bTimeIntegrationActive = bEnableTimeIntegratedRadiation && IntegrationConfig.bEnabled;
		UE_LOG(LogTemp, Error, TEXT("[RadTrace] Integration config built: bActive=%d, bEnabled=%d"), bTimeIntegrationActive, IntegrationConfig.bEnabled);
		bUseDiffuseCaptureThisFrame = bUseDiffuseCapture && !bUseReferenceTile;
		if (bUseDiffuseCapture && bUseReferenceTile)
		{
			static bool bLoggedCapturedDiffuseSuppressed = false;
			if (!bLoggedCapturedDiffuseSuppressed)
			{
				UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Ignoring dedicated diffuse capture in reference-tile calibrated mode; using Total-Direct so atmospheric diffuse stays in the non-direct residual."));
				bLoggedCapturedDiffuseSuppressed = true;
			}
		}
		if (bUseReferenceTile && !bNonDirectCapturesIncludeAtmosphere)
		{
			static bool bLoggedMissingNonDirectAtmosphere = false;
			if (!bLoggedMissingNonDirectAtmosphere)
			{
				UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Non-direct atmosphere/fog is disabled while reference-tile calibration is active. This can collapse diffuse and terrain residuals, especially at low solar elevation."));
				bLoggedMissingNonDirectAtmosphere = true;
			}
		}
		const bool bEffectiveDirectPassIncludesAtmosphere =
			(bDirectCaptureIncludesAtmosphere
				|| (bUseReferenceTile && bMatchDirectPassAtmosphereToReferenceCalibration && bNonDirectCapturesIncludeAtmosphere))
			&& !(ShouldUseDedicatedRadiationSkyLightForCapture() && bDisableAtmosphereWhenUsingDedicatedRadiationSkyLight);
		if (bUseReferenceTile && bNonDirectCapturesIncludeAtmosphere && !bEffectiveDirectPassIncludesAtmosphere)
		{
			static bool bLoggedDirectAtmosphereMismatchWarning = false;
			if (!bLoggedDirectAtmosphereMismatchWarning)
			{
				UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Reference-tile calibration is active with atmosphere enabled in non-direct passes but disabled in the direct pass. This can over-brighten strip direct luminance relative to Total/TotalNoGI and collapse the derived diffuse residual."));
				bLoggedDirectAtmosphereMismatchWarning = true;
			}
		}
		if (bUseReferenceTile && bEffectiveDirectPassIncludesAtmosphere)
		{
			static bool bLoggedDirectAtmosphereMatched = false;
			if (!bLoggedDirectAtmosphereMatched)
			{
				UE_LOG(LogTemp, Display, TEXT("[RadCapture] Direct pass atmosphere/fog is matched to reference calibration so strip direct stays energy-consistent with Total/TotalNoGI."));
				bLoggedDirectAtmosphereMatched = true;
			}
		}
		bUseDiffuseNoGICaptureThisFrame = bCaptureDiffuseNoGIForTerrain && RT_DiffuseNoGI && RTY_DiffuseNoGI && RTY_TotalNoGI;

		if (bTimeIntegrationActive)
		{
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] Time integration is active, initializing targets"));
			const int32 IntegrationWidth = RTY_Total ? RTY_Total->SizeX : CachedRadiationCaptureWidth;
			const int32 IntegrationHeight = RTY_Total ? RTY_Total->SizeY : CachedRadiationCaptureHeight;
			EnsureTimeIntegrationTargets(IntegrationWidth, IntegrationHeight);
			ResetTimeIntegrationTargets();
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] Time integration targets initialized"));
		}

		struct FRadiationSampleMetrics
		{
			float CosZenith = 0.0f;
			float SunVisibility = 0.0f;
		};

		static int32 SunVisibilityLogCount = 0;

		auto CaptureSample = [&](const FDateTime& LightingTime, float SampleWeight, bool bAccumulateOnly) -> FRadiationSampleMetrics
		{
			ApplySunForTime(LightingTime);
			ReapplySceneLightingForTime(LightingTime);

			FRadiationSampleMetrics Metrics;
			Metrics.CosZenith = SampleSunCosine();
			Metrics.SunVisibility = EvaluateSunVisibility(Metrics.CosZenith);

			if (SunVisibilityLogCount < 5)
			{
				UE_LOG(LogTemp, Display, TEXT("[RadCapture] Sun visibility sample: cosZ=%.4f -> mask=%.4f"),
					Metrics.CosZenith, Metrics.SunVisibility);
				++SunVisibilityLogCount;
			}

			LogCaptureTelemetry(TEXT("FinalCapture_BeforeInvalidation"), false, LightingTime);
			if (RadiationCapture)
			{
				RadiationCapture->MarkRenderStateDirty();
			}
			RefreshSkyLightCaptureForCurrentSample();

			// ================================================================================
			// Lumen Convergence Phase (Optional)
			// ================================================================================
			// Temporarily enable Lumen temporal history to build up diffuse/indirect lighting,
			// then restore disabled state for final capture to prevent cross-timestep lag.
			// This is critical for capturing realistic skylight/GI without temporal artifacts.

			UE_LOG(LogTemp, Error, TEXT("[RadTrace][Convergence] CHECK: bEnableLumenConvergence=%d"), bEnableLumenConvergence ? 1 : 0);

			if (bEnableLumenConvergence)
			{
				// 1. Store ALL original temporal settings that were disabled by FLumenCaptureQualityScope
				IConsoleVariable* ProbeGatherTemporalVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.ScreenProbeGather.TemporalFilter"));
				IConsoleVariable* HistoryWeightVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.ScreenProbeGather.HistoryWeight"));
				IConsoleVariable* DiffuseTemporalVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.DiffuseIndirect.TemporalFilter"));
				IConsoleVariable* ReflectionsTemporalVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.Reflections.TemporalFilter"));
				IConsoleVariable* FixedJitterVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.ScreenProbeGather.FixedJitterIndex"));

				// CRITICAL: Also store the AllowHistory master switches (disabled by FLumenHistoryDisableScope)
				IConsoleVariable* DiffuseAllowHistoryVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.DiffuseIndirect.AllowHistory"));
				IConsoleVariable* ReflectionsAllowHistoryVar = IConsoleManager::Get().FindConsoleVariable(TEXT("r.Lumen.Reflections.AllowHistory"));

				int32 OriginalProbeGatherTemporal = ProbeGatherTemporalVar ? ProbeGatherTemporalVar->GetInt() : 0;
				float OriginalHistoryWeight = HistoryWeightVar ? HistoryWeightVar->GetFloat() : 0.0f;
				int32 OriginalDiffuseTemporal = DiffuseTemporalVar ? DiffuseTemporalVar->GetInt() : 0;
				int32 OriginalReflectionsTemporal = ReflectionsTemporalVar ? ReflectionsTemporalVar->GetInt() : 0;
				int32 OriginalFixedJitter = FixedJitterVar ? FixedJitterVar->GetInt() : 0;
				int32 OriginalDiffuseAllowHistory = DiffuseAllowHistoryVar ? DiffuseAllowHistoryVar->GetInt() : 0;
				int32 OriginalReflectionsAllowHistory = ReflectionsAllowHistoryVar ? ReflectionsAllowHistoryVar->GetInt() : 0;

				// 2. Enable temporal accumulation ONLY for diffuse/skylight convergence
				//    CRITICAL: Must enable AllowHistory first (master switch) before temporal filters
				if (DiffuseAllowHistoryVar) DiffuseAllowHistoryVar->Set(1);  // Enable diffuse history MASTER SWITCH
				// Note: Keep reflections AllowHistory OFF (we don't need specular for snow irradiance)

				if (ProbeGatherTemporalVar) ProbeGatherTemporalVar->Set(1);
				if (HistoryWeightVar) HistoryWeightVar->Set(LumenConvergenceHistoryWeight);  // User-configurable
				if (DiffuseTemporalVar) DiffuseTemporalVar->Set(1);
				// Note: Intentionally NOT enabling r.Lumen.Reflections.TemporalFilter (keep disabled)
				// Note: Intentionally NOT changing FixedJitterIndex (keep disabled for determinism)

				if (bDebugRadiationCapture)
				{
					UE_LOG(LogTemp, Warning, TEXT("[RadTrace][Convergence] ENABLED Lumen temporal for %d warm-up frames (HistoryWeight=%.2f)"),
						LumenConvergenceFrames, LumenConvergenceHistoryWeight);
					UE_LOG(LogTemp, Warning, TEXT("[RadTrace][Convergence] Original state: ProbeGatherTemporal=%d, HistoryWeight=%.3f, DiffuseTemporal=%d, AllowHistory=%d"),
						OriginalProbeGatherTemporal, OriginalHistoryWeight, OriginalDiffuseTemporal, OriginalDiffuseAllowHistory);
					UE_LOG(LogTemp, Warning, TEXT("[RadTrace][Convergence] NEW state: AllowHistory=1, TemporalFilter=1, HistoryWeight=%.2f"),
						LumenConvergenceHistoryWeight);
				}

				// 3. Run convergence warm-up frames (render-only, no simulation side effects)
				//    These frames allow Lumen to accumulate diffuse/indirect lighting in its history buffers
				for (int32 ConvergenceFrame = 0; ConvergenceFrame < LumenConvergenceFrames; ++ConvergenceFrame)
				{
					CaptureTotalPass();  // Pure render pass - does NOT advance simulation time or game logic
				}

				// 4. Restore ALL original settings (return to disabled temporal state)
				//    CRITICAL: Restore AllowHistory LAST (after temporal filters are disabled)
				//    This ensures the final capture has no temporal lag and each timestep is independent
				if (ProbeGatherTemporalVar) ProbeGatherTemporalVar->Set(OriginalProbeGatherTemporal);
				if (HistoryWeightVar) HistoryWeightVar->Set(OriginalHistoryWeight);
				if (DiffuseTemporalVar) DiffuseTemporalVar->Set(OriginalDiffuseTemporal);
				if (ReflectionsTemporalVar) ReflectionsTemporalVar->Set(OriginalReflectionsTemporal);
				if (FixedJitterVar) FixedJitterVar->Set(OriginalFixedJitter);

				// Restore AllowHistory master switches
				if (DiffuseAllowHistoryVar) DiffuseAllowHistoryVar->Set(OriginalDiffuseAllowHistory);
				if (ReflectionsAllowHistoryVar) ReflectionsAllowHistoryVar->Set(OriginalReflectionsAllowHistory);

				if (bDebugRadiationCapture)
				{
					UE_LOG(LogTemp, Warning, TEXT("[RadTrace][Convergence] RESTORED original Lumen temporal settings"));
					UE_LOG(LogTemp, Warning, TEXT("[RadTrace][Convergence] Restored state: ProbeGatherTemporal=%d, HistoryWeight=%.3f, DiffuseTemporal=%d, AllowHistory=%d"),
						OriginalProbeGatherTemporal, OriginalHistoryWeight, OriginalDiffuseTemporal, OriginalDiffuseAllowHistory);
				}
			}

			// ================================================================================
			// Final Capture (No Temporal Lag)
			// ================================================================================
			// These captures run with temporal filtering DISABLED to ensure each timestep
			// is independent and matches the current sun/sky state without lag.
			LogCaptureTelemetry(TEXT("FinalCapture_Total"), false, LightingTime);
			CaptureTotalPass();
			if (bExportReferenceMappingDebug)
			{
				ExportReferenceMappingDebugSnapshot(LightingTime, TEXT("AfterTotalPass"), true, true);
			}

			LogCaptureTelemetry(TEXT("FinalCapture_Direct"), false, LightingTime);
			CaptureDirectPass();
			if (bExportReferenceMappingDebug)
			{
				ExportReferenceMappingDebugSnapshot(LightingTime, TEXT("AfterDirectPass"), true, true);
			}
			if (bUseDiffuseCaptureThisFrame)
			{
				LogCaptureTelemetry(TEXT("FinalCapture_Diffuse"), false, LightingTime);
				CaptureDiffusePass();
				if (bExportReferenceMappingDebug)
				{
					ExportReferenceMappingDebugSnapshot(LightingTime, TEXT("AfterDiffusePass"), true, true);
				}
			}
			if (bUseDiffuseNoGICaptureThisFrame)
			{
				// Fix B: After Lumen convergence frames (which run with GI history enabled),
				// flush the renderer before capturing the TotalNoGI (GI-off) pass.
				// Without this flush, Lumen's screen-probe accumulation from CaptureTotalPass
				// (GI on) bleeds into CaptureDiffuseNoGIPass (GI off) because the history
				// buffers are still warm from the convergence loop.  This causes Direct to
				// appear in the TotalNoGI target, driving RTY_DiffuseNoGI -> 0.
				if (bEnableLumenConvergence)
				{
					FlushRenderingCommands();
				}
				LogCaptureTelemetry(TEXT("FinalCapture_DiffuseNoGI"), false, LightingTime);
				CaptureDiffuseNoGIPass();
				if (bExportReferenceMappingDebug)
				{
					ExportReferenceMappingDebugSnapshot(LightingTime, TEXT("AfterDiffuseNoGIPass"), true, true);
				}
			}

			if (bAccumulateOnly)
			{
				ConvertRGBToLuminance();
				AccumulateLuminanceTexture(RTY_Total, RTY_TotalIntegration, SampleWeight);
				AccumulateLuminanceTexture(RTY_Direct, RTY_DirectIntegration, SampleWeight);
				if (bUseDiffuseCaptureThisFrame)
				{
					AccumulateLuminanceTexture(RTY_Diffuse, RTY_DiffuseIntegration, SampleWeight);
				}
				if (bUseDiffuseNoGICaptureThisFrame)
				{
					AccumulateLuminanceTexture(RTY_TotalNoGI, RTY_TotalNoGIIntegration, SampleWeight);
					AccumulateLuminanceTexture(RTY_DiffuseNoGI, RTY_DiffuseNoGIIntegration, SampleWeight);
				}
			}

			return Metrics;
		};

		float WeightedCosSum = 0.0f;
		float WeightedVisibilitySum = 0.0f;
		float WeightSum = 0.0f;
		UE_LOG(LogTemp, Error, TEXT("[RadTrace] About to check time integration: bActive=%d"), bTimeIntegrationActive);

		if (bTimeIntegrationActive)
		{
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] ENTERED if block"));
			const int32 SampleCount = IntegrationConfig.SampleCount;
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] SampleCount=%d"), SampleCount);
			UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Starting time integration: %d samples"), IntegrationConfig.SampleCount);
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] About to start for loop"));
			const float SampleWeight = 1.0f / static_cast<float>(IntegrationConfig.SampleCount);
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] Entering for loop with SampleCount=%d"), SampleCount);
			for (int32 SampleIndex = 0; SampleIndex < IntegrationConfig.SampleCount; ++SampleIndex)
			{
				UE_LOG(LogTemp, Error, TEXT("[RadTrace] Loop iteration %d/%d START"), SampleIndex + 1, SampleCount);
				const double SampleCenterSeconds = (SampleIndex + 0.5) * IntegrationConfig.SampleIntervalSeconds;
				const FDateTime SampleTime = IntegrationConfig.StepStartTime + FTimespan::FromSeconds(SampleCenterSeconds);
				UE_LOG(LogTemp, Error, TEXT("[RadTrace] About to call CaptureSample for iteration %d"), SampleIndex + 1);
				const FRadiationSampleMetrics Metrics = CaptureSample(SampleTime, SampleWeight, true);
				UE_LOG(LogTemp, Error, TEXT("[RadTrace] CaptureSample returned for iteration %d"), SampleIndex + 1);
				WeightedCosSum += Metrics.CosZenith * SampleWeight;
				WeightedVisibilitySum += Metrics.SunVisibility * SampleWeight;
				WeightSum += SampleWeight;
				UE_LOG(LogTemp, Error, TEXT("[RadTrace] Completed integration sample %d/%d"), SampleIndex + 1, IntegrationConfig.SampleCount);
			}

			UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Integration loop complete, copying results"));
			CopyIntegrationResult(RTY_TotalIntegration, RTY_Total);
			CopyIntegrationResult(RTY_DirectIntegration, RTY_Direct);
			if (bUseDiffuseCaptureThisFrame)
			{
				CopyIntegrationResult(RTY_DiffuseIntegration, RTY_Diffuse);
			}
			if (bUseDiffuseNoGICaptureThisFrame)
			{
				CopyIntegrationResult(RTY_TotalNoGIIntegration, RTY_TotalNoGI);
				CopyIntegrationResult(RTY_DiffuseNoGIIntegration, RTY_DiffuseNoGI);
			}
			ApplySunForTime(SimTime);
			ReapplySceneLightingForTime(SimTime);
			UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Integration results copied"));
		}
		else
		{
			const FRadiationSampleMetrics Metrics = CaptureSample(SimTime, 1.0f, false);
			UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Single Sample Captured"));
			WeightedCosSum = Metrics.CosZenith;
			WeightedVisibilitySum = Metrics.SunVisibility;
			WeightSum = 1.0f;
		}

		LastRadiationCaptureSimTime = SimTime;
		bLastRadiationCaptureTimeValid = true;

		const float Normalizer = WeightSum > KINDA_SMALL_NUMBER ? (1.0f / WeightSum) : 0.0f;
		CachedCaptureCosSolarZenith = WeightedCosSum * Normalizer;
		CachedSunVisibility = (WeightSum > KINDA_SMALL_NUMBER) ? WeightedVisibilitySum * Normalizer : 0.0f;

		if (bUseReferenceTile)
		{
			const float ReferenceVisibilityThreshold = FMath::Max(GetSunVisibilityThresholdCos() * 0.5f, 1e-3f);
			if (CachedSunVisibility <= ReferenceVisibilityThreshold)
			{
				// Sun obscured: Direct reference is zero. Total reference (diffuse/sky) remains valid.
				// Do NOT invalidate the reference system (bReferenceLuminanceValid = true remains)
				ReferenceLuminance_Direct = 0.0f;
				// ReferenceLuminance_Total should potentially be adjusted or kept as is (it's updated by Readback later anyway)
				// But here we are dealing with telemetry from LAST frame or accumulation.
				// Since we are about to readback NEW values in PASS 5/6, we shouldn't force zeros here unless necessary.
				// ACTUALLY: This block runs at the END of capture integration.
				// If visibility is low, we expect Direct to be Low.
				// We should NOT zero Total here.
			}
		}

		CaptureSurfaceStatePass();
		if (bUseSurfaceStateCaptureThisFrame)
		{
			ConvertSurfaceStateToLuminance();
		}

		// PASS 3: Convert RGB to Luminance (GPU compute) - only needed when not integrating per-sample
		if (!bTimeIntegrationActive)
		{
			ConvertRGBToLuminance();
		}
	}
	UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Capture Block Finished"));

	// PASS 4: Compute Diffuse Irradiance (GPU compute)
	// RTY_Diffuse = max(RTY_Total - RTY_Direct, epsilon), unless diffuse capture is enabled.
	// Optional 3x3 blur if enabled.
	UE_LOG(LogTemp, Error, TEXT("[RadTrace] About to compute diffuse. RTY_Total=%p, RTY_Direct=%p"), RTY_Total, RTY_Direct);
	ComputeDiffuseIrradiance();
	UE_LOG(LogTemp, Error, TEXT("[RadTrace] Diffuse computation complete"));

	// Validation logging: Verify Lumen convergence worked by checking if we captured diffuse component
	// This helps debug whether the convergence frames successfully built up skylight/GI energy
	if (bDebugRadiationCapture && bEnableLumenConvergence)
	{
		// Queue a readback to sample a single pixel and verify diffuse capture
		// This is a debug-only check - the actual data extraction happens later
		ExtractRadiationIndicesToBuffer();  // Extract full grid

		// Log that we're validating convergence (actual values will be logged in UpdateRTYLuminance)
		UE_LOG(LogTemp, Warning, TEXT("[RadTrace][Convergence] Validation: Checking if RTY_Diffuse > 0 after %d warm-up frames..."),
			LumenConvergenceFrames);
		UE_LOG(LogTemp, Warning, TEXT("[RadTrace][Convergence] Expected: RTY_Total > RTY_Direct (diffuse component present)"));
		UE_LOG(LogTemp, Warning, TEXT("[RadTrace][Convergence] If RTY_Diffuse=0, increase LumenConvergenceFrames or LumenConvergenceHistoryWeight"));
	}

	// Update reference luminance from border tiles (Option A implementation)
	// Queue readback NOW so index computation uses the current frame reference.
	if (bUseReferenceTile)
	{
		// Step 1: Enqueue the readback for the current frame
		UpdateReferenceLuminance(true, false);
		
		// Step 2: IMMEDIATELY block and process it to ensure no lag
		// This ensures ComputeRadiationIndices uses current frame data
		UpdateReferenceLuminance(false, true);
		if (bExportReferenceMappingDebug)
		{
			ExportReferenceMappingDebugSnapshot(SimTime, TEXT("PostReferenceReadback"));
		}
	}

	// PASS 5: Compute Dimensionless Radiation Indices (CPU reference mean + GPU index calculation)
	// RTF_DirIndex = RTY_Direct / R_direct
	// RTF_DiffIndex = RTY_Diffuse / R_diffuse
	// Where R_direct and R_diffuse are means from the reference strip
	ComputeRadiationIndices();
	UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Computed Radiation Indices (Pass 5)"));

	// PASS 6: Optional raw geometry-only radiation index diagnostic
	// RTF_rUE_raw = RTY_Total / R_total (pure UE engine-relative, no forcing)
	if (bEnableRawRadiationIndexTexture)
	{
		ComputeRawRadiationIndices();
		UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Computed Raw Indices (Pass 6)"));
	}

	// PASS 7: Extract radiation indices into GPU buffer for CPU access
	// Check if reference is valid before extracting
	// On first frame, ReferenceLuminance_Total will be the fallback value (1.0)
	// We need to wait until we have a real reference value from the GPU
	// We need to wait until we have a real reference value from the GPU
	UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Checking Reference Validity: UseRef=%d, Valid=%d"), bUseReferenceTile, bReferenceLuminanceValid);
	if (bUseReferenceTile && !bReferenceLuminanceValid)
	{
		static int32 WaitingCounter = 0;
		WaitingCounter++;
		if (WaitingCounter <= 5)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadExtract] ===== WAITING for valid reference luminance (current=%.4f, frame %d). Skipping extraction only. ====="),
				ReferenceLuminance_Total, WaitingCounter);
		}
		// Don't return - continue with the rest of the pipeline, just skip extraction
	}
	else
	{
		if (bUseReferenceTile)
		{
			static bool bLoggedValid = false;
			if (!bLoggedValid && bReferenceLuminanceValid)
			{
				UE_LOG(LogTemp, Warning, TEXT("[RadExtract] ===== SUCCESS: Valid reference luminance acquired (%.4f). Proceeding with extraction. ====="),
					ReferenceLuminance_Total);
				bLoggedValid = true;
			}
		}


		
		UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Entering Else block (Reference Valid or Disabled)"));

		// Extract radiation indices (only if reference is valid OR reference tile is disabled)
		ExtractRadiationIndicesToBuffer();
		UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Extracted Indices (Pass 7)"));
	}

	// Extract RTY luminance values for diagnostics (Always extract if capture ran, independent of reference validity)
	UE_LOG(LogTemp, Error, TEXT("[RadTrace] Calling ExtractRTYLuminanceToBuffers..."));
	ExtractRTYLuminanceToBuffers();
	UE_LOG(LogTemp, Error, TEXT("[RadTrace] ExtractRTYLuminanceToBuffers completed"));

	// Block until GPU work completes so RTY readback is available this tick for diagnostics
	// Note: This flush might be expensive, but is necessary for accurate diagnostics
	FlushRenderingCommands();
	UE_LOG(LogTemp, Error, TEXT("[RadTrace] Calling ReadbackRTYLuminance(true)..."));
	const bool bRTYReadbackImmediate = ReadbackRTYLuminance(true);
	UE_LOG(LogTemp, Error, TEXT("[RadTrace] ReadbackRTYLuminance returned: %d"), bRTYReadbackImmediate);
	bool bInjectedRTYFromIndices = false;

	// If readback failed or returned empty, reconstruct RTY from indices + reference luminance as a fallback
	if (!bRTYReadbackImmediate || (CachedRTY_Direct.Num() == CachedDirectIndices.Num() && CachedRTY_Direct.Num() > 0))
	{
		float MaxRTY = 0.0f;
		for (float Value : CachedRTY_Direct)
		{
			MaxRTY = FMath::Max(MaxRTY, Value);
		}

		if (MaxRTY <= KINDA_SMALL_NUMBER)
		{
			const float R_total = ReferenceLuminance_Total;
			const float R_direct = ReferenceLuminance_Direct;
			const float R_diffuse_raw = (FMath::IsFinite(ReferenceLuminance_Diffuse) && ReferenceLuminance_Diffuse > 0.0f)
				? ReferenceLuminance_Diffuse
				: (R_total - R_direct);
			const float R_diffuse = FMath::Max(R_diffuse_raw, 1e-3f);

			const bool bSizesMatch = (CachedDirectIndices.Num() == CachedRTY_Direct.Num()) &&
				(CachedDiffuseIndices.Num() == CachedRTY_Diffuse.Num());

			if (R_direct > KINDA_SMALL_NUMBER && bSizesMatch)
			{
				for (int32 Idx = 0; Idx < CachedRTY_Direct.Num(); ++Idx)
				{
					CachedRTY_Direct[Idx] = CachedDirectIndices[Idx] * R_direct;
					CachedRTY_Diffuse[Idx] = CachedDiffuseIndices[Idx] * R_diffuse;
				}

				bInjectedRTYFromIndices = true;
				UE_LOG(LogTemp, Warning, TEXT("[RTY Fallback] Injected RTY from indices (readback empty). R_total=%.3f R_direct=%.3f"), R_total, R_direct);
			}
		}
	}

		// Keep mapping debug export independent from RTY readback success so we can still
		// inspect strip-vs-cell texture sampling when readback is delayed or unavailable.
		if (bExportReferenceMappingDebug)
		{
			static int32 RefMapInvocationLogCount = 0;
			if (RefMapInvocationLogCount++ < 5)
			{
				UE_LOG(LogTemp, Display, TEXT("[RefMapDebug] Invocation: Capture=%d UseRefTile=%d Cells=%d PixelCoords=%d TargetCell=%d"),
					bEnableRadiationCapture ? 1 : 0,
					bUseReferenceTile ? 1 : 0,
					CellsDimensionX * CellsDimensionY,
					RadiationCellPixelCoords.Num(),
					ReferenceMappingDebugCellIndex);
			}
		}
		ExportReferenceMappingDebugSnapshot(SimTime, TEXT("PostTick"));

		if (bRTYReadbackImmediate || bInjectedRTYFromIndices)
		{
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] Readback success. CachedRTY_Direct.Num()=%d, CachedRTY_Diffuse.Num()=%d"),
				CachedRTY_Direct.Num(), CachedRTY_Diffuse.Num());

		// Log first few values to verify they're not zero
		if (CachedRTY_Direct.Num() > 0)
		{
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] Sample RTY_Direct[0]=%.4f, RTY_Diffuse[0]=%.4f"),
				CachedRTY_Direct[0], CachedRTY_Diffuse.Num() > 0 ? CachedRTY_Diffuse[0] : -1.0f);
		}

		bool bUsedTerrainFallbackMode = false;
		BuildTerrainResidualLuminance(
			CachedRTY_Total,
			CachedRTY_Direct,
			CachedRTY_Diffuse,
			CachedRTY_DiffuseNoGI,
			CachedRTY_TotalNoGI,
			TerrainResidualMode,
			CachedRTY_Terrain,
			bUsedTerrainFallbackMode);
		if (bBlurTerrainResidual)
		{
			ApplyGaussianBlurToGrid(CachedRTY_Terrain, CellsDimensionX, CellsDimensionY);
		}

			static bool bLoggedTerrainFallbackPostCapture = false;
			if (bUsedTerrainFallbackMode && !bLoggedTerrainFallbackPostCapture)
			{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] RTY_Terrain post-capture update uses fallback Total-Direct-Diffuse (no sky-only capture yet)."));
			bLoggedTerrainFallbackPostCapture = true;
		}

		if (bRadiationBenchmarkCaptureActive)
		{
			UE_LOG(LogTemp, Verbose, TEXT("[RadTrace] Benchmark capture active; skipped simulation RTY handoff."));
		}
		else if (UDegreeDaySimulation* DDSim = Cast<UDegreeDaySimulation>(Simulation))
		{
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] Calling DDSim->UpdateRTYLuminance() on Simulation instance %p"), DDSim);
			DDSim->UpdateRTYLuminance(CachedRTY_Total, CachedRTY_Direct, CachedRTY_Diffuse, CachedRTY_DiffuseNoGI, CachedRTY_TotalNoGI, CachedRTY_Terrain);
			UE_LOG(LogTemp, Error, TEXT("[RadTrace] UpdateRTYLuminance completed"));
		}
		else if (Cast<UFSM2SnowSimulation>(Simulation))
		{
			UE_LOG(LogTemp, Verbose, TEXT("[RadTrace] Active simulation is FSM2; RTY buffers are consumed from actor caches."));
		}
		else
		{
			const FString SimulationName = Simulation ? Simulation->GetClass()->GetName() : TEXT("None");
			UE_LOG(LogTemp, Warning, TEXT("[RadTrace] UpdateRTYLuminance skipped (simulation type: %s)"), *SimulationName);
		}
	}
	else
	{
		UE_LOG(LogTemp, Error, TEXT("[RadTrace] Readback FAILED."));
	}

	// Note: Sun position should already be synchronized via UpdateSunSkyActors()
	// or your existing sun positioning system based on SimTime

	// Debug verification: Check frame-to-frame consistency
	if (bDebugRadiationCapture)
	{
		DebugVerifyRadiationConsistency();
	}
}

void ASnowSimulationActor::ConfigureShowFlags_Total(FEngineShowFlags& Flags)
{
	// Enable all lighting for TOTAL irradiance
	Flags.SetLighting(true);
	Flags.SetDirectionalLights(true);
	Flags.SetSkyLighting(true);
	Flags.SetGlobalIllumination(true);
	Flags.SetReflectionEnvironment(true);

	// CRITICAL: Explicitly enable Lumen for indirect lighting (GI + diffuse)
	Flags.SetLumenGlobalIllumination(true);
	Flags.SetLumenReflections(true);

	// Disable unwanted features
	Flags.SetPostProcessing(false);
	Flags.SetAntiAliasing(false);
	Flags.SetMotionBlur(false);
	Flags.SetTemporalAA(false);
	ApplyAtmosphereShowFlagPolicy(Flags);

	// Keep necessary geometry
	Flags.SetStaticMeshes(true);
	Flags.SetLandscape(true);
	Flags.SetBSP(true);
	Flags.SetDynamicShadows(true);
	ApplyLambertianShowFlagOverride(Flags);
}

void ASnowSimulationActor::ConfigureShowFlags_Direct(FEngineShowFlags& Flags, bool bAllowReferenceTileAtmosphereMatch)
{
	const bool bStrictBenchmarkDirect = bRadiationBenchmarkCaptureActive && bRadiationBenchmarkStrictNoGIForBenchmark;
	const bool bIncludeAtmosphereInDirectPass = bDirectCaptureIncludesAtmosphere
		|| (bAllowReferenceTileAtmosphereMatch
			&& bUseReferenceTile
			&& bMatchDirectPassAtmosphereToReferenceCalibration
			&& bNonDirectCapturesIncludeAtmosphere);
	const bool bDisableAtmosphereForDedicatedSky = ShouldUseDedicatedRadiationSkyLightForCapture()
		&& bDisableAtmosphereWhenUsingDedicatedRadiationSkyLight;
	const bool bEffectiveDirectAtmosphere =
		!bStrictBenchmarkDirect
		&& bIncludeAtmosphereInDirectPass
		&& !bDisableAtmosphereForDedicatedSky;

	// Start with minimal flags
	Flags.SetLighting(true);
	Flags.SetDirectionalLights(true);
	Flags.SetDynamicShadows(true);

	// DISABLE all GI/Sky/Reflections for DIRECT-ONLY
	Flags.SetSkyLighting(false);
	Flags.SetGlobalIllumination(false);
	// Explicitly disable Lumen paths as an extra guard against GI leakage.
	Flags.SetLumenGlobalIllumination(false);
	Flags.SetLumenReflections(false);
	Flags.SetReflectionEnvironment(false);
	Flags.SetScreenSpaceReflections(false);
	Flags.SetAmbientOcclusion(false);

	// Leave disabled by default for a pure direct reference; an explicit opt-in is
	// still available for legacy comparisons.
	// When reference-tile calibration is active, matching atmosphere to the non-direct
	// passes keeps strip direct transmittance consistent with Total/TotalNoGI.
	Flags.SetAtmosphere(bEffectiveDirectAtmosphere);
	Flags.SetFog(bEffectiveDirectAtmosphere);
	Flags.SetVolumetricFog(bEffectiveDirectAtmosphere);

	// Disable post-processing
	Flags.SetPostProcessing(false);
	Flags.SetAntiAliasing(false);
	Flags.SetMotionBlur(false);
	Flags.SetTemporalAA(false);

	// Keep geometry
	Flags.SetStaticMeshes(true);
	Flags.SetLandscape(true);
	Flags.SetBSP(true);
	ApplyLambertianShowFlagOverride(Flags);
}

void ASnowSimulationActor::ConfigureShowFlags_Diffuse(FEngineShowFlags& Flags)
{
	// Diffuse-only: keep sky + GI, disable direct sun.
	Flags.SetLighting(true);
	Flags.SetDirectionalLights(false);
	Flags.SetSkyLighting(true);
	Flags.SetGlobalIllumination(true);
	Flags.SetReflectionEnvironment(true);

	// Keep Lumen GI for indirect lighting.
	Flags.SetLumenGlobalIllumination(true);
	Flags.SetLumenReflections(true);

	// Disable post-processing
	Flags.SetPostProcessing(false);
	Flags.SetAntiAliasing(false);
	Flags.SetMotionBlur(false);
	Flags.SetTemporalAA(false);

	ApplyAtmosphereShowFlagPolicy(Flags);

	// Keep geometry
	Flags.SetStaticMeshes(true);
	Flags.SetLandscape(true);
	Flags.SetBSP(true);
	Flags.SetDynamicShadows(true);
	ApplyLambertianShowFlagOverride(Flags);
}

void ASnowSimulationActor::ConfigureShowFlags_DiffuseNoGI(FEngineShowFlags& Flags)
{
	const bool bStrictBenchmarkNoGI = bRadiationBenchmarkCaptureActive && bRadiationBenchmarkStrictNoGIForBenchmark;
	// Capture TotalNoGI: preserve sun + sky + atmosphere, but disable the
	// Lumen GI / reflection systems that create scene bounce so that:
	//     TerrainBounce = max(0, Total - TotalNoGI)
	// is a genuine residual.
	//
	// IMPORTANT: GlobalIllumination must remain TRUE.  In UE5's deferred path
	// the SkyLight cubemap contribution to surfaces is routed through the same
	// indirect-lighting composite that GlobalIllumination controls.  Setting it
	// to false zeroes out the SkyLight surface term entirely (empirically
	// confirmed: TotalNoGI drops to ~0 in a cavity with SVF ~0.5).
	//
	// Instead we keep GlobalIllumination on and disable only the Lumen subsystems
	// that produce dynamic scene bounce (LumenGlobalIllumination, LumenReflections,
	// ReflectionEnvironment).  To prevent the SkyLight cubemap from already
	// containing terrain-reflected light (which would leak bounce into this pass),
	// each capture scope applies FScopedEmissiveOnlySkyCapture, which sets
	// bCaptureEmissiveOnly=true on the SLS_CapturedScene SkyLight before capture.
	// This restricts the cubemap to atmosphere / emissive sources only.
	Flags.SetLighting(true);
	Flags.SetDirectionalLights(true);
	Flags.SetSkyLighting(true);
	Flags.SetGlobalIllumination(!bStrictBenchmarkNoGI);
	Flags.SetReflectionEnvironment(false);
	Flags.SetScreenSpaceReflections(false);
	Flags.SetAmbientOcclusion(false);

	Flags.SetLumenGlobalIllumination(false);
	Flags.SetLumenReflections(false);

	Flags.SetPostProcessing(false);
	Flags.SetAntiAliasing(false);
	Flags.SetMotionBlur(false);
	Flags.SetTemporalAA(false);

	ApplyAtmosphereShowFlagPolicy(Flags);

	Flags.SetStaticMeshes(true);
	Flags.SetLandscape(true);
	Flags.SetBSP(true);
	Flags.SetDynamicShadows(true);
	ApplyLambertianShowFlagOverride(Flags);
}

void ASnowSimulationActor::ConfigureShowFlags_SurfaceState(FEngineShowFlags& Flags)
{
	Flags.SetLighting(false);
	Flags.SetDirectionalLights(false);
	Flags.SetSkyLighting(false);
	Flags.SetGlobalIllumination(false);
	Flags.SetReflectionEnvironment(false);
	Flags.SetScreenSpaceReflections(false);
	Flags.SetAmbientOcclusion(false);
	Flags.SetLumenGlobalIllumination(false);
	Flags.SetLumenReflections(false);
	Flags.SetPostProcessing(false);
	Flags.SetAntiAliasing(false);
	Flags.SetMotionBlur(false);
	Flags.SetTemporalAA(false);
	Flags.SetAtmosphere(false);
	Flags.SetFog(false);
	Flags.SetVolumetricFog(false);
	Flags.SetStaticMeshes(true);
	Flags.SetLandscape(true);
	Flags.SetBSP(true);
	Flags.SetDynamicShadows(false);
}

void ASnowSimulationActor::ApplyAtmosphereShowFlagPolicy(FEngineShowFlags& Flags) const
{
	const bool bDisableAtmosphereForDedicatedSky = ShouldUseDedicatedRadiationSkyLightForCapture()
		&& bDisableAtmosphereWhenUsingDedicatedRadiationSkyLight;
	const bool bEnableAtmosphere = bNonDirectCapturesIncludeAtmosphere && !bDisableAtmosphereForDedicatedSky;
	Flags.SetAtmosphere(bEnableAtmosphere);
	Flags.SetFog(bEnableAtmosphere);
	Flags.SetVolumetricFog(bEnableAtmosphere);
}

void ASnowSimulationActor::ApplyLambertianShowFlagOverride(FEngineShowFlags& Flags) const
{
	if (!bLambertianCaptureShowFlagOverride)
	{
		return;
	}

	Flags.SetReflectionEnvironment(false);
	Flags.SetSpecular(false);
	Flags.SetLumenReflections(false);
}

// ============================================================================
// Debug Utilities - Radiation Capture Consistency Verification
// ============================================================================

FLinearColor ASnowSimulationActor::ReadPixelFromRT(UTextureRenderTarget2D* RT, int32 X, int32 Y)
{
	if (!RT || !RT->GetResource())
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] ReadPixelFromRT: Invalid render target"));
		return FLinearColor::Black;
	}

	// Validate coordinates
	if (X < 0 || X >= RT->SizeX || Y < 0 || Y >= RT->SizeY)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] ReadPixelFromRT: Pixel (%d,%d) out of bounds (%dx%d)"),
			X, Y, RT->SizeX, RT->SizeY);
		return FLinearColor::Black;
	}

	FLinearColor PixelColor = FLinearColor::Black;

	// GPU readback: Read entire RT and extract a single pixel.
	// RGBA16f uses explicit half-float readback, while RGBA32f uses linear color readback.
	FTextureRenderTargetResource* RTResource = RT->GameThread_GetRenderTargetResource();
	if (!RTResource)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] ReadPixelFromRT: No RT resource available"));
		return FLinearColor::Black;
	}

	// Read render target data (blocks until GPU completes)
	TArray<FLinearColor> PixelData;
	FReadSurfaceDataFlags ReadFlags(RCM_MinMax); // Don't apply gamma/sRGB
	ReadFlags.SetLinearToGamma(false); // CRITICAL: Keep linear HDR values

	if (ReadRenderTargetLinearPixels(RT, RTResource, PixelData, ReadFlags))
	{
		if (PixelData.Num() == RT->SizeX * RT->SizeY)
		{
			int32 Index = Y * RT->SizeX + X;
			if (PixelData.IsValidIndex(Index))
			{
				PixelColor = PixelData[Index];
			}
		}
		else
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] ReadPixelFromRT: Pixel data size mismatch (%d vs %d)"),
				PixelData.Num(), RT->SizeX * RT->SizeY);
		}
	}
	else
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] ReadPixelFromRT: render-target readback failed"));
	}

	return PixelColor;
}

void ASnowSimulationActor::DebugVerifyRadiationConsistency()
{
	if (!RT_Total)
	{
		return;
	}

	// Validate debug pixel coordinates
	const int32 ClampedX = FMath::Clamp(DebugPixelX, 0, CellsDimensionX - 1);
	const int32 ClampedGridY = FMath::Clamp(DebugPixelY, 0, CellsDimensionY - 1);
	const int32 BorderOffset = bUseReferenceTile ? 1 : 0;
	const int32 PixelY = ClampedGridY + BorderOffset;

	// Read same pixel from RT_Total using the same mapping as the compute shader
	FLinearColor CurrentPixelValue = ReadPixelFromRT(RT_Total, ClampedX, PixelY);

	// Frame 0: Initialize baseline
	if (DebugFrameCounter == 0)
	{
		PreviousDebugPixelValue = CurrentPixelValue;
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Debug BASELINE at pixel (%d,%d): R=%.6f G=%.6f B=%.6f A=%.6f"),
			ClampedX, PixelY,
			CurrentPixelValue.R, CurrentPixelValue.G, CurrentPixelValue.B, CurrentPixelValue.A);
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Debug: Hex representation: R=%08X G=%08X B=%08X A=%08X"),
			*(uint32*)&CurrentPixelValue.R, *(uint32*)&CurrentPixelValue.G,
			*(uint32*)&CurrentPixelValue.B, *(uint32*)&CurrentPixelValue.A);
	}
	else
	{
		// Compare with previous frame - check bit-identical values
		const uint32* CurrentBits = reinterpret_cast<const uint32*>(&CurrentPixelValue);
		const uint32* PreviousBits = reinterpret_cast<const uint32*>(&PreviousDebugPixelValue);

		bool bIdentical = (CurrentBits[0] == PreviousBits[0]) &&
		                  (CurrentBits[1] == PreviousBits[1]) &&
		                  (CurrentBits[2] == PreviousBits[2]) &&
		                  (CurrentBits[3] == PreviousBits[3]);

		if (bIdentical)
		{
			UE_LOG(LogTemp, Display, TEXT("[RadCapture] Debug Frame %d: IDENTICAL to baseline (static lighting verified)"),
				DebugFrameCounter);
		}
		else
		{
			// Values changed - log difference
			FLinearColor Delta = CurrentPixelValue - PreviousDebugPixelValue;
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Debug Frame %d: VALUES CHANGED at pixel (%d,%d)"),
				DebugFrameCounter, ClampedX, PixelY);
			UE_LOG(LogTemp, Warning, TEXT("  Current:  R=%.6f G=%.6f B=%.6f A=%.6f"),
				CurrentPixelValue.R, CurrentPixelValue.G, CurrentPixelValue.B, CurrentPixelValue.A);
			UE_LOG(LogTemp, Warning, TEXT("  Previous: R=%.6f G=%.6f B=%.6f A=%.6f"),
				PreviousDebugPixelValue.R, PreviousDebugPixelValue.G, PreviousDebugPixelValue.B, PreviousDebugPixelValue.A);
			UE_LOG(LogTemp, Warning, TEXT("  Delta:    R=%.6f G=%.6f B=%.6f A=%.6f"),
				Delta.R, Delta.G, Delta.B, Delta.A);
			UE_LOG(LogTemp, Warning, TEXT("  Current hex:  R=%08X G=%08X B=%08X A=%08X"),
				CurrentBits[0], CurrentBits[1], CurrentBits[2], CurrentBits[3]);
			UE_LOG(LogTemp, Warning, TEXT("  Previous hex: R=%08X G=%08X B=%08X A=%08X"),
				PreviousBits[0], PreviousBits[1], PreviousBits[2], PreviousBits[3]);

			// Update baseline
			PreviousDebugPixelValue = CurrentPixelValue;
		}
	}

	DebugFrameCounter++;
}

FVector ASnowSimulationActor::GridCellToWorldPosition(int32 CellX, int32 CellY) const
{
	if (!Landscape)
	{
		UE_LOG(LogTemp, Warning, TEXT("[GridMapping] GridCellToWorldPosition: Landscape is null"));
		return FVector::ZeroVector;
	}

	// Grid origin and orientation from landscape actor transform
	const FVector LandscapeMin = Landscape->GetActorLocation();
	const FRotator LandscapeRotation = Landscape->GetActorRotation();
	const FVector LocalLandscapeScale = Landscape->GetActorScale();
	const float CellSizeWorld = LocalLandscapeScale.X * static_cast<float>(CellSize); // cm per cell

	// Cell center in landscape local space, then rotate into world space.
	const FVector LocalCellCenter(
		(static_cast<float>(CellX) + 0.5f) * CellSizeWorld,
		(static_cast<float>(CellY) + 0.5f) * CellSizeWorld,
		0.0f);

	return LandscapeMin + LandscapeRotation.RotateVector(LocalCellCenter);
}

FVector2D ASnowSimulationActor::WorldPositionToGridCell(const FVector& WorldPosition) const
{
	if (!Landscape)
	{
		UE_LOG(LogTemp, Warning, TEXT("[GridMapping] WorldPositionToGridCell: Landscape is null"));
		return FVector2D::ZeroVector;
	}

	// Grid origin and orientation from landscape actor transform
	const FVector LandscapeMin = Landscape->GetActorLocation();
	const FRotator LandscapeRotation = Landscape->GetActorRotation();
	const FVector LocalLandscapeScale = Landscape->GetActorScale();
	const float CellSizeWorld = LocalLandscapeScale.X * static_cast<float>(CellSize); // cm per cell

	// Transform into landscape local coordinates, then convert to fractional cell coordinates.
	const FVector LocalPos = LandscapeRotation.UnrotateVector(WorldPosition - LandscapeMin);
	const float GridX = LocalPos.X / CellSizeWorld;
	const float GridY = LocalPos.Y / CellSizeWorld;

	return FVector2D(GridX, GridY);
}

void ASnowSimulationActor::ValidateGridToPixelMapping()
{
	if (!bEnableRadiationCapture || !RadiationCapture || !RT_Total || !Landscape)
	{
		return;
	}

	UE_LOG(LogTemp, Display, TEXT("[RadCapture] ===== Grid-to-Pixel Mapping Validation ====="));

	// Test several known grid cells and verify pixel mapping
	const TArray<FIntPoint> TestCells = {
		FIntPoint(0, 0), // Bottom-left
		FIntPoint(CellsDimensionX - 1, 0), // Bottom-right
		FIntPoint(0, CellsDimensionY - 1), // Top-left
		FIntPoint(CellsDimensionX - 1, CellsDimensionY - 1), // Top-right
		FIntPoint(CellsDimensionX / 2, CellsDimensionY / 2) // Center
	};

	for (const FIntPoint& Cell : TestCells)
	{
		// Convert grid cell to world position
		const FVector WorldPos = GridCellToWorldPosition(Cell.X, Cell.Y);

		// Convert world position back to grid cell
		const FVector2D GridPos = WorldPositionToGridCell(WorldPos);

		// Check round-trip accuracy
		const float ErrorX = FMath::Abs(GridPos.X - static_cast<float>(Cell.X) - 0.5f); // 0.5 offset for cell center
		const float ErrorY = FMath::Abs(GridPos.Y - static_cast<float>(Cell.Y) - 0.5f);

		const bool bMappingCorrect = (ErrorX < 0.001f && ErrorY < 0.001f);

		if (bMappingCorrect)
		{
			UE_LOG(LogTemp, Display, TEXT("[RadCapture] Cell(%d,%d) → World(%.1f,%.1f) → Cell(%.3f,%.3f) ✓"),
				Cell.X, Cell.Y, WorldPos.X, WorldPos.Y, GridPos.X, GridPos.Y);
		}
		else
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Cell(%d,%d) → World(%.1f,%.1f) → Cell(%.3f,%.3f) ✗ ERROR! (%.4f, %.4f)"),
				Cell.X, Cell.Y, WorldPos.X, WorldPos.Y, GridPos.X, GridPos.Y, ErrorX, ErrorY);
		}
	}

	// Verify orthographic projection parameters
	const FVector LocalLandscapeScale = Landscape->GetActorScale();
	const float CellSizeWorld = LocalLandscapeScale.X * static_cast<float>(CellSize);
	const float GridWidthWorld = CellSizeWorld * static_cast<float>(CellsDimensionX);
	const float ExpectedOrthoWidth = GridWidthWorld;
	const float OrthoWidthError = FMath::Abs(RadiationCapture->OrthoWidth - ExpectedOrthoWidth);

	if (OrthoWidthError < 0.1f)
	{
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] OrthoWidth validation: %.3f cm (expected %.3f cm) ✓"),
			RadiationCapture->OrthoWidth, ExpectedOrthoWidth);
	}
	else
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] OrthoWidth validation FAILED: %.3f cm (expected %.3f cm, error %.3f cm)"),
			RadiationCapture->OrthoWidth, ExpectedOrthoWidth, OrthoWidthError);
	}

	// Verify capture orientation
	const FRotator CaptureRot = RadiationCapture->GetComponentRotation();
	const FRotator LandscapeRot = Landscape->GetActorRotation();
	const float EffectiveCaptureYawOffsetDeg = FMath::Clamp(CaptureYawOffsetDegrees, -180.0f, 180.0f);
	const float ExpectedPitch = -90.0f;
	const float ExpectedYaw = FRotator::NormalizeAxis(LandscapeRot.Yaw + EffectiveCaptureYawOffsetDeg);
	const float ExpectedRoll = FRotator::NormalizeAxis(LandscapeRot.Roll);
	const float PitchError = FMath::Abs(FRotator::NormalizeAxis(CaptureRot.Pitch - ExpectedPitch));
	const float YawError = FMath::Abs(FRotator::NormalizeAxis(CaptureRot.Yaw - ExpectedYaw));
	const float RollError = FMath::Abs(FRotator::NormalizeAxis(CaptureRot.Roll - ExpectedRoll));
	const bool bOrientationCorrect = (PitchError < 0.1f) && (YawError < 0.1f) && (RollError < 0.1f);

	if (bOrientationCorrect)
	{
		UE_LOG(LogTemp, Display, TEXT("[RadCapture] Capture orientation: Pitch=%.2f, Yaw=%.2f, Roll=%.2f ✓"),
			CaptureRot.Pitch, CaptureRot.Yaw, CaptureRot.Roll);
	}
	else
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Capture orientation INCORRECT: Pitch=%.2f (expect %.2f, err %.2f), Yaw=%.2f (expect %.2f, err %.2f), Roll=%.2f (expect %.2f, err %.2f)"),
			CaptureRot.Pitch, ExpectedPitch, PitchError,
			CaptureRot.Yaw, ExpectedYaw, YawError,
			CaptureRot.Roll, ExpectedRoll, RollError);
	}

	UE_LOG(LogTemp, Display, TEXT("[RadCapture] ============================================"));
}

void ASnowSimulationActor::ExportReferenceMappingDebugSnapshot(const FDateTime& CaptureTime, const TCHAR* StageLabel, bool bForceRenderSync, bool bSampleSceneCaptureTargets)
{
	if (!bExportReferenceMappingDebug)
	{
		return;
	}

	if (!bEnableRadiationCapture)
	{
		static bool bLoggedCaptureDisabled = false;
		if (!bLoggedCaptureDisabled)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefMapDebug] Export enabled but radiation capture is disabled."));
			bLoggedCaptureDisabled = true;
		}
		return;
	}

	if (!bUseReferenceTile)
	{
		static bool bLoggedNoReferenceTile = false;
		if (!bLoggedNoReferenceTile)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefMapDebug] Reference tile is disabled; exporting raw strip/cell texture stats anyway."));
			bLoggedNoReferenceTile = true;
		}
	}

	const int32 LocalNumCells = CellsDimensionX * CellsDimensionY;
	if (LocalNumCells <= 0)
	{
		static bool bLoggedNoCells = false;
		if (!bLoggedNoCells)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefMapDebug] No cells available (CellsDimensionX*CellsDimensionY <= 0)."));
			bLoggedNoCells = true;
		}
		return;
	}

	if (RadiationCellPixelCoords.Num() != LocalNumCells)
	{
		static int32 PixelCoordSizeMismatchLogCount = 0;
		if (PixelCoordSizeMismatchLogCount++ < 5)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefMapDebug] Pixel coord map size mismatch: coords=%d cells=%d."),
				RadiationCellPixelCoords.Num(), LocalNumCells);
		}
		return;
	}

	int32 TargetCellIndex = ReferenceMappingDebugCellIndex;
	if (TargetCellIndex < 0 || TargetCellIndex >= LocalNumCells)
	{
		for (int32 Candidate : DiagnosticsTrackedCellIndices)
		{
			if (Candidate >= 0 && Candidate < LocalNumCells)
			{
				TargetCellIndex = Candidate;
				break;
			}
		}
	}
	if (TargetCellIndex < 0 || TargetCellIndex >= LocalNumCells)
	{
		TargetCellIndex = FMath::Clamp(LocalNumCells / 2, 0, LocalNumCells - 1);
		static bool bLoggedFallbackCell = false;
		if (!bLoggedFallbackCell)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefMapDebug] No valid target cell configured; using fallback cell index %d."),
				TargetCellIndex);
			bLoggedFallbackCell = true;
		}
	}

	if (!RadiationCellPixelCoords.IsValidIndex(TargetCellIndex))
	{
		static int32 InvalidPixelCoordLogCount = 0;
		if (InvalidPixelCoordLogCount++ < 5)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefMapDebug] Invalid pixel coord index %d (coords size %d)."),
				TargetCellIndex, RadiationCellPixelCoords.Num());
		}
		return;
	}

	const FIntPoint TargetPixel = RadiationCellPixelCoords[TargetCellIndex];
	if (TargetPixel.X < 0 || TargetPixel.Y < 0)
	{
		static int32 NegativePixelLogCount = 0;
		if (NegativePixelLogCount++ < 5)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefMapDebug] Invalid mapped pixel for cell %d: (%d, %d)."),
				TargetCellIndex, TargetPixel.X, TargetPixel.Y);
		}
		return;
	}

	if (bForceRenderSync)
	{
		FlushRenderingCommands();
	}

	const TCHAR* TextureFamilyLabel = bSampleSceneCaptureTargets ? TEXT("RT") : TEXT("RTY");
	UTextureRenderTarget2D* const TotalSampleTarget = bSampleSceneCaptureTargets ? RT_Total : RTY_Total;
	UTextureRenderTarget2D* const DirectSampleTarget = bSampleSceneCaptureTargets ? RT_Direct : RTY_Direct;
	UTextureRenderTarget2D* const DiffuseSampleTarget = bSampleSceneCaptureTargets ? RT_Diffuse : RTY_Diffuse;
	UTextureRenderTarget2D* const DiffuseNoGISampleTarget = bSampleSceneCaptureTargets ? RT_DiffuseNoGI : RTY_DiffuseNoGI;

	auto ComputeTextureStats = [&](UTextureRenderTarget2D* Target, float& OutCellValue, float& OutStripMean, float& OutStripMin, float& OutStripMax, int32& OutStripSamples) -> bool
	{
		OutCellValue = 0.0f;
		OutStripMean = 0.0f;
		OutStripMin = 0.0f;
		OutStripMax = 0.0f;
		OutStripSamples = 0;

		if (!Target)
		{
			return false;
		}

		FTextureRenderTargetResource* Resource = Target->GameThread_GetRenderTargetResource();
		if (!Resource)
		{
			return false;
		}

		TArray<FLinearColor> PixelData;
		FReadSurfaceDataFlags ReadFlags(RCM_MinMax);
		ReadFlags.SetLinearToGamma(false);
		if (!ReadRenderTargetLinearPixels(Target, Resource, PixelData, ReadFlags))
		{
			return false;
		}

		const int32 Width = Target->SizeX;
		const int32 Height = Target->SizeY;
		const int32 ExpectedCount = Width * Height;
		if (Width <= 0 || Height <= 0 || PixelData.Num() != ExpectedCount)
		{
			return false;
		}

		if (TargetPixel.X >= 0 && TargetPixel.X < Width && TargetPixel.Y >= 0 && TargetPixel.Y < Height)
		{
			const int32 CellLinearIndex = TargetPixel.Y * Width + TargetPixel.X;
			OutCellValue = PixelData[CellLinearIndex].R;
		}

		const int32 StripH = FMath::Clamp(ReferenceStripHeight, 1, Height);
		double StripSum = 0.0;
		float StripMin = FLT_MAX;
		float StripMax = -FLT_MAX;
		int32 StripSamples = 0;
		for (int32 Y = 0; Y < StripH; ++Y)
		{
			for (int32 X = 0; X < Width; ++X)
			{
				const int32 LinearIdx = Y * Width + X;
				const float Value = PixelData[LinearIdx].R;
				if (!FMath::IsFinite(Value) || Value < 0.0f)
				{
					continue;
				}
				StripSum += Value;
				StripMin = FMath::Min(StripMin, Value);
				StripMax = FMath::Max(StripMax, Value);
				++StripSamples;
			}
		}

		OutStripSamples = StripSamples;
		if (StripSamples > 0)
		{
			OutStripMean = static_cast<float>(StripSum / static_cast<double>(StripSamples));
			OutStripMin = StripMin;
			OutStripMax = StripMax;
		}
		return true;
	};

	float DirectCell = 0.0f, DirectStripMean = 0.0f, DirectStripMin = 0.0f, DirectStripMax = 0.0f;
	float TotalCell = 0.0f, TotalStripMean = 0.0f, TotalStripMin = 0.0f, TotalStripMax = 0.0f;
	float DiffuseCell = 0.0f, DiffuseStripMean = 0.0f, DiffuseStripMin = 0.0f, DiffuseStripMax = 0.0f;
	float DiffNoGICell = 0.0f, DiffNoGIStripMean = 0.0f, DiffNoGIStripMin = 0.0f, DiffNoGIStripMax = 0.0f;
	int32 DirectStripSamples = 0, TotalStripSamples = 0, DiffuseStripSamples = 0, DiffNoGIStripSamples = 0;

	const bool bHasDirectStats = ComputeTextureStats(DirectSampleTarget, DirectCell, DirectStripMean, DirectStripMin, DirectStripMax, DirectStripSamples);
	const bool bHasTotalStats = ComputeTextureStats(TotalSampleTarget, TotalCell, TotalStripMean, TotalStripMin, TotalStripMax, TotalStripSamples);
	const bool bHasDiffuseStats = ComputeTextureStats(DiffuseSampleTarget, DiffuseCell, DiffuseStripMean, DiffuseStripMin, DiffuseStripMax, DiffuseStripSamples);
	const bool bHasDiffNoGIStats = ComputeTextureStats(DiffuseNoGISampleTarget, DiffNoGICell, DiffNoGIStripMean, DiffNoGIStripMin, DiffNoGIStripMax, DiffNoGIStripSamples);

	if (ReferenceMappingDebugCsvPath.IsEmpty())
	{
		const FString TargetDir = GetOutputCategoryDirectory(TEXT("Radiation"));
		if (!EnsureDirectoryExists(TargetDir))
		{
			UE_LOG(LogTemp, Error, TEXT("[RefMapDebug] Failed to create output directory: %s"), *TargetDir);
			return;
		}
		const FString Timestamp = FDateTime::Now().ToString(TEXT("%Y%m%d_%H%M%S"));
		const FString RunTag = BuildRunTag(Timestamp);
		ReferenceMappingDebugCsvPath = FPaths::Combine(TargetDir, FString::Printf(TEXT("ReferenceMappingDebug_%s.csv"), *RunTag));

		FString Header = TEXT("Timestamp,Stage,TextureFamily,CellIndex,PixelX,PixelY,ReferenceStripHeight,");
		Header += TEXT("RefLum_Total,RefLum_Direct,RefLum_Diffuse,RefLum_DiffuseNoGI,");
		Header += TEXT("DualRefEnabled,RefLum_Total_Ground,RefLum_Total_Snow,RefLum_Direct_Ground,RefLum_Direct_Snow,RefLum_Diffuse_Ground,RefLum_Diffuse_Snow,RefLum_DiffuseNoGI_Ground,RefLum_DiffuseNoGI_Snow,");
		Header += TEXT("RTY_Total_Cached,RTY_Direct_Cached,RTY_Diffuse_Cached,RTY_DiffuseNoGI_Cached,");
		Header += TEXT("Sample_Total_Cell,Sample_Total_StripMean,Sample_Total_StripMin,Sample_Total_StripMax,Sample_Total_StripSamples,");
		Header += TEXT("Sample_Direct_Cell,Sample_Direct_StripMean,Sample_Direct_StripMin,Sample_Direct_StripMax,Sample_Direct_StripSamples,");
		Header += TEXT("Sample_Diffuse_Cell,Sample_Diffuse_StripMean,Sample_Diffuse_StripMin,Sample_Diffuse_StripMax,Sample_Diffuse_StripSamples,");
		Header += TEXT("Sample_DiffuseNoGI_Cell,Sample_DiffuseNoGI_StripMean,Sample_DiffuseNoGI_StripMin,Sample_DiffuseNoGI_StripMax,Sample_DiffuseNoGI_StripSamples,");
		Header += TEXT("HasSample_TotalTex,HasSample_DirectTex,HasSample_DiffuseTex,HasSample_DiffuseNoGITex");
		Header.AppendChar(TEXT('\n'));

		const bool bHeaderSaved = FFileHelper::SaveStringToFile(
			Header,
			*ReferenceMappingDebugCsvPath,
			FFileHelper::EEncodingOptions::ForceUTF8WithoutBOM);
		if (!bHeaderSaved)
		{
			UE_LOG(LogTemp, Error, TEXT("[RefMapDebug] Failed to create CSV: %s"), *ReferenceMappingDebugCsvPath);
			ReferenceMappingDebugCsvPath.Empty();
			return;
		}

		UE_LOG(LogTemp, Display, TEXT("[RefMapDebug] Writing mapping debug CSV: %s"), *ReferenceMappingDebugCsvPath);
	}

	if (!bHasDirectStats && !bHasTotalStats && !bHasDiffuseStats && !bHasDiffNoGIStats)
	{
		static int32 MissingTextureStatsLogCount = 0;
		if (MissingTextureStatsLogCount++ < 12)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefMapDebug] Could not read RTY texture stats this tick (Total=%d Direct=%d Diffuse=%d DiffNoGI=%d). Writing cached-only row."),
				bHasTotalStats ? 1 : 0, bHasDirectStats ? 1 : 0, bHasDiffuseStats ? 1 : 0, bHasDiffNoGIStats ? 1 : 0);
		}
	}
	if (!bHasTotalStats)
	{
		TotalCell = -1.0f;
		TotalStripMean = -1.0f;
		TotalStripMin = -1.0f;
		TotalStripMax = -1.0f;
		TotalStripSamples = 0;
	}
	if (!bHasDirectStats)
	{
		DirectCell = -1.0f;
		DirectStripMean = -1.0f;
		DirectStripMin = -1.0f;
		DirectStripMax = -1.0f;
		DirectStripSamples = 0;
	}
	if (!bHasDiffNoGIStats)
	{
		DiffNoGICell = -1.0f;
		DiffNoGIStripMean = -1.0f;
		DiffNoGIStripMin = -1.0f;
		DiffNoGIStripMax = -1.0f;
		DiffNoGIStripSamples = 0;
	}
	if (!bHasDiffuseStats)
	{
		DiffuseCell = -1.0f;
		DiffuseStripMean = -1.0f;
		DiffuseStripMin = -1.0f;
		DiffuseStripMax = -1.0f;
		DiffuseStripSamples = 0;
	}

	const float CachedTotal = CachedRTY_Total.IsValidIndex(TargetCellIndex) ? CachedRTY_Total[TargetCellIndex] : 0.0f;
	const float CachedDirect = CachedRTY_Direct.IsValidIndex(TargetCellIndex) ? CachedRTY_Direct[TargetCellIndex] : 0.0f;
	const float CachedDiffuse = CachedRTY_Diffuse.IsValidIndex(TargetCellIndex) ? CachedRTY_Diffuse[TargetCellIndex] : 0.0f;
	const float CachedDiffNoGI = CachedRTY_DiffuseNoGI.IsValidIndex(TargetCellIndex) ? CachedRTY_DiffuseNoGI[TargetCellIndex] : 0.0f;

	FString Line;
	Line.Reserve(768);
	Line += CaptureTime.ToIso8601();
	Line += FString::Printf(TEXT(",%s,%s,%d,%d,%d,%d"), StageLabel ? StageLabel : TEXT("Unknown"), TextureFamilyLabel, TargetCellIndex, TargetPixel.X, TargetPixel.Y, ReferenceStripHeight);
	Line += FString::Printf(TEXT(",%.6f,%.6f,%.6f,%.6f"),
		ReferenceLuminance_Total,
		ReferenceLuminance_Direct,
		ReferenceLuminance_Diffuse,
		ReferenceLuminance_DiffuseNoGI);
	Line += FString::Printf(TEXT(",%d,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f"),
		bUseDualReferenceStrip ? 1 : 0,
		ReferenceLuminance_Total_Ground,
		ReferenceLuminance_Total_Snow,
		ReferenceLuminance_Direct_Ground,
		ReferenceLuminance_Direct_Snow,
		ReferenceLuminance_Diffuse_Ground,
		ReferenceLuminance_Diffuse_Snow,
		ReferenceLuminance_DiffuseNoGI_Ground,
		ReferenceLuminance_DiffuseNoGI_Snow);
	Line += FString::Printf(TEXT(",%.6f,%.6f,%.6f,%.6f"), CachedTotal, CachedDirect, CachedDiffuse, CachedDiffNoGI);
	Line += FString::Printf(TEXT(",%.6f,%.6f,%.6f,%.6f,%d"), TotalCell, TotalStripMean, TotalStripMin, TotalStripMax, TotalStripSamples);
	Line += FString::Printf(TEXT(",%.6f,%.6f,%.6f,%.6f,%d"), DirectCell, DirectStripMean, DirectStripMin, DirectStripMax, DirectStripSamples);
	Line += FString::Printf(TEXT(",%.6f,%.6f,%.6f,%.6f,%d"), DiffuseCell, DiffuseStripMean, DiffuseStripMin, DiffuseStripMax, DiffuseStripSamples);
	Line += FString::Printf(TEXT(",%.6f,%.6f,%.6f,%.6f,%d"), DiffNoGICell, DiffNoGIStripMean, DiffNoGIStripMin, DiffNoGIStripMax, DiffNoGIStripSamples);
	Line += FString::Printf(TEXT(",%d,%d,%d,%d"), bHasTotalStats ? 1 : 0, bHasDirectStats ? 1 : 0, bHasDiffuseStats ? 1 : 0, bHasDiffNoGIStats ? 1 : 0);
	Line.AppendChar(TEXT('\n'));

	const bool bAppendSaved = FFileHelper::SaveStringToFile(
		Line,
		*ReferenceMappingDebugCsvPath,
		FFileHelper::EEncodingOptions::ForceUTF8WithoutBOM,
		&IFileManager::Get(),
		FILEWRITE_Append);
	if (!bAppendSaved)
	{
		UE_LOG(LogTemp, Error, TEXT("[RefMapDebug] Failed to append CSV row: %s"), *ReferenceMappingDebugCsvPath);
	}
}

void ASnowSimulationActor::SetupReferencePlane()
{
	if (!Landscape)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RefTile] Cannot setup reference plane: Landscape is null"));
		return;
	}

	auto EnsureReferencePlane = [&](UStaticMeshComponent*& Mesh, const TCHAR* Name)
	{
		if (Mesh)
		{
			return;
		}
		Mesh = NewObject<UStaticMeshComponent>(this, Name);
		Mesh->RegisterComponent();
		Mesh->AttachToComponent(RootComponent, FAttachmentTransformRules::KeepRelativeTransform);

		// Use configured plane mesh asset (defaults to Engine/BasicShapes/Plane)
		if (ReferencePlaneMeshAsset.IsNull())
		{
			ReferencePlaneMeshAsset = TSoftObjectPtr<UStaticMesh>(FSoftObjectPath(TEXT("/Engine/BasicShapes/Plane.Plane")));
		}

		if (UStaticMesh* PlaneMesh = ReferencePlaneMeshAsset.LoadSynchronous())
		{
			Mesh->SetStaticMesh(PlaneMesh);
		}
		else
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefTile] Failed to load reference plane mesh asset %s"), *ReferencePlaneMeshAsset.ToSoftObjectPath().ToString());
		}
	};

	auto ApplyReferenceMaterial = [&](UStaticMeshComponent* Mesh, UMaterialInterface* OverrideMat)
	{
		if (!Mesh)
		{
			return;
		}
		if (OverrideMat)
		{
			Mesh->SetMaterial(0, OverrideMat);
			return;
		}
		if (ReferenceStripOverrideMaterial)
		{
			Mesh->SetMaterial(0, ReferenceStripOverrideMaterial);
			return;
		}

		// Create pure white Lambertian material
		UMaterialInstanceDynamic* RefMaterial = UMaterialInstanceDynamic::Create(
			LoadObject<UMaterial>(nullptr, TEXT("/Engine/BasicShapes/BasicShapeMaterial")), this);

		if (RefMaterial)
		{
			RefMaterial->SetVectorParameterValue(FName("Color"), FLinearColor::White);
			// Force Lambertian surface (Roughness=1, Specular=0)
			RefMaterial->SetScalarParameterValue(FName("Roughness"), 1.0f);
			RefMaterial->SetScalarParameterValue(FName("Specular"), 0.0f);
			RefMaterial->SetScalarParameterValue(FName("Metallic"), 0.0f);
			Mesh->SetMaterial(0, RefMaterial);
		}
	};

	auto HideReferenceStripColumns = [&]()
	{
		for (UStaticMeshComponent* Mesh : ReferenceStripColumnMeshes)
		{
			if (!Mesh)
			{
				continue;
			}
			Mesh->SetVisibility(false);
			Mesh->SetCastShadow(false);
		}
	};

	// Grid parameters
	const FVector LandscapeMin = Landscape->GetActorLocation();
	const FRotator LandscapeRotation = Landscape->GetActorRotation();
	const FVector LocalLandscapeScale = Landscape->GetActorScale();
	const float CellSizeWorld = LocalLandscapeScale.X * static_cast<float>(CellSize);
	const float GridWidthWorld = CellSizeWorld * static_cast<float>(CellsDimensionX);

	// Elevate reference strip relative to actual terrain relief, not just actor origin.
	float MaxLocalTerrainZ = 0.0f;
	if (LandscapeCells.Num() > 0)
	{
		MaxLocalTerrainZ = -FLT_MAX;
		for (const FLandscapeCell& Cell : LandscapeCells)
		{
			const FVector LocalCentroid = LandscapeRotation.UnrotateVector(Cell.Centroid - LandscapeMin);
			MaxLocalTerrainZ = FMath::Max(MaxLocalTerrainZ, LocalCentroid.Z);
		}
		if (!FMath::IsFinite(MaxLocalTerrainZ))
		{
			MaxLocalTerrainZ = 0.0f;
		}
	}

	// Position reference plane BELOW grid origin (captures to y=0 border row)
	// Calculate position in landscape LOCAL space, then transform to world space
	// Center the plane on the reference strip (which has height = ReferenceStripHeight * CellSizeWorld)
	// Grid origin is (0,0), strip starts at Y=0 and goes to negative Y in local space (since we capture Top-Down and standard UVs)
	// Actually, based on "Option A: y=0 border strip", it likely means the texture y=0..H-1 corresponds to world...
	// Wait, let's look at `UpdateRadiationCellPixelMapping`.
	// If `BorderRows` is added, the total height increases.
	// `CaptureCenterYLocal` shifts down.
	// The reference strip is typically at the "bottom" or "top" of the texture depending on mapping.
	// In SetupRadiationCapture: "Reference border is positioned BELOW the grid origin (negative Y offset in LANDSCAPE LOCAL SPACE)"
	// So the strip occupies Y=[-BorderHeight, 0] in local space.
	// The center of this strip is at Y = -BorderHeight / 2.
	const float BorderHeightWorld = ReferenceStripHeight * CellSizeWorld;
	const float RefPlaneYOffset = -BorderHeightWorld * 0.5f; // Center of border strip
	const float RefPlaneHeightOffsetCm = ReferencePlaneHeightOffsetMeters * 100.0f;
	const float RefPlaneHeightLocal = MaxLocalTerrainZ + RefPlaneHeightOffsetCm;

	// Local space offset (relative to landscape origin)
	const FVector RefPlaneBaseLocal = FVector(GridWidthWorld * 0.5f, RefPlaneYOffset, RefPlaneHeightLocal);

	// Scale plane to match grid width (UE plane is 100x100cm by default)
	const float PlaneScaleX = GridWidthWorld / 100.0f;  // Full grid width
	const float PlaneScaleY = BorderHeightWorld / 100.0f;   // Full border height

	if (bUseDualReferenceStrip)
	{
		EnsureReferencePlane(ReferencePlaneMesh, TEXT("ReferencePlaneMeshGround"));
		EnsureReferencePlane(ReferencePlaneMeshSnow, TEXT("ReferencePlaneMeshSnow"));
		HideReferenceStripColumns();

		const float HalfHeightWorld = BorderHeightWorld * 0.5f;
		const float HalfOffsetWorld = BorderHeightWorld * 0.25f;

		FVector TopLocalOffset = RefPlaneBaseLocal + FVector(0.0f, HalfOffsetWorld, 0.0f);
		FVector BottomLocalOffset = RefPlaneBaseLocal + FVector(0.0f, -HalfOffsetWorld, 0.0f);
		// Fixed split semantics: top half uses ground material, bottom half uses snow material.

		const FVector TopWorldOffset = LandscapeRotation.RotateVector(TopLocalOffset);
		const FVector BottomWorldOffset = LandscapeRotation.RotateVector(BottomLocalOffset);
		const FVector TopLocation = LandscapeMin + TopWorldOffset;
		const FVector BottomLocation = LandscapeMin + BottomWorldOffset;

		const FVector HalfScale = FVector(PlaneScaleX, HalfHeightWorld / 100.0f, 1.0f);

		ReferencePlaneMesh->SetWorldLocation(TopLocation);
		ReferencePlaneMesh->SetWorldRotation(LandscapeRotation);
		ReferencePlaneMesh->SetWorldScale3D(HalfScale);

		ReferencePlaneMeshSnow->SetWorldLocation(BottomLocation);
		ReferencePlaneMeshSnow->SetWorldRotation(LandscapeRotation);
		ReferencePlaneMeshSnow->SetWorldScale3D(HalfScale);

		ApplyReferenceMaterial(ReferencePlaneMesh,
			ReferenceStripGroundMaterial ? ReferenceStripGroundMaterial : ReferenceStripOverrideMaterial);
		ApplyReferenceMaterial(ReferencePlaneMeshSnow,
			ReferenceStripSnowMaterial ? ReferenceStripSnowMaterial : ReferenceStripOverrideMaterial);

		ReferencePlaneMesh->SetVisibility(true);
		ReferencePlaneMesh->SetCastShadow(false);
		ReferencePlaneMeshSnow->SetVisibility(true);
		ReferencePlaneMeshSnow->SetCastShadow(false);

		UE_LOG(LogTemp, Display, TEXT("[RefTile] Dual reference planes split top/bottom at Top(%.1f, %.1f, %.1f) and Bottom(%.1f, %.1f, %.1f) cm"),
			TopLocation.X, TopLocation.Y, TopLocation.Z,
			BottomLocation.X, BottomLocation.Y, BottomLocation.Z);
	}
	else
	{
		HideReferenceStripColumns();
		EnsureReferencePlane(ReferencePlaneMesh, TEXT("ReferencePlaneMesh"));

		const FVector RefPlaneWorldOffset = LandscapeRotation.RotateVector(RefPlaneBaseLocal);
		const FVector RefPlaneLocation = LandscapeMin + RefPlaneWorldOffset;
		const FVector RefPlaneScale = FVector(PlaneScaleX, PlaneScaleY, 1.0f);

		ReferencePlaneMesh->SetWorldLocation(RefPlaneLocation);
		ReferencePlaneMesh->SetWorldRotation(LandscapeRotation);
		ReferencePlaneMesh->SetWorldScale3D(RefPlaneScale);
		ApplyReferenceMaterial(ReferencePlaneMesh, ReferenceStripOverrideMaterial);
		ReferencePlaneMesh->SetVisibility(true);
		ReferencePlaneMesh->SetCastShadow(false);

		if (ReferencePlaneMeshSnow)
		{
			ReferencePlaneMeshSnow->SetVisibility(false);
		}

		UE_LOG(LogTemp, Display, TEXT("[RefTile] Reference plane created at (%.1f, %.1f, %.1f) cm, rotation (%.1f, %.1f, %.1f), scale (%.2f, %.2f, 1.0), height offset %.1f m (max local terrain z=%.1f cm)"),
			RefPlaneLocation.X, RefPlaneLocation.Y, RefPlaneLocation.Z,
			LandscapeRotation.Pitch, LandscapeRotation.Yaw, LandscapeRotation.Roll,
			PlaneScaleX, PlaneScaleY, ReferencePlaneHeightOffsetMeters, MaxLocalTerrainZ);
	}
}

ASnowSimulationActor::FTimeIntegrationConfig ASnowSimulationActor::BuildTimeIntegrationConfig(const FDateTime& SimTime, const FTimespan& StepDuration) const
{
	FTimeIntegrationConfig Config;
	Config.StepStartTime = SimTime;
	Config.EffectiveStepSeconds = StepDuration.GetTotalSeconds();
	if (Config.EffectiveStepSeconds <= 0.0)
	{
		Config.EffectiveStepSeconds = FMath::Max(SimDtSeconds, 0.0f);
	}

	if (!bEnableTimeIntegratedRadiation || RadiationIntegrationSubstepMinutes <= 0 || Config.EffectiveStepSeconds <= 0.0)
	{
		Config.SampleCount = 1;
		Config.SampleIntervalSeconds = Config.EffectiveStepSeconds;
		return Config;
	}

	const double SubstepSeconds = static_cast<double>(FMath::Max(1, RadiationIntegrationSubstepMinutes)) * 60.0;
	const int32 MaxSamples = 60; // Max 1 sample per minute
	int32 ComputedSamples = FMath::Clamp(static_cast<int32>(FMath::CeilToDouble(Config.EffectiveStepSeconds / SubstepSeconds)), 1, MaxSamples);

	Config.bEnabled = ComputedSamples > 1;
	Config.SampleCount = ComputedSamples;
	Config.SampleIntervalSeconds = Config.EffectiveStepSeconds / static_cast<double>(ComputedSamples);
	if (bCenterTimeIntegrationWindow)
	{
		Config.StepStartTime = SimTime - FTimespan::FromSeconds(Config.EffectiveStepSeconds * 0.5);
	}
	else
	{
		Config.StepStartTime = SimTime - FTimespan::FromSeconds(Config.EffectiveStepSeconds);
	}

	return Config;
}

void ASnowSimulationActor::EnsureTimeIntegrationTargets(int32 Width, int32 Height)
{
	auto EnsureTarget = [&](UTextureRenderTarget2D*& Target, const TCHAR* DebugName)
	{
		if (!Target)
		{
			Target = NewObject<UTextureRenderTarget2D>(this, DebugName);
		}

		const bool bSizeMismatch = (Target->SizeX != Width) || (Target->SizeY != Height);
		if (bSizeMismatch)
		{
			Target->RenderTargetFormat = RTF_R16f;
			Target->bAutoGenerateMips = false;
			Target->bCanCreateUAV = true;
			Target->InitAutoFormat(Width, Height);
			Target->UpdateResourceImmediate(true);
			return;
		}

		if (!Target->bCanCreateUAV)
		{
			Target->bCanCreateUAV = true;
			Target->UpdateResourceImmediate(true);
		}
	};

	if (Width <= 0 || Height <= 0)
	{
		return;
	}

	EnsureTarget(RTY_TotalIntegration, TEXT("RTY_TotalIntegration"));
	EnsureTarget(RTY_DirectIntegration, TEXT("RTY_DirectIntegration"));
	if (bUseDiffuseCaptureThisFrame)
	{
		EnsureTarget(RTY_DiffuseIntegration, TEXT("RTY_DiffuseIntegration"));
	}
	if (bCaptureDiffuseNoGIForTerrain || bUseDiffuseNoGICaptureThisFrame)
	{
		EnsureTarget(RTY_TotalNoGIIntegration, TEXT("RTY_TotalNoGIIntegration"));
		EnsureTarget(RTY_DiffuseNoGIIntegration, TEXT("RTY_DiffuseNoGIIntegration"));
	}
}

void ASnowSimulationActor::ResetTimeIntegrationTargets()
{
	auto ClearTarget = [](UTextureRenderTarget2D* Target)
	{
		if (!Target)
		{
			return;
		}

		FTextureRenderTargetResource* Resource = Target->GameThread_GetRenderTargetResource();
		if (!Resource)
		{
			return;
		}

		const FTextureRHIRef TextureRHI = Resource->TextureRHI;
		if (!TextureRHI.IsValid())
		{
			return;
		}

		ENQUEUE_RENDER_COMMAND(ClearIntegrationTargetCommand)(
			[TextureRHI](FRHICommandListImmediate& RHICmdList)
			{
				FRDGBuilder GraphBuilder(RHICmdList);
				FRDGTextureRef RDGTexture = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TextureRHI, TEXT("Rad_ClearIntegrationTarget")));
				FRDGTextureUAVRef UAV = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDGTexture));
				AddClearUAVPass(GraphBuilder, UAV, 0.0f);
				GraphBuilder.Execute();
			});
	};

	ClearTarget(RTY_TotalIntegration);
	ClearTarget(RTY_DirectIntegration);
	ClearTarget(RTY_DiffuseIntegration);
	ClearTarget(RTY_TotalNoGIIntegration);
	ClearTarget(RTY_DiffuseNoGIIntegration);
}

void ASnowSimulationActor::AccumulateLuminanceTexture(UTextureRenderTarget2D* Source, UTextureRenderTarget2D* Accumulator, float SampleWeight)
{
	if (!Source || !Accumulator)
	{
		return;
	}

	FTextureRenderTargetResource* SourceResource = Source->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* AccumulatorResource = Accumulator->GameThread_GetRenderTargetResource();
	if (!SourceResource || !AccumulatorResource)
	{
		return;
	}

	const FTextureRHIRef SourceRHI = SourceResource->TextureRHI;
	const FTextureRHIRef AccumulatorRHI = AccumulatorResource->TextureRHI;
	if (!SourceRHI.IsValid() || !AccumulatorRHI.IsValid())
	{
		return;
	}

	const int32 RTWidth = Source->SizeX;
	const int32 RTHeight = Source->SizeY;

	ENQUEUE_RENDER_COMMAND(AccumulateRadiationLuminanceCommand)(
		[SourceRHI, AccumulatorRHI, RTWidth, RTHeight, SampleWeight](FRHICommandListImmediate& RHICmdList)
		{
			FRDGBuilder GraphBuilder(RHICmdList);
			FRDGTextureRef RDGSource = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(SourceRHI, TEXT("Rad_RTY_SourceSample")));
			FRDGTextureRef RDGAccumulator = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(AccumulatorRHI, TEXT("Rad_RTY_Accumulator")));

			TShaderMapRef<FTextureAccumulateCS> Shader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
			FTextureAccumulateCS::FParameters* Params = GraphBuilder.AllocParameters<FTextureAccumulateCS::FParameters>();
			Params->TextureDimensions = FUintVector2(RTWidth, RTHeight);
			Params->Weight = SampleWeight;
			Params->SourceTexture = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDGSource));
			Params->AccumulatorTexture = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDGAccumulator));

			const FIntVector GroupCount(
				FMath::DivideAndRoundUp(RTWidth, 8),
				FMath::DivideAndRoundUp(RTHeight, 8),
				1);

			FComputeShaderUtils::AddPass(
				GraphBuilder,
				RDG_EVENT_NAME("AccumulateRadiationLuminance"),
				Shader,
				Params,
				GroupCount);

			GraphBuilder.Execute();
		});
}

void ASnowSimulationActor::CopyIntegrationResult(UTextureRenderTarget2D* Source, UTextureRenderTarget2D* Dest)
{
	if (!Source || !Dest)
	{
		return;
	}

	FTextureRenderTargetResource* SourceResource = Source->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DestResource = Dest->GameThread_GetRenderTargetResource();

	if (!SourceResource || !DestResource)
	{
		return;
	}

	const FTextureRHIRef SourceRHI = SourceResource->TextureRHI;
	const FTextureRHIRef DestRHI = DestResource->TextureRHI;

	if (!SourceRHI.IsValid() || !DestRHI.IsValid())
	{
		return;
	}

	ENQUEUE_RENDER_COMMAND(CopyIntegrationTextureCommand)(
		[SourceRHI, DestRHI](FRHICommandListImmediate& RHICmdList)
		{
			FRHICopyTextureInfo CopyInfo;
			RHICmdList.CopyTexture(SourceRHI, DestRHI, CopyInfo);
		});
}

void ASnowSimulationActor::ClearRenderTargetTexture(UTextureRenderTarget2D* Target)
{
	if (!Target)
	{
		return;
	}

	FTextureRenderTargetResource* Resource = Target->GameThread_GetRenderTargetResource();
	if (!Resource)
	{
		return;
	}

	const FTextureRHIRef TextureRHI = Resource->TextureRHI;
	if (!TextureRHI.IsValid())
	{
		return;
	}

	const FRHITextureDesc& Desc = TextureRHI->GetDesc();
	const bool bHasUAV = EnumHasAllFlags(Desc.Flags, TexCreate_UAV);
	if (!bHasUAV)
	{
		// Some optional RTs (e.g., legacy RT_DiffuseNoGI assets) might not carry UAV flags.
		// Use a safe game-thread clear path instead of RDG UAV clear to avoid validation asserts.
		if (GetWorld())
		{
			UKismetRenderingLibrary::ClearRenderTarget2D(this, Target, FLinearColor::Black);
		}
		else
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadCapture] Skipping clear for %s: texture has no UAV flag and world is null."),
				*Target->GetName());
		}
		return;
	}

	// Use target name for RDG texture to indentify culprit in crashes/assertions
	const FString DebugName = Target->GetName();

	ENQUEUE_RENDER_COMMAND(ClearNighttimeTargetCommand)(
		[TextureRHI, DebugName](FRHICommandListImmediate& RHICmdList)
		{
			FRDGBuilder GraphBuilder(RHICmdList);
			FRDGTextureRef RDGTexture = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TextureRHI, *DebugName));
			FRDGTextureUAVRef UAV = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDGTexture));
			AddClearUAVPass(GraphBuilder, UAV, 0.0f);
			GraphBuilder.Execute();
		});
}

void ASnowSimulationActor::ClearNighttimeRadiationState()
{
	CachedSunVisibility = 0.0f;
	CachedCaptureCosSolarZenith = 0.0f;
	ReferenceLuminance_Total = 0.0f;
	ReferenceLuminance_Direct = 0.0f;
	ReferenceLuminance_Diffuse = 0.0f;
	ReferenceLuminance_DiffuseNoGI = 0.0f;
	ReferenceLuminance_TotalNoGI = 0.0f;
	ReferenceLuminance_Total_Ground = 0.0f;
	ReferenceLuminance_Direct_Ground = 0.0f;
	ReferenceLuminance_Diffuse_Ground = 0.0f;
	ReferenceLuminance_DiffuseNoGI_Ground = 0.0f;
	ReferenceLuminance_TotalNoGI_Ground = 0.0f;
	ReferenceLuminance_Total_Snow = 0.0f;
	ReferenceLuminance_Direct_Snow = 0.0f;
	ReferenceLuminance_Diffuse_Snow = 0.0f;
	ReferenceLuminance_DiffuseNoGI_Snow = 0.0f;
	ReferenceLuminance_TotalNoGI_Snow = 0.0f;
	CachedReferenceStripRTY_Total.Reset();
	CachedReferenceStripRTY_Direct.Reset();
	CachedReferenceStripRTY_Diffuse.Reset();
	CachedReferenceStripRTY_DiffuseNoGI.Reset();
	CachedReferenceStripRTY_TotalNoGI.Reset();
	CachedReferenceStripWidth = 0;
	CachedReferenceStripHeight = 0;
	bReferenceLuminanceValid = false;

	auto ZeroArray = [](TArray<float>& Values)
	{
		for (float& Value : Values)
		{
			Value = 0.0f;
		}
	};

	ZeroArray(CachedRadiationIndices);
	ZeroArray(CachedRTY_Direct);
	ZeroArray(CachedRTY_Diffuse);
	ZeroArray(CachedRTY_Total);
	ZeroArray(CachedRTY_DiffuseNoGI);
	ZeroArray(CachedRTY_TotalNoGI);
	ZeroArray(CachedRTY_SurfaceState);
	ZeroArray(CachedRTY_Terrain);
	bRTYDiffuseNoGIReadbackQueued = false;
	bRTYTotalNoGIReadbackQueued = false;

	ClearRenderTargetTexture(RT_Total);
	ClearRenderTargetTexture(RT_Direct);
	ClearRenderTargetTexture(RT_Diffuse);
	ClearRenderTargetTexture(RT_DiffuseNoGI);
	ClearRenderTargetTexture(RT_SurfaceState);
	ClearRenderTargetTexture(RTY_Total);
	ClearRenderTargetTexture(RTY_Direct);
	ClearRenderTargetTexture(RTY_Diffuse);
	ClearRenderTargetTexture(RTY_DiffuseNoGI);
	ClearRenderTargetTexture(RTY_TotalNoGI);
	ClearRenderTargetTexture(RTY_SurfaceState);
	ClearRenderTargetTexture(RTY_TotalIntegration);
	ClearRenderTargetTexture(RTY_DirectIntegration);
	ClearRenderTargetTexture(RTY_DiffuseIntegration);
	ClearRenderTargetTexture(RTY_DiffuseNoGIIntegration);
	ClearRenderTargetTexture(RTY_TotalNoGIIntegration);
	ClearRenderTargetTexture(RTF_DirIndex);
	ClearRenderTargetTexture(RTF_DiffIndex);
	ClearRenderTargetTexture(RTF_rUE_raw);
}

void ASnowSimulationActor::UpdateReferenceLuminance(bool bQueueNewReadback /*= true*/, bool bBlockUntilReady /*= false*/)
{
	static int32 CallCounter = 0;
	static bool bFirstCallLogged = false;
    const bool bHadValidReferenceState = bReferenceLuminanceValid;
    const float PreviousReferenceLuminance_Total = ReferenceLuminance_Total;
    const float PreviousReferenceLuminance_Direct = ReferenceLuminance_Direct;
    const float PreviousReferenceLuminance_Diffuse = ReferenceLuminance_Diffuse;
    const float PreviousReferenceLuminance_DiffuseNoGI = ReferenceLuminance_DiffuseNoGI;
    const float PreviousReferenceLuminance_TotalNoGI = ReferenceLuminance_TotalNoGI;
    const float PreviousReferenceLuminance_SurfaceState = ReferenceLuminance_SurfaceState;
    const float PreviousReferenceLuminance_Total_Ground = ReferenceLuminance_Total_Ground;
    const float PreviousReferenceLuminance_Direct_Ground = ReferenceLuminance_Direct_Ground;
    const float PreviousReferenceLuminance_Diffuse_Ground = ReferenceLuminance_Diffuse_Ground;
    const float PreviousReferenceLuminance_DiffuseNoGI_Ground = ReferenceLuminance_DiffuseNoGI_Ground;
    const float PreviousReferenceLuminance_TotalNoGI_Ground = ReferenceLuminance_TotalNoGI_Ground;
    const float PreviousReferenceLuminance_SurfaceState_Ground = ReferenceLuminance_SurfaceState_Ground;
    const float PreviousReferenceLuminance_Total_Snow = ReferenceLuminance_Total_Snow;
    const float PreviousReferenceLuminance_Direct_Snow = ReferenceLuminance_Direct_Snow;
    const float PreviousReferenceLuminance_Diffuse_Snow = ReferenceLuminance_Diffuse_Snow;
    const float PreviousReferenceLuminance_DiffuseNoGI_Snow = ReferenceLuminance_DiffuseNoGI_Snow;
    const float PreviousReferenceLuminance_TotalNoGI_Snow = ReferenceLuminance_TotalNoGI_Snow;
    const float PreviousReferenceLuminance_SurfaceState_Snow = ReferenceLuminance_SurfaceState_Snow;

    auto RestorePreviousReferenceState = [&]()
    {
        ReferenceLuminance_Total = PreviousReferenceLuminance_Total;
        ReferenceLuminance_Direct = PreviousReferenceLuminance_Direct;
        ReferenceLuminance_Diffuse = PreviousReferenceLuminance_Diffuse;
        ReferenceLuminance_DiffuseNoGI = PreviousReferenceLuminance_DiffuseNoGI;
        ReferenceLuminance_TotalNoGI = PreviousReferenceLuminance_TotalNoGI;
        ReferenceLuminance_SurfaceState = PreviousReferenceLuminance_SurfaceState;
        ReferenceLuminance_Total_Ground = PreviousReferenceLuminance_Total_Ground;
        ReferenceLuminance_Direct_Ground = PreviousReferenceLuminance_Direct_Ground;
        ReferenceLuminance_Diffuse_Ground = PreviousReferenceLuminance_Diffuse_Ground;
        ReferenceLuminance_DiffuseNoGI_Ground = PreviousReferenceLuminance_DiffuseNoGI_Ground;
        ReferenceLuminance_TotalNoGI_Ground = PreviousReferenceLuminance_TotalNoGI_Ground;
        ReferenceLuminance_SurfaceState_Ground = PreviousReferenceLuminance_SurfaceState_Ground;
        ReferenceLuminance_Total_Snow = PreviousReferenceLuminance_Total_Snow;
        ReferenceLuminance_Direct_Snow = PreviousReferenceLuminance_Direct_Snow;
        ReferenceLuminance_Diffuse_Snow = PreviousReferenceLuminance_Diffuse_Snow;
        ReferenceLuminance_DiffuseNoGI_Snow = PreviousReferenceLuminance_DiffuseNoGI_Snow;
        ReferenceLuminance_TotalNoGI_Snow = PreviousReferenceLuminance_TotalNoGI_Snow;
        ReferenceLuminance_SurfaceState_Snow = PreviousReferenceLuminance_SurfaceState_Snow;
    };

    auto PreservePreviousReferenceIfPossible = [&](const TCHAR* Reason)
    {
        if (bHadValidReferenceState)
        {
            RestorePreviousReferenceState();
            bReferenceLuminanceValid = true;

            static int32 PreserveValidReferenceLogCount = 0;
            if (PreserveValidReferenceLogCount++ < 24)
            {
                UE_LOG(LogTemp, Warning, TEXT("[RefTile] %s Preserving previous valid reference state for this frame."), Reason);
            }
        }
        else
        {
            bReferenceLuminanceValid = false;
        }
    };

	if (!bFirstCallLogged)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RefTile] ===== FIRST CALL TO UpdateReferenceLuminance ====="));
		UE_LOG(LogTemp, Warning, TEXT("[RefTile]   bEnableRadiationCapture: %s"), bEnableRadiationCapture ? TEXT("TRUE") : TEXT("FALSE"));
		UE_LOG(LogTemp, Warning, TEXT("[RefTile]   bUseReferenceTile: %s"), bUseReferenceTile ? TEXT("TRUE") : TEXT("FALSE"));
		UE_LOG(LogTemp, Warning, TEXT("[RefTile]   bQueueNewReadback param: %s"), bQueueNewReadback ? TEXT("TRUE") : TEXT("FALSE"));
		bFirstCallLogged = true;
	}

	CallCounter++;

	if (!RTY_Total || !RTY_Direct)
	{
		static bool bLoggedOnce = false;
		if (!bLoggedOnce)
		{
			UE_LOG(LogTemp, Error, TEXT("[RefTile] ===== BLOCKED: Render targets not initialized ====="));
			UE_LOG(LogTemp, Error, TEXT("[RefTile]   RTY_Total: %s"), RTY_Total ? TEXT("Valid") : TEXT("NULL"));
			UE_LOG(LogTemp, Error, TEXT("[RefTile]   RTY_Direct: %s"), RTY_Direct ? TEXT("Valid") : TEXT("NULL"));
			UE_LOG(LogTemp, Error, TEXT("[RefTile]   This will prevent reference luminance from ever updating!"));
			UE_LOG(LogTemp, Error, TEXT("[RefTile] ================================================"));
			bLoggedOnce = true;
		}
		return;
	}

	FTextureRenderTargetResource* TotalResource = RTY_Total->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DirectResource = RTY_Direct->GameThread_GetRenderTargetResource();

	if (!TotalResource || !DirectResource)
	{
		static bool bLoggedOnce = false;
		if (!bLoggedOnce)
		{
			UE_LOG(LogTemp, Error, TEXT("[RefTile] ===== BLOCKED: Cannot acquire render target resources ====="));
			UE_LOG(LogTemp, Error, TEXT("[RefTile]   TotalResource: %s"), TotalResource ? TEXT("Valid") : TEXT("NULL"));
			UE_LOG(LogTemp, Error, TEXT("[RefTile]   DirectResource: %s"), DirectResource ? TEXT("Valid") : TEXT("NULL"));
			UE_LOG(LogTemp, Error, TEXT("[RefTile] ================================================="));
			bLoggedOnce = true;
		}
		return;
	}

	if (!bUseReferenceTile)
	{
		static bool bLoggedOnce = false;
		if (!bLoggedOnce)
		{
			UE_LOG(LogTemp, Display, TEXT("[RefTile] bUseReferenceTile=false, marking reference as valid immediately"));
			bLoggedOnce = true;
		}
		ReferenceLuminance_Total_Ground = 1.0f;
		ReferenceLuminance_Direct_Ground = 1.0f;
		ReferenceLuminance_Diffuse_Ground = 1.0f;
		ReferenceLuminance_DiffuseNoGI_Ground = 1.0f;
		ReferenceLuminance_TotalNoGI_Ground = 1.0f;
		ReferenceLuminance_Total_Snow = 1.0f;
		ReferenceLuminance_Direct_Snow = 1.0f;
		ReferenceLuminance_Diffuse_Snow = 1.0f;
		ReferenceLuminance_DiffuseNoGI_Snow = 1.0f;
		ReferenceLuminance_TotalNoGI_Snow = 1.0f;
		ReferenceLuminance_SurfaceState_Ground = 0.0f;
		ReferenceLuminance_SurfaceState_Snow = 0.0f;
		ReferenceLuminance_SurfaceState = 0.0f;
		ReferenceLuminance_Total = 1.0f;
		ReferenceLuminance_Direct = 1.0f;
		ReferenceLuminance_Diffuse = 1.0f;
		ReferenceLuminance_DiffuseNoGI = 1.0f;
		ReferenceLuminance_TotalNoGI = 1.0f;
		bReferenceLuminanceValid = true;
		return;
	}

	// If a readback was previously enqueued, check whether it has completed
	if (bReferenceReadbackPending && ReferenceTotalReadback && ReferenceDirectReadback)
	{
		const bool bUseDiffuseReadback = bReferenceDiffuseReadbackQueued && ReferenceDiffuseReadback;
		const bool bUseDiffuseNoGIReadback = bReferenceDiffuseNoGIReadbackQueued && ReferenceDiffuseNoGIReadback;
		const bool bUseTotalNoGIReadback = bReferenceTotalNoGIReadbackQueued && ReferenceTotalNoGIReadback;
		const bool bUseSurfaceStateReadback = bReferenceSurfaceStateReadbackQueued && ReferenceSurfaceStateReadback;
		bool bTotalReady = ReferenceTotalReadback->IsReady();
		bool bDirectReady = ReferenceDirectReadback->IsReady();
		bool bDiffuseReady = !bUseDiffuseReadback || ReferenceDiffuseReadback->IsReady();
		bool bDiffuseNoGIReady = !bUseDiffuseNoGIReadback || ReferenceDiffuseNoGIReadback->IsReady();
		bool bTotalNoGIReady = !bUseTotalNoGIReadback || ReferenceTotalNoGIReadback->IsReady();
		bool bSurfaceStateReady = !bUseSurfaceStateReadback || ReferenceSurfaceStateReadback->IsReady();

		if (bBlockUntilReady)
		{
			// Force flush to ensure commands are submitted to GPU
			FRenderCommandFence Fence;
			Fence.BeginFence();
			Fence.Wait();

			// Wait for GPU to finish (IsReady checks the GPU fence)
			int32 Retries = 0;
			const int32 MaxRetries = 500; // ~500ms timeout
			while ((!ReferenceTotalReadback->IsReady() || !ReferenceDirectReadback->IsReady() ||
					(bUseDiffuseReadback && !ReferenceDiffuseReadback->IsReady()) ||
					(bUseDiffuseNoGIReadback && !ReferenceDiffuseNoGIReadback->IsReady()) ||
					(bUseTotalNoGIReadback && !ReferenceTotalNoGIReadback->IsReady()) ||
					(bUseSurfaceStateReadback && !ReferenceSurfaceStateReadback->IsReady())) && Retries < MaxRetries)
			{
				FPlatformProcess::Sleep(0.001f);
				Retries++;
			}

			bTotalReady = ReferenceTotalReadback->IsReady();
			bDirectReady = ReferenceDirectReadback->IsReady();
			bDiffuseReady = !bUseDiffuseReadback || ReferenceDiffuseReadback->IsReady();
			bDiffuseNoGIReady = !bUseDiffuseNoGIReadback || ReferenceDiffuseNoGIReadback->IsReady();
			bTotalNoGIReady = !bUseTotalNoGIReadback || ReferenceTotalNoGIReadback->IsReady();
			bSurfaceStateReady = !bUseSurfaceStateReadback || ReferenceSurfaceStateReadback->IsReady();

			if (!bTotalReady || !bDirectReady || !bDiffuseReady || !bDiffuseNoGIReady || !bTotalNoGIReady || !bSurfaceStateReady)
			{
				UE_LOG(LogTemp, Warning, TEXT("[RefTile] Timed out waiting for GPU readback in blocking mode (Retries=%d)"), Retries);
			}
		}

		static int32 CheckCounter = 0;
		if (CheckCounter++ < 15)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefTile] [Call #%d] Checking readback status (check #%d): TotalReady=%s, DirectReady=%s, DiffuseReady=%s, DiffuseNoGIReady=%s, TotalNoGIReady=%s, SurfaceStateReady=%s, bReferenceLuminanceValid=%s"),
				CallCounter, CheckCounter,
				bTotalReady ? TEXT("TRUE") : TEXT("FALSE"),
				bDirectReady ? TEXT("TRUE") : TEXT("FALSE"),
				bDiffuseReady ? TEXT("TRUE") : TEXT("FALSE"),
				bDiffuseNoGIReady ? TEXT("TRUE") : TEXT("FALSE"),
				bTotalNoGIReady ? TEXT("TRUE") : TEXT("FALSE"),
				bSurfaceStateReady ? TEXT("TRUE") : TEXT("FALSE"),
				bReferenceLuminanceValid ? TEXT("TRUE") : TEXT("FALSE"));
		}

		if (bTotalReady && bDirectReady && bDiffuseReady && bDiffuseNoGIReady && bTotalNoGIReady && bSurfaceStateReady)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefTile] ===== READBACK COMPLETE - Processing data... ====="));
			int32 TotalRowPitch = 0;
			int32 TotalBufferHeight = 0;
			const FFloat16* TotalRow = static_cast<const FFloat16*>(ReferenceTotalReadback->Lock(TotalRowPitch, &TotalBufferHeight));

			int32 DirectRowPitch = 0;
			int32 DirectBufferHeight = 0;
			const FFloat16* DirectRow = static_cast<const FFloat16*>(ReferenceDirectReadback->Lock(DirectRowPitch, &DirectBufferHeight));

			int32 DiffuseRowPitch = 0;
			int32 DiffuseBufferHeight = 0;
			const FFloat16* DiffuseRow = bUseDiffuseReadback
				? static_cast<const FFloat16*>(ReferenceDiffuseReadback->Lock(DiffuseRowPitch, &DiffuseBufferHeight))
				: nullptr;
			int32 DiffuseNoGIRowPitch = 0;
			int32 DiffuseNoGIBufferHeight = 0;
			const FFloat16* DiffuseNoGIRow = bUseDiffuseNoGIReadback
				? static_cast<const FFloat16*>(ReferenceDiffuseNoGIReadback->Lock(DiffuseNoGIRowPitch, &DiffuseNoGIBufferHeight))
				: nullptr;
			int32 TotalNoGIRowPitch = 0;
			int32 TotalNoGIBufferHeight = 0;
			const FFloat16* TotalNoGIRow = bUseTotalNoGIReadback
				? static_cast<const FFloat16*>(ReferenceTotalNoGIReadback->Lock(TotalNoGIRowPitch, &TotalNoGIBufferHeight))
				: nullptr;
			int32 SurfaceStateRowPitch = 0;
			int32 SurfaceStateBufferHeight = 0;
			const FFloat16* SurfaceStateRow = bUseSurfaceStateReadback
				? static_cast<const FFloat16*>(ReferenceSurfaceStateReadback->Lock(SurfaceStateRowPitch, &SurfaceStateBufferHeight))
				: nullptr;

			UE_LOG(LogTemp, Warning, TEXT("[RefTile]   Lock results: TotalRow=%s, DirectRow=%s, DiffuseRow=%s, DiffuseNoGIRow=%s, TotalNoGIRow=%s, SurfaceStateRow=%s, ReferenceReadbackWidth=%d"),
				TotalRow ? TEXT("Valid") : TEXT("NULL"),
				DirectRow ? TEXT("Valid") : TEXT("NULL"),
				DiffuseRow ? TEXT("Valid") : TEXT("NULL"),
				DiffuseNoGIRow ? TEXT("Valid") : TEXT("NULL"),
				TotalNoGIRow ? TEXT("Valid") : TEXT("NULL"),
				SurfaceStateRow ? TEXT("Valid") : TEXT("NULL"),
				ReferenceReadbackWidth);
			UE_LOG(LogTemp, Warning, TEXT("[RefTile]   Buffer dimensions (row pitch in pixels): TotalRowPitch=%d, TotalBufferHeight=%d, DirectRowPitch=%d, DirectBufferHeight=%d, DiffuseRowPitch=%d, DiffuseBufferHeight=%d, DiffuseNoGIRowPitch=%d, DiffuseNoGIBufferHeight=%d, TotalNoGIRowPitch=%d, TotalNoGIBufferHeight=%d, SurfaceStateRowPitch=%d, SurfaceStateBufferHeight=%d"),
				TotalRowPitch, TotalBufferHeight, DirectRowPitch, DirectBufferHeight, DiffuseRowPitch, DiffuseBufferHeight, DiffuseNoGIRowPitch, DiffuseNoGIBufferHeight, TotalNoGIRowPitch, TotalNoGIBufferHeight, SurfaceStateRowPitch, SurfaceStateBufferHeight);

			// Keep previous sky-only reference values unless this update produces
			// fresh DiffuseNoGI samples. This avoids collapsing to zero on transient
			// readback misses and preserves terrain split stability.

			if (TotalRow && DirectRow && ReferenceReadbackWidth > 0)
			{
				int32 EffectiveWidth = FMath::Min3(ReferenceReadbackWidth, TotalRowPitch, DirectRowPitch);
				int32 EffectiveHeight = FMath::Min(TotalBufferHeight, DirectBufferHeight);
				if (DiffuseRow)
				{
					EffectiveWidth = FMath::Min(EffectiveWidth, DiffuseRowPitch);
					EffectiveHeight = FMath::Min(EffectiveHeight, DiffuseBufferHeight);
				}
				if (DiffuseNoGIRow)
				{
					EffectiveWidth = FMath::Min(EffectiveWidth, DiffuseNoGIRowPitch);
					EffectiveHeight = FMath::Min(EffectiveHeight, DiffuseNoGIBufferHeight);
				}
				if (TotalNoGIRow)
				{
					EffectiveWidth = FMath::Min(EffectiveWidth, TotalNoGIRowPitch);
					EffectiveHeight = FMath::Min(EffectiveHeight, TotalNoGIBufferHeight);
				}
				if (SurfaceStateRow)
				{
					EffectiveWidth = FMath::Min(EffectiveWidth, SurfaceStateRowPitch);
					EffectiveHeight = FMath::Min(EffectiveHeight, SurfaceStateBufferHeight);
				}

				CachedReferenceStripWidth = EffectiveWidth;
				CachedReferenceStripHeight = EffectiveHeight;
				const int32 CachedReferenceStripCount = EffectiveWidth * EffectiveHeight;
				CachedReferenceStripRTY_Total.SetNumUninitialized(CachedReferenceStripCount);
				CachedReferenceStripRTY_Direct.SetNumUninitialized(CachedReferenceStripCount);
				CachedReferenceStripRTY_Diffuse.SetNumUninitialized(CachedReferenceStripCount);
				CachedReferenceStripRTY_DiffuseNoGI.SetNumUninitialized(CachedReferenceStripCount);
				CachedReferenceStripRTY_TotalNoGI.SetNumUninitialized(CachedReferenceStripCount);

				float TotalSum = 0.0f;
				float DirectSum = 0.0f;
				float DiffuseSum = 0.0f;
				float DiffuseNoGISum = 0.0f;
				float TotalNoGISum = 0.0f;
				float SurfaceStateSum = 0.0f;
				int32 ValidSamples = 0;
				int32 DiffuseSamples = 0;
				int32 DiffuseNoGISamples = 0;
				int32 TotalNoGISamples = 0;
				int32 SurfaceStateSamples = 0;
					const bool bDualRef = bUseDualReferenceStrip;
					const int32 StripHeight = EffectiveHeight;
					const int32 StripStartY = 0;
					const int32 StripEndY = EffectiveHeight;
					const int32 SplitY = StripStartY + (StripHeight / 2);
					bool bTopRowsAreSnowHalf = true;
					if (bDualRef && Landscape && RadiationCapture)
					{
						const FVector CaptureUp = RadiationCapture->GetComponentRotation().RotateVector(FVector::UpVector).GetSafeNormal();
						const FVector LandscapeY = Landscape->GetActorRotation().RotateVector(FVector::RightVector).GetSafeNormal();
						// Top texture rows correspond to +CaptureUp. If +CaptureUp aligns with -LandscapeY,
						// then top rows map to more negative local Y (where the snow half is placed).
						bTopRowsAreSnowHalf = FVector::DotProduct(CaptureUp, -LandscapeY) >= 0.0f;

						static int32 DualRefOrientationLogCount = 0;
						if (DualRefOrientationLogCount++ < 5)
						{
							UE_LOG(LogTemp, Display, TEXT("[RefTile] DualRef orientation: Dot(CaptureUp,-LandscapeY)=%.4f -> TopRowsAreSnow=%d"),
								FVector::DotProduct(CaptureUp, -LandscapeY),
								bTopRowsAreSnowHalf ? 1 : 0);
						}
					}

				// Get current time context for diagnostics
				const int32 Hour = CurrentSimulationTime.GetHour();
				const int32 Minute = CurrentSimulationTime.GetMinute();
				const float TimeOfDay = Hour + Minute / 60.0f;
				const bool bIsNoonish = (TimeOfDay >= 11.0f && TimeOfDay <= 13.0f);
				const bool bIsDawn = (TimeOfDay >= 5.0f && TimeOfDay <= 7.0f);
				const bool bIsDusk = (TimeOfDay >= 17.0f && TimeOfDay <= 19.0f);
				const FString TimeContext = FString::Printf(TEXT("%02d:%02d (%.2fh)"), Hour, Minute, TimeOfDay);

				UE_LOG(LogTemp, Warning, TEXT("[RefTile]   Computing luminance from %d pixels at time: %s (top strip rows %d-%d)"),
					EffectiveWidth * StripHeight, *TimeContext, StripStartY, StripEndY - 1);
				float TotalSumGround = 0.0f;
				float DirectSumGround = 0.0f;
				float DiffuseSumGround = 0.0f;
				float DiffuseNoGISumGround = 0.0f;
				float TotalNoGISumGround = 0.0f;
				float SurfaceStateSumGround = 0.0f;
				float TotalSumSnow = 0.0f;
				float DirectSumSnow = 0.0f;
				float DiffuseSumSnow = 0.0f;
				float DiffuseNoGISumSnow = 0.0f;
				float TotalNoGISumSnow = 0.0f;
				float SurfaceStateSumSnow = 0.0f;
				int32 ValidSamplesGround = 0;
				int32 ValidSamplesSnow = 0;
				int32 DiffuseSamplesGround = 0;
				int32 DiffuseSamplesSnow = 0;
				int32 DiffuseNoGISamplesGround = 0;
				int32 DiffuseNoGISamplesSnow = 0;
				int32 TotalNoGISamplesGround = 0;
				int32 TotalNoGISamplesSnow = 0;
				int32 SurfaceStateSamplesGround = 0;
				int32 SurfaceStateSamplesSnow = 0;

				// Track min/max for diagnostics
				float TotalMin = FLT_MAX;
				float TotalMax = -FLT_MAX;
				float DirectMin = FLT_MAX;
				float DirectMax = -FLT_MAX;
				float DiffuseMin = FLT_MAX;
				float DiffuseMax = -FLT_MAX;

				// Equal tristimulus weights (not BT.709 photopic) — see RGBToLuminance.usf.
				auto ComputeRec709Luminance = [](const FFloat16Color& Color)
				{
					return (static_cast<float>(Color.R) +
						static_cast<float>(Color.G) +
						static_cast<float>(Color.B)) * (1.0f / 3.0f);
				};

				for (int32 Y = StripStartY; Y < StripEndY; ++Y)
				{
					// NOTE: The readback buffer contains ONLY the top-edge reference strip rows,
					// copied across the full texture width. We use the full width of that strip.
					
					const FFloat16* TotalRowPtr = reinterpret_cast<const FFloat16*>(reinterpret_cast<const uint8*>(TotalRow) + (Y * TotalRowPitch * static_cast<int32>(sizeof(FFloat16))));
					const FFloat16* DirectRowPtr = reinterpret_cast<const FFloat16*>(reinterpret_cast<const uint8*>(DirectRow) + (Y * DirectRowPitch * static_cast<int32>(sizeof(FFloat16))));
					const FFloat16* DiffuseRowPtr = DiffuseRow
						? reinterpret_cast<const FFloat16*>(reinterpret_cast<const uint8*>(DiffuseRow) + (Y * DiffuseRowPitch * static_cast<int32>(sizeof(FFloat16))))
						: nullptr;
					const FFloat16* DiffuseNoGIRowPtr = DiffuseNoGIRow
						? reinterpret_cast<const FFloat16*>(reinterpret_cast<const uint8*>(DiffuseNoGIRow) + (Y * DiffuseNoGIRowPitch * static_cast<int32>(sizeof(FFloat16))))
						: nullptr;
					const FFloat16* TotalNoGIRowPtr = TotalNoGIRow
						? reinterpret_cast<const FFloat16*>(reinterpret_cast<const uint8*>(TotalNoGIRow) + (Y * TotalNoGIRowPitch * static_cast<int32>(sizeof(FFloat16))))
						: nullptr;
					const FFloat16* SurfaceStateRowPtr = SurfaceStateRow
						? reinterpret_cast<const FFloat16*>(reinterpret_cast<const uint8*>(SurfaceStateRow) + (Y * SurfaceStateRowPitch * static_cast<int32>(sizeof(FFloat16))))
						: nullptr;

					for (int32 X = 0; X < EffectiveWidth; ++X)
					{
						const float TotalLum = static_cast<float>(TotalRowPtr[X]);
						const float DirectLum = static_cast<float>(DirectRowPtr[X]);
						const float DiffuseLumCached = DiffuseRowPtr ? static_cast<float>(DiffuseRowPtr[X]) : std::numeric_limits<float>::quiet_NaN();
						const float DiffuseNoGILumCached = DiffuseNoGIRowPtr ? static_cast<float>(DiffuseNoGIRowPtr[X]) : std::numeric_limits<float>::quiet_NaN();
						const float TotalNoGILumCached = TotalNoGIRowPtr ? static_cast<float>(TotalNoGIRowPtr[X]) : std::numeric_limits<float>::quiet_NaN();
						const int32 StripLinearIndex = (Y - StripStartY) * EffectiveWidth + X;
						CachedReferenceStripRTY_Total[StripLinearIndex] = TotalLum;
						CachedReferenceStripRTY_Direct[StripLinearIndex] = DirectLum;
						CachedReferenceStripRTY_Diffuse[StripLinearIndex] = DiffuseLumCached;
						CachedReferenceStripRTY_DiffuseNoGI[StripLinearIndex] = DiffuseNoGILumCached;
						CachedReferenceStripRTY_TotalNoGI[StripLinearIndex] = TotalNoGILumCached;
							const bool bSnowHalf = bDualRef
								? (bTopRowsAreSnowHalf ? (Y < SplitY) : (Y >= SplitY))
								: false;

						if (FMath::IsFinite(TotalLum) && TotalLum >= 0.0f &&
							FMath::IsFinite(DirectLum) && DirectLum >= 0.0f)
						{
							TotalSum += TotalLum;
							DirectSum += DirectLum;
							TotalMin = FMath::Min(TotalMin, TotalLum);
							TotalMax = FMath::Max(TotalMax, TotalLum);
							DirectMin = FMath::Min(DirectMin, DirectLum);
							DirectMax = FMath::Max(DirectMax, DirectLum);
							++ValidSamples;

							if (bDualRef)
							{
								if (bSnowHalf)
								{
									TotalSumSnow += TotalLum;
									DirectSumSnow += DirectLum;
									++ValidSamplesSnow;
								}
								else
								{
									TotalSumGround += TotalLum;
									DirectSumGround += DirectLum;
									++ValidSamplesGround;
								}
							}
						}

						if (DiffuseRowPtr)
						{
							const float DiffuseLum = DiffuseLumCached;
							if (FMath::IsFinite(DiffuseLum) && DiffuseLum >= 0.0f)
							{
								DiffuseSum += DiffuseLum;
								DiffuseMin = FMath::Min(DiffuseMin, DiffuseLum);
								DiffuseMax = FMath::Max(DiffuseMax, DiffuseLum);
								++DiffuseSamples;

								if (bDualRef)
								{
									if (bSnowHalf)
									{
										DiffuseSumSnow += DiffuseLum;
										++DiffuseSamplesSnow;
									}
									else
									{
										DiffuseSumGround += DiffuseLum;
										++DiffuseSamplesGround;
									}
								}
							}
						}
						if (DiffuseNoGIRowPtr)
						{
							const float DiffuseNoGILum = DiffuseNoGILumCached;
							if (FMath::IsFinite(DiffuseNoGILum) && DiffuseNoGILum >= 0.0f)
							{
								DiffuseNoGISum += DiffuseNoGILum;
								++DiffuseNoGISamples;

								if (bDualRef)
								{
									if (bSnowHalf)
									{
										DiffuseNoGISumSnow += DiffuseNoGILum;
										++DiffuseNoGISamplesSnow;
									}
									else
									{
										DiffuseNoGISumGround += DiffuseNoGILum;
										++DiffuseNoGISamplesGround;
									}
								}
							}
						}
						if (TotalNoGIRowPtr)
						{
							const float TotalNoGILum = TotalNoGILumCached;
							if (FMath::IsFinite(TotalNoGILum) && TotalNoGILum >= 0.0f)
							{
								TotalNoGISum += TotalNoGILum;
								++TotalNoGISamples;

								if (bDualRef)
								{
									if (bSnowHalf)
									{
										TotalNoGISumSnow += TotalNoGILum;
										++TotalNoGISamplesSnow;
									}
									else
									{
										TotalNoGISumGround += TotalNoGILum;
										++TotalNoGISamplesGround;
									}
								}
							}
						}
						if (SurfaceStateRowPtr)
						{
							const float SurfaceStateValue = static_cast<float>(SurfaceStateRowPtr[X]);
							if (FMath::IsFinite(SurfaceStateValue) && SurfaceStateValue >= 0.0f)
							{
								SurfaceStateSum += SurfaceStateValue;
								++SurfaceStateSamples;

								if (bDualRef)
								{
									if (bSnowHalf)
									{
										SurfaceStateSumSnow += SurfaceStateValue;
										++SurfaceStateSamplesSnow;
									}
									else
									{
										SurfaceStateSumGround += SurfaceStateValue;
										++SurfaceStateSamplesGround;
									}
								}
							}
						}
					}
				}

				if (ValidSamples > 0)
				{
					const float InvSamples = 1.0f / static_cast<float>(ValidSamples);
					const float TotalMean = TotalSum * InvSamples;
					const float DirectMean = DirectSum * InvSamples;
					const float InvDiffuseSamples = DiffuseSamples > 0
						? 1.0f / static_cast<float>(DiffuseSamples)
						: 0.0f;
					const float DiffuseMean = DiffuseSamples > 0
						? (DiffuseSum * InvDiffuseSamples)
						: 0.0f;
					const float InvDiffuseNoGISamples = DiffuseNoGISamples > 0
						? 1.0f / static_cast<float>(DiffuseNoGISamples)
						: 0.0f;
					const float DiffuseNoGIMean = DiffuseNoGISamples > 0
						? (DiffuseNoGISum * InvDiffuseNoGISamples)
						: 0.0f;
					const float InvTotalNoGISamples = TotalNoGISamples > 0
						? 1.0f / static_cast<float>(TotalNoGISamples)
						: 0.0f;
					const float TotalNoGIMean = TotalNoGISamples > 0
						? (TotalNoGISum * InvTotalNoGISamples)
						: 0.0f;
					const float InvSurfaceStateSamples = SurfaceStateSamples > 0
						? 1.0f / static_cast<float>(SurfaceStateSamples)
						: 0.0f;
					const float SurfaceStateMean = SurfaceStateSamples > 0
						? (SurfaceStateSum * InvSurfaceStateSamples)
						: 0.0f;
					const float SunVisibility = ReferenceReadbackSunVisibility;
					const float MaskedTotalMean = TotalMean; // Do NOT mask total luminance by sun visibility, as it includes diffuse sky
					const float MaskedDirectMean = DirectMean * SunVisibility; // Mask direct by visibility (if sun is blocked, direct is 0)
					const float ReferenceVisibilityThreshold = FMath::Max(GetSunVisibilityThresholdCos() * 0.5f, 1e-3f);
					const bool bSunVisible = SunVisibility > ReferenceVisibilityThreshold;
					if (bSunVisible && MaskedDirectMean > (MaskedTotalMean + 1.0e-3f))
					{
						static int32 DirectExceedsTotalLogCount = 0;
						if (DirectExceedsTotalLogCount++ < 48)
						{
							UE_LOG(LogTemp, Error, TEXT("[RefTile] Direct strip mean exceeds Total strip mean at %s: Direct=%.6f Total=%.6f (raw Direct=%.6f raw Total=%.6f, SunVisibility=%.4f, DirectAtmosphereRequested=%d, DirectAtmosphereMatched=%d, NonDirectAtmosphere=%d). This will collapse the strip diffuse residual."),
								*TimeContext,
								MaskedDirectMean,
								MaskedTotalMean,
								DirectMean,
								TotalMean,
								SunVisibility,
								bDirectCaptureIncludesAtmosphere ? 1 : 0,
								bMatchDirectPassAtmosphereToReferenceCalibration ? 1 : 0,
								bNonDirectCapturesIncludeAtmosphere ? 1 : 0);
						}
					}

					// Compute standard deviation for quality assessment
					float TotalSumSqDiff = 0.0f;
					float DirectSumSqDiff = 0.0f;
					float DiffuseSumSqDiff = 0.0f;
					for (int32 Y = StripStartY; Y < StripEndY; ++Y)
					{
						const FFloat16* TotalRowPtr = reinterpret_cast<const FFloat16*>(reinterpret_cast<const uint8*>(TotalRow) + (Y * TotalRowPitch * static_cast<int32>(sizeof(FFloat16))));
						const FFloat16* DirectRowPtr = reinterpret_cast<const FFloat16*>(reinterpret_cast<const uint8*>(DirectRow) + (Y * DirectRowPitch * static_cast<int32>(sizeof(FFloat16))));
						const FFloat16* DiffuseRowPtr = DiffuseRow
							? reinterpret_cast<const FFloat16*>(reinterpret_cast<const uint8*>(DiffuseRow) + (Y * DiffuseRowPitch * static_cast<int32>(sizeof(FFloat16))))
							: nullptr;

						for (int32 X = 0; X < EffectiveWidth; ++X)
						{
							const float TotalLum = static_cast<float>(TotalRowPtr[X]);
							const float DirectLum = static_cast<float>(DirectRowPtr[X]);
							if (FMath::IsFinite(TotalLum) && TotalLum >= 0.0f)
							{
								const float Diff = TotalLum - TotalMean;
								TotalSumSqDiff += Diff * Diff;
							}
							if (FMath::IsFinite(DirectLum) && DirectLum >= 0.0f)
							{
								const float Diff = DirectLum - DirectMean;
								DirectSumSqDiff += Diff * Diff;
							}
							if (DiffuseRowPtr)
							{
								const float DiffuseLum = static_cast<float>(DiffuseRowPtr[X]);
								if (FMath::IsFinite(DiffuseLum) && DiffuseLum >= 0.0f)
								{
									const float Diff = DiffuseLum - DiffuseMean;
									DiffuseSumSqDiff += Diff * Diff;
								}
							}
						}
					}
					const float TotalStdDev = FMath::Sqrt(TotalSumSqDiff * InvSamples);
					const float DirectStdDev = FMath::Sqrt(DirectSumSqDiff * InvSamples);
					const float DiffuseStdDev = DiffuseSamples > 0
						? FMath::Sqrt(DiffuseSumSqDiff * InvDiffuseSamples)
						: 0.0f;

					// Apply Direct Masking based on Visibility
					// If Sun is effectively invisible (visibility < threshold), force Direct to 0.
					// Total remains as is (capturing Diffuse/Sky).
					if (bSunVisible)
					{
						ReferenceLuminance_Total = FMath::Max(MaskedTotalMean, KINDA_SMALL_NUMBER); // KINDA_SMALL_NUMBER usually 1e-4
						ReferenceLuminance_Direct = FMath::Max(MaskedDirectMean, 0.0f);
					}
					else
					{
						ReferenceLuminance_Total = FMath::Max(MaskedTotalMean, KINDA_SMALL_NUMBER); // Keep Total (Diffuse) even if Sun is blocked
						ReferenceLuminance_Direct = 0.0f; // Force Direct to 0
					}
					if (DiffuseSamples > 0 && FMath::IsFinite(DiffuseMean))
					{
						ReferenceLuminance_Diffuse = FMath::Max(DiffuseMean, 0.0f);
					}
					else
					{
						ReferenceLuminance_Diffuse = FMath::Max(MaskedTotalMean - MaskedDirectMean, 0.0f);
						DiffuseMin = 0.0f;
						DiffuseMax = 0.0f;
					}
					if (DiffuseNoGISamples > 0 && FMath::IsFinite(DiffuseNoGIMean))
					{
						ReferenceLuminance_DiffuseNoGI = FMath::Max(DiffuseNoGIMean, 0.0f);
					}
					else
					{
						// Fallback: keep previous valid sky-only reference if available,
						// otherwise initialize from diffuse reference to stay physically bounded.
						const float PreviousNoGI = ReferenceLuminance_DiffuseNoGI;
						const float SafeNoGI = (FMath::IsFinite(PreviousNoGI) && PreviousNoGI > 0.0f)
							? PreviousNoGI
							: ReferenceLuminance_Diffuse;
						ReferenceLuminance_DiffuseNoGI = FMath::Max(SafeNoGI, 0.0f);
					}
					if (SurfaceStateSamples > 0 && FMath::IsFinite(SurfaceStateMean))
					{
						ReferenceLuminance_SurfaceState = FMath::Max(SurfaceStateMean, 0.0f);
					}
					else
					{
						ReferenceLuminance_SurfaceState = 0.0f;
					}

					// Physical consistency guard: the TOTAL reference cannot be lower than DIRECT.
					// Clamp to avoid negative residuals and invalid scaling.
					if (ReferenceLuminance_Direct > ReferenceLuminance_Total)
					{
						UE_LOG(LogTemp, Warning, TEXT("[RefTile] Consistency clamp applied: Total %.6f < Direct %.6f, forcing Total=Direct"),
							ReferenceLuminance_Total, ReferenceLuminance_Direct);
						ReferenceLuminance_Total = ReferenceLuminance_Direct;
					}
					ReferenceLuminance_Diffuse = FMath::Max(ReferenceLuminance_Diffuse, ReferenceLuminance_Total - ReferenceLuminance_Direct);
					ReferenceLuminance_DiffuseNoGI = FMath::Clamp(ReferenceLuminance_DiffuseNoGI, 0.0f, ReferenceLuminance_Total);
					if (TotalNoGISamples > 0 && FMath::IsFinite(TotalNoGIMean))
					{
						ReferenceLuminance_TotalNoGI = FMath::Clamp(TotalNoGIMean, ReferenceLuminance_Direct, ReferenceLuminance_Total);
					}
					else
					{
						ReferenceLuminance_TotalNoGI = FMath::Clamp(
							ReferenceLuminance_Direct + ReferenceLuminance_DiffuseNoGI,
							ReferenceLuminance_Direct,
							ReferenceLuminance_Total);
					}

					if (bDualRef)
					{
						const float InvSamplesGround = ValidSamplesGround > 0
							? 1.0f / static_cast<float>(ValidSamplesGround)
							: 0.0f;
						const float InvSamplesSnow = ValidSamplesSnow > 0
							? 1.0f / static_cast<float>(ValidSamplesSnow)
							: 0.0f;

						const float TotalMeanGround = TotalSumGround * InvSamplesGround;
						const float DirectMeanGround = DirectSumGround * InvSamplesGround;
						const float TotalMeanSnow = TotalSumSnow * InvSamplesSnow;
						const float DirectMeanSnow = DirectSumSnow * InvSamplesSnow;

						const float DiffuseMeanGround = DiffuseSamplesGround > 0
							? (DiffuseSumGround / static_cast<float>(DiffuseSamplesGround))
							: 0.0f;
						const float DiffuseMeanSnow = DiffuseSamplesSnow > 0
							? (DiffuseSumSnow / static_cast<float>(DiffuseSamplesSnow))
							: 0.0f;
						const float DiffuseNoGIMeanGround = DiffuseNoGISamplesGround > 0
							? (DiffuseNoGISumGround / static_cast<float>(DiffuseNoGISamplesGround))
							: 0.0f;
						const float DiffuseNoGIMeanSnow = DiffuseNoGISamplesSnow > 0
							? (DiffuseNoGISumSnow / static_cast<float>(DiffuseNoGISamplesSnow))
							: 0.0f;
						const float TotalNoGIMeanGround = TotalNoGISamplesGround > 0
							? (TotalNoGISumGround / static_cast<float>(TotalNoGISamplesGround))
							: 0.0f;
						const float TotalNoGIMeanSnow = TotalNoGISamplesSnow > 0
							? (TotalNoGISumSnow / static_cast<float>(TotalNoGISamplesSnow))
							: 0.0f;
						const float SurfaceStateMeanGround = SurfaceStateSamplesGround > 0
							? (SurfaceStateSumGround / static_cast<float>(SurfaceStateSamplesGround))
							: 0.0f;
						const float SurfaceStateMeanSnow = SurfaceStateSamplesSnow > 0
							? (SurfaceStateSumSnow / static_cast<float>(SurfaceStateSamplesSnow))
							: 0.0f;

						auto ApplyHalf = [&](bool bSnowHalf)
						{
							const float TotalMeanHalf = bSnowHalf ? TotalMeanSnow : TotalMeanGround;
							const float DirectMeanHalf = bSnowHalf ? DirectMeanSnow : DirectMeanGround;
							const float DiffuseMeanHalf = bSnowHalf ? DiffuseMeanSnow : DiffuseMeanGround;
							const float DiffuseNoGIMeanHalf = bSnowHalf ? DiffuseNoGIMeanSnow : DiffuseNoGIMeanGround;
							const float TotalNoGIMeanHalf = bSnowHalf ? TotalNoGIMeanSnow : TotalNoGIMeanGround;
							const bool bHasSamples = bSnowHalf ? (ValidSamplesSnow > 0) : (ValidSamplesGround > 0);
							const float MaskedTotalHalf = bHasSamples ? TotalMeanHalf : TotalMean;
							const float MaskedDirectHalf = (bHasSamples ? DirectMeanHalf : DirectMean) * SunVisibility;

							float& RefTotal = bSnowHalf ? ReferenceLuminance_Total_Snow : ReferenceLuminance_Total_Ground;
							float& RefDirect = bSnowHalf ? ReferenceLuminance_Direct_Snow : ReferenceLuminance_Direct_Ground;
							float& RefDiffuse = bSnowHalf ? ReferenceLuminance_Diffuse_Snow : ReferenceLuminance_Diffuse_Ground;
							float& RefDiffuseNoGI = bSnowHalf ? ReferenceLuminance_DiffuseNoGI_Snow : ReferenceLuminance_DiffuseNoGI_Ground;
							float& RefTotalNoGI = bSnowHalf ? ReferenceLuminance_TotalNoGI_Snow : ReferenceLuminance_TotalNoGI_Ground;
							float& RefSurfaceState = bSnowHalf ? ReferenceLuminance_SurfaceState_Snow : ReferenceLuminance_SurfaceState_Ground;

							if (bSunVisible)
							{
								RefTotal = FMath::Max(MaskedTotalHalf, KINDA_SMALL_NUMBER);
								RefDirect = FMath::Max(MaskedDirectHalf, 0.0f);
							}
							else
							{
								RefTotal = FMath::Max(MaskedTotalHalf, KINDA_SMALL_NUMBER);
								RefDirect = 0.0f;
							}

							if (bHasSamples && (bSnowHalf ? DiffuseSamplesSnow : DiffuseSamplesGround) > 0 && FMath::IsFinite(DiffuseMeanHalf))
							{
								RefDiffuse = FMath::Max(DiffuseMeanHalf, 0.0f);
							}
							else
							{
								RefDiffuse = FMath::Max(MaskedTotalHalf - MaskedDirectHalf, 0.0f);
							}

							if (RefDirect > RefTotal)
							{
								RefTotal = RefDirect;
							}
							RefDiffuse = FMath::Max(RefDiffuse, RefTotal - RefDirect);
							if ((bSnowHalf ? DiffuseNoGISamplesSnow : DiffuseNoGISamplesGround) > 0 && FMath::IsFinite(DiffuseNoGIMeanHalf))
							{
								RefDiffuseNoGI = FMath::Clamp(DiffuseNoGIMeanHalf, 0.0f, RefTotal);
							}
							else
							{
								const float PreviousHalfNoGI = RefDiffuseNoGI;
								const float SafeHalfNoGI = (FMath::IsFinite(PreviousHalfNoGI) && PreviousHalfNoGI > 0.0f)
									? PreviousHalfNoGI
									: RefDiffuse;
								RefDiffuseNoGI = FMath::Clamp(SafeHalfNoGI, 0.0f, RefTotal);
							}
							if ((bSnowHalf ? TotalNoGISamplesSnow : TotalNoGISamplesGround) > 0 && FMath::IsFinite(TotalNoGIMeanHalf))
							{
								RefTotalNoGI = FMath::Clamp(TotalNoGIMeanHalf, RefDirect, RefTotal);
							}
							else
							{
								RefTotalNoGI = FMath::Clamp(RefDirect + RefDiffuseNoGI, RefDirect, RefTotal);
							}

							const float SurfaceStateMeanHalf = bSnowHalf ? SurfaceStateMeanSnow : SurfaceStateMeanGround;
							const bool bHasSurfaceStateSamples = bSnowHalf ? (SurfaceStateSamplesSnow > 0) : (SurfaceStateSamplesGround > 0);
							RefSurfaceState = (bHasSurfaceStateSamples && FMath::IsFinite(SurfaceStateMeanHalf))
								? FMath::Max(SurfaceStateMeanHalf, 0.0f)
								: ReferenceLuminance_SurfaceState;
						};

						ApplyHalf(false);
						ApplyHalf(true);

						UE_LOG(LogTemp, Display, TEXT("[RefTile] Dual reference means (Ground/Snow) at %s: Total=%.4f/%.4f, Direct=%.4f/%.4f, Diffuse=%.4f/%.4f"),
							*TimeContext,
							ReferenceLuminance_Total_Ground, ReferenceLuminance_Total_Snow,
							ReferenceLuminance_Direct_Ground, ReferenceLuminance_Direct_Snow,
							ReferenceLuminance_Diffuse_Ground, ReferenceLuminance_Diffuse_Snow);
					}
					else
					{
						ReferenceLuminance_Total_Ground = ReferenceLuminance_Total;
						ReferenceLuminance_Direct_Ground = ReferenceLuminance_Direct;
						ReferenceLuminance_Diffuse_Ground = ReferenceLuminance_Diffuse;
						ReferenceLuminance_DiffuseNoGI_Ground = ReferenceLuminance_DiffuseNoGI;
						ReferenceLuminance_TotalNoGI_Ground = ReferenceLuminance_TotalNoGI;
						ReferenceLuminance_Total_Snow = ReferenceLuminance_Total;
						ReferenceLuminance_Direct_Snow = ReferenceLuminance_Direct;
						ReferenceLuminance_Diffuse_Snow = ReferenceLuminance_Diffuse;
						ReferenceLuminance_DiffuseNoGI_Snow = ReferenceLuminance_DiffuseNoGI;
						ReferenceLuminance_TotalNoGI_Snow = ReferenceLuminance_TotalNoGI;
						ReferenceLuminance_SurfaceState_Ground = ReferenceLuminance_SurfaceState;
						ReferenceLuminance_SurfaceState_Snow = ReferenceLuminance_SurfaceState;
					}
					// FIX: Accept both day and night as valid states after successful readback
					// Nighttime with zero luminance is physically correct and should not block simulation
					bReferenceLuminanceValid = true;

					// Enhanced logging with time context and statistics
					UE_LOG(LogTemp, Warning, TEXT("[RefTile] ===== Updated reference luminance at %s ====="), *TimeContext);
					UE_LOG(LogTemp, Warning, TEXT("[RefTile]   Total:  mean=%.4f (raw %.4f), min=%.4f, max=%.4f, stddev=%.4f"),
						ReferenceLuminance_Total, TotalMean, TotalMin, TotalMax, TotalStdDev);
					UE_LOG(LogTemp, Warning, TEXT("[RefTile]   Direct: mean=%.4f (raw %.4f), min=%.4f, max=%.4f, stddev=%.4f"),
						ReferenceLuminance_Direct, DirectMean, DirectMin, DirectMax, DirectStdDev);
					UE_LOG(LogTemp, Warning, TEXT("[RefTile]   Diffuse: mean=%.4f (raw %.4f), min=%.4f, max=%.4f, stddev=%.4f"),
						ReferenceLuminance_Diffuse, DiffuseMean, DiffuseMin, DiffuseMax, DiffuseStdDev);
					UE_LOG(LogTemp, Warning, TEXT("[RefTile]   SunVisibility=%.4f (threshold=%.4f) -> Valid=%s"),
						SunVisibility, ReferenceVisibilityThreshold, bReferenceLuminanceValid ? TEXT("TRUE") : TEXT("FALSE"));
					UE_LOG(LogTemp, Warning, TEXT("[RefTile]   Samples: total/direct=%d / %d valid, diffuse=%d / %d, diffuseNoGI=%d / %d"),
						ValidSamples, EffectiveWidth * EffectiveHeight, DiffuseSamples, EffectiveWidth * EffectiveHeight, DiffuseNoGISamples, EffectiveWidth * EffectiveHeight);
					if (bCaptureDiffuseNoGIForTerrain && DiffuseNoGISamples == 0)
					{
						static int32 NoGISampleMissLogCount = 0;
						if (NoGISampleMissLogCount++ < 24)
						{
							UE_LOG(LogTemp, Warning, TEXT("[RefTile] DiffuseNoGI reference samples missing; keeping previous/fallback NoGI reference for this frame."));
						}
					}
					if (DiffuseSamples > 0)
					{
						static int32 DiffuseCompareCount = 0;
						if (DiffuseCompareCount++ < 30)
						{
							const float DerivedDiffuse = FMath::Max(TotalMean - DirectMean, 0.0f);
							const float DiffuseDelta = DiffuseMean - DerivedDiffuse;
							UE_LOG(LogTemp, Display, TEXT("[RefTile] Diffuse strip check at %s: RTY_Diffuse=%.4f, Total-Direct=%.4f, Delta=%.4f"),
								*TimeContext, DiffuseMean, DerivedDiffuse, DiffuseDelta);
						}
					}

					if (bDebugRadiationCapture)
					{
						static int32 StripCheckCount = 0;
						if (StripCheckCount < 5)
						{
							auto LogStripCheck = [&](UTextureRenderTarget2D* Target, const TCHAR* Label)
							{
								if (!Target)
								{
									return;
								}

								FTextureRenderTargetResource* TargetResource = Target->GameThread_GetRenderTargetResource();
								if (!TargetResource)
								{
									return;
								}

								TArray<FLinearColor> PixelData;
								FReadSurfaceDataFlags ReadFlags(RCM_MinMax);
								ReadFlags.SetLinearToGamma(false);
								if (!ReadRenderTargetLinearPixels(Target, TargetResource, PixelData, ReadFlags))
								{
									UE_LOG(LogTemp, Display, TEXT("[RefTile] Strip check %s: render-target readback failed"), Label);
									return;
								}

								const int32 Width = Target->SizeX;
								const int32 Height = Target->SizeY;
								if (PixelData.Num() != Width * Height)
								{
									UE_LOG(LogTemp, Display, TEXT("[RefTile] Strip check %s: size mismatch %d vs %d"),
										Label, PixelData.Num(), Width * Height);
									return;
								}

								const int32 StripH = FMath::Clamp(ReferenceStripHeight, 1, Height);
								const int32 StripW = FMath::Clamp(ReferenceStripHeight, 1, Width);

								auto ComputeMeanRegion = [&](int32 X0, int32 Y0, int32 X1, int32 Y1) -> float
								{
									double Sum = 0.0;
									int32 Count = 0;
									for (int32 Y = Y0; Y < Y1; ++Y)
									{
										const int32 RowOffset = Y * Width;
										for (int32 X = X0; X < X1; ++X)
										{
											const float Lum = ComputeRec709LuminanceLinear(PixelData[RowOffset + X]);
											if (FMath::IsFinite(Lum))
											{
												Sum += Lum;
												++Count;
											}
										}
									}
									return Count > 0 ? static_cast<float>(Sum / Count) : 0.0f;
								};

								const float BottomMean = ComputeMeanRegion(0, Height - StripH, Width, Height);
								const float LeftMean = ComputeMeanRegion(0, 0, StripW, Height);
								const float TopMean = ComputeMeanRegion(0, 0, Width, StripH);
								const float RightMean = ComputeMeanRegion(Width - StripW, 0, Width, Height);

								UE_LOG(LogTemp, Display, TEXT("[RefTile] Strip check %s: bottom=%.4f left=%.4f top=%.4f right=%.4f (strip=%dx%d)"),
									Label, BottomMean, LeftMean, TopMean, RightMean, StripW, StripH);
							};

							UE_LOG(LogTemp, Display, TEXT("[RefTile] Strip check: sampling full RT for orientation (debug only)"));
							LogStripCheck(RT_Total, TEXT("RT_Total"));
							LogStripCheck(RT_Direct, TEXT("RT_Direct"));
							++StripCheckCount;
						}
					}

					// Shadow detection: warn if suspiciously low at noon
					if (bIsNoonish && ReferenceLuminance_Total < 0.1f)
					{
						UE_LOG(LogTemp, Error, TEXT("[RefTile] !!!!! SHADOW DETECTED AT NOON !!!!!"));
						UE_LOG(LogTemp, Error, TEXT("[RefTile] Reference patch appears shadowed at %s"), *TimeContext);
						UE_LOG(LogTemp, Error, TEXT("[RefTile] Total luminance %.4f is suspiciously low for midday sun"), ReferenceLuminance_Total);
						UE_LOG(LogTemp, Error, TEXT("[RefTile] This will cause INVERSE radiation correlation!"));
						UE_LOG(LogTemp, Error, TEXT("[RefTile] Fix: Ensure the reference strip is on flat, unoccluded terrain"));
					}
					else if (bIsNoonish && ReferenceLuminance_Total < 0.5f)
					{
						UE_LOG(LogTemp, Warning, TEXT("[RefTile] CAUTION: Low midday reference luminance %.4f at %s"),
							ReferenceLuminance_Total, *TimeContext);
						UE_LOG(LogTemp, Warning, TEXT("[RefTile] May indicate partial shadowing or low-quality GI"));
					}

					// Also warn if dawn/dusk values are higher than noon (inverse correlation)
					static float LastNoonValue = -1.0f;
					static float LastNoonTime = -1.0f;
					if (bIsNoonish)
					{
						LastNoonValue = ReferenceLuminance_Total;
						LastNoonTime = TimeOfDay;
					}
					else if ((bIsDawn || bIsDusk) && LastNoonValue > 0.0f && ReferenceLuminance_Total > LastNoonValue * 1.5f)
					{
						UE_LOG(LogTemp, Error, TEXT("[RefTile] !!!!! INVERSE CORRELATION DETECTED !!!!!"));
						UE_LOG(LogTemp, Error, TEXT("[RefTile] Dawn/dusk luminance %.4f at %s exceeds noon value %.4f (at %.2fh) by %.1fx"),
							ReferenceLuminance_Total, *TimeContext, LastNoonValue, LastNoonTime,
							ReferenceLuminance_Total / LastNoonValue);
						UE_LOG(LogTemp, Error, TEXT("[RefTile] This indicates reference patch is shadowed during midday"));
					}

					if (ReferenceLuminance_Total <= KINDA_SMALL_NUMBER)
					{
						UE_LOG(LogTemp, Warning, TEXT("[RefTile] Warning: reference total luminance %.6f is near zero at %s; results may be noisy."),
							TotalMean, *TimeContext);
					}
				}
				else
				{
                    PreservePreviousReferenceIfPossible(TEXT("[RefTile] Reference readback contained no valid samples."));
                    if (!bReferenceLuminanceValid)
                    {
                        UE_LOG(LogTemp, Warning, TEXT("[RefTile] Reference readback contained no valid samples"));
                    }
				}
			}
			else
			{
                PreservePreviousReferenceIfPossible(TEXT("[RefTile] Failed to process readback data."));
				UE_LOG(LogTemp, Error, TEXT("[RefTile] ===== FAILED TO PROCESS READBACK DATA ====="));
				UE_LOG(LogTemp, Error, TEXT("[RefTile]   Reason: TotalRow=%s, DirectRow=%s, SurfaceStateRow=%s, ReferenceReadbackWidth=%d"),
					TotalRow ? TEXT("Valid") : TEXT("NULL"),
					DirectRow ? TEXT("Valid") : TEXT("NULL"),
					SurfaceStateRow ? TEXT("Valid") : TEXT("NULL"),
					ReferenceReadbackWidth);
				UE_LOG(LogTemp, Error, TEXT("[RefTile]   This will cause UE radiation to remain unavailable!"));
				UE_LOG(LogTemp, Error, TEXT("[RefTile] ======================================="));
			}

			if (TotalRow)
			{
				ReferenceTotalReadback->Unlock();
			}
			if (DirectRow)
			{
				ReferenceDirectReadback->Unlock();
			}
			if (DiffuseRow)
			{
				ReferenceDiffuseReadback->Unlock();
			}
			if (DiffuseNoGIRow)
			{
				ReferenceDiffuseNoGIReadback->Unlock();
			}
			if (TotalNoGIRow)
			{
				ReferenceTotalNoGIReadback->Unlock();
			}
			if (SurfaceStateRow)
			{
				ReferenceSurfaceStateReadback->Unlock();
			}
			bReferenceReadbackPending = false;
			bReferenceDiffuseReadbackQueued = false;
			bReferenceDiffuseNoGIReadbackQueued = false;
			bReferenceTotalNoGIReadbackQueued = false;
			bReferenceSurfaceStateReadbackQueued = false;

			UE_LOG(LogTemp, Display, TEXT("[RefTile] Readback processing complete. bReferenceLuminanceValid=%s"),
				bReferenceLuminanceValid ? TEXT("TRUE") : TEXT("FALSE"));

			// Track reference luminance history for periodic summary
			struct FRefLuminanceHistoryEntry
			{
				float TimeOfDay;
				float TotalLuminance;
				float DirectLuminance;
				FString TimeString;
			};
			static TArray<FRefLuminanceHistoryEntry> History;
			static int32 LastSummaryHour = -1;

			if (bReferenceLuminanceValid)
			{
				const int32 Hour = CurrentSimulationTime.GetHour();
				const int32 Minute = CurrentSimulationTime.GetMinute();
				const float TimeOfDay = Hour + Minute / 60.0f;

				FRefLuminanceHistoryEntry Entry;
				Entry.TimeOfDay = TimeOfDay;
				Entry.TotalLuminance = ReferenceLuminance_Total;
				Entry.DirectLuminance = ReferenceLuminance_Direct;
				Entry.TimeString = FString::Printf(TEXT("%02d:%02d"), Hour, Minute);
				History.Add(Entry);

				// Keep only last 100 entries
				if (History.Num() > 100)
				{
					History.RemoveAt(0, History.Num() - 100);
				}

				// Log periodic summary every hour
				if (Hour != LastSummaryHour && History.Num() > 5)
				{
					LastSummaryHour = Hour;

					UE_LOG(LogTemp, Display, TEXT("[RefTile] ========== HOURLY REFERENCE LUMINANCE SUMMARY =========="));
					UE_LOG(LogTemp, Display, TEXT("[RefTile] History entries: %d"), History.Num());

					// Find min/max/mean across history
					float HistoryTotalMin = FLT_MAX;
					float HistoryTotalMax = -FLT_MAX;
					float HistoryTotalSum = 0.0f;
					int32 NoonCount = 0;
					float NoonSum = 0.0f;
					int32 DawnDuskCount = 0;
					float DawnDuskSum = 0.0f;

					for (const FRefLuminanceHistoryEntry& HistEntry : History)
					{
						HistoryTotalMin = FMath::Min(HistoryTotalMin, HistEntry.TotalLuminance);
						HistoryTotalMax = FMath::Max(HistoryTotalMax, HistEntry.TotalLuminance);
						HistoryTotalSum += HistEntry.TotalLuminance;

						if (HistEntry.TimeOfDay >= 11.0f && HistEntry.TimeOfDay <= 13.0f)
						{
							NoonSum += HistEntry.TotalLuminance;
							NoonCount++;
						}
						else if ((HistEntry.TimeOfDay >= 5.0f && HistEntry.TimeOfDay <= 7.0f) ||
						         (HistEntry.TimeOfDay >= 17.0f && HistEntry.TimeOfDay <= 19.0f))
						{
							DawnDuskSum += HistEntry.TotalLuminance;
							DawnDuskCount++;
						}
					}

					const float HistoryTotalMean = HistoryTotalSum / History.Num();
					const float NoonMean = NoonCount > 0 ? NoonSum / NoonCount : 0.0f;
					const float DawnDuskMean = DawnDuskCount > 0 ? DawnDuskSum / DawnDuskCount : 0.0f;

					UE_LOG(LogTemp, Display, TEXT("[RefTile] Overall: min=%.4f, max=%.4f, mean=%.4f"),
						HistoryTotalMin, HistoryTotalMax, HistoryTotalMean);
					UE_LOG(LogTemp, Display, TEXT("[RefTile] Noon avg (11-13h): %.4f (%d samples)"), NoonMean, NoonCount);
					UE_LOG(LogTemp, Display, TEXT("[RefTile] Dawn/Dusk avg: %.4f (%d samples)"), DawnDuskMean, DawnDuskCount);

					if (NoonCount > 0 && DawnDuskCount > 0 && DawnDuskMean > NoonMean * 1.2f)
					{
						UE_LOG(LogTemp, Error, TEXT("[RefTile] !!!!! HISTORICAL INVERSE CORRELATION DETECTED !!!!!"));
						UE_LOG(LogTemp, Error, TEXT("[RefTile] Dawn/Dusk mean (%.4f) exceeds Noon mean (%.4f) by %.1fx"),
							DawnDuskMean, NoonMean, DawnDuskMean / NoonMean);
						UE_LOG(LogTemp, Error, TEXT("[RefTile] This confirms reference patch is shadowed at midday!"));
					}

					// Show last few entries
					UE_LOG(LogTemp, Display, TEXT("[RefTile] Recent values:"));
					const int32 ShowCount = FMath::Min(10, History.Num());
					for (int32 i = History.Num() - ShowCount; i < History.Num(); ++i)
					{
						const FRefLuminanceHistoryEntry& HistEntry = History[i];
						UE_LOG(LogTemp, Display, TEXT("[RefTile]   %s (%.2fh): Total=%.4f, Direct=%.4f"),
							*HistEntry.TimeString, HistEntry.TimeOfDay,
							HistEntry.TotalLuminance, HistEntry.DirectLuminance);
					}
					UE_LOG(LogTemp, Display, TEXT("[RefTile] ========================================================"));
				}
			}
		}
		else
		{
			// Still waiting on GPU readback; skip queuing a new one if requested
			static int32 WaitCounter = 0;
			if (WaitCounter++ % 100 == 0)
			{
				UE_LOG(LogTemp, Log, TEXT("[RefTile] Still waiting for reference readback to complete (waited %d frames)"), WaitCounter);
			}

			if (!bQueueNewReadback)
			{
				return;
			}

			// Avoid scheduling another readback until current one completes
			return;
		}
	}

	if (bReferenceReadbackPending || !bQueueNewReadback)
	{
		static bool bLoggedSkip = false;
		if (!bLoggedSkip && bReferenceReadbackPending)
		{
			UE_LOG(LogTemp, Log, TEXT("[RefTile] Skipping new readback - already pending"));
			bLoggedSkip = true;
		}
		return;
	}

	if (!ReferenceTotalReadback)
	{
		ReferenceTotalReadback = new FRHIGPUTextureReadback(TEXT("RadReferenceTotalReadback"));
		UE_LOG(LogTemp, Display, TEXT("[RefTile] Created ReferenceTotalReadback GPU readback object"));
	}

	if (!ReferenceDirectReadback)
	{
		ReferenceDirectReadback = new FRHIGPUTextureReadback(TEXT("RadReferenceDirectReadback"));
		UE_LOG(LogTemp, Display, TEXT("[RefTile] Created ReferenceDirectReadback GPU readback object"));
	}

	const FTextureRHIRef TotalRHI = TotalResource->TextureRHI;
	const FTextureRHIRef DirectRHI = DirectResource->TextureRHI;
	FTextureRenderTargetResource* DiffuseResource = RTY_Diffuse ? RTY_Diffuse->GameThread_GetRenderTargetResource() : nullptr;
	const FTextureRHIRef DiffuseRHI = DiffuseResource ? DiffuseResource->TextureRHI : nullptr;
	FTextureRenderTargetResource* DiffuseNoGIResource = RTY_DiffuseNoGI ? RTY_DiffuseNoGI->GameThread_GetRenderTargetResource() : nullptr;
	const FTextureRHIRef DiffuseNoGIRHI = DiffuseNoGIResource ? DiffuseNoGIResource->TextureRHI : nullptr;
	FTextureRenderTargetResource* TotalNoGIResource = RTY_TotalNoGI ? RTY_TotalNoGI->GameThread_GetRenderTargetResource() : nullptr;
	const FTextureRHIRef TotalNoGIRHI = TotalNoGIResource ? TotalNoGIResource->TextureRHI : nullptr;
	FTextureRenderTargetResource* SurfaceStateResource = RTY_SurfaceState ? RTY_SurfaceState->GameThread_GetRenderTargetResource() : nullptr;
	const FTextureRHIRef SurfaceStateRHI = SurfaceStateResource ? SurfaceStateResource->TextureRHI : nullptr;

	if (!TotalRHI.IsValid() || !DirectRHI.IsValid())
	{
		UE_LOG(LogTemp, Error, TEXT("[RefTile] ===== BLOCKED: Texture RHI invalid ====="));
		UE_LOG(LogTemp, Error, TEXT("[RefTile]   TotalRHI.IsValid(): %s"), TotalRHI.IsValid() ? TEXT("TRUE") : TEXT("FALSE"));
		UE_LOG(LogTemp, Error, TEXT("[RefTile]   DirectRHI.IsValid(): %s"), DirectRHI.IsValid() ? TEXT("TRUE") : TEXT("FALSE"));
		UE_LOG(LogTemp, Error, TEXT("[RefTile]   Cannot enqueue GPU readback!"));
		UE_LOG(LogTemp, Error, TEXT("[RefTile] ================================="));
		return;
	}

	bool bQueueDiffuse = DiffuseRHI.IsValid();
	if (bQueueDiffuse && !ReferenceDiffuseReadback)
	{
		ReferenceDiffuseReadback = new FRHIGPUTextureReadback(TEXT("RadReferenceDiffuseReadback"));
		UE_LOG(LogTemp, Display, TEXT("[RefTile] Created ReferenceDiffuseReadback GPU readback object"));
	}
	bQueueDiffuse = bQueueDiffuse && ReferenceDiffuseReadback != nullptr;
	if (!bQueueDiffuse)
	{
		static bool bLoggedDiffuseMissing = false;
		if (!bLoggedDiffuseMissing)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RefTile] RTY_Diffuse not available; diffuse reference will fall back to Total-Direct"));
			bLoggedDiffuseMissing = true;
		}
	}

	bool bQueueDiffuseNoGI = bCaptureDiffuseNoGIForTerrain && DiffuseNoGIRHI.IsValid();
	if (bQueueDiffuseNoGI && !ReferenceDiffuseNoGIReadback)
	{
		ReferenceDiffuseNoGIReadback = new FRHIGPUTextureReadback(TEXT("RadReferenceDiffuseNoGIReadback"));
		UE_LOG(LogTemp, Display, TEXT("[RefTile] Created ReferenceDiffuseNoGIReadback GPU readback object"));
	}
	bQueueDiffuseNoGI = bQueueDiffuseNoGI && ReferenceDiffuseNoGIReadback != nullptr;

	bool bQueueTotalNoGI = bCaptureDiffuseNoGIForTerrain && TotalNoGIRHI.IsValid();
	if (bQueueTotalNoGI && !ReferenceTotalNoGIReadback)
	{
		ReferenceTotalNoGIReadback = new FRHIGPUTextureReadback(TEXT("RadReferenceTotalNoGIReadback"));
		UE_LOG(LogTemp, Display, TEXT("[RefTile] Created ReferenceTotalNoGIReadback GPU readback object"));
	}
	bQueueTotalNoGI = bQueueTotalNoGI && ReferenceTotalNoGIReadback != nullptr;

	bool bQueueSurfaceState = bUseDualReferenceStrip && SurfaceStateRHI.IsValid();
	if (bQueueSurfaceState && !ReferenceSurfaceStateReadback)
	{
		ReferenceSurfaceStateReadback = new FRHIGPUTextureReadback(TEXT("RadReferenceSurfaceStateReadback"));
		UE_LOG(LogTemp, Display, TEXT("[RefTile] Created ReferenceSurfaceStateReadback GPU readback object"));
	}
	bQueueSurfaceState = bQueueSurfaceState && ReferenceSurfaceStateReadback != nullptr;

	const int32 Width = RTY_Total->SizeX;
	const int32 Height = RTY_Total->SizeY;
	const int32 StripHeight = FMath::Clamp(ReferenceStripHeight, 1, Height);

	ENQUEUE_RENDER_COMMAND(QueueReferenceLuminanceReadback)(
		[this, TotalRHI, DirectRHI, DiffuseRHI, DiffuseNoGIRHI, TotalNoGIRHI, SurfaceStateRHI, Width, StripHeight, bQueueDiffuse, bQueueDiffuseNoGI, bQueueTotalNoGI, bQueueSurfaceState,
		 TotalReadback = ReferenceTotalReadback,
		 DirectReadback = ReferenceDirectReadback,
		 DiffuseReadback = ReferenceDiffuseReadback,
		 DiffuseNoGIReadback = ReferenceDiffuseNoGIReadback,
		 TotalNoGIReadback = ReferenceTotalNoGIReadback,
		 SurfaceStateReadback = ReferenceSurfaceStateReadback](FRHICommandListImmediate& RHICmdList)
		{
			FRDGBuilder GraphBuilder(RHICmdList);

			FRDGTextureRef RDG_Total = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TotalRHI, TEXT("RadRefTotal")));
			FRDGTextureRef RDG_Direct = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DirectRHI, TEXT("RadRefDirect")));
			FRDGTextureRef RDG_Diffuse = nullptr;
			FRDGTextureRef RDG_DiffuseNoGI = nullptr;
			FRDGTextureRef RDG_TotalNoGI = nullptr;
			FRDGTextureRef RDG_SurfaceState = nullptr;
			if (bQueueDiffuse && DiffuseRHI.IsValid())
			{
				RDG_Diffuse = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseRHI, TEXT("RadRefDiffuse")));
			}
			if (bQueueDiffuseNoGI && DiffuseNoGIRHI.IsValid())
			{
				RDG_DiffuseNoGI = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseNoGIRHI, TEXT("RadRefDiffuseNoGI")));
			}
			if (bQueueTotalNoGI && TotalNoGIRHI.IsValid())
			{
				RDG_TotalNoGI = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TotalNoGIRHI, TEXT("RadRefTotalNoGI")));
			}
			if (bQueueSurfaceState && SurfaceStateRHI.IsValid())
			{
				RDG_SurfaceState = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(SurfaceStateRHI, TEXT("RadRefSurfaceState")));
			}

			const FResolveRect StripRect(0, 0, Width, StripHeight);
			AddEnqueueCopyPass(GraphBuilder, TotalReadback, RDG_Total, StripRect);
			AddEnqueueCopyPass(GraphBuilder, DirectReadback, RDG_Direct, StripRect);
			if (bQueueDiffuse && DiffuseReadback && RDG_Diffuse)
			{
				AddEnqueueCopyPass(GraphBuilder, DiffuseReadback, RDG_Diffuse, StripRect);
			}
			if (bQueueDiffuseNoGI && DiffuseNoGIReadback && RDG_DiffuseNoGI)
			{
				AddEnqueueCopyPass(GraphBuilder, DiffuseNoGIReadback, RDG_DiffuseNoGI, StripRect);
			}
			if (bQueueTotalNoGI && TotalNoGIReadback && RDG_TotalNoGI)
			{
				AddEnqueueCopyPass(GraphBuilder, TotalNoGIReadback, RDG_TotalNoGI, StripRect);
			}
			if (bQueueSurfaceState && SurfaceStateReadback && RDG_SurfaceState)
			{
				AddEnqueueCopyPass(GraphBuilder, SurfaceStateReadback, RDG_SurfaceState, StripRect);
			}

			GraphBuilder.Execute();
		});

	bReferenceReadbackPending = true;
	bReferenceDiffuseReadbackQueued = bQueueDiffuse;
	bReferenceDiffuseNoGIReadbackQueued = bQueueDiffuseNoGI;
	bReferenceTotalNoGIReadbackQueued = bQueueTotalNoGI;
	bReferenceSurfaceStateReadbackQueued = bQueueSurfaceState;
	ReferenceReadbackWidth = Width;
	ReferenceReadbackSunVisibility = CachedSunVisibility;

	static int32 QueueCounter = 0;
	QueueCounter++;
	if (QueueCounter <= 5)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RefTile] ===== QUEUED reference readback #%d ====="), QueueCounter);
		UE_LOG(LogTemp, Warning, TEXT("[RefTile]   Reading reference tile rows: y=0..%d, width=%d pixels"),
			StripHeight - 1, Width);
		UE_LOG(LogTemp, Warning, TEXT("[RefTile]   Will be ready in 2-5 frames (GPU readback latency)"));
		UE_LOG(LogTemp, Warning, TEXT("[RefTile] ========================================"));
	}
}



void ASnowSimulationActor::ConvertRGBToLuminance()
{
	const bool bDiffuseCaptureActive = bUseDiffuseCaptureThisFrame && RT_Diffuse && RTY_Diffuse;
	const bool bDiffuseNoGICaptureActive = bUseDiffuseNoGICaptureThisFrame && RT_DiffuseNoGI && RTY_DiffuseNoGI && RTY_TotalNoGI;
	if (!RT_Total || !RT_Direct || !RTY_Total || !RTY_Direct)
	{
		UE_LOG(LogTemp, Warning, TEXT("[Luminance] Cannot convert: render targets not initialized"));
		return;
	}

	FTextureRenderTargetResource* TotalResource = RT_Total->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DirectResource = RT_Direct->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DiffuseResource = bDiffuseCaptureActive ? RT_Diffuse->GameThread_GetRenderTargetResource() : nullptr;
	FTextureRenderTargetResource* DiffuseNoGIResource = bDiffuseNoGICaptureActive ? RT_DiffuseNoGI->GameThread_GetRenderTargetResource() : nullptr;
	FTextureRenderTargetResource* TotalYResource = RTY_Total->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DirectYResource = RTY_Direct->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DiffuseYResource = bDiffuseCaptureActive ? RTY_Diffuse->GameThread_GetRenderTargetResource() : nullptr;
	FTextureRenderTargetResource* DiffuseNoGIYResource = bDiffuseNoGICaptureActive ? RTY_DiffuseNoGI->GameThread_GetRenderTargetResource() : nullptr;
	FTextureRenderTargetResource* TotalNoGIYResource = bDiffuseNoGICaptureActive ? RTY_TotalNoGI->GameThread_GetRenderTargetResource() : nullptr;

	if (!TotalResource || !DirectResource || !TotalYResource || !DirectYResource)
	{
		UE_LOG(LogTemp, Warning, TEXT("[Luminance] Render target resources not ready"));
		return;
	}
	if (bDiffuseCaptureActive && (!DiffuseResource || !DiffuseYResource))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Luminance] Diffuse capture enabled but resources not ready"));
	}
	if (bDiffuseNoGICaptureActive && (!DiffuseNoGIResource || !DiffuseNoGIYResource || !TotalNoGIYResource))
	{
		UE_LOG(LogTemp, Warning, TEXT("[Luminance] DiffuseNoGI capture enabled but resources not ready"));
	}

	const int32 RTWidth = RT_Total->SizeX;
	const int32 RTHeight = RT_Total->SizeY;

	const FTextureRHIRef TotalRHI = TotalResource->TextureRHI;
	const FTextureRHIRef DirectRHI = DirectResource->TextureRHI;
	const FTextureRHIRef DiffuseRHI = DiffuseResource ? DiffuseResource->TextureRHI : nullptr;
	const FTextureRHIRef DiffuseNoGIRHI = DiffuseNoGIResource ? DiffuseNoGIResource->TextureRHI : nullptr;
	const FTextureRHIRef TotalYRHI = TotalYResource->TextureRHI;
	const FTextureRHIRef DirectYRHI = DirectYResource->TextureRHI;
	const FTextureRHIRef DiffuseYRHI = DiffuseYResource ? DiffuseYResource->TextureRHI : nullptr;
	const FTextureRHIRef DiffuseNoGIYRHI = DiffuseNoGIYResource ? DiffuseNoGIYResource->TextureRHI : nullptr;
	const FTextureRHIRef TotalNoGIYRHI = TotalNoGIYResource ? TotalNoGIYResource->TextureRHI : nullptr;

	if (!TotalRHI.IsValid() || !DirectRHI.IsValid() || !TotalYRHI.IsValid() || !DirectYRHI.IsValid())
	{
		UE_LOG(LogTemp, Warning, TEXT("[Luminance] Invalid texture handles for conversion"));
		return;
	}
	const bool bDiffuseRHIValid = bDiffuseCaptureActive && DiffuseRHI.IsValid() && DiffuseYRHI.IsValid();
	const bool bDiffuseNoGIRHIValid = bDiffuseNoGICaptureActive
		&& DiffuseNoGIRHI.IsValid()
		&& DiffuseNoGIYRHI.IsValid()
		&& TotalNoGIYRHI.IsValid();

	ENQUEUE_RENDER_COMMAND(ConvertRGBToLuminanceCommand)(
		[TotalRHI, DirectRHI, DiffuseRHI, DiffuseNoGIRHI, TotalYRHI, DirectYRHI, DiffuseYRHI, DiffuseNoGIYRHI, TotalNoGIYRHI, bDiffuseRHIValid, bDiffuseNoGIRHIValid, RTWidth, RTHeight](FRHICommandListImmediate& RHICmdList)
		{
			FRDGBuilder GraphBuilder(RHICmdList);

			const FIntVector GroupCount((RTWidth + 7) / 8, (RTHeight + 7) / 8, 1);

			FRDGTextureRef RDG_Total = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TotalRHI, TEXT("Rad_RT_Total")));
			FRDGTextureRef RDG_Direct = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DirectRHI, TEXT("Rad_RT_Direct")));
			FRDGTextureRef RDG_TotalY = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TotalYRHI, TEXT("Rad_RTY_Total")));
			FRDGTextureRef RDG_DirectY = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DirectYRHI, TEXT("Rad_RTY_Direct")));
			FRDGTextureRef RDG_Diffuse = nullptr;
			FRDGTextureRef RDG_DiffuseY = nullptr;
			FRDGTextureRef RDG_DiffuseNoGI = nullptr;
			FRDGTextureRef RDG_DiffuseNoGIY = nullptr;
			FRDGTextureRef RDG_TotalNoGIY = nullptr;
			if (bDiffuseRHIValid)
			{
				RDG_Diffuse = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseRHI, TEXT("Rad_RT_Diffuse")));
				RDG_DiffuseY = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseYRHI, TEXT("Rad_RTY_Diffuse")));
			}
			if (bDiffuseNoGIRHIValid)
			{
				RDG_DiffuseNoGI = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseNoGIRHI, TEXT("Rad_RT_DiffuseNoGI")));
				RDG_DiffuseNoGIY = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseNoGIYRHI, TEXT("Rad_RTY_DiffuseNoGI")));
				RDG_TotalNoGIY = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TotalNoGIYRHI, TEXT("Rad_RTY_TotalNoGI")));
			}

			auto DispatchConversion = [&](FRDGTextureRef Input, FRDGTextureRef Output, const TCHAR* EventName)
			{
				TShaderMapRef<FRGBToLuminanceCS> Shader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
				FRGBToLuminanceCS::FParameters* Params = GraphBuilder.AllocParameters<FRGBToLuminanceCS::FParameters>();
				Params->TextureDimensions = FUintVector2(RTWidth, RTHeight);
				Params->InputTexture = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(Input));
				Params->OutputTexture = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(Output));

				FComputeShaderUtils::AddPass(
					GraphBuilder,
					RDG_EVENT_NAME("%s", EventName),
					Shader,
					Params,
					GroupCount);
			};

			DispatchConversion(RDG_Total, RDG_TotalY, TEXT("RGBToLuminance_Total"));
			DispatchConversion(RDG_Direct, RDG_DirectY, TEXT("RGBToLuminance_Direct"));
			if (bDiffuseRHIValid)
			{
				DispatchConversion(RDG_Diffuse, RDG_DiffuseY, TEXT("RGBToLuminance_Diffuse"));
			}
			if (bDiffuseNoGIRHIValid)
			{
				DispatchConversion(RDG_DiffuseNoGI, RDG_TotalNoGIY, TEXT("RGBToLuminance_TotalNoGI"));

				TShaderMapRef<FComputeDiffuseCS> ResidualShader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
				FComputeDiffuseCS::FParameters* ResidualParams = GraphBuilder.AllocParameters<FComputeDiffuseCS::FParameters>();
				ResidualParams->TextureDimensions = FUintVector2(RTWidth, RTHeight);
				ResidualParams->bEnableBlur = 0u;
				ResidualParams->CosSolarZenith = 1.0f;
				ResidualParams->RTY_Total = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_TotalNoGIY));
				ResidualParams->RTY_Direct = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_DirectY));
				ResidualParams->RTY_Diffuse = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_DiffuseNoGIY));
				ResidualParams->RTY_DiffuseTemp = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_DiffuseNoGIY));

				FComputeShaderUtils::AddPass(
					GraphBuilder,
					RDG_EVENT_NAME("ComputeSkyOnlyNoGI"),
					ResidualShader,
					ResidualParams,
					GroupCount);
			}

			GraphBuilder.Execute();
		});
}

void ASnowSimulationActor::ConvertSurfaceStateToLuminance()
{
	if (!RT_SurfaceState || !RTY_SurfaceState)
	{
		return;
	}

	FTextureRenderTargetResource* SurfaceStateResource = RT_SurfaceState->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* SurfaceStateYResource = RTY_SurfaceState->GameThread_GetRenderTargetResource();
	if (!SurfaceStateResource || !SurfaceStateYResource)
	{
		UE_LOG(LogTemp, Warning, TEXT("[SurfaceState] Cannot convert: render target resources not ready"));
		return;
	}

	const FTextureRHIRef SurfaceStateRHI = SurfaceStateResource->TextureRHI;
	const FTextureRHIRef SurfaceStateYRHI = SurfaceStateYResource->TextureRHI;
	if (!SurfaceStateRHI.IsValid() || !SurfaceStateYRHI.IsValid())
	{
		UE_LOG(LogTemp, Warning, TEXT("[SurfaceState] Cannot convert: invalid texture handles"));
		return;
	}

	const int32 RTWidth = RT_SurfaceState->SizeX;
	const int32 RTHeight = RT_SurfaceState->SizeY;
	ENQUEUE_RENDER_COMMAND(ConvertSurfaceStateToLuminanceCommand)(
		[SurfaceStateRHI, SurfaceStateYRHI, RTWidth, RTHeight](FRHICommandListImmediate& RHICmdList)
		{
			FRDGBuilder GraphBuilder(RHICmdList);
			const FIntVector GroupCount((RTWidth + 7) / 8, (RTHeight + 7) / 8, 1);

			FRDGTextureRef RDG_SurfaceState = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(SurfaceStateRHI, TEXT("Rad_RT_SurfaceState")));
			FRDGTextureRef RDG_SurfaceStateY = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(SurfaceStateYRHI, TEXT("Rad_RTY_SurfaceState")));

			TShaderMapRef<FRGBToLuminanceCS> Shader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
			FRGBToLuminanceCS::FParameters* Params = GraphBuilder.AllocParameters<FRGBToLuminanceCS::FParameters>();
			Params->TextureDimensions = FUintVector2(RTWidth, RTHeight);
			Params->InputTexture = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_SurfaceState));
			Params->OutputTexture = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_SurfaceStateY));

			FComputeShaderUtils::AddPass(
				GraphBuilder,
				RDG_EVENT_NAME("RGBToLuminance_SurfaceState"),
				Shader,
				Params,
				GroupCount);

			GraphBuilder.Execute();
		});
}

void ASnowSimulationActor::ComputeDiffuseIrradiance()
{
	const bool bUseCapturedDiffuse = bUseDiffuseCaptureThisFrame && RT_Diffuse;
	if (bUseCapturedDiffuse)
	{
		if (!RTY_Diffuse)
		{
			UE_LOG(LogTemp, Warning, TEXT("[Diffuse] Diffuse capture enabled but RTY_Diffuse is not initialized"));
			return;
		}

		if (!bBlurDiffuse)
		{
			return;
		}

		// Ensure temp buffer exists if blur is enabled
		if (!RTY_DiffuseTemp)
		{
			const int32 RTWidth = RTY_Diffuse->SizeX;
			const int32 RTHeight = RTY_Diffuse->SizeY;

			RTY_DiffuseTemp = NewObject<UTextureRenderTarget2D>(this, TEXT("RTY_DiffuseTemp"));
			RTY_DiffuseTemp->RenderTargetFormat = RTF_R16f;
			RTY_DiffuseTemp->InitAutoFormat(RTWidth, RTHeight);
			RTY_DiffuseTemp->UpdateResourceImmediate(true);

			UE_LOG(LogTemp, Display, TEXT("[Diffuse] Created temp buffer for blur: %dx%d"), RTWidth, RTHeight);
		}

		FTextureRenderTargetResource* DiffuseResource = RTY_Diffuse->GameThread_GetRenderTargetResource();
		FTextureRenderTargetResource* DiffuseTempResource = RTY_DiffuseTemp
			? RTY_DiffuseTemp->GameThread_GetRenderTargetResource()
			: nullptr;

		if (!DiffuseResource || !DiffuseTempResource)
		{
			UE_LOG(LogTemp, Warning, TEXT("[Diffuse] Blur skipped: diffuse resources not ready"));
			return;
		}

		const int32 RTWidth = RTY_Diffuse->SizeX;
		const int32 RTHeight = RTY_Diffuse->SizeY;
		const FTextureRHIRef DiffuseRHI = DiffuseResource->TextureRHI;
		const FTextureRHIRef DiffuseTempRHI = DiffuseTempResource->TextureRHI;

		if (!DiffuseRHI.IsValid() || !DiffuseTempRHI.IsValid())
		{
			UE_LOG(LogTemp, Warning, TEXT("[Diffuse] Blur skipped: invalid texture handles"));
			return;
		}

		ENQUEUE_RENDER_COMMAND(BlurCapturedDiffuseCommand)(
			[DiffuseRHI, DiffuseTempRHI, RTWidth, RTHeight](FRHICommandListImmediate& RHICmdList)
			{
				FRDGBuilder GraphBuilder(RHICmdList);

				FRDGTextureRef RDG_Diffuse = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseRHI, TEXT("Rad_RTY_Diffuse")));
				FRDGTextureRef RDG_DiffuseTemp = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseTempRHI, TEXT("Rad_RTY_DiffuseTemp")));

				AddCopyTexturePass(GraphBuilder, RDG_Diffuse, RDG_DiffuseTemp);

				TShaderMapRef<FBlurDiffuseCS> BlurShader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
				FBlurDiffuseCS::FParameters* BlurParams = GraphBuilder.AllocParameters<FBlurDiffuseCS::FParameters>();
				BlurParams->TextureDimensions = FUintVector2(RTWidth, RTHeight);
				BlurParams->RTY_DiffuseTemp = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_DiffuseTemp));
				BlurParams->RTY_Diffuse = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_Diffuse));

				const FIntVector GroupCount((RTWidth + 7) / 8, (RTHeight + 7) / 8, 1);
				FComputeShaderUtils::AddPass(
					GraphBuilder,
					RDG_EVENT_NAME("BlurCapturedDiffuse"),
					BlurShader,
					BlurParams,
					GroupCount);

				GraphBuilder.Execute();
			});
		return;
	}

	if (!RTY_Total || !RTY_Direct || !RTY_Diffuse)
	{
		UE_LOG(LogTemp, Warning, TEXT("[Diffuse] Cannot compute: luminance RTs not initialized"));
		return;
	}

	// Ensure temp buffer exists if blur is enabled
	if (bBlurDiffuse && !RTY_DiffuseTemp)
	{
		const int32 RTWidth = RTY_Total->SizeX;
		const int32 RTHeight = RTY_Total->SizeY;

		RTY_DiffuseTemp = NewObject<UTextureRenderTarget2D>(this, TEXT("RTY_DiffuseTemp"));
		RTY_DiffuseTemp->RenderTargetFormat = RTF_R16f;
		RTY_DiffuseTemp->InitAutoFormat(RTWidth, RTHeight);
		RTY_DiffuseTemp->UpdateResourceImmediate(true);

		UE_LOG(LogTemp, Display, TEXT("[Diffuse] Created temp buffer for blur: %dx%d"), RTWidth, RTHeight);
	}

	FTextureRenderTargetResource* TotalResource = RTY_Total->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DirectResource = RTY_Direct->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DiffuseResource = RTY_Diffuse->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DiffuseTempResource = bBlurDiffuse && RTY_DiffuseTemp
		? RTY_DiffuseTemp->GameThread_GetRenderTargetResource()
		: nullptr;

	if (!TotalResource || !DirectResource || !DiffuseResource)
	{
		UE_LOG(LogTemp, Warning, TEXT("[Diffuse] Render target resources not ready"));
		return;
	}

	const int32 RTWidth = RTY_Total->SizeX;
	const int32 RTHeight = RTY_Total->SizeY;

	const FTextureRHIRef TotalRHI = TotalResource->TextureRHI;
	const FTextureRHIRef DirectRHI = DirectResource->TextureRHI;
	const FTextureRHIRef DiffuseRHI = DiffuseResource->TextureRHI;
	const FTextureRHIRef DiffuseTempRHI = (bBlurDiffuse && DiffuseTempResource) ? DiffuseTempResource->TextureRHI : DiffuseRHI;

	if (!TotalRHI.IsValid() || !DirectRHI.IsValid() || !DiffuseRHI.IsValid() || !DiffuseTempRHI.IsValid())
	{
		UE_LOG(LogTemp, Warning, TEXT("[Diffuse] Invalid texture handles for diffuse computation"));
		return;
	}

	// Updated before the final capture (defaults to day-time for initialization)
	float CosSolarZenith = 1.0f;

	const bool bLocalBlur = bBlurDiffuse && DiffuseTempResource != nullptr;

	ENQUEUE_RENDER_COMMAND(ComputeDiffuseIrradianceCommand)(
		[TotalRHI, DirectRHI, DiffuseRHI, DiffuseTempRHI, RTWidth, RTHeight, CosSolarZenith, bLocalBlur](FRHICommandListImmediate& RHICmdList)
		{
			FRDGBuilder GraphBuilder(RHICmdList);

			const FIntVector GroupCount((RTWidth + 7) / 8, (RTHeight + 7) / 8, 1);

			FRDGTextureRef RDG_Total = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TotalRHI, TEXT("Rad_RTY_Total")));
			FRDGTextureRef RDG_Direct = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DirectRHI, TEXT("Rad_RTY_Direct")));
			FRDGTextureRef RDG_Diffuse = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseRHI, TEXT("Rad_RTY_Diffuse")));
			FRDGTextureRef RDG_DiffuseTemp = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseTempRHI, TEXT("Rad_RTY_DiffuseTemp")));

			// Pass 1: compute diffuse component
			{
				TShaderMapRef<FComputeDiffuseCS> Shader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
				FComputeDiffuseCS::FParameters* Params = GraphBuilder.AllocParameters<FComputeDiffuseCS::FParameters>();
				Params->TextureDimensions = FUintVector2(RTWidth, RTHeight);
				Params->bEnableBlur = bLocalBlur ? 1u : 0u;
				Params->CosSolarZenith = CosSolarZenith;
				Params->RTY_Total = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_Total));
				Params->RTY_Direct = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_Direct));
				Params->RTY_Diffuse = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_Diffuse));
				Params->RTY_DiffuseTemp = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_DiffuseTemp));

				FComputeShaderUtils::AddPass(
					GraphBuilder,
					RDG_EVENT_NAME("ComputeDiffuseIrradiance"),
					Shader,
					Params,
					GroupCount);
			}

			// Optional blur to suppress speckle
			if (bLocalBlur)
			{
				TShaderMapRef<FBlurDiffuseCS> BlurShader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
				FBlurDiffuseCS::FParameters* BlurParams = GraphBuilder.AllocParameters<FBlurDiffuseCS::FParameters>();
				BlurParams->TextureDimensions = FUintVector2(RTWidth, RTHeight);
				BlurParams->RTY_DiffuseTemp = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_DiffuseTemp));
				BlurParams->RTY_Diffuse = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_Diffuse));

				FComputeShaderUtils::AddPass(
					GraphBuilder,
					RDG_EVENT_NAME("BlurDiffuseIrradiance"),
					BlurShader,
					BlurParams,
					GroupCount);
			}

			GraphBuilder.Execute();
		});
}

void ASnowSimulationActor::ComputeRadiationIndices()
{
	if (!RTY_Direct || !RTY_Diffuse || !RTF_DirIndex || !RTF_DiffIndex)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadIndex] Cannot compute: render targets not initialized"));
		return;
	}

	if (!bUseReferenceTile)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadIndex] Cannot compute: reference tile disabled (bUseReferenceTile=false)"));
		return;
	}

	if (ReferenceLuminance_Total <= KINDA_SMALL_NUMBER)
	{
		UE_LOG(LogTemp, Verbose, TEXT("[RadIndex] Reference mean (Total) not ready yet (Total=%.6f, Direct=%.6f)"),
			ReferenceLuminance_Total, ReferenceLuminance_Direct);
		return;
	}

	const float ReferenceMean_Direct = FMath::Max(ReferenceLuminance_Direct, 1e-4f);
	const float ReferenceMean_Total = FMath::Max(ReferenceLuminance_Total, 1e-4f);
	const float DiffuseReference = (FMath::IsFinite(ReferenceLuminance_Diffuse) && ReferenceLuminance_Diffuse > 0.0f)
		? ReferenceLuminance_Diffuse
		: (ReferenceMean_Total - ReferenceMean_Direct);
	const float ReferenceMean_Diffuse = FMath::Max(DiffuseReference, 1e-6f);

	FTextureRenderTargetResource* DirectResource = RTY_Direct->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DiffuseResource = RTY_Diffuse->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DirIndexResource = RTF_DirIndex->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DiffIndexResource = RTF_DiffIndex->GameThread_GetRenderTargetResource();

	if (!DirectResource || !DiffuseResource || !DirIndexResource || !DiffIndexResource)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadIndex] Render target resources not ready"));
		return;
	}

	const int32 RTWidth = RTY_Direct->SizeX;
	const int32 RTHeight = RTY_Direct->SizeY;

	const FTextureRHIRef DirectRHI = DirectResource->TextureRHI;
	const FTextureRHIRef DiffuseRHI = DiffuseResource->TextureRHI;
	const FTextureRHIRef DirIndexRHI = DirIndexResource->TextureRHI;
	const FTextureRHIRef DiffIndexRHI = DiffIndexResource->TextureRHI;

	if (!DirectRHI.IsValid() || !DiffuseRHI.IsValid() || !DirIndexRHI.IsValid() || !DiffIndexRHI.IsValid())
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadIndex] Invalid texture handles for index computation"));
		return;
	}

	const uint32 BorderRows = bUseReferenceTile ? static_cast<uint32>(ReferenceStripHeight) : 0u;
	const float SunVisibility = CachedSunVisibility;

	ENQUEUE_RENDER_COMMAND(ComputeRadiationIndicesCommand)(
		[DirectRHI, DiffuseRHI, DirIndexRHI, DiffIndexRHI, RTWidth, RTHeight, ReferenceMean_Direct, ReferenceMean_Diffuse, BorderRows, SunVisibility](FRHICommandListImmediate& RHICmdList)
		{
			FRDGBuilder GraphBuilder(RHICmdList);

			FRDGTextureRef RDG_Direct = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DirectRHI, TEXT("Rad_RTY_Direct")));
			FRDGTextureRef RDG_Diffuse = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffuseRHI, TEXT("Rad_RTY_Diffuse")));
			FRDGTextureRef RDG_DirIndex = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DirIndexRHI, TEXT("Rad_RTF_DirIndex")));
			FRDGTextureRef RDG_DiffIndex = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffIndexRHI, TEXT("Rad_RTF_DiffIndex")));

			TShaderMapRef<FComputeRadiationIndexCS> Shader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
			FComputeRadiationIndexCS::FParameters* Params = GraphBuilder.AllocParameters<FComputeRadiationIndexCS::FParameters>();
			Params->TextureDimensions = FUintVector2(RTWidth, RTHeight);
			Params->ReferenceMean_Direct = ReferenceMean_Direct;
			Params->ReferenceMean_Diffuse = ReferenceMean_Diffuse;
			Params->BorderRows = BorderRows;
			Params->SunVisibility = SunVisibility;
			Params->RTY_Direct = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_Direct));
			Params->RTY_Diffuse = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_Diffuse));
			Params->RTF_DirIndex = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_DirIndex));
			Params->RTF_DiffIndex = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_DiffIndex));

			const FIntVector GroupCount((RTWidth + 7) / 8, (RTHeight + 7) / 8, 1);

			FComputeShaderUtils::AddPass(
				GraphBuilder,
				RDG_EVENT_NAME("ComputeRadiationIndices"),
				Shader,
				Params,
				GroupCount);

			GraphBuilder.Execute();
		});
}

void ASnowSimulationActor::ComputeRawRadiationIndices()
{
	if (!bEnableRawRadiationIndexTexture)
	{
		return;
	}

	if (!RTY_Total || !RTF_rUE_raw)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RawRadIndex] Cannot compute: render targets not initialized"));
		return;
	}

	if (!bUseReferenceTile)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RawRadIndex] Cannot compute: reference tile disabled"));
		return;
	}

	// Read reference means from UpdateReferenceLuminance() cached values
	// These were already computed and stored during the capture pipeline
	const float R_total = ReferenceLuminance_Total;
	if (R_total <= KINDA_SMALL_NUMBER)
	{
		UE_LOG(LogTemp, Verbose, TEXT("[RawRadIndex] Reference luminance not ready yet"));
		return;
	}

	FTextureRenderTargetResource* TotalResource = RTY_Total->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* RawTotalResource = RTF_rUE_raw ? RTF_rUE_raw->GameThread_GetRenderTargetResource() : nullptr;

	if (!TotalResource || !RawTotalResource)
	{
		return;
	}

	const int32 RTWidth = RTY_Total->SizeX;
	const int32 RTHeight = RTY_Total->SizeY;

	const FTextureRHIRef TotalRHI = TotalResource->TextureRHI;
	FTextureRHIRef RawTotalRHI = RawTotalResource->TextureRHI;
	if (!TotalRHI.IsValid() || !RawTotalRHI.IsValid())
	{
		return;
	}

	// Guard against missing UAV support on output RT to avoid RenderGraph validation crash.
	auto HasUAVSupport = [](const FTextureRHIRef& Texture) -> bool
	{
		return Texture.IsValid() && EnumHasAllFlags(Texture->GetDesc().Flags, TexCreate_UAV);
	};

	if (!HasUAVSupport(RawTotalRHI))
	{
		if (RTF_rUE_raw)
		{
			RTF_rUE_raw->bCanCreateUAV = true;
			RTF_rUE_raw->UpdateResourceImmediate(true);
			RawTotalResource = RTF_rUE_raw->GameThread_GetRenderTargetResource();
			RawTotalRHI = RawTotalResource ? RawTotalResource->TextureRHI : nullptr;
		}

		if (!HasUAVSupport(RawTotalRHI))
		{
			static int32 MissingRawUAVLogCount = 0;
			if (MissingRawUAVLogCount++ < 8)
			{
				UE_LOG(LogTemp, Warning, TEXT("[RawRadIndex] Skipping raw-index compute: RTF_rUE_raw has no UAV support."));
			}
			return;
		}
	}
	const float SunVisibility = CachedSunVisibility;

	ENQUEUE_RENDER_COMMAND(ComputeRawRadiationIndicesCommand)(
		[TotalRHI, RawTotalRHI, RTWidth, RTHeight, R_total, SunVisibility](FRHICommandListImmediate& RHICmdList)
		{
			FRDGBuilder GraphBuilder(RHICmdList);

			const FIntVector GroupCount((RTWidth + 7) / 8, (RTHeight + 7) / 8, 1);

			auto DispatchDivision = [&](FTextureRHIRef SourceRHI, FTextureRHIRef DestRHI, float ReferenceMean, const TCHAR* EventName)
			{
				if (!SourceRHI.IsValid() || !DestRHI.IsValid() || ReferenceMean <= KINDA_SMALL_NUMBER)
				{
					return;
				}

				FRDGTextureRef RDG_Source = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(SourceRHI, EventName));
				FRDGTextureRef RDG_Output = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DestRHI, EventName));

				TShaderMapRef<FComputeRadiationIndexCS> Shader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
				FComputeRadiationIndexCS::FParameters* Params = GraphBuilder.AllocParameters<FComputeRadiationIndexCS::FParameters>();
				Params->TextureDimensions = FUintVector2(RTWidth, RTHeight);
				Params->ReferenceMean_Direct = ReferenceMean;
				Params->ReferenceMean_Diffuse = ReferenceMean;
				Params->BorderRows = 0;
				Params->SunVisibility = SunVisibility;
				Params->RTY_Direct = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_Source));
				Params->RTY_Diffuse = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_Source));
				Params->RTF_DirIndex = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_Output));
				Params->RTF_DiffIndex = GraphBuilder.CreateUAV(FRDGTextureUAVDesc(RDG_Output));

				FComputeShaderUtils::AddPass(
					GraphBuilder,
					RDG_EVENT_NAME("%s", EventName),
					Shader,
					Params,
					GroupCount);
			};

			DispatchDivision(TotalRHI, RawTotalRHI, R_total, TEXT("RawRadiation_Total"));

			GraphBuilder.Execute();
		});
}

void ASnowSimulationActor::InitializeRadiationExtraction()
{
 const int32 LocalNumCells = CellsDimensionX * CellsDimensionY;

 if (!bEnableRadiationCapture || LocalNumCells <= 0)
 {
 	return;
 }

 	if (!RadiationReadbackBuffer)
	{
		RadiationReadbackBuffer = new FRHIGPUBufferReadback(TEXT("RadiationIndicesReadback"));
		DirectIndexReadbackBuffer = new FRHIGPUBufferReadback(TEXT("DirectIndicesReadback"));
		DiffuseIndexReadbackBuffer = new FRHIGPUBufferReadback(TEXT("DiffuseIndicesReadback"));
		UE_LOG(LogTemp, Display, TEXT("[RadExtract] Created GPU readback buffers"));
	}

	CachedRadiationIndices.SetNum(LocalNumCells);
	CachedDirectIndices.SetNum(LocalNumCells);
	CachedDiffuseIndices.SetNum(LocalNumCells);

	for (int32 i = 0; i < LocalNumCells; ++i)
	{
		CachedRadiationIndices[i] = 0.0f;
		CachedDirectIndices[i] = 0.0f;
		CachedDiffuseIndices[i] = 0.0f;
	}

	ReferenceLuminance_Total = FMath::Max(ReferenceLuminance_Total, 1e-6f);
	ReferenceLuminance_Direct = FMath::Max(ReferenceLuminance_Direct, 1e-6f);
	ReferenceLuminance_Diffuse = FMath::Max(ReferenceLuminance_Diffuse, 1e-6f);
 bReferenceReadbackPending = false;
	bReferenceDiffuseReadbackQueued = false;
	bReferenceDiffuseNoGIReadbackQueued = false;
	bRTYDiffuseNoGIReadbackQueued = false;
	ReferenceReadbackWidth = 0;
	LastRadiationExtractionFrame = INDEX_NONE;
    if (!bUseReferenceTile)
    {
        bReferenceLuminanceValid = true;
    }
}

void ASnowSimulationActor::ExtractRadiationIndicesToBuffer()
{
 if (!bEnableRadiationCapture || !RTY_Total)
 {
 	return;
 }

 if (!RadiationReadbackBuffer)
 {
 	InitializeRadiationExtraction();
 }

 if (!RadiationReadbackBuffer)
 {
 	return;
 }

 const int32 LocalNumCells = CellsDimensionX * CellsDimensionY;
 if (LocalNumCells <= 0)
 {
 	return;
 }

	if (bUseReferenceTile && !bReferenceLuminanceValid)
 {
 	return;
 }

 if (LastRadiationExtractionFrame == GFrameCounter)
 {
 	return;
 }
 LastRadiationExtractionFrame = GFrameCounter;

 FTextureRenderTargetResource* TotalResource = RTY_Total->GameThread_GetRenderTargetResource();
 if (!TotalResource)
 {
 	return;
 }

 const FTextureRHIRef TotalRHI = TotalResource->TextureRHI;
	if (!TotalRHI.IsValid())
	{
		return;
	}

	if (!RadiationPixelCoordSRV.IsValid())
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadExtract] Pixel coordinate buffer missing - skipping extraction."));
		return;
	}

 const uint32 GridDimX = CellsDimensionX;
 const uint32 GridDimY = CellsDimensionY;
	const uint32 NumCellsLocal = GridDimX * GridDimY;
	const float ReferenceMean = bUseReferenceTile ? ReferenceLuminance_Total : FMath::Max(ReferenceLuminance_Total, 1.0f);
	const bool bHasReferenceTile = bUseReferenceTile;
	const float MaxClamp = FMath::Max(MaxRadiationIndexClamp, 0.1f);
	const float SunVisibility = CachedSunVisibility;

	// Note: Low sun angle fallback to Hock Model 3 (I * Gs/Is) is handled in DegreeDay simulation
	// The shader extraction always runs normally and extracts UE radiation indices
	// The DegreeDay simulation will compute parametric radiation when needed
	const float MeasuredGHI_Wm2 = 0.0f;
	const float ClearSkyRef_Wm2 = 0.0f;
	const bool bUsePhysicalIrradianceInput = false;

		// Prepare RHI refs for split indices if available
		FTextureRHIRef DirIndexRHI = nullptr;
		FTextureRHIRef DiffIndexRHI = nullptr;
		if (RTF_DirIndex)
		{
			FTextureRenderTargetResource* Res = RTF_DirIndex->GameThread_GetRenderTargetResource();
			if (Res) DirIndexRHI = Res->TextureRHI;
		}
		if (RTF_DiffIndex)
		{
			FTextureRenderTargetResource* Res = RTF_DiffIndex->GameThread_GetRenderTargetResource();
			if (Res) DiffIndexRHI = Res->TextureRHI;
		}

	ENQUEUE_RENDER_COMMAND(ExtractRadiationIndicesCommand)(
		[TotalRHI,
		 DirIndexRHI,
		 DiffIndexRHI,
		 RadiationIndexBuffer = &this->RadiationIndexBuffer,
		 RadiationReadbackBuffer = this->RadiationReadbackBuffer,
		 DirectIndexReadbackBuffer = this->DirectIndexReadbackBuffer,
		 DiffuseIndexReadbackBuffer = this->DiffuseIndexReadbackBuffer,
		 ReferenceMean,
		 GridDimX,
		 GridDimY,
		 NumCellsLocal,
		 bHasReferenceTile,
		 MaxClamp,
		 SunVisibility,
		 MeasuredGHI_Wm2,
		 ClearSkyRef_Wm2,
		 bUsePhysicalIrradianceInput,
		 ReferenceStripHeight = this->ReferenceStripHeight,
		 PixelCoordSRV = RadiationPixelCoordSRV,
		 this](FRHICommandListImmediate& RHICmdList)
 	{
 		if (!TotalRHI.IsValid() || !RadiationReadbackBuffer)
 		{
 			return;
 		}

 		FRDGBuilder GraphBuilder(RHICmdList);

 		FRDGTextureRef RDG_Total = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(TotalRHI, TEXT("Rad_RTY_Total")));

		FRDGBufferRef RDG_OutputBuffer = GraphBuilder.CreateBuffer(
			FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumCellsLocal),
 			TEXT("RadiationIndexBuffer"));

 		TShaderMapRef<FExtractRadiationIndicesCS> Shader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
 		FExtractRadiationIndicesCS::FParameters* Params = GraphBuilder.AllocParameters<FExtractRadiationIndicesCS::FParameters>();
 		Params->GridDimX = GridDimX;
		Params->GridDimY = GridDimY;
		Params->NumCells = NumCellsLocal;
		Params->ReferenceMean = ReferenceMean;
		Params->BorderRows = bHasReferenceTile ? ReferenceStripHeight : 0u;
		Params->MaxRadiationIndex = MaxClamp;
		Params->SunVisibility = SunVisibility;
		Params->MeasuredGHI_Wm2 = MeasuredGHI_Wm2;
		Params->ClearSkyReference_Wm2 = ClearSkyRef_Wm2;
		Params->bUsePhysicalIrradiance = bUsePhysicalIrradianceInput ? 1u : 0u;
		Params->RTY_Total = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_Total));
		Params->RTF_Etot = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(RDG_Total));
		Params->CellPixelCoords = PixelCoordSRV;
		Params->RadiationIndexBuffer = GraphBuilder.CreateUAV(FRDGBufferUAVDesc(RDG_OutputBuffer));

		const uint32 ThreadGroupCount = FMath::DivideAndRoundUp(NumCellsLocal, 256u);

		FComputeShaderUtils::AddPass(
			GraphBuilder,
			RDG_EVENT_NAME("ExtractRadiationIndices"),
			Shader,
			Params,
			FIntVector(ThreadGroupCount, 1, 1));

		AddEnqueueCopyPass(GraphBuilder, RadiationReadbackBuffer, RDG_OutputBuffer, NumCellsLocal * sizeof(float));

		// Also extract Direct and Diffuse indices if available
		if (DirectIndexReadbackBuffer && DiffuseIndexReadbackBuffer && DirIndexRHI.IsValid() && DiffIndexRHI.IsValid())
		{
			// Note: We are reusing the ExtractRadiationIndicesCS logic here but applying it to the pre-computed index textures
			// RTF_DirIndex and RTF_DiffIndex are already computed in ComputeRadiationIndices()
			// We just need to copy them to a buffer for readback.
			// Ideally we would use a simple texture-to-buffer copy shader, but for now we can rely on the fact that
			// we need to extract them per-cell anyway.
			
			// Actually, since RTF_DirIndex/DiffIndex are already computed as textures, we can use a simpler extraction
			// or just reuse the same shader with different inputs if we want to be consistent.
			// However, RTF_DirIndex is already the result of (RTY / Ref).
			// So we can just extract the texture values directly.
			
			// Let's use a simple copy pass for now, assuming we have a shader for it or can reuse the extraction shader
			// with specific flags.
			// For simplicity and robustness, we will use the existing extraction shader but pass the Index texture as RTY_Total
			// and set ReferenceMean to 1.0 so it just copies the value (Index / 1.0 = Index).
			
			auto DispatchExtraction = [&](FRDGTextureRef InputTexture, FRHIGPUBufferReadback* OutputBuffer, const TCHAR* Name)
			{
				FRDGBufferRef RDG_Out = GraphBuilder.CreateBuffer(
					FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumCellsLocal),
					Name);

				FExtractRadiationIndicesCS::FParameters* ExParams = GraphBuilder.AllocParameters<FExtractRadiationIndicesCS::FParameters>();
				ExParams->GridDimX = GridDimX;
				ExParams->GridDimY = GridDimY;
				ExParams->NumCells = NumCellsLocal;
				ExParams->ReferenceMean = 1.0f; // Pass-through
				ExParams->BorderRows = bHasReferenceTile ? ReferenceStripHeight : 0u;
				ExParams->MaxRadiationIndex = MaxClamp;
				ExParams->SunVisibility = 1.0f; // Always visible for indices
				ExParams->MeasuredGHI_Wm2 = 0.0f;
				ExParams->ClearSkyReference_Wm2 = 0.0f;
				ExParams->bUsePhysicalIrradiance = 0u;
				ExParams->RTY_Total = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(InputTexture));
				ExParams->RTF_Etot = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(InputTexture)); // Unused in pass-through mode
				ExParams->CellPixelCoords = PixelCoordSRV;
				ExParams->RadiationIndexBuffer = GraphBuilder.CreateUAV(FRDGBufferUAVDesc(RDG_Out));

				FComputeShaderUtils::AddPass(
					GraphBuilder,
					RDG_EVENT_NAME("Extract%s", Name),
					Shader,
					ExParams,
					FIntVector(ThreadGroupCount, 1, 1));

				AddEnqueueCopyPass(GraphBuilder, OutputBuffer, RDG_Out, NumCellsLocal * sizeof(float));
			};

			if (DirIndexRHI.IsValid())
			{
				FRDGTextureRef RDG_DirIndex = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DirIndexRHI, TEXT("Rad_RTF_DirIndex")));
				DispatchExtraction(RDG_DirIndex, DirectIndexReadbackBuffer, TEXT("DirectIndex"));
			}

			if (DiffIndexRHI.IsValid())
			{
				FRDGTextureRef RDG_DiffIndex = GraphBuilder.RegisterExternalTexture(CreateRenderTarget(DiffIndexRHI, TEXT("Rad_RTF_DiffIndex")));
				DispatchExtraction(RDG_DiffIndex, DiffuseIndexReadbackBuffer, TEXT("DiffuseIndex"));
			}
		}

 		GraphBuilder.QueueBufferExtraction(RDG_OutputBuffer, RadiationIndexBuffer);

 		GraphBuilder.Execute();
 	});
}

bool ASnowSimulationActor::ReadbackRadiationIndices()
{
	if (!RadiationReadbackBuffer || CachedRadiationIndices.Num() == 0)
	{
		return false;
	}

	if (!RadiationReadbackBuffer->IsReady())
	{
		return false;
	}

	const int32 LocalNumCells = CachedRadiationIndices.Num();
	const int32 BufferSize = LocalNumCells * sizeof(float);

	TArray<float> LocalCopy;
	LocalCopy.SetNum(LocalNumCells);
	float* LocalDataPtr = LocalCopy.GetData();

	bool bReadbackSuccess = false;
	FEvent* CompletionEvent = FPlatformProcess::GetSynchEventFromPool(true);

	ENQUEUE_RENDER_COMMAND(ReadbackRadiationIndicesCommand)(
		[ReadbackBuffer = RadiationReadbackBuffer,
		 DirectBuffer = DirectIndexReadbackBuffer,
		 DiffuseBuffer = DiffuseIndexReadbackBuffer,
		 BufferSize,
		 LocalDataPtr,
		 DirectDataPtr = CachedDirectIndices.GetData(),
		 DiffuseDataPtr = CachedDiffuseIndices.GetData(),
		 CompletionEvent,
		 &bReadbackSuccess](FRHICommandListImmediate& RHICmdList)
		{
			const void* BufferData = ReadbackBuffer ? ReadbackBuffer->Lock(BufferSize) : nullptr;
			if (BufferData)
			{
				FMemory::Memcpy(LocalDataPtr, BufferData, BufferSize);
				ReadbackBuffer->Unlock();
				bReadbackSuccess = true;
			}
			else
			{
				UE_LOG(LogTemp, Error, TEXT("[RadExtract] Failed to lock readback buffer on render thread"));
				bReadbackSuccess = false;
			}

			// Read split indices in the same command to avoid race with diagnostics.
			if (DirectBuffer && DirectBuffer->IsReady())
			{
				const void* DirectData = DirectBuffer->Lock(BufferSize);
				if (DirectData)
				{
					FMemory::Memcpy(DirectDataPtr, DirectData, BufferSize);
					DirectBuffer->Unlock();
				}
			}
			if (DiffuseBuffer && DiffuseBuffer->IsReady())
			{
				const void* DiffuseData = DiffuseBuffer->Lock(BufferSize);
				if (DiffuseData)
				{
					FMemory::Memcpy(DiffuseDataPtr, DiffuseData, BufferSize);
					DiffuseBuffer->Unlock();
				}
			}

			CompletionEvent->Trigger();
		});

	CompletionEvent->Wait();
	FPlatformProcess::ReturnSynchEventToPool(CompletionEvent);

	if (!bReadbackSuccess)
	{
		return false;
	}

	CachedRadiationIndices = MoveTemp(LocalCopy);

	float MinVal = MAX_flt;
	float MaxVal = -MAX_flt;
	float SumVal = 0.0f;
	const int32 SampleCount = FMath::Min(LocalNumCells, 16);
	for (int32 Index = 0; Index < SampleCount; ++Index)
	{
		const float Value = CachedRadiationIndices[Index];
		MinVal = FMath::Min(MinVal, Value);
		MaxVal = FMath::Max(MaxVal, Value);
		SumVal += Value;
	}

	const float AvgVal = SampleCount > 0 ? SumVal / SampleCount : 0.0f;

	static int32 ReadbackLogCounter = 0;
	if (ReadbackLogCounter++ < 3)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadExtract] ===== Readback #%d complete: %d cells | Min=%.3f Max=%.3f Avg=%.3f | RefLum=%.3f ====="),
			ReadbackLogCounter, LocalNumCells, MinVal, MaxVal, AvgVal, ReferenceLuminance_Total);
	}

	return true;
}

void ASnowSimulationActor::ExtractRTYLuminanceToBuffers()
{
	if (!bEnableRadiationCapture || !RTY_Total || !RTY_Direct || !RTY_Diffuse)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] SKIPPED: Capture=%d, Total=%p, Direct=%p, Diffuse=%p"),
			bEnableRadiationCapture, RTY_Total, RTY_Direct, RTY_Diffuse);
		bRTYDiffuseNoGIReadbackQueued = false;
		bRTYTotalNoGIReadbackQueued = false;
		bRTYSurfaceStateReadbackQueued = false;
		CachedRTY_DiffuseNoGI.Reset();
		CachedRTY_TotalNoGI.Reset();
		CachedRTY_SurfaceState.Reset();
		return;
	}

	// Double check we have valid render targets before trying to lock/read them
	if (RTY_Direct->SizeX != CellsDimensionX || RTY_Direct->SizeY != (CellsDimensionY + (bUseReferenceTile ? ReferenceStripHeight : 0)))
	{
		UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] SKIPPED: Dimension mismatch."));
		bRTYDiffuseNoGIReadbackQueued = false;
		bRTYTotalNoGIReadbackQueued = false;
		bRTYSurfaceStateReadbackQueued = false;
		CachedRTY_DiffuseNoGI.Reset();
		CachedRTY_TotalNoGI.Reset();
		CachedRTY_SurfaceState.Reset();
		return;
	}

	// Initialize readback buffers if needed
	if (!RTYDirectReadback)
	{
		RTYDirectReadback = new FRHIGPUBufferReadback(TEXT("RTYDirectReadback"));
	}
	if (!RTYDiffuseReadback)
	{
		RTYDiffuseReadback = new FRHIGPUBufferReadback(TEXT("RTYDiffuseReadback"));
	}
	if (!RTYTotalReadback)
	{
		RTYTotalReadback = new FRHIGPUBufferReadback(TEXT("RTYTotalReadback"));
	}
	const bool bExtractDiffuseNoGI = bUseDiffuseNoGICaptureThisFrame && RTY_DiffuseNoGI;
	const bool bExtractTotalNoGI = bUseDiffuseNoGICaptureThisFrame && RTY_TotalNoGI;
	if (bExtractDiffuseNoGI && !RTYDiffuseNoGIReadback)
	{
		RTYDiffuseNoGIReadback = new FRHIGPUBufferReadback(TEXT("RTYDiffuseNoGIReadback"));
	}
	if (bExtractTotalNoGI && !RTYTotalNoGIReadback)
	{
		RTYTotalNoGIReadback = new FRHIGPUBufferReadback(TEXT("RTYTotalNoGIReadback"));
	}
	const bool bExtractSurfaceState = bUseDualReferenceStrip && RTY_SurfaceState;
	if (bExtractSurfaceState && !RTYSurfaceStateReadback)
	{
		RTYSurfaceStateReadback = new FRHIGPUBufferReadback(TEXT("RTYSurfaceStateReadback"));
	}

	const uint32 NumCellsLocal = CellsDimensionX * CellsDimensionY;
	if (NumCellsLocal == 0)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] SKIPPED: NumCellsLocal is 0."));
		bRTYDiffuseNoGIReadbackQueued = false;
		bRTYTotalNoGIReadbackQueued = false;
		bRTYSurfaceStateReadbackQueued = false;
		CachedRTY_DiffuseNoGI.Reset();
		CachedRTY_TotalNoGI.Reset();
		CachedRTY_SurfaceState.Reset();
		return;
	}

	// Resize cached arrays if needed
	if (CachedRTY_Direct.Num() != NumCellsLocal)
	{
		CachedRTY_Direct.SetNum(NumCellsLocal);
	}
	if (CachedRTY_Diffuse.Num() != NumCellsLocal)
	{
		CachedRTY_Diffuse.SetNum(NumCellsLocal);
	}
	if (CachedRTY_Total.Num() != NumCellsLocal)
	{
		CachedRTY_Total.SetNum(NumCellsLocal);
	}
	if (bExtractDiffuseNoGI)
	{
		if (CachedRTY_DiffuseNoGI.Num() != NumCellsLocal)
		{
			CachedRTY_DiffuseNoGI.SetNum(NumCellsLocal);
		}
	}
	else
	{
		CachedRTY_DiffuseNoGI.Reset();
	}
	if (bExtractTotalNoGI)
	{
		if (CachedRTY_TotalNoGI.Num() != NumCellsLocal)
		{
			CachedRTY_TotalNoGI.SetNum(NumCellsLocal);
		}
	}
	else
	{
		CachedRTY_TotalNoGI.Reset();
	}
	if (bExtractSurfaceState)
	{
		if (CachedRTY_SurfaceState.Num() != NumCellsLocal)
		{
			CachedRTY_SurfaceState.SetNum(NumCellsLocal);
		}
	}
	else
	{
		CachedRTY_SurfaceState.Reset();
	}

	FTextureRenderTargetResource* TotalResource = RTY_Total->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DirectResource = RTY_Direct->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DiffuseResource = RTY_Diffuse->GameThread_GetRenderTargetResource();
	FTextureRenderTargetResource* DiffuseNoGIResource = bExtractDiffuseNoGI ? RTY_DiffuseNoGI->GameThread_GetRenderTargetResource() : nullptr;
	FTextureRenderTargetResource* TotalNoGIResource = bExtractTotalNoGI ? RTY_TotalNoGI->GameThread_GetRenderTargetResource() : nullptr;
	FTextureRenderTargetResource* SurfaceStateResource = bExtractSurfaceState ? RTY_SurfaceState->GameThread_GetRenderTargetResource() : nullptr;

	if (!TotalResource || !DirectResource || !DiffuseResource)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] SKIPPED: Missing GameThread resources (Total=%p, Dir=%p, Diff=%p)"),
			TotalResource, DirectResource, DiffuseResource);
		bRTYDiffuseNoGIReadbackQueued = false;
		bRTYTotalNoGIReadbackQueued = false;
		bRTYSurfaceStateReadbackQueued = false;
		CachedRTY_DiffuseNoGI.Reset();
		CachedRTY_TotalNoGI.Reset();
		CachedRTY_SurfaceState.Reset();
		return;
	}

	const FTextureRHIRef TotalRHI = TotalResource->TextureRHI;
	const FTextureRHIRef DirectRHI = DirectResource->TextureRHI;
	const FTextureRHIRef DiffuseRHI = DiffuseResource->TextureRHI;
	const FTextureRHIRef DiffuseNoGIRHI = DiffuseNoGIResource ? DiffuseNoGIResource->TextureRHI : nullptr;
	const FTextureRHIRef TotalNoGIRHI = TotalNoGIResource ? TotalNoGIResource->TextureRHI : nullptr;
	const FTextureRHIRef SurfaceStateRHI = SurfaceStateResource ? SurfaceStateResource->TextureRHI : nullptr;
	const bool bHasDiffuseNoGI = bExtractDiffuseNoGI && DiffuseNoGIRHI.IsValid() && RTYDiffuseNoGIReadback != nullptr;
	const bool bHasTotalNoGI = bExtractTotalNoGI && TotalNoGIRHI.IsValid() && RTYTotalNoGIReadback != nullptr;
	const bool bHasSurfaceState = bExtractSurfaceState && SurfaceStateRHI.IsValid() && RTYSurfaceStateReadback != nullptr;

	if (!TotalRHI.IsValid() || !DirectRHI.IsValid() || !DiffuseRHI.IsValid())
	{
		UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] SKIPPED: Invalid RHI refs (Total=%d, Dir=%d, Diff=%d)"),
			TotalRHI.IsValid(), DirectRHI.IsValid(), DiffuseRHI.IsValid());
		bRTYDiffuseNoGIReadbackQueued = false;
		bRTYTotalNoGIReadbackQueued = false;
		bRTYSurfaceStateReadbackQueued = false;
		CachedRTY_DiffuseNoGI.Reset();
		CachedRTY_TotalNoGI.Reset();
		CachedRTY_SurfaceState.Reset();
		return;
	}
	if (bExtractDiffuseNoGI && !bHasDiffuseNoGI)
	{
		static bool bLoggedNoGIMissing = false;
		if (!bLoggedNoGIMissing)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] DiffuseNoGI capture requested but RTY_DiffuseNoGI resource/readback is unavailable."));
			bLoggedNoGIMissing = true;
		}
		CachedRTY_DiffuseNoGI.Reset();
	}
	if (bExtractTotalNoGI && !bHasTotalNoGI)
	{
		static bool bLoggedTotalNoGIMissing = false;
		if (!bLoggedTotalNoGIMissing)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] TotalNoGI capture requested but RTY_TotalNoGI resource/readback is unavailable."));
			bLoggedTotalNoGIMissing = true;
		}
		CachedRTY_TotalNoGI.Reset();
	}
	if (bExtractSurfaceState && !bHasSurfaceState)
	{
		static bool bLoggedSurfaceStateMissing = false;
		if (!bLoggedSurfaceStateMissing)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] SurfaceState capture requested but RTY_SurfaceState resource/readback is unavailable."));
			bLoggedSurfaceStateMissing = true;
		}
		CachedRTY_SurfaceState.Reset();
	}

	// IMPORTANT: Use the same PixelCoordSRV as ExtractRadiationIndices
	if (!RadiationPixelCoordSRV.IsValid())
	{
		UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] SKIPPED: Pixel coordinate buffer missing."));
		// Note: This might happen on the very first frame if the upload command hasn't run yet.
		bRTYDiffuseNoGIReadbackQueued = false;
		bRTYTotalNoGIReadbackQueued = false;
		bRTYSurfaceStateReadbackQueued = false;
		CachedRTY_DiffuseNoGI.Reset();
		CachedRTY_TotalNoGI.Reset();
		CachedRTY_SurfaceState.Reset();
		return;
	}

	const uint32 GridDimX = CellsDimensionX;
	const uint32 GridDimY = CellsDimensionY;
	// NumCellsLocal already defined above
	const uint32 BorderRows = bUseReferenceTile ? ReferenceStripHeight : 0;

	ENQUEUE_RENDER_COMMAND(ExtractRTYLuminanceCommand)(
		[TotalRHI,
		 DirectRHI,
		 DiffuseRHI,
		 DiffuseNoGIRHI,
		 TotalNoGIRHI,
		 SurfaceStateRHI,
		 bHasDiffuseNoGI,
		 bHasTotalNoGI,
		 bHasSurfaceState,
		 GridDimX,
		 GridDimY,
		 NumCellsLocal,
		 BorderRows,
		 RTYTotalReadback = this->RTYTotalReadback,
		 RTYDirectReadback = this->RTYDirectReadback,
		 RTYDiffuseReadback = this->RTYDiffuseReadback,
		 RTYDiffuseNoGIReadback = this->RTYDiffuseNoGIReadback,
		 RTYTotalNoGIReadback = this->RTYTotalNoGIReadback,
		 RTYSurfaceStateReadback = this->RTYSurfaceStateReadback,
		 PixelCoordSRV = RadiationPixelCoordSRV](FRHICommandListImmediate& RHICmdList)
		{
			FRDGBuilder GraphBuilder(RHICmdList);

			if (!TotalRHI.IsValid() || !DirectRHI.IsValid() || !DiffuseRHI.IsValid())
			{
				GraphBuilder.Execute();
				return;
			}

			// Register textures
			FRDGTextureRef RDG_TotalTexture = GraphBuilder.RegisterExternalTexture(
				CreateRenderTarget(TotalRHI, TEXT("RTY_Total")));
			FRDGTextureRef RDG_DirectTexture = GraphBuilder.RegisterExternalTexture(
				CreateRenderTarget(DirectRHI, TEXT("RTY_Direct")));
			FRDGTextureRef RDG_DiffuseTexture = GraphBuilder.RegisterExternalTexture(
				CreateRenderTarget(DiffuseRHI, TEXT("RTY_Diffuse")));
			FRDGTextureRef RDG_DiffuseNoGITexture = nullptr;
			if (bHasDiffuseNoGI && DiffuseNoGIRHI.IsValid())
			{
				RDG_DiffuseNoGITexture = GraphBuilder.RegisterExternalTexture(
					CreateRenderTarget(DiffuseNoGIRHI, TEXT("RTY_DiffuseNoGI")));
			}
			FRDGTextureRef RDG_TotalNoGITexture = nullptr;
			if (bHasTotalNoGI && TotalNoGIRHI.IsValid())
			{
				RDG_TotalNoGITexture = GraphBuilder.RegisterExternalTexture(
					CreateRenderTarget(TotalNoGIRHI, TEXT("RTY_TotalNoGI")));
			}
			FRDGTextureRef RDG_SurfaceStateTexture = nullptr;
			if (bHasSurfaceState && SurfaceStateRHI.IsValid())
			{
				RDG_SurfaceStateTexture = GraphBuilder.RegisterExternalTexture(
					CreateRenderTarget(SurfaceStateRHI, TEXT("RTY_SurfaceState")));
			}

			// Create output buffers
			FRDGBufferDesc TotalBufferDesc = FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumCellsLocal);
			FRDGBufferRef RDG_TotalBuffer = GraphBuilder.CreateBuffer(TotalBufferDesc, TEXT("RTYTotalBuffer"));

			FRDGBufferDesc DirectBufferDesc = FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumCellsLocal);
			FRDGBufferRef RDG_DirectBuffer = GraphBuilder.CreateBuffer(DirectBufferDesc, TEXT("RTYDirectBuffer"));

			FRDGBufferDesc DiffuseBufferDesc = FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumCellsLocal);
			FRDGBufferRef RDG_DiffuseBuffer = GraphBuilder.CreateBuffer(DiffuseBufferDesc, TEXT("RTYDiffuseBuffer"));
			FRDGBufferRef RDG_DiffuseNoGIBuffer = nullptr;
			if (RDG_DiffuseNoGITexture)
			{
				FRDGBufferDesc DiffuseNoGIBufferDesc = FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumCellsLocal);
				RDG_DiffuseNoGIBuffer = GraphBuilder.CreateBuffer(DiffuseNoGIBufferDesc, TEXT("RTYDiffuseNoGIBuffer"));
			}
			FRDGBufferRef RDG_TotalNoGIBuffer = nullptr;
			if (RDG_TotalNoGITexture)
			{
				FRDGBufferDesc TotalNoGIBufferDesc = FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumCellsLocal);
				RDG_TotalNoGIBuffer = GraphBuilder.CreateBuffer(TotalNoGIBufferDesc, TEXT("RTYTotalNoGIBuffer"));
			}
			FRDGBufferRef RDG_SurfaceStateBuffer = nullptr;
			if (RDG_SurfaceStateTexture)
			{
				FRDGBufferDesc SurfaceStateBufferDesc = FRDGBufferDesc::CreateStructuredDesc(sizeof(float), NumCellsLocal);
				RDG_SurfaceStateBuffer = GraphBuilder.CreateBuffer(SurfaceStateBufferDesc, TEXT("RTYSurfaceStateBuffer"));
			}

			// Use the same extraction shader we use for radiation indices
			// This shader samples the texture at each cell location
			TShaderMapRef<FExtractRadiationIndicesCS> Shader(GetGlobalShaderMap(GMaxRHIFeatureLevel));

			auto DispatchExtraction = [&](FRDGTextureRef InputTexture, FRDGBufferRef OutputBuffer, const TCHAR* EventName)
			{
				FExtractRadiationIndicesCS::FParameters* Params = GraphBuilder.AllocParameters<FExtractRadiationIndicesCS::FParameters>();
				Params->GridDimX = GridDimX;
				Params->GridDimY = GridDimY;
				Params->NumCells = NumCellsLocal;
				Params->ReferenceMean = 1.0f; // No normalization, just raw values
				Params->BorderRows = BorderRows;
				// Raw RTY extraction should preserve the full float range coming from the
				// source texture. The configurable radiation-index clamp is only meant for
				// normalized index products, not cached luminance diagnostics.
				Params->MaxRadiationIndex = FLT_MAX;
				Params->MeasuredGHI_Wm2 = 0.0f;
				Params->ClearSkyReference_Wm2 = 0.0f;
				Params->bUsePhysicalIrradiance = 0;
				Params->RTY_Total = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(InputTexture));
				Params->RTF_Etot = GraphBuilder.CreateSRV(FRDGTextureSRVDesc::Create(InputTexture));
				Params->CellPixelCoords = PixelCoordSRV;
				Params->RadiationIndexBuffer = GraphBuilder.CreateUAV(OutputBuffer);
				Params->SunVisibility = 1.0f;

				const uint32 ThreadGroupCount = FMath::DivideAndRoundUp(NumCellsLocal, 256u);
				FComputeShaderUtils::AddPass(
					GraphBuilder,
					RDG_EVENT_NAME("%s", EventName),
					Shader,
					Params,
					FIntVector(ThreadGroupCount, 1, 1));
			};

			DispatchExtraction(RDG_TotalTexture, RDG_TotalBuffer, TEXT("ExtractRTYTotal"));
			DispatchExtraction(RDG_DirectTexture, RDG_DirectBuffer, TEXT("ExtractRTYDirect"));
			DispatchExtraction(RDG_DiffuseTexture, RDG_DiffuseBuffer, TEXT("ExtractRTYDiffuse"));
			if (RDG_DiffuseNoGITexture && RDG_DiffuseNoGIBuffer)
			{
				DispatchExtraction(RDG_DiffuseNoGITexture, RDG_DiffuseNoGIBuffer, TEXT("ExtractRTYDiffuseNoGI"));
			}
			if (RDG_TotalNoGITexture && RDG_TotalNoGIBuffer)
			{
				DispatchExtraction(RDG_TotalNoGITexture, RDG_TotalNoGIBuffer, TEXT("ExtractRTYTotalNoGI"));
			}
			if (RDG_SurfaceStateTexture && RDG_SurfaceStateBuffer)
			{
				DispatchExtraction(RDG_SurfaceStateTexture, RDG_SurfaceStateBuffer, TEXT("ExtractRTYSurfaceState"));
			}

			AddEnqueueCopyPass(GraphBuilder, RTYTotalReadback, RDG_TotalBuffer, NumCellsLocal * sizeof(float));
			AddEnqueueCopyPass(GraphBuilder, RTYDirectReadback, RDG_DirectBuffer, NumCellsLocal * sizeof(float));
			AddEnqueueCopyPass(GraphBuilder, RTYDiffuseReadback, RDG_DiffuseBuffer, NumCellsLocal * sizeof(float));
			if (RDG_DiffuseNoGIBuffer && RTYDiffuseNoGIReadback)
			{
				AddEnqueueCopyPass(GraphBuilder, RTYDiffuseNoGIReadback, RDG_DiffuseNoGIBuffer, NumCellsLocal * sizeof(float));
			}
			if (RDG_TotalNoGIBuffer && RTYTotalNoGIReadback)
			{
				AddEnqueueCopyPass(GraphBuilder, RTYTotalNoGIReadback, RDG_TotalNoGIBuffer, NumCellsLocal * sizeof(float));
			}
			if (RDG_SurfaceStateBuffer && RTYSurfaceStateReadback)
			{
				AddEnqueueCopyPass(GraphBuilder, RTYSurfaceStateReadback, RDG_SurfaceStateBuffer, NumCellsLocal * sizeof(float));
			}

			GraphBuilder.Execute();
	});
	bRTYDiffuseNoGIReadbackQueued = bHasDiffuseNoGI;
	bRTYTotalNoGIReadbackQueued = bHasTotalNoGI;
	bRTYSurfaceStateReadbackQueued = bHasSurfaceState;
	if (!bHasDiffuseNoGI)
	{
		CachedRTY_DiffuseNoGI.Reset();
	}
	if (!bHasTotalNoGI)
	{
		CachedRTY_TotalNoGI.Reset();
	}
	if (!bHasSurfaceState)
	{
		CachedRTY_SurfaceState.Reset();
	}
}

bool ASnowSimulationActor::ReadbackRTYLuminance(bool bBlockUntilReady)
{
	UE_LOG(LogTemp, Warning, TEXT("[RadTrace] ReadbackRTYLuminance Called. Block=%d"), bBlockUntilReady);

	if (!RTYTotalReadback || !RTYDirectReadback || !RTYDiffuseReadback)
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Readback failed: Readback objects null."));
		bRTYDiffuseNoGIReadbackQueued = false;
		bRTYTotalNoGIReadbackQueued = false;
		bRTYSurfaceStateReadbackQueued = false;
		CachedRTY_DiffuseNoGI.Reset();
		CachedRTY_TotalNoGI.Reset();
		CachedRTY_SurfaceState.Reset();
		return false;
	}

	const bool bUseDiffuseNoGIReadback = bRTYDiffuseNoGIReadbackQueued && RTYDiffuseNoGIReadback;
	const bool bUseTotalNoGIReadback = bRTYTotalNoGIReadbackQueued && RTYTotalNoGIReadback;
	const bool bUseSurfaceStateReadback = bRTYSurfaceStateReadbackQueued && RTYSurfaceStateReadback;
	auto IsAnyRequiredReadbackPending = [&]() -> bool
	{
		if (!RTYTotalReadback->IsReady() || !RTYDirectReadback->IsReady() || !RTYDiffuseReadback->IsReady())
		{
			return true;
		}
		if (bUseDiffuseNoGIReadback && !RTYDiffuseNoGIReadback->IsReady())
		{
			return true;
		}
		if (bUseTotalNoGIReadback && !RTYTotalNoGIReadback->IsReady())
		{
			return true;
		}
		if (bUseSurfaceStateReadback && !RTYSurfaceStateReadback->IsReady())
		{
			return true;
		}
		return false;
	};

	if (IsAnyRequiredReadbackPending())
	{
		if (bBlockUntilReady)
		{
			// Spin-wait for readiness (up to 100ms)
			// Since we flushed commands, this should be quick.
			int32 Retries = 0;
			while (IsAnyRequiredReadbackPending() && Retries < 100)
			{
				FPlatformProcess::Sleep(0.001f); // 1ms sleep
				Retries++;
			}
			
			if (Retries > 0 && Retries < 100)
			{
				// UE_LOG(LogTemp, Verbose, TEXT("[ReadbackRTY] Blocked for %d ms to get data."), Retries);
			}
		}
		else
		{
			UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Readback skipped: Not ready and blocking not requested."));
			return false;
		}
	}

	if (IsAnyRequiredReadbackPending())
	{
		UE_LOG(LogTemp, Warning, TEXT("[ReadbackRTY] Readback buffers NOT READY after wait. (TotalReady=%d, DirectReady=%d, DiffuseReady=%d, DiffuseNoGIReady=%d, TotalNoGIReady=%d, SurfaceStateReady=%d)"),
				RTYTotalReadback->IsReady(), RTYDirectReadback->IsReady(), RTYDiffuseReadback->IsReady(),
				bUseDiffuseNoGIReadback ? RTYDiffuseNoGIReadback->IsReady() : 1,
				bUseTotalNoGIReadback ? RTYTotalNoGIReadback->IsReady() : 1,
				bUseSurfaceStateReadback ? RTYSurfaceStateReadback->IsReady() : 1);
		return false;
	}

	const int32 LocalNumCells = CachedRTY_Direct.Num();
	if (LocalNumCells == 0 || LocalNumCells != CachedRTY_Diffuse.Num() || LocalNumCells != CachedRTY_Total.Num())
	{
		UE_LOG(LogTemp, Warning, TEXT("[RadTrace] Readback failed: Cached array size mismatch."));
		return false;
	}
	if (bUseDiffuseNoGIReadback && CachedRTY_DiffuseNoGI.Num() != LocalNumCells)
	{
		CachedRTY_DiffuseNoGI.SetNum(LocalNumCells);
	}
	if (bUseDiffuseNoGIReadback && CachedRTY_TotalNoGI.Num() != LocalNumCells)
	{
		CachedRTY_TotalNoGI.SetNum(LocalNumCells);
	}
	if (bUseSurfaceStateReadback && CachedRTY_SurfaceState.Num() != LocalNumCells)
	{
		CachedRTY_SurfaceState.SetNum(LocalNumCells);
	}

	const int32 BufferSize = LocalNumCells * sizeof(float);

	TArray<float> LocalTotalCopy;
	TArray<float> LocalDirectCopy;
	TArray<float> LocalDiffuseCopy;
	TArray<float> LocalDiffuseNoGICopy;
	TArray<float> LocalTotalNoGICopy;
	TArray<float> LocalSurfaceStateCopy;
	LocalTotalCopy.SetNum(LocalNumCells);
	LocalDirectCopy.SetNum(LocalNumCells);
	LocalDiffuseCopy.SetNum(LocalNumCells);
	if (bUseDiffuseNoGIReadback)
	{
		LocalDiffuseNoGICopy.SetNum(LocalNumCells);
	}
	if (bUseTotalNoGIReadback)
	{
		LocalTotalNoGICopy.SetNum(LocalNumCells);
	}
	if (bUseSurfaceStateReadback)
	{
		LocalSurfaceStateCopy.SetNum(LocalNumCells);
	}

	float* TotalDataPtr = LocalTotalCopy.GetData();
	float* DirectDataPtr = LocalDirectCopy.GetData();
	float* DiffuseDataPtr = LocalDiffuseCopy.GetData();
	float* DiffuseNoGIDataPtr = bUseDiffuseNoGIReadback ? LocalDiffuseNoGICopy.GetData() : nullptr;
	float* TotalNoGIDataPtr = bUseTotalNoGIReadback ? LocalTotalNoGICopy.GetData() : nullptr;
	float* SurfaceStateDataPtr = bUseSurfaceStateReadback ? LocalSurfaceStateCopy.GetData() : nullptr;

	bool bReadbackSuccess = false;
	FEvent* CompletionEvent = FPlatformProcess::GetSynchEventFromPool(true);

	ENQUEUE_RENDER_COMMAND(ReadbackRTYLuminanceCommand)(
		[TotalReadback = RTYTotalReadback,
		 DirectReadback = RTYDirectReadback,
		 DiffuseReadback = RTYDiffuseReadback,
		 DiffuseNoGIReadback = RTYDiffuseNoGIReadback,
		 TotalNoGIReadback = RTYTotalNoGIReadback,
		 SurfaceStateReadback = RTYSurfaceStateReadback,
		 bUseDiffuseNoGIReadback,
		 bUseTotalNoGIReadback,
		 bUseSurfaceStateReadback,
		 BufferSize,
		 TotalDataPtr,
		 DirectDataPtr,
		 DiffuseDataPtr,
		 DiffuseNoGIDataPtr,
		 TotalNoGIDataPtr,
		 SurfaceStateDataPtr,
		 CompletionEvent,
		 &bReadbackSuccess](FRHICommandListImmediate& RHICmdList)
		{
			const void* TotalData = TotalReadback ? TotalReadback->Lock(BufferSize) : nullptr;
			const void* DirectData = DirectReadback ? DirectReadback->Lock(BufferSize) : nullptr;
			const void* DiffuseData = DiffuseReadback ? DiffuseReadback->Lock(BufferSize) : nullptr;
			const void* DiffuseNoGIData = (bUseDiffuseNoGIReadback && DiffuseNoGIReadback) ? DiffuseNoGIReadback->Lock(BufferSize) : nullptr;
			const void* TotalNoGIData = (bUseTotalNoGIReadback && TotalNoGIReadback) ? TotalNoGIReadback->Lock(BufferSize) : nullptr;
			const void* SurfaceStateData = (bUseSurfaceStateReadback && SurfaceStateReadback) ? SurfaceStateReadback->Lock(BufferSize) : nullptr;

			const bool bCoreReady = (TotalData && DirectData && DiffuseData);
			const bool bNoGIReady = !bUseDiffuseNoGIReadback || DiffuseNoGIData;
			const bool bTotalNoGIReady = !bUseTotalNoGIReadback || TotalNoGIData;
			const bool bSurfaceStateReady = !bUseSurfaceStateReadback || SurfaceStateData;
			if (bCoreReady && bNoGIReady && bTotalNoGIReady && bSurfaceStateReady)
			{
				FMemory::Memcpy(TotalDataPtr, TotalData, BufferSize);
				FMemory::Memcpy(DirectDataPtr, DirectData, BufferSize);
				FMemory::Memcpy(DiffuseDataPtr, DiffuseData, BufferSize);
				if (bUseDiffuseNoGIReadback && DiffuseNoGIDataPtr)
				{
					FMemory::Memcpy(DiffuseNoGIDataPtr, DiffuseNoGIData, BufferSize);
				}
				if (bUseTotalNoGIReadback && TotalNoGIDataPtr)
				{
					FMemory::Memcpy(TotalNoGIDataPtr, TotalNoGIData, BufferSize);
				}
				if (bUseSurfaceStateReadback && SurfaceStateDataPtr)
				{
					FMemory::Memcpy(SurfaceStateDataPtr, SurfaceStateData, BufferSize);
				}
				TotalReadback->Unlock();
				DirectReadback->Unlock();
				DiffuseReadback->Unlock();
				if (bUseDiffuseNoGIReadback && DiffuseNoGIData)
				{
					DiffuseNoGIReadback->Unlock();
				}
				if (bUseTotalNoGIReadback && TotalNoGIData)
				{
					TotalNoGIReadback->Unlock();
				}
				if (bUseSurfaceStateReadback && SurfaceStateData)
				{
					SurfaceStateReadback->Unlock();
				}
				bReadbackSuccess = true;
			}
			else
			{
				if (TotalData)
				{
					TotalReadback->Unlock();
				}
				if (DirectData)
				{
					DirectReadback->Unlock();
				}
				if (DiffuseData)
				{
					DiffuseReadback->Unlock();
				}
				if (DiffuseNoGIData)
				{
					DiffuseNoGIReadback->Unlock();
				}
				if (TotalNoGIData)
				{
					TotalNoGIReadback->Unlock();
				}
				if (SurfaceStateData)
				{
					SurfaceStateReadback->Unlock();
				}
				bReadbackSuccess = false;
			}

			CompletionEvent->Trigger();
		});

	CompletionEvent->Wait();
	FPlatformProcess::ReturnSynchEventToPool(CompletionEvent);

	if (!bReadbackSuccess)
	{
		return false;
	}

	// Copy data to cached arrays
	FMemory::Memcpy(CachedRTY_Total.GetData(), LocalTotalCopy.GetData(), BufferSize);
	FMemory::Memcpy(CachedRTY_Direct.GetData(), LocalDirectCopy.GetData(), BufferSize);
	FMemory::Memcpy(CachedRTY_Diffuse.GetData(), LocalDiffuseCopy.GetData(), BufferSize);
	if (bUseDiffuseNoGIReadback && CachedRTY_DiffuseNoGI.Num() == LocalNumCells)
	{
		FMemory::Memcpy(CachedRTY_DiffuseNoGI.GetData(), LocalDiffuseNoGICopy.GetData(), BufferSize);
	}
	else
	{
		CachedRTY_DiffuseNoGI.Reset();
	}
	if (bUseTotalNoGIReadback && CachedRTY_TotalNoGI.Num() == LocalNumCells)
	{
		FMemory::Memcpy(CachedRTY_TotalNoGI.GetData(), LocalTotalNoGICopy.GetData(), BufferSize);
	}
	else if (!bUseDiffuseNoGIReadback)
	{
		CachedRTY_TotalNoGI.Reset();
	}
	if (bUseSurfaceStateReadback && CachedRTY_SurfaceState.Num() == LocalNumCells)
	{
		FMemory::Memcpy(CachedRTY_SurfaceState.GetData(), LocalSurfaceStateCopy.GetData(), BufferSize);
	}
	else
	{
		CachedRTY_SurfaceState.Reset();
	}

	int32 TotalVsDirectClampCount = 0;
	for (int32 Index = 0; Index < LocalNumCells; ++Index)
	{
		float& Total = CachedRTY_Total[Index];
		float& Direct = CachedRTY_Direct[Index];
		float& Diffuse = CachedRTY_Diffuse[Index];
		Total = FMath::IsFinite(Total) ? FMath::Max(0.0f, Total) : 0.0f;
		Direct = FMath::IsFinite(Direct) ? FMath::Max(0.0f, Direct) : 0.0f;
		Diffuse = FMath::IsFinite(Diffuse) ? FMath::Max(0.0f, Diffuse) : 0.0f;

		if (Total < Direct)
		{
			Total = Direct;
			++TotalVsDirectClampCount;
		}
		if (bUseDiffuseNoGIReadback && CachedRTY_DiffuseNoGI.IsValidIndex(Index))
		{
			float& DiffuseNoGI = CachedRTY_DiffuseNoGI[Index];
			DiffuseNoGI = FMath::IsFinite(DiffuseNoGI) ? FMath::Max(0.0f, DiffuseNoGI) : 0.0f;
			DiffuseNoGI = FMath::Min(DiffuseNoGI, Total);
		}
		if (CachedRTY_TotalNoGI.IsValidIndex(Index))
		{
			float& TotalNoGI = CachedRTY_TotalNoGI[Index];
			if (bUseTotalNoGIReadback)
			{
				TotalNoGI = FMath::IsFinite(TotalNoGI) ? FMath::Max(0.0f, TotalNoGI) : 0.0f;
				TotalNoGI = FMath::Clamp(TotalNoGI, Direct, Total);
			}
			else if (bUseDiffuseNoGIReadback)
			{
				TotalNoGI = FMath::Clamp(Direct + CachedRTY_DiffuseNoGI[Index], Direct, Total);
			}
			else
			{
				TotalNoGI = 0.0f;
			}
		}
		if (bUseSurfaceStateReadback && CachedRTY_SurfaceState.IsValidIndex(Index))
		{
			float& SurfaceState = CachedRTY_SurfaceState[Index];
			SurfaceState = FMath::IsFinite(SurfaceState) ? FMath::Max(0.0f, SurfaceState) : 0.0f;
		}
	}
	if (TotalVsDirectClampCount > 0)
	{
		static int32 TotalVsDirectClampLogCount = 0;
		if (TotalVsDirectClampLogCount++ < 8)
		{
			UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] Applied physical consistency clamp on %d cells (Total < Direct)."), TotalVsDirectClampCount);
		}
	}

	bRTYDiffuseNoGIReadbackQueued = false;
	bRTYTotalNoGIReadbackQueued = false;
	bRTYSurfaceStateReadbackQueued = false;

	static int32 RTYReadbackLogCounter = 0;
	if (RTYReadbackLogCounter++ < 3)
	{
		float MinVal = FLT_MAX;
		float MaxVal = -FLT_MAX;
		double SumVal = 0.0;

		for (float Value : CachedRTY_Direct)
		{
			MinVal = FMath::Min(MinVal, Value);
			MaxVal = FMath::Max(MaxVal, Value);
			SumVal += Value;
		}

		const float AvgVal = (LocalNumCells > 0) ? static_cast<float>(SumVal / static_cast<double>(LocalNumCells)) : 0.0f;

		UE_LOG(LogTemp, Warning, TEXT("[RTY Extract] Readback #%d complete: %d cells | Min=%.3f Max=%.3f Avg=%.3f"),
			RTYReadbackLogCounter, LocalNumCells, MinVal, MaxVal, AvgVal);
	}

	return true;
}

void ASnowSimulationActor::CleanupRadiationExtraction()
{
 if (RadiationReadbackBuffer)
 {
 	ENQUEUE_RENDER_COMMAND(DestroyRadiationReadbackBuffer)(
 		[Readback = RadiationReadbackBuffer](FRHICommandListImmediate& RHICmdList)
 		{
 			delete Readback;
 		});

 	RadiationReadbackBuffer = nullptr;
 }

 if (RTYDirectReadback || RTYDiffuseReadback || RTYTotalReadback || RTYDiffuseNoGIReadback || RTYTotalNoGIReadback || RTYSurfaceStateReadback)
 {
 	FRHIGPUBufferReadback* LocalTotalBuf = RTYTotalReadback;
 	FRHIGPUBufferReadback* LocalDirectBuf = RTYDirectReadback;
 	FRHIGPUBufferReadback* LocalDiffuseBuf = RTYDiffuseReadback;
	FRHIGPUBufferReadback* LocalDiffuseNoGIBuf = RTYDiffuseNoGIReadback;
	FRHIGPUBufferReadback* LocalTotalNoGIBuf = RTYTotalNoGIReadback;
	FRHIGPUBufferReadback* LocalSurfaceStateBuf = RTYSurfaceStateReadback;

	ENQUEUE_RENDER_COMMAND(DestroyRTYReadbacks)(
		[LocalTotalBuf, LocalDirectBuf, LocalDiffuseBuf, LocalDiffuseNoGIBuf, LocalTotalNoGIBuf, LocalSurfaceStateBuf](FRHICommandListImmediate& RHICmdList)
 		{
 			delete LocalTotalBuf;
 			delete LocalDirectBuf;
 			delete LocalDiffuseBuf;
			delete LocalDiffuseNoGIBuf;
			delete LocalTotalNoGIBuf;
			delete LocalSurfaceStateBuf;
 		});

 	RTYTotalReadback = nullptr;
 	RTYDirectReadback = nullptr;
 	RTYDiffuseReadback = nullptr;
	RTYDiffuseNoGIReadback = nullptr;
	RTYTotalNoGIReadback = nullptr;
	RTYSurfaceStateReadback = nullptr;
	bRTYDiffuseNoGIReadbackQueued = false;
	bRTYTotalNoGIReadbackQueued = false;
	bRTYSurfaceStateReadbackQueued = false;
 }

 if (ReferenceTotalReadback || ReferenceDirectReadback || ReferenceDiffuseReadback || ReferenceDiffuseNoGIReadback || ReferenceTotalNoGIReadback || ReferenceSurfaceStateReadback)
 {
 	FRHIGPUTextureReadback* LocalTotal = ReferenceTotalReadback;
 	FRHIGPUTextureReadback* LocalDirect = ReferenceDirectReadback;
	FRHIGPUTextureReadback* LocalDiffuse = ReferenceDiffuseReadback;
	FRHIGPUTextureReadback* LocalDiffuseNoGI = ReferenceDiffuseNoGIReadback;
	FRHIGPUTextureReadback* LocalTotalNoGI = ReferenceTotalNoGIReadback;
	FRHIGPUTextureReadback* LocalSurfaceState = ReferenceSurfaceStateReadback;

	ENQUEUE_RENDER_COMMAND(DestroyReferenceReadbacks)(
		[LocalTotal, LocalDirect, LocalDiffuse, LocalDiffuseNoGI, LocalTotalNoGI, LocalSurfaceState](FRHICommandListImmediate& RHICmdList)
 		{
 			delete LocalTotal;
 			delete LocalDirect;
			delete LocalDiffuse;
			delete LocalDiffuseNoGI;
			delete LocalTotalNoGI;
			delete LocalSurfaceState;
 		});

 	ReferenceTotalReadback = nullptr;
 	ReferenceDirectReadback = nullptr;
	ReferenceDiffuseReadback = nullptr;
	ReferenceDiffuseNoGIReadback = nullptr;
	ReferenceTotalNoGIReadback = nullptr;
	ReferenceSurfaceStateReadback = nullptr;
 }

 RadiationIndexBuffer.SafeRelease();
	bReferenceReadbackPending = false;
	bReferenceDiffuseReadbackQueued = false;
	bReferenceDiffuseNoGIReadbackQueued = false;
	bReferenceTotalNoGIReadbackQueued = false;
	bReferenceSurfaceStateReadbackQueued = false;
	ReferenceReadbackWidth = 0;
	ReferenceLuminance_Total = 1.0f;
	ReferenceLuminance_Direct = 1.0f;
	ReferenceLuminance_Diffuse = 1.0f;
	ReferenceLuminance_DiffuseNoGI = 1.0f;
	ReferenceLuminance_TotalNoGI = 1.0f;
	ReferenceLuminance_SurfaceState = 0.0f;
	ReferenceLuminance_Total_Ground = 1.0f;
	ReferenceLuminance_Direct_Ground = 1.0f;
	ReferenceLuminance_Diffuse_Ground = 1.0f;
	ReferenceLuminance_DiffuseNoGI_Ground = 1.0f;
	ReferenceLuminance_TotalNoGI_Ground = 1.0f;
	ReferenceLuminance_SurfaceState_Ground = 0.0f;
	ReferenceLuminance_Total_Snow = 1.0f;
	ReferenceLuminance_Direct_Snow = 1.0f;
	ReferenceLuminance_Diffuse_Snow = 1.0f;
	ReferenceLuminance_DiffuseNoGI_Snow = 1.0f;
	ReferenceLuminance_TotalNoGI_Snow = 1.0f;
	ReferenceLuminance_SurfaceState_Snow = 0.0f;
	CachedReferenceStripRTY_Total.Reset();
	CachedReferenceStripRTY_Direct.Reset();
	CachedReferenceStripRTY_Diffuse.Reset();
	CachedReferenceStripRTY_DiffuseNoGI.Reset();
	CachedReferenceStripRTY_TotalNoGI.Reset();
	CachedReferenceStripWidth = 0;
	CachedReferenceStripHeight = 0;
	bReferenceLuminanceValid = false;
	CachedRadiationIndices.Empty();
	ReferenceMappingDebugCsvPath.Empty();
	LastRadiationExtractionFrame = INDEX_NONE;
	bRadiationCaptureInitialized = false;
	CachedRadiationCaptureWidth = 0;
	CachedRadiationCaptureHeight = 0;
	bCachedUseReferenceTile = false;

	ReleaseRadiationPixelCoordResources();
}
